def quest_state(args):
    """{quest id: {"on": bool, "n": hand-ins, "last": epoch s}} off the
    stored character (_store_char_field 'quests')."""
    st = _load_char_field(args, "quests", None)
    return dict(st) if isinstance(st, dict) else {}


def quest_cooldown(args, q):
    over = int(getattr(args, "quest_cooldown_secs", -1))
    return over if over >= 0 else int(QUESTS[q].get("cooldown", 0))


def quest_script_for(args, row, now=None):
    """The conversation a quest giver plays for THIS character, or None when
    the row gives no quest (or --quests off)."""
    if str(getattr(args, "quests", "on") or "on") != "on":
        return None
    try:
        q = QUEST_BY_GIVER.get(int(row.get("script") or 0))
    except (TypeError, ValueError):
        return None
    if q is None:
        return None
    d, st = QUESTS[q], quest_state(args).get(q, {})
    if not st.get("on"):
        return [("text", d["offer"]),
                ("menu", d["prompt"], ["Yes", "No"],
                 {0: [("qset", q, "accept"), ("text", d["accept"]), QUEST_END],
                  1: [("text", d["refuse"]), QUEST_END],
                  "cancel": [("text", d["refuse"]), QUEST_END]})]
    if d.get("repeat") == "once" and int(st.get("n", 0) or 0) > 0:
        return [("text", d["rest"]), QUEST_END]
    if not any(int(r[1]) == int(d["item"]) for r in item_rows(args)):
        return [("text", d["remind"]), QUEST_END]
    now = time.time() if now is None else now
    wait = float(st.get("last", 0) or 0) + quest_cooldown(args, q) - now
    if wait > 0:
        return [("text", d["rest"]), QUEST_END]
    return [("text", d["ask"]),
            ("menu", d["hand"], ["Yes", "No"],
             {0: [("take", d["item"], q), ("credit", d["gold"], q),
                  ("qset", q, "done"), ("text", d["thanks"]), QUEST_END],
              1: [("text", d["later"]), QUEST_END],
              "cancel": [("text", d["later"]), QUEST_END]})]


def event_menu_pick(ev, a, b, c):
    """Splice the branch the player picked into the running event. Only a
    real menu reply (b == 0x107) naming an option we offered takes it; any
    other ack while a menu is up is the 'cancel' branch."""
    branches = ev.pop("await_menu", None)
    if branches is None:
        return None
    key = int(c) if (int(b) == EV_MENU and int(c) in branches) else "cancel"
    rest = branches.get(key) or branches.get("cancel") or [QUEST_END]
    ev["steps"] = ev["steps"][:ev["pc"]] + list(rest)
    print("[feworld]    menu pick a=%d b=0x%X c=%d -> branch %r (%d step(s))%s"
          % (a, b, c, key, len(rest),
             "" if int(b) == EV_MENU else " -- not a menu reply (0x107): "
             "treated as CANCEL"), flush=True)
    return key


def event_after(conn, outbound, mode, be, args, ev):
    """Run the steps a conversation deferred until it CLOSED: take an item,
    credit gold, update a quest. A take that finds nothing (the item left
    the bag mid-conversation) stops the rest -- no reward without it."""
    todo = list((ev or {}).get("after") or [])
    for step in todo:
        kind = step[0]
        if kind == "take":
            item, q = int(step[1]), step[2]
            rows = item_rows(args)
            hit = next((i for i, r in enumerate(rows) if int(r[1]) == item), None)
            if hit is None:
                print("[feworld]    quest %s: item %d is no longer in the bag "
                      "-- nothing taken, NO reward" % (q, item), flush=True)
                return False
            uid, no, flag, count = rows[hit]
            new, gone = list(rows), []
            if int(count) > 1:
                new[hit] = (uid, no, flag, int(count) - 1)
            else:
                del new[hit]
                gone = [(uid, hit)]
            _store_char_field(args, "items", [list(x) for x in new])
            bag_layout_push(conn, outbound, mode, be, args, rows, new, gone,
                            "quest %s hand-in" % q)
        elif kind == "credit":
            wallet_credit(conn, outbound, mode, be, args, gold=int(step[1]),
                          why="quest %s reward" % step[2])
        elif kind == "qset":
            q, what = step[1], step[2]
            st = quest_state(args)
            cur = dict(st.get(q, {}))
            if what == "accept":
                cur["on"] = True
            elif what == "done":
                cur["on"] = True
                cur["n"] = int(cur.get("n", 0) or 0) + 1
                cur["last"] = int(time.time())
            st[q] = cur
            _store_char_field(args, "quests", st)
            print("[feworld]    quest %s: %s -> %r" % (q, what, cur), flush=True)
    return True


def event_script_for(args, row):
    """The conversation a town-file NPC row plays, as a list of steps:
    ("text", s) | ("window", type, arg) | ("menu", prompt, [opts])."""
    name = str(row.get("name") or "")
    greet = getattr(args, "event_greeting", None)
    # WARNING: THE NAME GUARD COMES AFTER THE OVERRIDE, and it used to come before.
    # A row's dat.pak type NAME is what picks a shop or a bank script, so a
    # nameless row has nothing to play -- but an `event=` override is exactly
    # the case where the name does not matter, and returning [] first meant a
    # hand-placed guard with `event=say:...;goto:15` silently said nothing.
    # Found 2026-09-06 while wiring the castle gate: `!npc` fills the name from
    # the modeltype, so it is usually non-empty by luck, and any model the type
    # table does not name would have failed with no message at all.
    if not name and not row.get("event"):
        return []
    # A row-level OVERRIDE: `"event": "goto:15"` (a room), `"goto:39"` (a
    # field), `"shop:2"`, `"bank"`, `"say:Hello there"`; steps separated by
    # `;`. This is how the castle gets a door: a guard at the gate whose
    # conversation ends in the transition the street doors use (0x1166).
    # Set with `!town set npcs IDX event=goto:15`.
    if row.get("event"):
        steps = []
        for part in str(row["event"]).split(";"):
            kind, _, val = part.strip().partition(":")
            if kind == "say":
                steps.append(("text", val))
            elif kind == "goto":
                try:
                    tgt = int(val, 0)
                except ValueError:
                    continue
                steps.append(("goto", ROOM_AREA_BASE + tgt if tgt < 0x100 and tgt in ROOM_INDEX_WINDOW else tgt))
            elif kind == "shop":
                steps.append(("window", int(val or 1, 0), int(row.get("script") or 0)))
            elif kind == "bank":
                steps.append(("window", EV_WIN_BANK, 0))
            elif kind == "end":
                steps.append(("window", EV_WIN_END, 0))
        if steps and steps[0][0] != "text":
            steps.insert(0, ("text", greet or "..."))
        if steps and steps[-1][0] == "window" and steps[-1][1] != EV_WIN_END:
            steps.append(("window", EV_WIN_END, 0))
        return steps
    # A shop/bank script ENDS with the END window (op 8 type 0x13): the
    # client clears its own talk mode and sends 0x2099 -> 0x1152 -- the path
    # the tavern proved live. WARNING: LIVE 2026-09-05 #1 and #4: answering the
    # shop's close ack with 0x1172 instead left the client STUCK both times.
    # A TOWNSFOLK row (script 1xx..9xx) says its own line -- SE's words from
    # atwiki 243, in our English -- whatever its row is named.
    # a QUEST GIVER plays its quest for this character (quest_script_for)
    quest = quest_script_for(args, row)
    if quest is not None:
        return quest
    tf = fegamedata.townsfolk_by_script(row.get("script"))
    if tf is not None:
        if tf["kind"] == "weapon":
            return free_weapon_script(args, tf)
        return [("text", greet or tf["line_en"] or "Good day."),
                ("window", EV_WIN_END, 0)]
    shop = shop_type_for(args, name)
    if shop is not None:
        return [("text", greet or "Welcome. Have a look."),
                ("window", shop, int(row.get("script") or 0)),
                ("window", EV_WIN_END, 0)]
    if name == "Bank_Keeper":
        return [("text", greet or "Welcome to the bank."),
                ("window", EV_WIN_BANK, int(row.get("script") or 0)),
                ("window", EV_WIN_END, 0)]
    if name == "Inn_Master":
        # SE's 2006 guide (flow06): the inn restores HP and Pw in full -- free
        # to level 5, then priced by level. The brackets are fewiki's 2006
        # Q&A (inn_fee, --inn-fees rod): 10 / 20 / 50 G.
        fee = inn_fee(args)
        if fee and wallet_short(args, fee):
            return [("text", greet or "A room is %d gold at your level, "
                                      "traveller, and your purse won't cover "
                                      "it. Come back when it will." % fee),
                    ("window", EV_WIN_END, 0)]
        line = ("Welcome to the inn. That's %d gold -- rest a while, you're "
                "back to full strength." % fee if fee else
                "Welcome to the inn. Rest a while -- you're back to full "
                "strength.")
        return ([("pay", fee)] if fee else []) + [
                ("heal",),
                ("text", greet or line),
                ("window", EV_WIN_END, 0)]
    slot = role_slot(row)
    if slot in ROLE_MANAGERS:
        return [("text", greet or ("A message from the King. "
                                   + campaign_report(args))),
                ("window", EV_WIN_END, 0)]
    if slot == ROLE_PRIZE_CLERK:
        return [("text", greet or prize_clerk_line(args)),
                ("window", EV_WIN_END, 0)]
    if slot in ROLE_LINES:
        return [("text", greet or ROLE_LINES[slot]), ("window", EV_WIN_END, 0)]
    return [("text", greet or "Good day."), ("window", EV_WIN_END, 0)]


def event_step(conn, outbound, mode, be, args):
    """Send the current command of the session's event, or END it."""
    ev = _SESSION.get("event")
    if not ev:
        return
    pc = ev["pc"]
    if pc >= len(ev["steps"]):
        send(conn, outbound, inner_msg(0x1175, b"", ev["npc"]),
             mode, be, args.seq_mode == "echo", args.world_prefix)
        print("[feworld] -> 0x30 inner 0x1175 event END (%s, %d step(s) done)"
              % (ev.get("name"), pc), flush=True)
        _SESSION.pop("event", None)
        # what the conversation deferred (a quest's take / gold / state)
        event_after(conn, outbound, mode, be, args, ev)
        # A conversation ends TWO ways and both have to offer the room exit.
        # This is the one where the script simply runs out (a `say`-only NPC);
        # the other is the END window -> 0x2099 -> conversation_close. Only
        # that second one called the exit until 2026-09-06, which would have
        # made a plain talking NPC inside a room a dead end -- the same trap
        # the tavern sprang, one step further in.
        room_exit_push(conn, outbound, mode, be, args, "the script ran out")
        return
    step = ev["steps"][pc]
    ev["pc"] = pc + 1
    if step[0] in ("take", "credit", "qset"):
        # a quest's bag/wallet/state change waits for the CLOSE (event_after)
        ev.setdefault("after", []).append(step)
        return event_step(conn, outbound, mode, be, args)
    # WARNING: LIVE 2026-09-05 #4: the head u32 of every 0x1174 is the NPC UNIT id,
    # not the script. The interpreter (0x5173a70) reads it into a local and
    # hands its ADDRESS to every op handler unchecked; the op-8 handler
    # passes it as the window ctor's argument (0x51746bb: [esp+0x20] = arg
    # 1), which lands at [win+0x84] -- the unit the shop polices and the
    # (id, 8, 0) it acks with. We sent the script id (2102) there for four
    # attempts; the window's own u32 argument never reached +0x84 at all
    # (the ack still said 2102 after it carried 500).
    evt = ev["npc"]
    if step[0] == "give":
        # the free weapon: into the bag, pushed, then straight on to the line
        old = item_rows(args)
        nxt = new_item_uid(args, old)                   # bag AND bank uids
        new = old + [(nxt, int(step[1]), 1, 1)]
        _store_char_field(args, "items", [list(x) for x in new])
        bag_layout_push(conn, outbound, mode, be, args, old, new, [],
                        "free weapon %d from %s" % (int(step[1]), ev.get("name")))
        return event_step(conn, outbound, mode, be, args)
    if step[0] == "pay":
        # the inn's fee: charged when the step RUNS, not when the script was
        # written at the click, so the wallet read is the current one. A
        # wallet that went short in between skips the rest (the heal).
        ok, _short = wallet_charge(conn, outbound, mode, be, args, int(step[1]),
                                   0, "the inn (%s)" % ev.get("name"))
        if not ok:
            ev["steps"] = ev["steps"][:ev["pc"]] + [
                ("text", "Your purse won't cover a room. Come back when it "
                         "will."), ("window", EV_WIN_END, 0)]
        return event_step(conn, outbound, mode, be, args)
    if step[0] == "heal":
        hp = player_hp_max(args)
        _SESSION["player_hp"] = hp
        player_hp_push(conn, outbound, mode, be, args, hp)
        print("[feworld]    the inn: HP %d/%d" % (hp, hp), flush=True)
        return event_step(conn, outbound, mode, be, args)
    if step[0] == "goto":
        # end the conversation first (0x1175 releases event mode), then move
        send(conn, outbound, inner_msg(0x1175, b"", ev["npc"]),
             mode, be, args.seq_mode == "echo", args.world_prefix)
        _SESSION.pop("event", None)
        print("[feworld] -> 0x30 inner 0x1175 event END, then the transition:",
              flush=True)
        goto_push(conn, outbound, mode, be, args, int(step[1]))
        return
    if step[0] == "text":
        body = ev_body(evt, EV_TEXT,
                       talk_wrap(step[1], int(getattr(args, "talk_wrap", 48) or 0),
                                 int(getattr(args, "talk_lines", 4) or 4)))
    elif step[0] == "window":
        # the op's own u32 is NOT what the shop polices (see `evt` above);
        # it goes out as the unit id too, and step[2] (the row's script id)
        # is kept for the log only
        body = ev_body(evt, EV_WINDOW, step[1], ev["npc"])
        if int(step[1]) == EV_WIN_BANK:
            # the bank window sizes itself from [unit+0x4fe] IN ITS CTOR and
            # lists the kind-1 array: both have to be there before op 8 lands
            bank_open_push(conn, outbound, mode, be, args)
        # a SHOP/BANK window owns the conversation from here: its own
        # requests follow (0x2073 -> 0x1102, 0x204A..); its CLOSE is 0x2085
        # + a 0x20A8 (npc, 8, 0) ack, which cues the next command (END).
        # The END window (0x13) is the client closing itself -- 0x2099 follows.
        ev["in_window"] = True
        if 1 <= int(step[1]) <= 4:
            kind = shop_kind_for(args, ev.get("name"), int(step[1]))
            cls = shop_class_for(ev.get("name"))
            stock = shop_stock(args, kind, cls)
            _SESSION["shop"] = {"npc": ev["npc"], "kind": kind, "class": cls,
                                "type": int(step[1]), "stock": stock}
            print("[feworld]    shop context: %s%s, %d item(s) in %d page(s) "
                  "(fet_items slot types %s; --shop-prices %s)"
                  % (kind, "" if cls is None else " for class %d" % cls,
                     len(stock), shop_pages(args, stock),
                     SHOP_SLOTS.get(kind), getattr(args, "shop_prices", "table")),
                  flush=True)
    elif step[0] == "menu":
        body = ev_body(evt, EV_MENU, step[1], step[2])
        if len(step) > 3:
            # the next ack is the pick; event_menu_pick splices its branch
            ev["await_menu"] = step[3]
    else:
        body = ev_body(evt, EV_U32, int(step[1]))
    send(conn, outbound, inner_msg(0x1174, body, ev["npc"]), mode, be,
         args.seq_mode == "echo", args.world_prefix)
    print("[feworld] -> 0x30 inner 0x1174 event step %d/%d for %s (unit %d): %s "
          "-- wait for the window's 0x20A8 ack"
          % (pc + 1, len(ev["steps"]), ev.get("name"), ev["npc"],
             step if step[0] != "text" else ("text", step[1][:40])), flush=True)


def conversation_close(conn, outbound, mode, be, args, f, how):
    """0x2099 -> 0x1152 [u32 npc][cstr farewell]: the conversation CLOSE.

    Sent by opcode 8 type 0x13 (0x05174560) after clearing the talk mode;
    it registers 0x1152 OK / 0x1153 NG in the pending table. WARNING: LIVE
    2026-09-05 #7: the END op writes the request through a STACK-LOCAL
    stream object (`lea ecx,[esp+8]` at 0x517457c, not the session stream
    0x5338350), so it leaves the client as a BARE OUTER frame, id 0x2099,
    outside the 0x30 envelope. We logged it as OUTER and never answered;
    the pending entry drew "waiting..." after every Cancel. Both arrivals
    land here. 0x1152's arm (0x0505397d) reads [u32][cstr]."""
    ev = _SESSION.pop("event", None)
    _SESSION.pop("shop", None)
    _SESSION.pop("bank_open", None)
    npc = ev["npc"] if ev else (struct.unpack_from(">I", f, 0)[0]
                                if len(f) >= 4 else 0)
    send(conn, outbound,
         inner_msg(0x1152, struct.pack(">I", npc) + b"\x00", unit_id_of(args)),
         mode, be, args.seq_mode == "echo", args.world_prefix)
    print("[feworld]    0x2099 conversation close (%s) body=%s -> 0x1152 "
          "[npc %d][empty]; event cleared" % (how, f.hex(), npc), flush=True)
    # KEY: LIVE 2026-09-05 #8/#9: the EVENT END is **0x1175**. The dispatcher's
    # table (0x5057650 via 0x505768c, base 0x1165) maps 0x1172 -> 0x5055f70,
    # the arm that ARMS event mode (scene flag 0x4000, byte 0x53378f3 = 1,
    # the manager's modal bit, [mgr+0x94] slot 32) -- i.e. START OK locks
    # the player for the conversation -- and 0x1175 -> 0x5056039, the arm
    # that releases all of it (and the talk-mode bit). Every "stuck" was us
    # sending 0x1172 at the END: re-locking. 0x1175 reads nothing.
    send(conn, outbound, inner_msg(0x1175, b"", unit_id_of(args)),
         mode, be, args.seq_mode == "echo", args.world_prefix)
    print("[feworld] -> 0x30 inner 0x1175 event END (header-only, after the "
          "close OK): releases event mode", flush=True)
    # what the conversation deferred (a quest's take / gold / state) -- now
    # that event mode is released
    event_after(conn, outbound, mode, be, args, ev)
    room_exit_push(conn, outbound, mode, be, args, "the conversation ended")


def room_exit_push(conn, outbound, mode, be, args, why):
    """Walk the player OUT of a room, because the client will not.

    WARNING: REPORTED LIVE 2026-09-06: "I'm in the tavern, talked to the person, it
    gave me dialogue but then closed. Also, can't leave the tavern by any means
    (door doesn't work, gating out doesn't work)." The session then idled out.

    **A room has no exit of its own and that is measured, twice.** Inside, the
    client sends NOTHING at the room's door -- the 0x2017/0x2000 area -1 pair
    seen on 2026-09-04 was the war screen's "Army info" leave when its 60 s
    countdown ran out, not a door. A room is a scene we put the player in
    (0x1166 -> area ROOM_AREA_BASE+idx), so getting back out is the SERVER's
    move, and until now the only one that made it was a hand-typed `!goto` in
    the gm command file. A player without that is trapped until the read window
    times out.

    So the conversation END doubles as the exit: 0x1166 unsolicited, back to the
    field the door came from (`outside`, remembered when the door was taken).
    That is the same message and the same arm the door uses -- the arm
    (0x05056089) registers no request of its own and just acts on A.

    WARNING: Only when we are actually IN a room. Outdoors this must do nothing: A
    equal to the current field with B == -1 is a same-field WARP, so an
    unguarded call would teleport the player to the spawn point every time they
    finished talking to anybody.
    """
    if getattr(args, "room_exit", "conversation") == "off":
        print("[feworld]    --room-exit off: staying in room %s (%s). The "
              "client has no door out of a room -- only !goto will move it."
              % (_SESSION.get("room"), why), flush=True)
        return 0
    room = _SESSION.get("room", -1)
    if room == -1 or not _SESSION.get("in_field"):
        return 0
    # ONCE PER ROOM. A conversation can end down both paths in quick
    # succession (the script runs out, and a late 0x2099 arrives after the
    # event is already popped), and [room] does not change until the client
    # answers our 0x1166 with its own 0x2000 -- so without this the second
    # push goes out while the session still says "in room" and the player is
    # transitioned twice.
    if _SESSION.get("room_exit_sent") == room:
        print("[feworld]    room exit for room %s already pushed -- waiting "
              "for the client's 0x2000, not sending a second one" % room,
              flush=True)
        return 0
    outside = _SESSION.get("outside") or _SESSION.get("field")
    if not outside:
        print("[feworld]    WARNING: in room %s but nothing remembers the field it "
              "was entered from -- NOT pushing an exit, because 0x1166 to the "
              "wrong area is a transition to somewhere the player never was"
              % _SESSION.get("room"), flush=True)
        return 0
    print("[feworld]    ROOM EXIT: %s and this session is in room %s, which "
          "has no door of its own -- pushing the player back out to field %d"
          % (why, room, outside), flush=True)
    _SESSION["room_exit_sent"] = room
    goto_push(conn, outbound, mode, be, args, int(outside))
    return 1


def goto_push(conn, outbound, mode, be, args, area, pos=None, via=None,
              face=None):
    """0x1166 MSG_GOTO_SEARCH_OK -- send the client somewhere.

    The door's answer, and it works UNSOLICITED too: the arm (0x05056089)
    registers no request of its own, it just acts on A. A != the current
    field starts the field transition to area A (kind 3 -> 0x20A6 -> 0x2000);
    A == the current field with B == -1 is a same-field warp to `pos`. So
    this is both the door reply and a server-side "leave": `!goto 39` in
    --gmcmd-file pulls a player out of a room that has no exit of its own.
    """
    sx, sy, sz = pos if pos is not None else spawn_for(args, area)
    # WARNING: THE POSITION IN THIS MESSAGE IS ONLY USED FOR A SAME-FIELD WARP.
    # When A is a DIFFERENT area the arm starts a field TRANSITION instead
    # (kind 3 -> 0x20A6 -> 0x2000), and the place the player ends up is
    # whatever the ENTRY sequence sends -- 0x1027 MSG_SET_POSITION and the
    # self record, both of which ask spawn_for(). So a door's own arrival
    # point was computed, put on the wire, and then silently ignored: you
    # walked through a door and arrived at the area's spawn.
    # Reported live 2026-09-10, and true of the SHIPPED doors as well as
    # `!link` ones.
    #
    # So hand it forward: stash it against the destination, and spawn_for
    # prefers it for exactly that area. A goto with no position of its own
    # CLEARS the stash, so `!goto 91` still means "the spawn point".
    # KEY: WHICH DOOR YOU CAME OUT OF, recorded HERE and nowhere earlier: this
    # is where the move is committed. A door that is looked up and then
    # refused by the latch never reaches this line, so it is never reported
    # as "the door you just came through". The panel pre-selects it, which
    # turns fixing a bad landing into: walk through, walk to where you should
    # have appeared, press one button.
    if pos is not None:
        _SESSION["arrived_via"] = int(via) if via is not None else None
    else:
        _SESSION.pop("arrived_via", None)
    if pos is not None and area != _SESSION.get("field"):
        _SESSION["arrive_at"] = (int(area), (sx, sy, sz))
        # and the way to face on arrival: SE ships one per portal, pointing
        # away from the door -- we used to arrive every player facing north
        # whatever the door, which at a south-facing gate means staring back
        # into the doorway you just came out of
        if face is not None:
            _SESSION["arrive_face"] = (int(area), (face[0], face[1]))
        else:
            _SESSION.pop("arrive_face", None)
        # KEY: THE RE-ENTRY LATCH. SE's own arrival points sit a few units from
        # the doorway they belong to -- portal 12's is 5.7 units from its gate
        # -- and our match radius is the door's own plus --door-radius, so the
        # spot you arrive at is INSIDE the trigger. Land badly once and the
        # first step re-fires the door, which is a trap the player cannot walk
        # out of. Latch it: this door does not fire again until the player has
        # left its radius. Cleared in door_latch_ok below.
        _SESSION["door_latch"] = (int(area), sx, sz)
    elif pos is None:
        _SESSION.pop("arrive_at", None)
        _SESSION.pop("arrive_face", None)
    body = struct.pack(">IIfff", area & 0xFFFFFFFF, 0xFFFFFFFF, sx, sy, sz)
    send(conn, outbound, inner_msg(0x1166, body, unit_id_of(args)),
         mode, be, args.seq_mode == "echo", args.world_prefix)
    what = ("room %d (%s)" % (area - ROOM_AREA_BASE, room_label(area - ROOM_AREA_BASE))
            if ROOM_AREA_BASE <= area < ROOM_AREA_BASE + 0x100 else "field/group %d" % area)
    print("[feworld] -> 0x30 inner 0x1166 MSG_GOTO_SEARCH_OK A=0x%X (%s) B=-1 "
          "pos=(%g,%g,%g) -- A != the current field, so the arm 0x050561b7 "
          "stores it and sets 0x5345ea0=1: expect 0x20A6 MSG_MOVE_REQUEST "
          "(answered 0x1168), then 0x2000 area=0x%X"
          % (area, what, sx, sy, sz, area), flush=True)


def npc_walk_push(conn, outbound, mode, be, args, client_body):
    """Walk the NPC with `0x2023` action 0 -- the message the PLAYER cannot use.

    2026-08-25. Action 0's arm (0x04fea890) resolves the target and takes the
    speed-writing block only for kind 2 (0x04fea923), which is why three
    iterations of aiming it at the player -- kind 1 -- were discarded unread.
    A served avatar is stamped kind 2 by its own ctor (0x05067a32), so this is
    the first legitimate target that message has ever had here.

    THE TICK PAIR IS THE CLIENT'S OWN, NOT INVENTED. The two u32 after the
    action code are handed to 0x515ba10 -> 0x515b870 alongside the position,
    and their timebase is unmeasured. Rather than guess one, this reuses the
    pair off the client's most recent 28-byte 0x2023 heartbeat, so the record
    sits in whatever clock the client is already using. That is why this is
    driven from the inbound frame instead of a timer.

    \u26a0 THE POSITION IS DEAD-RECKONED SERVER-SIDE. We advance our own idea of
    where the NPC is by --npc-walk's step each push. The client is never asked
    where it thinks he is, so this WILL drift from what is drawn if the client
    interpolates differently. It is a probe for "does he move", not a
    simulation. i16 at x10 caps the world at +-3276.7 units.

    \u26a0 state is forced to 1: zero makes 0x04feadd8 skip the controller
    entirely, and then only the speed pair would be written.
    """
    if not args.npc_walk or not args.npc:
        return
    if len(client_body) != _MV_LEN:
        return
    speed, step = args.npc_walk
    for k, spec in enumerate(args.npc):
        obj = args.npc_base + k
        f = spec.split(":")
        try:
            home = tuple(float(v) for v in f[1:4]) if len(f) >= 4 else (0.0, 0.0, 0.0)
        except ValueError:
            return
        # flat per-object key: _SessionProxy forwards only
        # get/pop/__setitem__/__contains__, so a nested dict pulled back
        # through get() is not guaranteed to be the live object to mutate.
        key = "npc_z_%d" % obj
        x, y = home[0], home[1]
        z = _SESSION.get(key, home[2]) + step
        if abs(z) > 3000.0:            # stay inside the i16 the client reads
            z = home[2]
        _SESSION[key] = z
        out = bytearray(_MV_LEN)
        struct.pack_into(">I", out, _MV_ACTION, 0)
        # the client's OWN tick pair, lifted verbatim
        out[_MV_A:_MV_A + 8] = client_body[_MV_A:_MV_A + 8]
        # WARNING: STATE 0, NOT 1 -- RETRACTION, measured 2026-08-25.
        # I read the `je` at 0x04feadd8 as "zero SKIPS the controller" and
        # forced 1. Backwards. The two branches are:
        #   state != 0 -> 0x515ba10, which requires [ctrl+0x8c] to be 0 or
        #                 1 and RETURNS otherwise
        #   state == 0 -> 0x04feae15 calls 0x515b870 DIRECTLY -- the same
        #                 mover, NO mode check, and it passes the tail u32
        #                 where 0x515ba10 passes 0
        # `felive --npc Bob` measured [ctrl+0x8c] = 4, which is what the
        # controller's own initialiser stamps at birth (0x0515b535). A
        # fresh avatar is therefore ALWAYS in a mode 0x515ba10 rejects, and
        # state 1 could never have moved him. State 0 -- what the client's
        # own heartbeat sends -- is the path that works.
        # KEY: The speed pair landed either way (felive read 1.0): 0x04feadcc
        # writes it BEFORE the branch. Which is exactly why the probe prints
        # the controller mode too -- "the record arrived" and "the record
        # did something" are different claims.
        struct.pack_into(">H", out, _MV_STATE, 0)
        struct.pack_into(">hh", out, _MV_SPD, _i16(speed * 1000.0), 0)
        struct.pack_into(">hhh", out, _MV_POS,
                         _i16(x * 10.0), _i16(y * 10.0), _i16(z * 10.0))
        send(conn, outbound, inner_msg(0x2023, bytes(out), obj), mode, be,
             args.seq_mode == "echo", args.world_prefix)
        n = _SESSION.get("npc_walk_n", 0) + 1
        _SESSION["npc_walk_n"] = n
        if n <= 3 or n % 40 == 0:
            print("[feworld]    -> 0x2023 action 0 NPC id=%d #%d speed=%g "
                  "target=(%.1f, %.1f, %.1f) -- kind 2, so this arm ACCEPTS it. "
                  "Watch the NPC, not felive (felive reads YOUR unit)."
                  % (obj, n, speed, x, y, z), flush=True)


def _stat_num(x):
    """--add-stats value: an int (any base) or, for the f32 rows, a float."""
    x = x.strip()
    if x.lower().startswith("0x"):
        return int(x, 16)
    return float(x) if ("." in x or "e" in x.lower()) else int(x, 0)


# 0x2024 maskA bits whose destination is CONFIRMED, that read live as ZERO, and
# that nothing else writes -- so a value appearing on screen can only be ours.
# (bit, offset, struct code, sentinel). Ascending bit order IS the wire order.
#
# DELIBERATELY EXCLUDED, and each for its own reason:
#   0x1     +0x498  Skill Points -- another worker's --add-stats owns it
#   0x2/0x8/0x10    HP and Pw -- already carry 200/200 and 100/100, so they
#                   have a writer; a second one would silently drift
#   0x4             not a setter at all: it drives the damage-number colour
#                   palette at 0x5336b60
#   0x20000 +0x4d4  OUR WALK SPEED, live at 1.0. Overwriting it would break
#                   movement mid-probe and confuse the result.
#   0x100000, 0x400000, 0x800000, 0x1000000, 0x2000000, 0x8000000 -- their
#                   destinations did NOT fall out of the scan, so I cannot say
#                   the analyser tracked every read they make. A missed read is
#                   a desync of everything after it, not a wrong number.
#
# KEY: 2026-08-27: fe2024.py's ladder() never saw the eight `test ah,N` arms,
# so maskA bits 0x100..0x8000 (+0x4b0..+0x4ca, all i16 via 0x5045ec0) were
# absent from its table and read as "no such bit". They are in now, with the
# next sentinels, 4011..4017 -- EXCEPT bit 0x800: its setter 0x04ff41b0 is
# not a store, it is the KNOCKBACK EVENT (gates [+0x20]==3 AND [+0x24]==1,
# writes +0x4bc, and if the value >= [+0x4b8]+[+0x4ba] launches a 2500 ms
# flight with anims 0x57/0x58). A sentinel there throws the player.
_U2024_PROBE = [
    (0x00000020, 0x4A6, "H", 4001),
    (0x00000040, 0x4AA, "H", 4002),
    (0x00000080, 0x4AC, "H", 4003),
    (0x00000100, 0x4B0, "H", 4011),
    (0x00000200, 0x4B4, "H", 4012),
    (0x00000400, 0x4B8, "H", 4013),
    (0x00001000, 0x4BE, "H", 4014),
    (0x00002000, 0x4C2, "H", 4015),
    (0x00004000, 0x4C6, "H", 4016),
    (0x00008000, 0x4CA, "H", 4017),
    (0x00010000, 0x4CE, "H", 4004),
    (0x00040000, 0x4DC, "f", 4005.0),
    (0x00080000, 0x4E4, "f", 4006.0),
    (0x00200000, 0x4EC, "I", 4007),
    (0x04000000, 0x4F0, "I", 4008),
    (0x20000000, 0x4FC, "H", 4009),
    (0x40000000, 0x4FE, "H", 4010),
]


def stat_probe_push(conn, outbound, mode, be, args):
    """Name the unnamed half of the 0x2024 stat block with DISTINCT SENTINELS.

    2026-08-25. `felive --avatar` read the whole block before anything was
    served, and it sorted three ways: HP and Pw already carry correct values
    (so they have a writer), Skill Points has another channel, and TEN fields
    are zero AND unnamed. Serving plausible numbers into those would be
    an earlier note exactly -- every screen still renders
    and nothing is learned.

    So each gets an IMPOSSIBLE, DISTINCT value, 4001..4010, and one look at the
    Status screen and the gauges names them all at once. It is the same trick
    that settled `0x303E` in a single screenshot: nine sentinels made "the
    message did nothing" readable, where nine plausible numbers would have
    rendered a believable screen full of our own data and taught us nothing.

    The last digit identifies the field, so a number on screen maps straight
    back: 4001 = +0x4a6, 4005 = +0x4dc, 4010 = +0x4fe.

    WARNING: THIS PUTS DELIBERATELY WRONG NUMBERS ON SCREEN. It is off by default and
    is not something to leave running.

    WARNING: ASCENDING BIT ORDER IS THE WIRE ORDER -- 0x04ff36c0 tests bit 0 first and
    each setter reads as it goes, so the fields must be laid down in that
    order. A bit set with nothing behind it desynchronises the rest.
    """
    if args.stat_probe == "off":
        return
    maskA = 0
    body = b""
    for bit, _off, code, val in _U2024_PROBE:
        maskA |= bit
        body += struct.pack(">" + code, val)
    out = struct.pack(">II", maskA, 0) + body
    send(conn, outbound, inner_msg(0x2024, out, unit_id_of(args)), mode, be,
         args.seq_mode == "echo", args.world_prefix)
    print("[feworld]    -> 0x2024 STAT PROBE maskA=0x%08X, %d fields, %d bytes. "
          "Sentinels 4001..4010; the LAST DIGIT names the field: %s"
          % (maskA, len(_U2024_PROBE), len(out),
             ", ".join("%d=+0x%x" % (v if isinstance(v, int) else int(v), o)
                       for _b, o, _c, v in _U2024_PROBE)), flush=True)
    print("[feworld]       open the Status screen AND look at the gauges. A "
          "4001..4010 anywhere on screen names that offset. Nothing anywhere "
          "means these fields are not drawn, which is also an answer.",
          flush=True)


# 0x2025 (arm 0x0503a6d1 -> 0x04ff39a0) is the SECOND COLUMN of the same
# stat block: ONE u32 mask (no maskB), and every setter is the 0x2024 one
# called with index 1, so it writes [unit + base + 2] (i16) or [+4] (f32).
# Mapped 2026-08-27 by the stat-block bit sweep:
#     bit 0x2 -> +0x49c  HP bonus (drawn: HP max = +0x49a + THIS)
#     bit 0x4 -> +0x4a2  Pw bonus          0x8 -> +0x4a8
#     bit 0x10 -> +0x4ae 攻撃力 2nd term  (Status: +0x4ac + +0x4ae + +0x514 + +0x516)
#     bit 0x20 -> +0x4b2 equip-gate-2 2nd term   0x40 -> +0x4b6
#     bit 0x80 -> +0x4ba knockback-threshold 2nd term
#     0x100/0x200/0x400/0x800/0x1000 -> +0x4c0/+0x4c4/+0x4c8/+0x4cc/+0x4d0
#     0x2000 -> +0x4d8 (f32, the controller's OWN speed slot -- excluded)
#     0x4000 -> +0x4e0 / 0x8000 -> +0x4e8 (jump physics 2nd terms -- excluded)
#     0x10000 -> +0x508 / 0x20000 -> +0x510 (f32 -- excluded)
# Sentinels 5001..5012, last two digits name the field; HP/Pw bonuses are
# INCLUDED on purpose -- the gauge draws max = base + bonus, so "HP 200/5201"
# is the readable proof that +0x49c is the bonus column.
_U2025_PROBE = [
    (0x00000002, 0x49C, "h", 5001),
    (0x00000004, 0x4A2, "h", 5002),
    (0x00000008, 0x4A8, "h", 5003),
    (0x00000010, 0x4AE, "h", 5004),
    (0x00000020, 0x4B2, "h", 5005),
    (0x00000040, 0x4B6, "h", 5006),
    (0x00000080, 0x4BA, "h", 5007),
    (0x00000100, 0x4C0, "h", 5008),
    (0x00000200, 0x4C4, "h", 5009),
    (0x00000400, 0x4C8, "h", 5010),
    (0x00000800, 0x4CC, "h", 5011),
    (0x00001000, 0x4D0, "h", 5012),
]


def stat_probe2_push(conn, outbound, mode, be, args):
    """DISTINCT SENTINELS into the 0x2025 second column. Off by default."""
    if args.stat_probe2 == "off":
        return
    mask = 0
    body = b""
    for bit, _off, code, val in _U2025_PROBE:
        mask |= bit
        body += struct.pack(">" + code, val)
    out = struct.pack(">I", mask) + body
    send(conn, outbound, inner_msg(0x2025, out, unit_id_of(args)), mode, be,
         args.seq_mode == "echo", args.world_prefix)
    print("[feworld]    -> 0x2025 STAT PROBE (2nd column) mask=0x%08X, %d "
          "fields, %d bytes. Sentinels 5001..5012: %s"
          % (mask, len(_U2025_PROBE), len(out),
             ", ".join("%d=+0x%x" % (v, o) for _b, o, _c, v in _U2025_PROBE)),
          flush=True)
    print("[feworld]       expect HP x/5201 and Pw x/5102 on the gauges (max = "
          "base + bonus), 攻撃力 up by 5004 on the Status screen; anything "
          "else on screen names its offset by its last two digits.", flush=True)


# ---------------------------------------------------------------------------
# MOVEMENT: what --unit-speed and --jump-phys ACTUALLY MEAN (static 2026-09-09)
#
# Both knobs are MULTIPLIERS on a shipped per-form table, not raw speeds, and
# the client picks the row from the METAMORPHOSIS form and the AREA:
#
#     speed = ([unit+0x4d8] + [unit+0x4d4]) * row[0]      (0x0515B8EE and
#                                                          0x0515B7E3/0x0515BCFD)
#     dash  = direction * row[2]                          (the horizontal)
#     up    = ([unit+0x4e0] + [unit+0x4dc]) * row[3]      (0x0504B640)
#     grav  = ([unit+0x4e8] + [unit+0x4e4]) * 24.5        (0x0504B680, whose
#                                                          non-player fallback
#                                                          IS 24.5 -- so 1.0 is
#                                                          the engine's own g)
#
# THE ROW is `0x5158E40`: for a class-3 object it is ([unit+0x3b4] & 0x3f) - 1
# through the byte map at 0x5159060; f28 = 0 (no metamorphosis, our case) falls
# out of range and takes the default arm, which asks 0x04FF7EF0 -- and that
# predicate is literally "am I in a capital": it indexes [world+0x4ec] - 21 and
# returns true for exactly 21, 39, 57, 62, 78, 91..95. CAPITAL_GROUP_IDS,
# arrived at from a third direction.
#
# WARNING: THE TABLE IS A GATHER, NOT A BLOCK COPY. 0x5158E40 lazily builds the
# runtime rows at 0x5349460 out of SCATTERED source dwords near 0x5297460 --
# dest +0x08 comes from source +0x10, and so on. Reading the source as four
# contiguous floats per row (the obvious thing) yields a table that is wrong in
# every row but the first, which is how "row[0xc] = 4.7" got written down.
# 4.7 is column [2], the horizontal dash. Column [3] is the launch.
_MOVE_ROWS = {           # row: (speed base, col1, dash, jump launch)
    0: (4.0, 4.0, 4.7, 16.5),     # war field, no metamorphosis
    1: (2.0, 6.0, 4.7, 9.9),
    2: (10.0, 10.0, 4.7, 13.2),
    3: (4.0, 9.5, 4.7, 16.5),
    4: (9.5, 8.5, 10.0, 21.45),
    5: (4.0, 4.0, 4.7, 11.55),
    6: (6.0, 6.0, 4.7, 16.5),     # CAPITAL, no metamorphosis
}


def move_row(args, area=None):
    """(row index, speed base, dash, jump launch) for where the player is.

    Only the f28 = 0 case, which is ours: we never serve a metamorphosis form
    (see _AVATAR_SUB's f28 note -- it swaps the player's model). Rows 1..5 are
    listed for completeness and are what a transformed character would get.
    """
    if area is None:
        area = _SESSION.get("field")
    row = 6 if area in CAPITAL_GROUP_IDS else 0
    speed, _c1, dash, jump = _MOVE_ROWS[row]
    return row, speed, dash, jump


# VERIFIED KEY: THE 3x MEASURED LIVE IS 16.5 / 4.7 = 3.51.
#
# This block used to model the launch as `x4.7` and predict a 0.58 s flight for
# 1.5:1.0. LIVE 2026-09-08 run 4 measured SmartJumpMessage N ~2700 -- a ~2 s
# flight -- and the note written then said "the launch term in this model is
# low by ~3x". It was: the launch multiplier is row[3] = 16.5, and 4.7 is
# row[2], the HORIZONTAL dash, taken from a mis-assembled table.
#
#     1.5:1.0 -> launch 1.5*16.5 = 24.75 u/s, g 1.0*24.5 = 24.5 u/s^2
#             -> flight 2*24.75/24.5 = 2.02 s -> N = 700 + 2020 = 2720 ms
#
# against a measured ~2700. A static fix that lands within 1% of a number
# somebody already wrote down is worth more than the fix itself: it says the
# whole model (launch, gravity, the 300+400 ms immediates) is right and only
# the constant was wrong.
#
# The local jump handler 0x05152670 (single caller 0x051512ee) builds the dash:
#   horizontal = key direction (normalised, 0x04fd0d60) * row[2]
#   vertical   = 0x0504b640(unit, row[3]) = ([+0x4e0]+[+0x4dc]) * row[3]
#   gravity    = 0x0504b680(unit)         = ([+0x4e8]+[+0x4e4]) * 24.5
# then 0x05065240 flies that ballistic path in 0.1 s steps against the
# collision mesh and returns the flight time in ms (edi); the SmartJump is
# issued as THREE phases (0x05049730 args): 300 ms wind-up (push 0x12c at
# 0x05152b2c), edi ms of travel, 400 ms landing (push 0x190 at 0x05152b24;
# 0 while the key-state byte has bits 0/1), so the logged N = 300 + edi + 400
# and NO server field scales those two.
_U2024_JUMP_V_BIT = 0x00040000
_U2024_JUMP_G_BIT = 0x00080000
_JUMP_GRAVITY_BASE = 24.5        # 0x0504B680's own non-player fallback


def jump_flight_ms(args, v, g, area=None):
    """Predicted SmartJumpMessage N for a launch/gravity pair, in ms."""
    _row, _speed, _dash, jump = move_row(args, area)
    if g <= 0:
        return None
    return int(round((2.0 * v * jump / (g * _JUMP_GRAVITY_BASE)) * 1000)) + 700


def jump_phys_push(conn, outbound, mode, be, args):
    if args.jump_phys is None:
        return
    v, g = args.jump_phys
    body = struct.pack(">IIff", _U2024_JUMP_V_BIT | _U2024_JUMP_G_BIT, 0, v, g)
    send(conn, outbound, inner_msg(0x2024, body, unit_id_of(args)), mode, be,
         args.seq_mode == "echo", args.world_prefix)
    row, _speed, _dash, jump = move_row(args)
    n = jump_flight_ms(args, v, g)
    print("[feworld]    -> 0x2024 JUMP PHYSICS +0x4dc=%g (x%g = %.2f u/s up) "
          "+0x4e4=%g (x%g = %.1f u/s^2), movement row %d (%s). Read the "
          "client's own 'SmartJumpMessage [..]->[..] N' lines: predicted "
          "N = %s ms including the 300+400 ms immediates."
          % (v, jump, v * jump, g, _JUMP_GRAVITY_BASE, g * _JUMP_GRAVITY_BASE,
             row, "capital" if row == 6 else "war field",
             n if n is not None else "-"), flush=True)


# 0x2024 maskA bits for the two stat-block fields the Status screen actually
# DRAWS, named live 2026-08-25 by distinct sentinels and confirmed against the
# client's own label table at 0x052e29d8 / 0x052e29e8:
#     bit 0x00200000 -> +0x4ec  GOLD  (u32; the label's format is "%lu")
#     bit 0x04000000 -> +0x4f0  RING  (u32)
_U2024_GOLD = (0x00200000, 0x4EC)
_U2024_RING = (0x04000000, 0x4F0)
# maskB bit 0x1 -> +0x500 TOTAL SCORE (u32). Found late, because
# fe2024.py's destination filter only matched 0x3xx/0x4xx/0x9xx and
# reported this row as writing nothing -- a gap that read as a finding.
# The Status window draws it at 0x050e13ca against the label at
# 0x052e29a8, one row above Skill Points.
_U2024_SCORE = (0x00000001, 0x500)      # <- maskB, not maskA


def crystal_push(conn, outbound, mode, be, args, value=None):
    """CRYSTAL -- `0x2035`, mask bit 1, one u32 into [unit+0x8ac].

    2026-08-26, and it closes the row the 08-25 sentinel probe could not:
    CRYSTAL sits between Skill Points and GOLD on the Status screen, took no
    sentinel, and was written down as "probably one of the six ladder bits
    whose destination did not fall out of the scan". It is not a 0x2024 bit at
    all -- **it is not even in the +0x4xx block the probe covered.**

    FOUND DRAW-SITE-BACKWARDS, the move that found 0x1075 and the chat ids.
    The Status screen draws its fields from a table of {label, x, y, fmt} rows
    at 0x052e28e8 -- 'Lv', 'HP', 'Pw', 'Exp', 'Total Score', 'Skill Points',
    'CRYSTAL', 'GOLD', 'RING' -- one straight-line block per row, and CRYSTAL's
    pushes its fmt from 0x052e29d4:

        050e142e  mov eax, [esi + 0x8ac]     <- the value
        050e1434  mov ecx, [0x52e29d4]       <- 'CRYSTAL' fmt '%d'

    so CRYSTAL is `[unit+0x8ac]`, a u32. Its only writer outside the ctor
    (0x0507abb6 zero-inits it beside +0x8a8) is reached from message **0x2035**
    (c0 arm 0x0503a71f -> 0x04fe4de0), and that handler is mask-driven like
    everything else here:

        04fe4ded  0x5045e60(&mask)          u32
        04fe4dfa  test al, 1     -> 0x4fe4e20: u32 -> [obj+0x8a8]
        04fe4e08  test al, 2     -> 0x4fe4e50: u32 -> [obj+0x8ac]  CRYSTAL

    KEY: THE TARGET IS THE HEADER'S UNIT ID, and that took reading the c0
    dispatcher's own frame rather than trusting a slot number. 0x05039fa0 is
    called with (unit_id, msg_id, stream): before its `push edi` it reads the
    msg id at [esp+0x1c], and after it the arms push [esp+0x24] (stream) then
    [esp+0x1c] (unit id). Both sub-setters then resolve the object by that id
    (0x504cb30 / 0x504d3a0, kind 3 -- the same lookup the avatar path uses), so
    this must carry the same unit id as everything else we send.

    WARNING: IT IS NOT A BALANCE. 0x04fe4e9a compares the incoming value against the
    stored one and plays the E25_GetCrystal pickup effect when it INCREASED, so
    the client treats this as an authoritative total, not a delta -- and
    nothing here debits it. Do not build the summon economy on it:
    an earlier note is what that costs.

    WARNING: BIT 0 (+0x8a8) IS LEFT ALONE. It is unnamed, zeroed beside CRYSTAL by the
    same ctor, and drawn by no screen we have opened. Serving an invented value
    into an unnamed field is an earlier note exactly.
    """
    # `value` is an explicit one-off (the `!crystal N` probe) and is NOT
    # persisted; otherwise the per-character stored value, seeded from the
    # flag the first time -- see _seeded_value.
    if value is None:
        value = _seeded_value(args, "crystal", getattr(args, "crystal", None))
    if value is None:
        return
    body = struct.pack(">II", 0x2, value & 0xFFFFFFFF)
    send(conn, outbound, inner_msg(0x2035, body, unit_id_of(args)), mode, be,
         args.seq_mode == "echo", args.world_prefix)
    print("[feworld]    -> 0x2035 CRYSTAL %d -> [unit+0x8ac] (mask bit 1). The "
          "Status screen draws it at 0x050e142e with '%%d'. WARNING: per-character "
          "and stored, but nothing debits it yet." % value, flush=True)


def wallet_push(conn, outbound, mode, be, args):
    """GOLD and RING, via `0x2024` -- the two stat-block fields that DRAW.

    2026-08-25. The sentinel probe put impossible values in the ten unnamed
    stat-block fields; exactly two reached the screen. The live screen read 4007
    against GOLD and 4008 against RING, and the client's own layout table
    confirms it independently:

        0x052e29d8  'GOLD'  fmt '%lu'      <- sentinel 4007 = +0x4ec
        0x052e29e8  'RING'  fmt '%d'       <- sentinel 4008 = +0x4f0

    Two sources agreeing -- what rendered, and what the table says renders
    there -- is why these are named rather than guessed. The other EIGHT
    sentinels appeared nowhere, which is its own result: those fields are not
    drawn, and nobody should spend a session serving them.

    \u26a0 UNSET SENDS NOTHING. A zero here is a real value -- it would show the
    player as broke -- so "no flag" and "zero gold" have to be different
    things. This is the an earlier note shape: a wallet that reads
    zero because nobody served it looks exactly like a wallet that is empty.

    \u26a0 NOT PERSISTED. This serves whatever the flag says on every field
    entry; it is not a balance, and nothing debits it. Do not build buying or
    selling on it until there is a store behind it -- see
    an earlier note for how that goes wrong.

    \u26a0 CRYSTAL sits between Skill Points and GOLD in the same table
    (0x052e29c8) and NONE of the sentinels landed on it, so its offset is not
    in the ten probed. It is probably one of the six ladder bits whose
    destination did not fall out of the static scan. Unfinished, not absent.
    """
    # Each row is the CHARACTER's stored value, seeded from the flag the first
    # time it is served -- see _seeded_value. An unset flag still sends
    # nothing for that row.
    fields = []
    gold = _seeded_value(args, "gold", args.gold)
    if gold is not None:
        fields.append((_U2024_GOLD[0], _U2024_GOLD[1], "GOLD", gold))
    ring = _seeded_value(args, "ring", args.ring)
    if ring is not None:
        fields.append((_U2024_RING[0], _U2024_RING[1], "RING", ring))
    scoreb = []
    score = _seeded_value(args, "total_score", args.total_score)
    if score is not None:
        scoreb.append((_U2024_SCORE[0], _U2024_SCORE[1], "SCORE", score))
    if not fields and not scoreb:
        return
    # WARNING: ASCENDING BIT ORDER IS THE WIRE ORDER, and maskA's fields come
    # BEFORE maskB's -- 0x04ff36c0 walks maskA's ladder to the end and
    # only then tests maskB. Sorting the two lists together would put a
    # maskB bit 0x1 field first and desynchronise everything after it.
    fields.sort()
    maskA = 0
    maskB = 0
    body = b""
    for bit, _off, _name, val in fields:
        maskA |= bit
        body += struct.pack(">I", val & 0xFFFFFFFF)
    for bit, _off, _name, val in scoreb:
        maskB |= bit
        body += struct.pack(">I", val & 0xFFFFFFFF)
    fields = fields + scoreb
    send(conn, outbound, inner_msg(0x2024,
                                   struct.pack(">II", maskA, maskB) + body,
                                   unit_id_of(args)),
         mode, be, args.seq_mode == "echo", args.world_prefix)
    print("[feworld]    -> 0x2024 wallet maskA=0x%08X maskB=0x%08X  %s  -- "
          "Status screen fields, each named from the window's own draw "
          "code at 0x050e13ca.."
          % (maskA, maskB, ", ".join("%s=%d (+0x%x)" % (n, v, o)
                                     for _b, o, n, v in fields)), flush=True)


# ---------------------------------------------------------------------------
# THE WALLET AS A LEDGER -- 2026-09-11, the day something first SPENDS it.
#
# GOLD and RING were per-character stored numbers (festore columns `gold` and
# `ring`, seeded once from --gold / --ring by _seeded_value) that nothing but
# the enchant cost and mail attachments ever moved. The shops, the inn and the
# bank now charge and credit them, and every one of those goes through the
# four helpers below so the rule is written once:
#
#   * the STORE is the balance and the 0x2024 push is only a view of it --
#     write first, then push;
#   * an UNSET flag means that currency's channel is OFF (not "broke"): a cost
#     in it is waived and logged, a credit in it is dropped and logged. Same
#     contract as feitems._debit, which predates these.
#
# KEY: RINGS: the war worker AWARDS them and this file SPENDS them (the Ring
# Shop). Both sides use rings_get / rings_add; the balance is festore's `ring`
# column, the same one wallet_push has served since 2026-09-04.
def gold_get(args):
    """The character's GOLD, or None when no gold wallet is served."""
    return _seeded_value(args, "gold", getattr(args, "gold", None))


def rings_get(args):
    """The character's RINGS, or None when no ring wallet is served."""
    return _seeded_value(args, "ring", getattr(args, "ring", None))


def rings_set(args, n):
    """Store the character's RINGS (clamped at 0). No push -- see wallet_push."""
    return _store_char_field(args, "ring", max(0, int(n)))


def rings_add(args, n):
    """Add `n` RINGS (negative spends) to the stored balance; returns the new
    balance, or None when nothing was stored. With --ring unset the stored
    column is still written (a war award must not vanish because the display
    channel is off) -- it is served the moment the flag is set."""
    have = rings_get(args)
    if have is None:
        try:
            have = int(_load_char_field(args, "ring", 0) or 0)
        except (TypeError, ValueError):
            have = 0
    new = max(0, int(have) + int(n))
    return new if rings_set(args, new) else None


def wallet_short(args, gold=0, rings=0):
    """None when the character can pay `gold` and `rings`, else the currency
    that is short ("gold" / "rings"). A currency whose channel is off (flag
    unset) never runs short -- see the block comment. Writes nothing."""
    gold, rings = max(0, int(gold or 0)), max(0, int(rings or 0))
    g = gold_get(args) if gold else None
    if gold and g is not None and int(g) < gold:
        return "gold"
    r = rings_get(args) if rings else None
    if rings and r is not None and int(r) < rings:
        return "rings"
    return None


def wallet_charge(conn, outbound, mode, be, args, gold=0, rings=0, why=""):
    """Spend `gold` and `rings` together, or neither. Returns (ok, short) where
    `short` names the currency that ran out ("gold" / "rings") on a refusal.

    Checks BOTH balances before writing EITHER, so a purchase priced in both
    can never take the gold and then fail on the rings."""
    gold, rings = max(0, int(gold or 0)), max(0, int(rings or 0))
    short = wallet_short(args, gold, rings)
    if short:
        return False, short
    g = gold_get(args) if gold else None
    r = rings_get(args) if rings else None
    waived = []
    if gold and g is None:
        waived.append("%d gold (--gold unset: no gold wallet)" % gold)
    if rings and r is None:
        waived.append("%d rings (--ring unset: no ring wallet)" % rings)
    wrote = []
    if gold and g is not None and _store_char_field(args, "gold", int(g) - gold):
        wrote.append("gold %d -> %d" % (int(g), int(g) - gold))
    if rings and r is not None and rings_set(args, int(r) - rings):
        wrote.append("rings %d -> %d" % (int(r), int(r) - rings))
    if wrote:
        wallet_push(conn, outbound, mode, be, args)
    if wrote or waived:
        print("[feworld]    wallet %s: %s%s" % (why, "; ".join(wrote) or "nothing",
                                               ("  WAIVED " + "; ".join(waived))
                                               if waived else ""), flush=True)
    return True, None


def wallet_credit(conn, outbound, mode, be, args, gold=0, rings=0, why=""):
    """Add `gold` / `rings` to the stored balances and push the wallet. The
    client's own GOLD setter (0x04ff47a0) prints "%dGold入手しました。" when
    the value it is handed GREW, so a credit shows the player what they got
    without us sending a word. Returns the gold actually credited."""
    gold, rings = max(0, int(gold or 0)), max(0, int(rings or 0))
    done, g = [], None
    if gold:
        g = gold_get(args)
        if g is None:
            print("[feworld]    wallet %s: %d gold NOT credited -- --gold is "
                  "unset, so no gold wallet is served" % (why, gold), flush=True)
            gold = 0
        elif _store_char_field(args, "gold", int(g) + gold):
            done.append("gold %d -> %d" % (int(g), int(g) + gold))
        else:
            gold = 0
    if rings:
        new = rings_add(args, rings)
        if new is not None:
            done.append("rings -> %d" % new)
    if done:
        wallet_push(conn, outbound, mode, be, args)
        print("[feworld]    wallet %s: %s" % (why, "; ".join(done)), flush=True)
    return gold


# ---- CHAT, THE INBOUND DIRECTION.  2026-08-25.
#
# KEY: THE INBOUND CHAT ID IS THE OUTBOUND ONE. There is no separate reply
# family to find: the ids the client SENDS on /say, /all, /army and /party are
# the same ids its receive dispatcher accepts, and one shared arm draws them.
# The old note in this file ("the numbers are unknown, none of MSG_CHAT_NG's
# family carries an id") was looking for a message that does not exist.
#
# HOW IT WAS FOUND, and it is the DRAW-SITE-BACKWARDS trick again: /say echoes
# locally (0x051334f0) through 0x05077cc0 then 0x05129890, so 0x05129890 is the
# chat LOG sink. It has fifteen callers; eleven are the local /say /all /army
# /tell family, and the rest are dispatcher arms. One of them, 0x05053cbe,
# reads two strings off the wire and prints them.
#
# WARNING: fedisp.py --sweep MIS-RESOLVED THIS ONE. It reported 0x201A -> 0x05053d50,
# an address in the MIDDLE of the arm, because the ladder hangs two ids off one
# compare (`cmp eax,0x201b / jg / cmp eax,0x201a / jge 0x5053cbe`) and the
# emulator took the second branch's target as the arm. The jump TABLES were
# decoded by hand to settle it -- 0x0505418c/0x05054178 for 0x1152..0x117D and
# 0x050541d8/0x050541b8 for 0x2056..0x208A.
#
# THE ARM, 0x05053cbe, in order:
#   1. read cstr -> [esp+0xd5]   the SPEAKER NAME
#   2. read cstr -> [esp+0x54]   the TEXT
#   3. 0x05170e10(name)          THE BLACKLIST -- it walks the list at
#                                [0x535c29c]..[0x535c2a0] comparing strings and
#                                returns 1 on a hit, and a hit DROPS THE LINE
#                                with no log. A blacklisted test name reads
#                                exactly like a broken message.
#   4. 0x05129890(id, name, text, 0, -1)   the chat log window
# The sink's FIRST argument is the message id itself, which is why the five ids
# share one arm and can still render differently -- that argument is what
# 0x05077cc0 computes for a locally-echoed line.
#
# WARNING: THE READER IS AN UNBOUNDED strcpy (0x05045f50 -> 0x0522f5e0) INTO A STACK
# FRAME, and the text slot is 0x81 bytes ([esp+0x54] up to the name at
# [esp+0xd5]). A relay that passes a long line through smashes the receiving
# client's stack. Both strings are clamped here, and any future
# player-to-player relay MUST clamp too -- this is a remote write on every
# client in the field, not a cosmetic limit.
#
# WARNING: THE TEXT IS cp932 ON THE WIRE and FE splits DBCS with IsDBCSLeadByte,
# which answers for the SYSTEM codepage (1252 on this host), so Japanese echoed
# back draws as dot pairs -- an earlier note. ASCII is safe.
_CHAT_IDS = {
    0x201A: ("/say (area)", 2),
    0x201B: ("/all", 2),
    0x2065: ("/army", 2),
    0x2066: ("/army, second form", 2),
    0x208A: ("/party", 2),
    # /tell is a DIFFERENT arm (0x05053e28) and it reads THREE strings, into
    # [esp+0xf6], [esp+0xd5] and [esp+0x54]. It sets the arm's channel slot to
    # 3 where the five above set 2. Which of its three is from/to/text is NOT
    # measured -- serve it with distinct sentinels and read the screen.
    0x2067: ("/tell (3 strings, UNMEASURED order)", 3),
}
_CHAT_NAME_MAX = 0x20       # the unit's own name field is [unit+0x389..0x3ac]
_CHAT_TEXT_MAX = 0x80       # the client's stack slot is 0x81 including the NUL


def chat_body(parts):
    """`[cstr][cstr]...` -- NUL-terminated, no length prefix, no terminator run.

    Matched to the client's own outbound capture byte for byte:

        20 1a | "Lex\\0" | 82 b1 82 f1 82 c9 82 bf 82 cd 00
          id     speaker   cp932  こ ん に ち は

    The first string is the one the blacklist is tested against, so it is the
    SPEAKER; the second is the text.
    """
    out = b""
    for i, p in enumerate(parts):
        raw = p.encode("cp932", "replace")
        cap = _CHAT_NAME_MAX if i == 0 else _CHAT_TEXT_MAX
        if len(raw) > cap:
            print("[feworld]    WARNING: chat field %d clamped %d -> %d bytes: the "
                  "client copies it with strcpy into a fixed stack slot"
                  % (i, len(raw), cap), flush=True)
            raw = raw[:cap]
        out += raw + b"\x00"
    return out


def chat_send(conn, outbound, mode, be, args, mid, parts, speaker=None):
    """Push one chat line as message `mid`.

    WARNING: 2026-08-26 -- **THE HEADER u32 IS THE SPEAKER'S UNIT ID, AND SENDING OUR
    OWN THREW EVERY LINE AWAY.** Chat was reported dead on its first
    live run; the arm says why, and the record decoded perfectly the whole time.
    Both display paths in 0x05053cbe are gated on that u32 (`ebx`, read at
    0x05053cbe from the dispatcher's arg1):

        05053d7e  call 0x507d570        ; the LOCAL player unit
        05053d85  call 0x5077cc0        ; -> [unit+0x3c], its unit id
        05053d8a  cmp eax, ebx
        05053d8c  je  0x5053d9e         ; speaker == me -> NO bubble
        05053d8e  [0x534ae88]->vt[0x2c](text)

        05053dab  push 1 / push ebx
        05053dae  call 0x504cb30        ; the object list [0x5339cc4]
        05053db5  call 0x504d410        ; find [obj+0x3c]==ebx AND [obj+0x24]==1
        05053dba  test eax, eax
        05053dbc  jne 0x5053dd7         ; FOUND -> NO chat-log line either
        05053dcf  call 0x5129890        ; the chat log sink

    We sent `unit_id_of(args)`, and prod runs `--unit-id 1`, so the u32 was the
    player's own id: the first test took the `je` (no bubble) and the second
    FOUND the player -- id 1, kind 1 -- and took the `jne` (no log line).
    **Every sentinel was parsed and discarded.** Nothing about the six ids,
    the two arms or the string layout is retracted by this.

    KEY: `0x504d410` matches on BOTH `[obj+0x3c]` (id) and `[obj+0x24]` (kind,
    and it passes **1**, which is the kind the player reads) -- the same pair of
    fields the 0x2023 movement family gates on. an earlier note: CHECK THE
    GATE BEFORE THE PAYLOAD.

    So the speaker id must NOT resolve to a live kind-1 unit if the line is to
    reach the chat log, which is what a served/relayed line wants. 0 is the
    client's own "no unit" sentinel and no object carries it -- hence the
    default. `--chat-unit-id` exists for the deliberate opposite: give a real
    unit's id and the text should appear over THAT unit instead, which is the
    experiment that proves the reading.
    """
    name, want = _CHAT_IDS.get(mid, ("NOT A KNOWN CHAT ID", None))
    if want is not None and len(parts) != want:
        print("[feworld]    WARNING: 0x%04X (%s) reads %d strings, %d given -- a "
              "short record leaves the reader on the next message's bytes"
              % (mid, name, want, len(parts)), flush=True)
    # getattr, not args.chat_unit_id: fe_ui_test builds a SimpleNamespace and
    # the suite is meant to run without knowing every flag.
    # An EXPLICIT speaker is the caller meaning it -- --chat-echo self passes
    # the player's own id on purpose ("the speaker IS this player"), so the
    # warning below must not fire on it. It used to, and it claimed a
    # working line would be discarded while the line visibly appeared.
    speaker_from_flag = speaker is None
    if speaker is None:
        speaker = getattr(args, "chat_unit_id", 0)
    if speaker_from_flag and speaker and speaker == unit_id_of(args):
        print("[feworld]    WARNING: --chat-unit-id %d is the player's own unit id. "
              "0x05053cbe suppresses the speech BALLOON when the speaker is you "
              "(0x05053d8a) -- the chat LOG still shows the line, because it is "
              "an unconditional broadcast at 0x05053da3 gated only by the "
              "blacklist. Use 0 if you want the bubble too." % speaker,
              flush=True)
    send(conn, outbound, inner_msg(mid, chat_body(parts), speaker),
         mode, be, args.seq_mode == "echo", args.world_prefix)
    print("[feworld]    -> 0x%04X CHAT %s %s -- arm %s, speaker unit id %d "
          "(%s)"
          % (mid, name, " | ".join(repr(p) for p in parts),
             "0x05053cbe" if mid != 0x2067 else "0x05053e28", speaker,
             "no such unit -> the CHAT LOG path" if not speaker
             else "resolves? -> bubble if it is a live kind-1 unit"), flush=True)


def parse_chat_line(spec):
    """`ID|NAME|TEXT` (or `ID|A|B|TEXT` for 0x2067) -> (id, [parts]) or None."""
    fields = spec.split("|")
    if len(fields) < 3:
        print("[feworld]    WARNING: --chat-line %r needs ID|NAME|TEXT" % spec,
              flush=True)
        return None
    try:
        mid = int(fields[0], 0) & 0xFFFF
    except ValueError:
        print("[feworld]    WARNING: --chat-line %r: %r is not an id"
              % (spec, fields[0]), flush=True)
        return None
    if mid not in _CHAT_IDS:
        print("[feworld]    WARNING: --chat-line id 0x%04X is not one of the six the "
              "client's dispatcher routes to a chat arm (%s) -- sending it "
              "anyway, but the arm that receives it is unknown"
              % (mid, ", ".join("0x%04X" % k for k in sorted(_CHAT_IDS))),
              flush=True)
    return mid, fields[1:]


def chat_push(conn, outbound, mode, be, args):
    """Serve every --chat-line once, at field entry.

    WARNING: ONE-SHOT, like npc_push: this fires inside the add-complete block, so a
    line served here lands as the field comes up. Use `!chat ID|NAME|TEXT` in
    --gmcmd-file to fire one at a moment of your choosing instead -- that is
    the lever that lets all six ids be compared on ONE screen in ONE session
    rather than one redeploy per id.
    """
    for spec in getattr(args, "chat_line", None) or []:
        got = parse_chat_line(spec)
        if got:
            chat_send(conn, outbound, mode, be, args, got[0], got[1])


def world_frame(mid, body, prefix):
    """`[u16 len][prefix bytes][u16 id][body]` -- the WORLD connection's framing.

    WARNING: THE ID IS NOT AT A FIXED OFFSET. The transport reads it at
    `cursor + [conn+0x1ca]`, and that field is the "mode" the connect call chose:
    `0x5046b40` maps connect mode 1 -> 0 and connect mode 2 -> **4**
    (`0x05046b8b`), and `0x522fd70` stores it at `+0x1ca`. The lobby dials with
    mode 1, the relay with mode 2, so the same protocol has the id at +0 on one
    door and +4 on the other.

    Read it in the frame-id reader at `0x05230582`:

        mov ecx, [ebx+4]           ; read cursor
        mov ax, word [edi+0x1ca]   ; the mode
        add eax, ecx               ; cursor + mode
        mov ax, word [eax]         ; the id lives HERE

    and the same shape governs the enciphered path at `0x05232e7c`, which also
    sizes the ciphertext as `total - header - 2`.

    This is why EVERY frame we sent on 54850 was refused, including a trivial
    one -- the client read a garbage id out of our payload and tore the
    connection down. Four message-level hypotheses died on this before a bisect
    showed the transport itself was at fault.

    The skipped bytes are never read, so their value is free.
    """
    return (struct.pack(">H", len(body) + 2 + prefix)
            + bytes(prefix)
            + struct.pack(">H", mid) + body)


def send_world_frame(conn, mid, body, prefix):
    conn.sendall(world_frame(mid, body, prefix))



def send(conn, outbound, body, mode, be, echo=True, prefix=4):
    """Send one enciphered message, numbered from OUR OWN counter.

    WARNING: OUR OUTBOUND SEQUENCE IS OUR OWN COUNTER, NOT AN ECHO OF THE CLIENT'S.
    This is what broke the world door on its first live reply, and the failure
    is silent from here: the client validates the sequence in the enveloped
    body (exchange_key_phase3's error strings include `illegal(sequence)`, and
    it keeps a decremented copy at [obj+0x20]). Our 0x302B answer carried
    seq=2, because 0x20 MSG_AUTH_CODE_NOTIFY arrived first and we did not
    answer it -- so our first outbound frame claimed to be our second. The
    client received the frame, never dispatched it (no `> MSG_SERVER_UNIT_
    LOGIN_OK` and no NG either), and dropped the connection with
    `>Disconnected. err=0`.
   
    The lobby door had been echoing too and got away with it ONLY because it
    answers essentially every enveloped message, so the echoed number happened
    to equal its own count. That is a coincidence, not a design, and it would
    have broken the first time an unanswered message arrived mid-session.
    """
    _OUT_SEQ[0] += 1
    seq = _LAST_IN[0] if echo else _OUT_SEQ[0]
    print("[feworld]    [seq] client sent %d; replying with %d (%s)"
          % (_LAST_IN[0], seq, "echo" if echo else "count"), flush=True)
    send_world_frame(conn, 0x30,
                     fenet.bf_encrypt(outbound, fenet.traffic_wrap(body, seq),
                                      mode, be), prefix)


def serve(conn, args, session, outbound, mode, be):
    """Read, decode, print. Answers NOTHING -- see the module docstring."""
    print("\n[feworld] --- post-handshake. CAPTURE ONLY: nothing here answers, "
          "because nothing past 0x20 is measured yet ---", flush=True)
    conn.settimeout(args.read_window)
    _OUT_SEQ[0] = 0
    _SESSION.pop("entered", None)
    _chat_room_join()
    try:
        _serve_loop(conn, args, session, outbound, mode, be)
    finally:
        _chat_room_leave()


def _serve_loop(conn, args, session, outbound, mode, be):
    seen = 0
    # WARNING:KEY: THE IDLE TICK (2026-09-11). Until now this loop BLOCKED in
    # recv_frame until the client said something, so every pump -- chat, the
    # revive, fecampaign's phases, fepresence's relays -- ran at the mercy of
    # THIS client's outbound rate. war_deadline_pump's own comment claimed it
    # ran "on the read loop's idle path"; there was no such path, and the
    # comment had been wrong since it was written.
    #
    # What it cost, measured live: a player standing still watching another
    # player walk got a position update every 3-6 SECONDS, because their own
    # client was quiet and nothing else could wake their thread. The peer
    # walked in 3-6 unit jumps with a run animation in between.
    #
    # select() rather than a socket timeout, so recv_frame is only ever
    # entered when a frame is actually there -- a short recv timeout would
    # tear a frame in half. --idle-tick-ms 0 restores the blocking loop.
    tick = max(0.0, float(getattr(args, "idle_tick_ms", 250) or 0) / 1000.0)
    idle_since = time.monotonic()
    wake_r = _my_wake_socket()
    while True:
        if tick:
            try:
                ready = select.select([conn] + ([wake_r] if wake_r else []),
                                      [], [], tick)[0]
            except (OSError, ValueError):
                print("[feworld] socket gone while waiting -- hanging up",
                      flush=True)
                return
            except (TypeError, AttributeError):
                # not a real socket: the test harnesses hand this loop a stub
                # with recv() and nothing else. Fall back to the blocking
                # path, which is exactly what they ran against before.
                tick, ready = 0.0, [conn]
            if wake_r is not None and wake_r in ready:
                # another session posted us a relay: drain the poke and run
                # the pumps right now instead of at the next tick
                try:
                    wake_r.recv(256)
                except (OSError, BlockingIOError):
                    pass
                ready = [r for r in ready if r is not wake_r]
            if not ready:
                if time.monotonic() - idle_since >= args.read_window:
                    print("[feworld] no further traffic (idle %gs) -- hanging "
                          "up so FE fails fast" % args.read_window, flush=True)
                    return
                # the same pumps the inbound path runs, on our own clock
                field_ready_pump(conn, outbound, mode, be, args)
                gm_pump(conn, outbound, mode, be, args)
                chat_pump(conn, outbound, mode, be, args)
                validate_pump(conn, outbound, mode, be, args)
                war_deadline_pump(conn, outbound, mode, be, args)
                monster_wander_pump(conn, outbound, mode, be, args)
                revive_tick(conn, outbound, mode, be, args)   # a respawn wait
                drop_pump(conn, outbound, mode, be, args)
                item_effect_pump(conn, outbound, mode, be, args)
                ext_pump(Ctx(conn, outbound, mode, be, args))
                continue
            idle_since = time.monotonic()
        # the client IS talking (0x209F from the scene update lands 23 ms
        # after 0x100E), so the batch held for field-load can go on any
        # message once the grace has passed -- not only on a movement sample
        field_ready_pump(conn, outbound, mode, be, args)
        exp_max_seed_pump(conn, outbound, mode, be, args)
        try:
            fr = fenet.recv_frame(conn)
        except (OSError, IOError):
            print("[feworld] no further traffic (idle %gs) -- hanging up so FE "
                  "fails fast" % args.read_window, flush=True)
            return
        if not fr:
            print("[feworld] client closed after %d message(s)" % seen, flush=True)
            return
        outer, body = fr
        if outer != 0x30:
            print("\n[feworld] <- OUTER id=0x%04X %d bytes  (%s)"
                  % (outer, len(body), KNOWN.get(outer, "unknown")), flush=True)
            if body:
                print(fenet.hexdump(body), flush=True)
            if outer == 0x2099:
                # the END op's stack-local stream: the close arrives BARE
                conversation_close(conn, outbound, mode, be, args, body, "outer")
            continue
        plain = fenet.bf_decrypt(session, body, mode, be)
        env = fenet.traffic_unwrap(plain)
        if not env:
            print("\n[feworld] <- 0x30 whose envelope did not validate:", flush=True)
            print(fenet.hexdump(plain), flush=True)
            continue
        seq, inner = env
        _LAST_IN[0] = seq
        seen += 1
        # The admin's live console into the client: anything dropped into
        # --gmcmd-file goes out as a 0xF900 command line. Polled here rather
        # than on a timer because the read loop is already woken constantly by
        # the client's 0x2023 telemetry.
        gm_pump(conn, outbound, mode, be, args)
        chat_pump(conn, outbound, mode, be, args)
        validate_pump(conn, outbound, mode, be, args)
        war_deadline_pump(conn, outbound, mode, be, args)
        monster_wander_pump(conn, outbound, mode, be, args)
        revive_tick(conn, outbound, mode, be, args)   # a respawn wait
        drop_pump(conn, outbound, mode, be, args)
        item_effect_pump(conn, outbound, mode, be, args)
        ctx = Ctx(conn, outbound, mode, be, args)
        ext_pump(ctx)
        real_id = struct.unpack(">H", inner[:2])[0] if len(inner) >= 2 else -1
        spawn_protect_note(real_id)     # an action ends the 15 s protection
        print("\n[feworld] <- 0x30 seq=%d inner id=0x%04X, %d bytes of fields  (%s)"
              % (seq, real_id, max(0, len(inner) - 2),
                 KNOWN.get(real_id, "NOT SEEN BEFORE -- this is the finding")),
              flush=True)
        print(fenet.hexdump(inner), flush=True)
        if real_id == 0x0020 and args.probe_on_auth:
            # BISECT: answer the AUTH_CODE_NOTIFY -- which needs no answer -- with
            # a minimal enciphered frame, and see whether the connection survives
            # it. This splits the failure cleanly and RE was not converging:
            #
            #   dies here too   -> ANY enciphered frame from us is rejected, so
            #                      the fault is our ciphering/envelope on this
            #                      connection, not 0x302B's contents
            #   survives here   -> the transport takes our frames fine and the
            #                      problem really is the 0x302B message
            #
            # Worth stating why this is a live test rather than more disassembly:
            # with NO reply at all the client sits happily sending keepalives
            # (measured, first capture), and the disconnect follows our first
            # outbound frame every single time. So the trigger is ours; the open
            # question is whether it is the envelope or the payload.
            body = inner_msg(0x0001)
            send(conn, outbound, body, mode, be, args.seq_mode == "echo")
            print("[feworld]    --probe-on-auth: sent a minimal inner 0x0001. If "
                  "the client now disconnects WITHOUT sending 0x400F, the fault "
                  "is our transport, not the login message.", flush=True)
        if (real_id in EXT_HANDLERS
                and ext_dispatch(ctx, real_id, inner) is not False):
            # THE EXTENSION SEAM -- first in the chain on purpose, see the
            # registries at the top of the file. A handler that returns False
            # DECLINED the message and the chain below answers it as if no
            # extension existed (fecampaign with --campaign off).
            pass
        elif real_id == 0x0020 and len(inner) >= 6:
            code = struct.unpack(">I", inner[2:6])[0]
            print("[feworld]    MSG_AUTH_CODE_NOTIFY code=%d (0x%08X) -- this is "
                  "the CODE the lobby issued in 0x7821. Matching it against what "
                  "felobby handed out is what ties the two doors together."
                  % (code, code), flush=True)
        elif real_id == 0x206A:
            # MSG_GET_FORCE_INFO_REQUEST -- the first thing the client asks once
            # it is IN the world, and the reason the screen sits black. Named by
            # its own log format at 0x52d2cb0, built at 0x05005030 / 0x05005610:
            #
            #     [u32 ForceID][u32 BitMask]
            #
            # A "Force" is the faction/army; the mask says which fields to send
            # back, and the client asks for 0xFFFFFFFF -- everything.
            #
            # The answer is 0x3027 OK / 0x3028 NG, from the dispatcher at
            # 0x050057c0: `id - 0x3027`, a byte index table at 0x5005958 and a
            # jump table at 0x5005944. (0x3033/0x3034 are JOIN_FORCE OK/NG in the
            # same family.)
            #
            #     0x3027 = [u32 ForceID][u32 Bit] + the fields Bit selects
            #
            # WARNING: WE SEND Bit = 0 ON PURPOSE. The handler at 0x05005868 reads the
            # two dwords, then only parses fields when the force lookup
            # (0x5005560) finds an object, and it sets the screen's state word
            # `[esi+0x50] = 3` EITHER WAY. So an empty record is a complete valid
            # answer and unblocks the client -- the same shape as answering the
            # character list with count 0. The eleven m_* fields (KingMessage,
            # WinTotalNum, TargetFieldID, ...) are named in the strings at
            # 0x52d2cdc..0x52d2e6c and can be filled in later.
            f = inner[2:]
            force_id = struct.unpack_from(">I", f, 0)[0] if len(f) >= 4 else 0
            bits = struct.unpack_from(">I", f, 4)[0] if len(f) >= 8 else 0
            print("[feworld]    GET_FORCE_INFO ForceID=%d mask=0x%08X"
                  % (force_id, bits), flush=True)
            vals = args.force_table.get(force_id)
            if vals is None:
                body = inner_msg(0x3027, struct.pack(">II", force_id, 0))
                send(conn, outbound, body, mode, be,
                     args.seq_mode == "echo", args.world_prefix)
                print("[feworld] -> 0x3027 ForceID=%d NOT in --forces, empty "
                      "record" % force_id, flush=True)
            else:
                vals = campaign_force_vals(args, force_id, vals)
                # KEY: THE NATION'S OWN COLOUR (force+0x1bc, FORCE_FIELDS `f1bc`)
                # -- never set, so every nation sent palette index 0, which is
                # BLACK. Observed live, 2026-09-12: the "<nation> (of Player)" circle
                # on the continent map is black for Netzawar AND Gebrand while
                # their fields are red and cyan. 0x05105280 resolves the
                # character's nation ([char+0x30]) through force_by_id
                # (0x5005560) and draws `movsx byte [force+0x1bc]` through the
                # same palette as the field colour byte (0x5008680 ->
                # 0x5336fe8); the war-prep window colours both sides with it
                # too (0x051157ff). The palette IS indexed by force id -- 1 red,
                # 2 green, 3 blue, 4 yellow, 5 cyan, matching the live
                # screenshots byte for byte -- so the index is the id.
                _nc = str(getattr(args, "force_color", "id") or "off")
                if _nc != "off":
                    vals = dict(vals)
                    if _nc == "id":
                        vals["f1bc"] = int(force_id)
                    else:
                        try:
                            vals["f1bc"] = max(-128, min(127, int(_nc, 0)))
                        except ValueError:
                            pass
                rec = build_force_record(vals)
                body = inner_msg(0x3027,
                                 struct.pack(">II", force_id, bits) + rec)
                send(conn, outbound, body, mode, be,
                     args.seq_mode == "echo", args.world_prefix)
                print("[feworld] -> 0x30 inner 0x3027 MSG_GET_FORCE_INFO_OK "
                      "ForceID=%d name=%r TargetFieldID=%d (%d record bytes)"
                      % (force_id, vals.get("name"),
                         vals.get("TargetFieldID", 0), len(rec)), flush=True)
        elif real_id == 0x400A:
            # MSG_REGISTER_DISTRIBUTER_OF_FIELDINFO_REQUEST -- no fields, sent
            # straight after the nation is registered (built 0x0500950d, logged
            # `<MSG_REGISTER_DISTRIBUTER_OF_FIELDINFO_REQUEST` at 0x52d338c).
            #
            # It has no registration call, so its answer came from the state word
            # instead: the builder sets [obj+0x14] = 2, and two sibling functions
            # set it to 0 and 1. Their only callers are dispatcher arms at
            # 0x050569af, which decodes `sub 0x3016 / dec / dec`:
            #
            #     0x3016 OK   -> logs MSG_REGISTER_DISTRIBUTER_OF_FIELDINFO_OK,
            #                    calls 0x5009540 ([obj+0x14] = 0)
            #     0x3017 NG   -> 0x5009550 ([obj+0x14] = 1)
            #     0x3018      -> 0x5009590, a third arm
            #
            # The OK arm reads NOTHING from the message, so 0x3016 carries no
            # fields. "Find the state word the sending code set, then the handler
            # that clears it" keeps being the fastest route when a request has no
            # registered reply list.
            print("[feworld]    REGISTER FIELDINFO DISTRIBUTER (no fields)",
                  flush=True)
            send(conn, outbound, inner_msg(0x3016), mode, be,
                 args.seq_mode == "echo", args.world_prefix)
            print("[feworld] -> 0x30 inner 0x3016 "
                  "MSG_REGISTER_DISTRIBUTER_OF_FIELDINFO_OK (no fields)",
                  flush=True)
            # ...and then PUSH the island list, because registering a distributer
            # is a subscription: the client asked to be sent field info, so the
            # ack alone leaves it waiting for the thing it subscribed to.
            #
            #     0x3030 MSG_DISTRIBUTE_GROUPINFO_LIST_NOTIFY
            #            [u16 count][count x u16 islandId]
            #
            # Handler 0x050095b0, named by the log line at 0x52d5b54 and reached
            # from the dispatcher at 0x05056a3c (`id - 0x301F`, byte table
            # 0x50576cc into jump table 0x50576ac -> slot 5). It prints
            # `num island = %d` (0x52d33bc) with the count, allocates a vector of
            # count 16-BYTE records, then reads one u16 per island and marks
            # `array[id-1]` through 0x5008d50 -- bounds-checked as (id-1) < count,
            # so the ids must be 1..count.
            #
            # It ALSO clears [obj+0x14] itself (0x050095cf), the same word 0x3016
            # clears -- so this notify is what 0x400A was really waiting for, and
            # the ack is the lesser half of the answer.
            #
            # `Island Info was Updated. Open War Prepare Window.` (0x52e620c) is
            # what the client does next, so this should move it to the war-prepare
            # screen. The 16-byte record is NOT mapped -- only the id list is
            # served -- so expect the map to be sparse until it is.
            # WARNING: EACH ISLAND IS MORE THAN AN ID, and sending only ids is what put
            # the client in a RETRY LOOP -- thousands of iterations of
            # 0x400A/0x3030/0x400B/0x4011, and 0x4011 asking about island
            # 65535, which was garbage read past the end of our short record.
            #
            # The caller's loop (0x0500968f) reads the island id, then hands the
            # record to 0x5008d50 -- which reads ANOTHER u16 and treats it as a
            # count, frees and reallocates that many 0x100-byte buffers
            # (0x05008df8) and reads that many NUL-terminated strings into them
            # (0x05008e2a). So:
            #
            #     0x3030 = [u16 islandCount]
            #              + islandCount x { u16 id, u16 nameCount,
            #                                nameCount x cstr }
            #
            # With only ids on the wire, island N's id was being consumed as
            # island N-1's name count, and everything after it desynchronised --
            # which is exactly the shape of a stream whose element is bigger than
            # the sender thinks.
            #
            # nameCount 0 is a complete, aligned record. --island-names attaches
            # names when we know what they should be; the strings land in
            # 0x100-byte buffers, so they are not short.
            n = args.islands
            names = [x for x in (args.island_names or "").split(",") if x]
            payload = struct.pack(">H", n)
            for i in range(n):
                these = [names[i]] if i < len(names) else []
                payload += struct.pack(">HH", i + 1, len(these))
                for nm in these:
                    payload += nm.encode("cp932", "replace") + bytes(1)
            send(conn, outbound, inner_msg(0x3030, payload), mode, be,
                 args.seq_mode == "echo", args.world_prefix)
            print("[feworld] -> 0x30 inner 0x3030 "
                  "MSG_DISTRIBUTE_GROUPINFO_LIST_NOTIFY, %d island(s) 1..%d"
                  % (n, n), flush=True)
            print("[feworld]    expect the client to log 'num island = %d' and "
                  "then 'Island Info was Updated. Open War Prepare Window.'" % n,
                  flush=True)
        elif real_id == 0x4015:
            # One u8 -- the character's UNIT id, read from [char+0x1258], the same
            # field the character record's first byte carries (see
            # fe-character-screen). Built at 0x05105cfc; it parks the screen's
            # state ladder at [obj+0x6c] = 6.
            #
            # No registration call, so the answer came from the result byte again.
            # [obj+0xec] is 0 while pending, and the only writer is the handler at
            # 0x0510bb00, which switches on the message id:
            #
            #     0x303C -> [i32 id][cstr][cstr], sets [obj+0xec] = 1
            #     0x303D -> sets [obj+0xec] = 0xFF
            #
            # and the waiter at 0x05105d36 advances to state 7 for ANY non-zero
            # value that is not 1 -- i.e. for 0x303D. A 1 falls through into a
            # different path instead.
            #
            # WARNING: THIS IS A NOTICE, and 0x303D is "nothing to show". The tell is the
            # i32 being compared against a cached value at 0x52e4a48 and only
            # acted on when it DIFFERS, plus two strings -- exactly the lobby's
            # 0xD014/0xD015 pair (fe-lobby-blowfish), where 0xD014 opens a window
            # the player must close and 0xD015 moves on. So the id here is a
            # seen-already key, not a payload.
            #
            # Default to 0x303D for the same reason the lobby defaults to 0xD015:
            # it advances. --world-notice sends the 0x303C form instead.
            #
            # WARNING: 2026-08-19 -- 0x303D IS WHAT RESTARTS THE BLACK-SCREEN LOOP.
            #
            # The reply handler is 0x0510bb00, a method of the map-select /
            # war-prepare screen, and it switches on the id at msg[+4]:
            #
            #     0x303C  [i32 id][cstr][cstr]   -> [screen+0xec] = 1, and then
            #                                       ONLY if `id != [0x52e4a48]`
            #                                       (the seen-already cache) does
            #                                       it stay 1; a repeat id falls
            #                                       through to 0xFF
            #     0x303D  no fields              -> [screen+0xec] = 0xFF
            #
            # and the screen's state 6 (0x05105d36) reads that byte:
            #
            #     0    keep waiting
            #     1    BUILD THE SCREEN (allocates 0x4C0 and goes on)
            #     else 0x05105e91 -> [+0xec]=0, state = 7
            #
            # State 7 (0x05105eb2) needs `[screen+0x5c] == 4` and otherwise runs
            # 0x051060a6 -> 0x5101280(2,0) -> **0x051060b1: [screen+0x6c] = 0**,
            # which is state 0 again -- and state 0 sends 0x400A. That is the
            # whole observed cycle, mechanically:
            #
            #     0x400A subscribe -> wait for the island list -> 0x400B stop
            #     -> 0x4011 per island (states 2/3, once each) -> 0x4015 notice
            #     -> 0x303D -> 0xFF -> state 7 -> RESET TO STATE 0 -> 0x400A ...
            #
            # So the default is now 0x303C with a per-session id. --world-notice
            # supplies real text; without it a minimal notice is still sent,
            # because "nothing to show" is the one answer that provably cannot
            # advance this screen. --world-notice-none restores 0x303D.
            f = inner[2:]
            unit = f[0] if f else 0
            if not args.world_notice_none:
                # WARNING: AN EMPTY NOTICE RENDERS AS AN EMPTY BOX. Seen live 2026-08-19:
                # the player got a dialog with no text and reasonably wondered
                # whether the translation had broken. It had not -- we were
                # sending two empty cstrs and the client drew exactly that.
                # A default that says something also PROVES the two string fields
                # land, which an empty notice never could.
                title, _, text = (args.world_notice or DEFAULT_NOTICE).partition("|")
                # WARNING: DO NOT BUMP THIS PER SEND. Bumping it was a real bug, seen
                # live on prod 2026-08-19: the player got a notice dialog built
                # and torn down on EVERY refresh lap, rendering as a flickering
                # fragment.
                #
                # 0x0510bb5b compares the id against the cached [0x52e4a48]:
                # a NEW id shows the window, a REPEAT falls to the same 0xFF path
                # as 0x303D. That cache is the feature, not an obstacle -- the
                # 0x400A/0x400B/0x4011-sweep/0x4015 cycle is the war map's own
                # island-info REFRESH loop (0x400A is literally
                # "島情報更新要求", 0x400B its stop), so 0x4015 is asked once per
                # lap and a constant id is what makes the notice appear once and
                # then stay quiet.
                nid = args.world_notice_id
                payload = (struct.pack(">i", nid)
                           + title.encode("cp932", "replace") + bytes(1)
                           + text.encode("cp932", "replace") + bytes(1))
                send(conn, outbound, inner_msg(0x303C, payload), mode, be,
                     args.seq_mode == "echo", args.world_prefix)
                # MEASURED LIVE 2026-08-19 on prod: this DOES reach
                # [screen+0xec]=1 and the notice window is really built -- the
                # player saw it on screen. It is NOT sufficient on its own. The
                # build path (0x05105d4c..0x05105e8e) falls straight through into
                # 0x05105e91 `[screen+0xec]=0` / 0x05105e98 `[screen+0x6c]=7`,
                # and state 7 (0x05105eb2) demands `[screen+0x5c] == 4` or it
                # runs 0x051060a6 -> 0x051060b1 `[screen+0x6c]=0` and starts the
                # whole 0x400A cycle again. So the dialog is built and torn down
                # once per lap, which is why it renders as a flickering fragment.
                # WARNING: THE OPEN GATE IS [screen+0x5c]==4, not this message.
                _SESSION["notices"] = _SESSION.get("notices", 0) + 1
                print("[feworld]    unit=%d -> 0x303C notice id=%d %r "
                      "(#%d this session; the client caches the id at 0x52e4a48, "
                      "so only the FIRST builds a window)"
                      % (unit, nid, title, _SESSION["notices"]), flush=True)
            else:
                send(conn, outbound, inner_msg(0x303D), mode, be,
                     args.seq_mode == "echo", args.world_prefix)
                print("[feworld]    unit=%d -> 0x303D --world-notice-none: sets "
                      "[screen+0xec]=0xFF -> state 7 -> state 0 = THE LOOP"
                      % unit, flush=True)
        elif real_id == 0x4011:
            # MSG_GET_GROUP_DETAIL_INFO_REQUEST (built 0x050092aa, logged at
            # 0x52d32bc) -- one u16, the island the client wants the groups for.
            # It sets [obj+0x2c] = 2; the NG arm at 0x050094c5 sets it to 1 and
            # uses id 0x3032, and the OK is 0x3031 -- slot 6 of the same
            # `id - 0x301F` table that produced the island notify, logged
            # `> MSG_GET_GROUP_DETAIL_INFO_OK` (0x52d5b34) and parsed by
            # 0x050092f0:
            #
            #     0x3031 = [u16 islandId][u16 groupCount]
            #              + groupCount x { u32 groupId, u32 MASK, ...gated }
            #
            # WARNING: THIS ONE REALLY IS MASK-DRIVEN, unlike force-info. Verified rather
            # than assumed this time: 0x5008850 reads the group id into [rec+0],
            # then a u32 mask into a local, and EVERY subsequent field sits behind
            # a `test byte [mask], <bit> / je` -- bit 0 gates a u8 at +4, bit 1 a
            # u32 at +8, and so on through +0x8c. So mask = 0 means "no optional
            # fields", and a group record is then just its id and a zero mask.
            # (Per-group records are 0xCC bytes in memory, which is where the
            # `count * 0xcc` allocation comes from.)
            #
            # --groups sets how many to announce; 0 is a complete valid answer.
            f = inner[2:]
            island = struct.unpack_from(">H", f, 0)[0] if len(f) >= 2 else 0
            # WARNING: GROUP IDS MUST BE GLOBALLY UNIQUE AND 1..0x5F. MSG_ENTER_AREA_OK
            # names a GROUP, and the client resolves it with 0x5009820 to find
            # which island it belongs to ([group+0xc8], written here by the outer
            # parser at 0x0500943a). With groupCount=0 nothing can ever resolve,
            # the current island stays -1, and the war-prepare window is
            # unreachable -- which is what left the client spinning.
            n = args.groups
            # The war fields, then any CAPITAL announced for this island. A
            # capital rides in the same list because the client picks a field
            # off it; what makes it a town rather than a battlefield is purely
            # the ID (CAPITAL_GROUP_IDS), which it tests on ENTRY, not here.
            caps = [g for g in _CAPITALS.get(island, [])]
            gids = group_ids_for(island, args)
            # one census for the whole answer -- the marker each field draws is
            # a population tier (field_census)
            census = field_census(args)
            by_nation = field_census_nations(args)
            _recs = []
            payload = struct.pack(">HH", island, len(gids))
            for gid in gids:
                # In dat mode a capital is whatever fet_area's 500 marker says,
                # not whatever --capital was pointed at: the table knows all
                # ten, and island 2 carries 21 and 91 whether or not anyone
                # named them on the command line.
                if world_from_dat(args):
                    is_capital = gid in CAPITAL_GROUP_IDS
                else:
                    is_capital = gid in caps
                vals = {}
                if args.field_status is not None:
                    vals["status"] = args.field_status
                # KEY: A LIVE PHASE BEATS THE CONSTANT. The client draws this
                # byte through its own five-name table (0 Peace, 1 War Prep,
                # 2 At war, 3 Truce, 4 ServerDown, 0x0510b540 -> 0x52e4b1c),
                # so once a campaign is running the war map says what is
                # actually happening on each field instead of one value for
                # the whole world.
                _ph = campaign_phase(args, gid)
                if _ph is not None:
                    vals["status"] = _ph
                # KEY: THE FIELD'S MARKER IS ITS POPULATION (see field_census).
                # Sent for every field, including 0: the client needs the field
                # present in the record to size a marker, and "nobody here" is
                # a true answer that the ~9 tier can draw.
                if str(getattr(args, "field_census", "on") or "off") == "on":
                    vals["chars_all"] = census.get(int(gid), 0)
                    # (F%d): players of THIS VIEWER's own nation in the field.
                    # WARNING: "F" is a READING -- Force is the obvious expansion and
                    # the viewer's own side is the only per-viewer quantity in
                    # a line that otherwise has ALL and the two war sides --
                    # but nothing names it. --field-census off drops it.
                    _mine = nation_of(args)
                    if _mine:
                        vals["chars_f"] = (by_nation.get(int(gid), {})
                                           .get(int(_mine), 0))
                # KEY: THE COLOUR BYTE (+0x96, mask bit 19, the client's own log
                # calls it COLOR[%d]) -- NEVER SENT until 2026-09-12, and it is
                # the original design question: "should map circles/lines be
                # coloured depending upon area ownership?" There is a literal
                # per-field colour on the wire and we left its bit clear.
                #
                # It is a PALETTE INDEX. Both map-screen readers do
                # `movsx <r>, byte [group+0x96]` (SIGNED -- -1 reads as "none")
                # then call 0x5008680, which is one instruction of arithmetic:
                #     return 0x5336fe8 + (variant + colour*2) * 4
                # i.e. table[colour*2 + variant], two dwords per colour, and
                # the result's first dword is stored into the widget at +0x89.
                # The map screen reads it SIX times per field
                # (0x0510b10b/b1b9/b20b/b55e/b57e/b605), around the same panel
                # updater that draws Total Players and Status.
                #
                # WARNING: THE VALUE IS A READING: the owning nation is the only
                # per-field quantity that a five-nation palette would be keyed
                # on, and `--field-color owner` sends def_id. The table is
                # runtime-built (0x5336fe8 is writable) so its length is not
                # readable statically -- if the wrong end of the palette comes
                # out, `--field-color N` pins one index for a probe run and
                # `off` restores the absent field.
                _fc = str(getattr(args, "field_color", "owner") or "off")
                if _fc != "off":
                    if _fc == "owner":
                        vals["color"] = int(territory_owner(gid, args) or 0)
                    else:
                        try:
                            vals["color"] = max(-128, min(127, int(_fc, 0)))
                        except ValueError:
                            pass
                if args.field_flags is not None:
                    # WARNING: REQUIRED for the map screen to ever build. The home-field
                    # resolve 0x05009240 -- called from map-select state 7
                    # (0x05105eed) -- only accepts a group when BOTH
                    # [group+0x78] == the character's nation AND
                    # [group+0x8c] has BIT 3 set. +0x8c is mask bit 15 of this
                    # record (u16, read at 0x05008a3f), and it was never served,
                    # so the resolve returned NULL for every nation and state 7
                    # restarted the island sweep each lap -- the 267-lap loop /
                    # black window. Bit 3's meaning beyond "counts as a home
                    # field" is unmeasured; 8 is the minimum that passes.
                    #
                    # VERIFIED 2026-09-09: BIT 3 IS "THIS GROUP IS A CAPITAL",
                    # found by looking at the live world map: every
                    # marker read "Cap <name>". The map-label builder at
                    # 0x0510A2A4 does
                    #     mov al,[group+0x8c] ; test al,8
                    #     jne  -> sprintf("首都%s", name)   (0x052E5DCC)
                    #     je   -> sprintf("%s", name)       (0x052D2214)
                    # and 首都 is "capital city", which our UI table renders
                    # "Cap" (it has 4 bytes to fit in). So the same bit the
                    # home-field resolve needs is the one that prefixes the
                    # label -- and setting it on EVERY field, which is what
                    # makes the resolve succeed, tells the map that every
                    # field is a capital.
                    #
                    # --field-home capital sets it only on the capitals, which
                    # is what the client means by it. It is NOT the default:
                    # the resolve wants a group with BOTH def_id == the
                    # player's nation AND this bit, so narrowing it can put a
                    # nation back in the 2026-08-27 black screen if that
                    # nation's capital is not in the island's list with a
                    # matching def_id. PARTIAL: UNTESTED either way.
                    flags = args.field_flags
                    if getattr(args, "field_home", "all") == "capital" and not is_capital:
                        flags &= ~0x8
                    vals["g8c"] = flags
                # 2026-09-06: dat.pak SHIPS THE FIELD NAMES. fet_area has a
                # row for every area 1..95 carrying its cp932 name, the pixel
                # it draws at on the continent map, its owning nation and its
                # adjacency list -- and prod has been running with five
                # invented English names ("Ruined Plain", "Old Bridge", ...)
                # hardcoded in docker-compose. `--field-names dat` serves the
                # shipped ones. It is not the default only because the names
                # are Japanese and the rest of this client is being run in
                # English; --field-names dat-en falls back to the id for a
                # field with no translation, which is every field today.
                if getattr(args, "field_names", "") in ("dat", "dat-en"):
                    if args.field_names == "dat":
                        nm = fegamedata.areas().get(gid, {}).get("name")
                    else:
                        # 2026-09-09: dat-en is no longer a placeholder. All 95
                        # areas have an English name in
                        # fedata/fe-area-names-en.tsv -- OURS, not SE's, since
                        # dat.pak ships none. A missing row still falls back to
                        # "Field N", so the file can be edited or removed
                        # without breaking field entry.
                        nm = fegamedata.area_names_en().get(gid)
                    vals["name"] = nm or "Field %d" % gid
                elif args.field_names:
                    names = [x for x in args.field_names.split(",") if x]
                    if is_capital:
                        vals["name"] = args.capital_name
                    elif gid - 1 < len(names):
                        vals["name"] = names[gid - 1]
                    else:
                        vals["name"] = "Field %d" % gid
                contest = field_contest(island, args)
                if contest:
                    # KEY: PER-ISLAND DEFENDER OVERRIDE -- the Elena black screen fix
                    # (2026-08-27). The map-select home-field resolve 0x05009240
                    # (called from state 7, 0x05105eed) accepts a group ONLY when
                    #     [group+0x78] == [char+0x30]  AND  ([group+0x8c] & 8)
                    # where [char+0x30] is the 0xD002 `force` field = the player's
                    # NATION (read at 0x0502513d; felobby CHAR_FIELDS `force`->0x30).
                    # [group+0x78] is `def_id`. With one DEF:ATK pair for every
                    # field (`--field-nations 1:5`) EVERY group has def_id=1, so
                    # ONLY nation 1 has a home field: Lex (force 1) resolves and
                    # enters; Elena (force 5) matches no group, the resolve returns
                    # NULL every lap, state 7 restarts the island sweep forever ->
                    # the 267-lap 0x4011 flood that renders as a black screen,
                    # and 0x2000 MSG_ENTER_AREA is never sent. Giving each island
                    # its own defender means every nation 1..5 owns exactly one
                    # home field, so the resolve succeeds for whatever `force` the
                    # character carries. Unset -> old single-pair behaviour (so a
                    # capture replay is unchanged). The rule lives in
                    # field_contest() so the force records agree with it.
                    dfn, atk = contest
                    # KEY: AND THE REAL OWNER BEATS THE KNOB (2026-09-12). SE's own
                    # continent-map page says a normal field is marked with the
                    # ICON OF THE NATION THAT HOLDS IT -- 「通常フィールドには国
                    # アイコンが表示されます」 (guide/interface/interface02) -- and
                    # [group+0x78] `def_id` is the only owning-nation field on the
                    # wire, so that icon is this value. field_contest answers per
                    # ISLAND from --field-nations/--field-defenders: a static
                    # constant for all fifteen fields of a continent. So the
                    # frontier island, which the five nations split three ways
                    # each, showed every field as nation 1's -- and a field that
                    # CHANGED HANDS in a war never changed on the map, because
                    # nothing in this record came from the territory board.
                    #
                    # territory_owner is that board: the same function force_vals
                    # counts held fields with, and the one fecampaign moves when a
                    # war resolves. It wins here; the knob stays the fallback for
                    # a field it has no answer for, which keeps the 2026-08-27
                    # home-field resolve working (every nation still owns its own
                    # continent, so [group+0x78] == [char+0x30] still matches for
                    # every `force`).
                    own = None
                    if getattr(args, "field_owner", "board") == "board":
                        own = territory_owner(gid, args)
                    if own:
                        dfn = int(own)
                    # ...and the ATTACKER is whoever actually declared on this
                    # field, not a per-island constant. A field at peace has
                    # none: fecampaign answers 0 and the knob's value stands.
                    live_atk = campaign_attacker(args, gid)
                    if live_atk:
                        atk = int(live_atk)
                    vals["def_id"] = dfn
                    vals["def_name"] = args.force_table.get(dfn, {}).get("name", "")
                    vals["atk_id"] = atk
                    vals["atk_name"] = args.force_table.get(atk, {}).get("name", "")
                    # THE WHOLE `Char[D%d/%dvsA%d/%d...]` BLOCK, from the war
                    # itself (2026-09-12). Only def_chars was served before, and
                    # only it of the four: the D and A ceilings and the attacker
                    # count were absent, so a field at war could not show its
                    # strengths. The ceilings are the per-side cap -- SE
                    # warsystem01's 最大50人対50人, fecampaign --war-cap.
                    if str(getattr(args, "field_census", "on") or "off") == "on":
                        d = campaign_side_count(args, gid, "def")
                        a_ = campaign_side_count(args, gid, "atk")
                        if d is not None:
                            vals["def_chars"] = d
                            vals["def_now"] = d
                            cap = campaign_war_cap(args)
                            if cap:
                                vals["def_max"] = cap
                                vals["atk_max"] = cap
                        if a_ is not None:
                            vals["atk_now"] = a_
                # Marker position on the continent map (mask bit 17, the
                # [%03d-%03d] pair in the client's own FIELD log line). Never
                # served -> every field's marker rendered at (0,0), stacked in
                # the top-left corner (reported the first time the map
                # was seen live, 2026-08-22). The coordinate SPACE is unmeasured;
                # these defaults exist to spread the markers so it can be
                # calibrated from one look at the screen.
                if is_capital and args.capital_coords:
                    # WARNING: A CAPITAL GOT NO MARKER AT ALL. --field-coords is
                    # indexed `gid - 1`, and a capital id (21..95) is far past
                    # a five-entry list, so bit 17 was never set and the marker
                    # rendered at the origin -- which the client then CLAMPS to
                    # 40 (0x0500fae6 `mov word [ebp+0x90], 0x28`), planting it
                    # hard in the corner. Reported from the screen 2026-09-04.
                    cx, _, cy = args.capital_coords.partition(":")
                    try:
                        vals["coords"] = (int(cx, 0), int(cy, 0))
                    except ValueError:
                        pass
                elif args.field_coords:
                    pairs = [p for p in args.field_coords.split(",") if p]
                    if gid - 1 < len(pairs):
                        cx, _, cy = pairs[gid - 1].partition(":")
                        try:
                            vals["coords"] = (int(cx, 0), int(cy, 0))
                        except ValueError:
                            pass
                # The Hmap map number (mask bit 18). See GROUP_FIELDS: on the
                # OUTDOOR entry path this decides which Data\Hmap\mapNN.pak is
                # loaded, and a value the client's table 0x52d30e0 does not know
                # is a null deref, not a blank field. Only 1..14 are shipped.
                if args.field_hmaps:
                    maps = [m for m in args.field_hmaps.split(",") if m]
                    if maps:
                        try:
                            vals["hmap"] = int(maps[(gid - 1) % len(maps)], 0)
                        except ValueError:
                            pass
                if is_capital and args.capital_attacker != "on":
                    # \U0001f534 THIS DROPPED THE ATTACKER PAIR ON THE FIRST TRY AND THE
                    # MAP SCREEN CRASHED (2026-09-04). Reasoning: "a town is not
                    # contested". The record was verified afterwards to be a
                    # clean SUBSET of a war field's -- same bits minus these
                    # two, body well-formed -- so it PARSES; that is not the
                    # same as the client tolerating it. atk_name is an INLINE
                    # buffer at struct offset 0x97 and atk_id a u32 at 0xB8, so
                    # omitting them leaves those bytes of the 0xCC record as
                    # whatever the allocation held, and the map screen reads a
                    # name out of there.
                    # Default is now ON: a capital carries the SAME fields as a
                    # war field, differing only in its id and name, because a
                    # war-field record demonstrably does not crash that screen.
                    # `off` reproduces the crash on purpose -- it is the other
                    # half of the A/B, not a setting anyone should run.
                    vals.pop("atk_id", None)
                    vals.pop("atk_name", None)
                if world_from_dat(args):
                    # KEY: THE SHIPPED WORLD WINS. Everything above authored a
                    # field by formula -- a name off a list index, a def_id off
                    # the island number, an hmap cycled `(gid-1) % 5`, a marker
                    # off a five-entry --field-coords. fet_area has the real
                    # value for all 95 areas, so overwrite rather than restate:
                    # the blocks above stay exactly as they are and keep
                    # working for --world synthetic.
                    row = fegamedata.areas().get(gid)
                    if row:
                        # def_id is the LIVE holder, which starts as SE's board
                        # and moves when a war is won. atk_id stays whatever
                        # --field-nations said until the war layer owns it;
                        # dropping it here would leave the 0xCC record's
                        # +0x97/+0xB8 as allocation junk, which is the crash
                        # recorded under --capital-attacker.
                        vals["def_id"] = territory_owner(gid, args)
                        vals["def_name"] = args.force_table.get(
                            vals["def_id"], {}).get("name", "")
                        # WARNING: NEVER LEAVE THE ATTACKER PAIR UNSET. atk_name is
                        # an INLINE buffer at struct offset 0x97 and atk_id a
                        # u32 at 0xB8, so an unserved pair is whatever the 0xCC
                        # allocation happened to hold -- and the map screen
                        # reads a name out of there. That crashed it on
                        # 2026-09-04 (see --capital-attacker). With 95 fields
                        # and only one DEF:ATK pair configured, most fields
                        # would have hit exactly that.
                        #
                        # A field nobody is attacking gets id -1 and an EMPTY
                        # name: -1 is what the client's own FIELD line prints
                        # for "unset" ((ID:-1)), and an empty cstr is one NUL
                        # into a buffer rather than no write at all. PARTIAL: that -1
                        # is SE's "no attacker" is a reading; that junk is
                        # wrong is measured.
                        vals.setdefault("atk_id", 0xFFFFFFFF)
                        vals.setdefault("atk_name", "")
                        # Same hazard, and this one the map screen acts on.
                        # 0x051067d2 does `cmp byte [group+4], 4` and refuses
                        # the field with "the server is down" (0x052e4d14) on a
                        # match. +4 is mask bit 0, unset by default, so the
                        # byte is whatever the count*0xCC allocation held --
                        # and a field that happens to hold 4 is unreachable for
                        # no reason anyone could see. Serve 0.
                        vals.setdefault("status", 0)
                        # WARNING: hmap is a NULL DEREF, not a blank field, if the
                        # client's table 0x52d30e0 does not know it. A capital
                        # is 101..105 there -- in the table but NOT shipped as
                        # a pak -- which is fine because the capital loader
                        # never consults it, and dangerous if a capital ever
                        # takes the outdoor arm. Serve what the table says.
                        if row.get("hmap"):
                            vals["hmap"] = row["hmap"]
                        vals["coords"] = (row["map_x"], row["map_y"])
                        # The flags word, including bit 3 = CAPITAL. --field-home
                        # still narrows it, so a run can go back to the old
                        # "every field is a home field" behaviour.
                        flags = row.get("flags", 0)
                        if getattr(args, "field_home", "all") == "all":
                            flags |= 0x8
                        vals["g8c"] = flags
                        # THE ADJACENCY LIST. Without it the client's frontier
                        # test collapses to "my nation already holds this" and
                        # no enemy field is enterable by anyone -- see
                        # GROUP_FIELDS bit 12.
                        if args.world_neighbours == "on":
                            vals["neighbours"] = row["neighbours"]
                # KEY: THE ALWAYS-READ TAIL (see build_group_record), from the
                # FINAL owner and attacker above. +0xC0 = the attacker's palette
                # index -- only a real nation; "no attacker" is 0xFFFFFFFF and
                # 0x5008680 has no bounds check, so anything else sends 0.
                # +0xC4 = how many fields the holder has, counted exactly as
                # fecampaign.force_vals counts the nation record's pairs, so
                # the field panel and the nation legend cannot disagree.
                if getattr(args, "field_tail", "on") == "on":
                    _atk = int(vals.get("atk_id", 0) or 0)
                    vals["tail_color"] = _atk if _atk in args.force_table else 0
                    _hold = int(vals.get("def_id", 0) or 0)
                    if _hold:
                        vals["tail_held"] = sum(
                            1 for _a in fegamedata.areas()
                            if territory_owner(_a, args) == _hold)
                _r = build_group_record(gid, vals)
                _recs.append(_r)
                payload += _r
            send(conn, outbound, inner_msg(0x3031, payload), mode, be,
                 args.seq_mode == "echo", args.world_prefix)
            # WARNING: THIS PRINTED `n` -- the war-field count -- while the record
            # list could be longer. On 2026-09-04 it reported "1 group(s)" for
            # an island that was announcing TWO, so the first question asked
            # about the capital crash ("did it even go out?") could not be
            # answered from our own log. Report what was actually SENT.
            # Print the MASK per record, not the literal "mask 0" this used
            # to claim. Reconstructing masks by hand is how the 5-byte tail was
            # finally cornered on 2026-09-04; the log should just say them.
            print("[feworld]    GROUP DETAIL for island %d -> 0x3031 with %d "
                  "group(s) %s, masks %s, %d bytes"
                  % (island, len(gids), gids,
                     ["0x%08X" % struct.unpack_from(">I", r, 4)[0]
                      for r in _recs],
                     len(payload)), flush=True)
            # A 0x4011 arriving AFTER the enter-area round trip is mode 0xb
            # substate 1 asking for the entered field's detail -- the client is
            # past the +0x509 clear (0x4ff9d64, in the field-entry step), so
            # 0x100E lands and sticks. ONCE per entry: measured live 2026-08-23,
            # the in-field war screen re-sends 0x4011 EVERY FRAME, and answering
            # each with 0x100E flooded the client log with `> MSG_ADD_COMPLETE`
            # (harmless -- the arm is an idempotent flag-set -- but noise). The
            # 0x2000 handler clears this flag so a re-entry gets its 0x100E.
            if (_SESSION.get("in_field") and args.add_complete == "on"
                    and not _SESSION.get("add_complete_sent")):
                _SESSION["add_complete_sent"] = True
                # THE ADD STREAM COMES FIRST, then 0x100E says it is complete --
                # that is what 0x100E MEANS ("the initial ADD stream is done, go
                # live"). Sending the entities after it would be telling the
                # client the stream finished and then continuing it.
                _SESSION.pop("self_redressed", None)
                if args.add_self in ("on", "client"):
                    if args.add_self == "on":
                        add_entities(conn, outbound, mode, be, args)
                        # the self record just rebuilt the body and stripped
                        # the bag reader's armour -- put it back before 0x100E
                        # (see self_redress_push; --self-redress, default off)
                        self_redress_push(conn, outbound, mode, be, args)
                    else:
                        print("[feworld]    --add-self client: NO self 0x1006 -- "
                              "the client's own 'Chara 1' stands (dressed by the "
                              "lobby list, USESKILLRDY from 0x04fe78aa, items in "
                              "the manager); the stat block goes by 0x2024 after "
                              "0x100E", flush=True)
                    # WARNING: THE HUD EXP GAUGE'S MAX GOES OUT FIRST -- ahead of
                    # skill_list_push, which carries the NUMERATOR (the
                    # per-class EXP dword), and ahead of the 0x100E that
                    # releases the field. The gauge CACHES [unit+0x135c] when
                    # it is built and can never refresh it while the exp is
                    # above that cache, so a max written later in this burst
                    # is a max the widget never reads -- the deadlock behind
                    # five reports of "the bar shows 100%". Disassembly in
                    # exp_max_push. It still rides AFTER the ADD, for the same
                    # reason the skill list does (below).
                    exp_max_push(conn, outbound, mode, be, args,
                                 "field entry, ahead of the gauge")
                    # ...and the skills that unit already owns. It has to
                    # ride AFTER the ADD, because 0x1075 resolves the unit by
                    # id (0x0504CB30) and writes onto it -- on a miss it
                    # consumes the stream and writes nothing, which is a silent
                    # no-op, not an error.
                    if args.skill_list != "off":
                        skill_list_push(conn, outbound, mode, be, args)
                    # ...and the SKILL BAR, which is a separate thing from the
                    # acquired list: 0x1075 writes [unit+0xA14+id*2] (do I own
                    # it), the palette is eight UI slots the player filled by
                    # double-clicking. Nothing else restores it, so without
                    # this the bar is empty every session -- the same shape
                    # --skill-list fixed for the skill window.
                    # THE PALETTE REPLAY, 2026-09-08: it was gated on
                    # --skill-palette on, and prod runs the default 'request'
                    # -- so the stored bar was never restored and the player
                    # re-set it every session ("my equipped skills did not
                    # persist"). It is now sent in every mode, but NOT here:
                    # both 0x2029 workers deref the HUD singletons with no null
                    # check and the HUD is built after PLAY_START, so it is
                    # HELD until the client's first 28-byte 0x2023 -- the same
                    # beat the war notify waits for -- and sent from there.
                    if getattr(args, "skill_palette", "request") != "off":
                        _SESSION["palette_replay_due"] = True
                add_complete(conn, outbound, mode, be, args)
                if args.add_self == "client":
                    stat_2024_push(conn, outbound, mode, be, args)
                draw_self_push(conn, outbound, mode, be, args)
                # WARNING: NOT INDOORS. A room is a UI scene the player stands in;
                # live 2026-09-05 the arms shop received the field's nine
                # orcs, Bob and the goblin along with the player, because
                # the room rides the war field's gid. Population is for the
                # field, not the shop.
                if _SESSION.get("room", -1) == -1:
                    npc_push(conn, outbound, mode, be, args)
                    monster_push(conn, outbound, mode, be, args)
                    building_push(conn, outbound, mode, be, args)
                    town_push(conn, outbound, mode, be, args)
                    spawn_push(conn, outbound, mode, be, args)
                    door_table_log(args, _SESSION.get("field"))
                else:
                    # indoors only the ROOM's own keepers (town file key
                    # "room:N") -- no field NPCs, monsters, buildings, spawns
                    print("[feworld]    in room %s -- serving its keepers only"
                          % _SESSION.get("room"), flush=True)
                    town_push(conn, outbound, mode, be, args)
                if getattr(args, "unit_physics", "table") == "push":
                    unit_speed_push(conn, outbound, mode, be, args)
                else:
                    # the client's own unit takes walk speed, jump launch and
                    # gravity from the class table (0x0506a5e0 copies rec+0x44/
                    # +0x48/+0x4c into +0x4d4/+0x4dc/+0x4e4); our 1.0 over the
                    # top of that read as "moves so much slower" (run 5).
                    print("[feworld]    --add-self client: no --unit-speed / "
                          "--jump-phys push -- the class table's own values "
                          "stand on the client's unit", flush=True)
                bag_size_push(conn, outbound, mode, be, args)
                # THE STORED EQUIPMENT, RE-APPLIED AFTER THE FIELD IS BUILT.
                # Not in the 0x1000 bag record: setting the marker there made
                # the bag reader's tail equip DURING field entry, which dressed
                # the character over the default outfit and froze movement
                # (live 2026-09-05 #14). Here the avatar already exists and the
                # same Equip call is the client's own mid-session path.
                if getattr(args, "field_items", "bag") in ("on", "bag"):
                    rows = stored_equip_rows(args)
                    rows = [r for r in rows if r[3] is not None]
                    if rows and args.add_self in ("on", "client"):
                        # WARNING: run 5 (2026-09-08): the bag record's markers
                        # dressed the client's unit, and gate 4 STILL read
                        # `NOT IN MANAGER` for the wand in hand. The bag reader
                        # registers each item (0x504cd00) into whatever
                        # [0x5339cc8] holds while 0x1000 is applied -- during
                        # the load, before the field scene stands -- and by the
                        # time a cast looks, that registration is gone. The
                        # 0x107A worker (0x0503d540) does the same lookup ->
                        # construct -> register (0x0503d614) -> Equip, so one
                        # 0x107A per worn item AFTER the field is live puts the
                        # worn objects in the manager the gate walks. HELD for
                        # the first 28-byte 0x2023, with the palette.
                        # (--self-redress: minus the armour already back on)
                        _SESSION["equip_replay_due"] = replay_rows_after_redress(rows)
                    elif rows:
                        equip_reflect_push(conn, outbound, mode, be, args,
                                           rows, "stored equipment, on entry",
                                           "entry")
                stat_probe_push(conn, outbound, mode, be, args)
                stat_probe2_push(conn, outbound, mode, be, args)
                # THE STATE WORD, and with it every skill gate. It rides here
                # rather than earlier because 0x2024's applier resolves the
                # unit by id and does nothing on a miss -- the avatar has to
                # exist first. See unit_state_push.
                unit_state_push(conn, outbound, mode, be, args)
                cast_report_log(args, "on field entry")
                if getattr(args, "unit_physics", "table") == "push":
                    jump_phys_push(conn, outbound, mode, be, args)
                wallet_push(conn, outbound, mode, be, args)
                crystal_push(conn, outbound, mode, be, args)
                # This visit's battle starts at zero; the STORED EXP total
                # rides in behind the wallet so the Status screen shows what
                # the character has already earned (see exp_resume_push).
                battle_reset()
                # WARNING: A DEATH MUST NOT SURVIVE A FIELD ENTRY. Live 2026-09-09:
                # a player died, pressed Return to Base, and came back with
                # the DEAD bit still set and 0 HP -- the revive is driven off
                # the 0x2023 tick and the tick is gated on `in_field`, so it
                # did not run until the next field entry two minutes later.
                # Whatever else is true, arriving in a field means alive.
                if _SESSION.pop("player_dead", False) or "player_hp" in _SESSION:
                    _SESSION["player_hp"] = player_hp_max(args)
                    _SESSION.pop("revive_at", None)
                    if getattr(args, "monster_attack", "off") == "on":
                        player_dead_push(conn, outbound, mode, be, args, False)
                        player_hp_push(conn, outbound, mode, be, args,
                                       player_hp_max(args))
                        print("[feworld]    entering a field ALIVE: HP %d/%d, "
                              "DEAD cleared" % (player_hp_max(args),
                                                player_hp_max(args)), flush=True)
                exp_resume_push(conn, outbound, mode, be, args)
                # skill points (earned by level) and a full Pw gauge -- see
                # the PROGRESSION block
                progress_entry_push(conn, outbound, mode, be, args)
                chat_push(conn, outbound, mode, be, args)
            # WARNING: WE USED TO PUSH 0x1000 MSG_ENTER_AREA_OK HERE. That was wrong,
            # and it is why the live 2026-08-18 run answered with
            # `!!!異常なエンターエリアを受信しました。!!!` and never set the current
            # island. 0x1000 is the ANSWER to the client's own 0x2000
            # MSG_ENTER_AREA, and the client only accepts it after it has armed
            # [player+0x295] = 0xFF by sending that request. See enter_area().
            #
            # --push-enter-area restores the old behaviour for a comparison run;
            # it is off by default because the disassembly says it cannot work.
            if n and args.push_enter_area and not _SESSION.get("entered"):
                _SESSION["entered"] = True
                enter_area(conn, outbound, mode, be, args,
                           _group_id(island, 0, n), 0)
                if args.war != "none":
                    war_notify(conn, outbound, mode, be, args)
            elif n:
                # Remember what we would answer 0x2000 with, and wait for it.
                _SESSION["group"] = _group_id(island, 0, n)
                print("[feworld]    waiting for the client's 0x2000 "
                      "MSG_ENTER_AREA (it must arm itself before 0x1000 is "
                      "accepted); will answer with group=%d"
                      % _SESSION["group"], flush=True)
                # WARNING: SENDING THIS ONCE IS NOT ENOUGH -- IT CAN MISS THE SCREEN.
                # Measured on prod 2026-08-19: feworld sent exactly one 0x1018
                # and the client's log contains NO `MsgType->0x1018` at all,
                # while `MsgType->0x303C` (logged by the SAME handler) appears
                # 795 times. So the frame arrived when no screen was active to
                # receive it and was simply dropped. On 08-18 a single 0x1018 did
                # land -- the difference is timing, not delivery.
                #
                # 0x1018 is the arm that is safe to repeat: per its handler
                # (0x0511843b) it sets war-view [+0x70]=0 and just stores u32_3/
                # u32_4, with no scene transition (that is 0x1019, which must
                # never be sent blind). So push it once per LAP instead of once
                # per session and let it land whenever the screen is up.
                #
                # WARNING: BUT NOT IN-FIELD. Measured live 2026-08-23: the war-prep
                # window polls the group-detail machine every frame WHILE its
                # arm byte [screen+0x62] is set, and clears it when the round
                # trip completes (0x5117c87..0x5117cbe, success log "Island
                # Info was Updated. Open War Prepare Window."). Re-pushing
                # 0x1018 with every 0x4011 answer RE-ARMS +0x62 -- we were
                # feeding the very loop that flooded 0x4011 at frame rate. Push
                # per-lap only BEFORE the field entry; once per entry after.
                # WARNING: AND OUT OF FIELD IT IS STILL UNBOUNDED -- measured on prod
                # 2026-08-24, a brand-new character on its first
                # login sent 3,185 and then 1,401 0x4011 in two sessions, each
                # answered with a fresh 0x1018, never once reaching field entry.
                # The comment above says "push per-lap only BEFORE the field
                # entry" and that is exactly the case with no ceiling: a client
                # that never enters the field re-arms [screen+0x62] forever, at
                # frame rate, and the player sees a black screen.
                #
                # --war-max-laps caps the PRE-FIELD pushes. Default 0 = the
                # unbounded behaviour, deliberately, because per-lap was chosen
                # for a measured reason -- a single 0x1018 can arrive when no
                # screen is up and be dropped (prod 2026-08-19: one sent, zero
                # `MsgType->0x1018` in the client log) -- so a cap trades a
                # known delivery problem for an unknown one and must not become
                # the default until it is measured. It is also NOT established
                # that this loop is what blacks the screen: no working session
                # was captured in the same window to compare against.
                lap_cap = getattr(args, "war_max_laps", 0)
                capped = (lap_cap and not _SESSION.get("in_field")
                          and _SESSION.get("warned", 0) >= lap_cap)
                if capped and not _SESSION.get("war_capped"):
                    _SESSION["war_capped"] = True
                    print("[feworld]    --war-max-laps %d reached out of field: "
                          "no further 0x1018. If the war-prep window now settles "
                          "instead of re-polling 0x4011 every frame, the re-arm "
                          "WAS the loop; if 0x4011 keeps coming, it is not and "
                          "this cap should go back to 0." % lap_cap, flush=True)
                if (args.war != "none" and not capped
                        and (not _SESSION.get("in_field")
                             or not _SESSION.get("war_notified"))):
                    if _SESSION.get("in_field"):
                        _SESSION["war_notified"] = True
                    _SESSION["warned"] = _SESSION.get("warned", 0) + 1
                    war_notify(conn, outbound, mode, be, args)
                    # 0x1015 rides immediately behind the notify that arms the
                    # wait, in the same burst, so the two cannot be separated by
                    # a lap. Once per entry only -- the arm advances a phase, and
                    # re-sending a phase advance every lap is exactly the
                    # re-arming loop the 0x1018 comment above warns about.
                    if (args.war_start == "on" and _SESSION.get("in_field")
                            and not _SESSION.get("war_started")):
                        _SESSION["war_started"] = True
                        war_start(conn, outbound, mode, be, args)
        elif real_id == 0x2018:
            # KEY: MSG_DECIDE_COUNTRY_REQUEST -- THE ARMY CHOICE, and the client
            # asks it the moment the battle actually starts.
            #
            # Measured 2026-08-24 in the client's own debug log (the local
            # per-pid shim log, polshim.<pid>.log -- NOT the shipped
            # shim-<host>.log, which is a different file and cost me a round):
            #
            #     MsgType->0x1015          <- our war-phase advance lands
            #     PLAY_START done.         <- THE GAME STARTS
            #     << MSG_DECIDE_COUNTRY_REQUEST
            #     army choice req sent : 0
            #     [Data\Window\battlestart.tex] Stand-By ok.
            #     nation state: now at war.
            #
            # So the sequence is: answer 0x2084, advance the phase with 0x1015,
            # the client starts the battle -- and then asks us which army it is
            # fighting for and waits. We had never answered.
            #
            # The sender is CWarPrepareWindow's vtable slot +0x7c (0x05118940):
            # it logs both strings above, sets [screen+0x70] = 1 ("request in
            # flight"), and registers exactly two acceptable replies as u16s at
            # 0x05118989/0x05118990 -- 0x1020 OK and 0x1021 NG. Body is one u32,
            # the chosen army; the live wire bytes `20 18 00 00 00 00` are that
            # u32 = 0, which is also what the client's own log line prints.
            #
            # 0x1020's arm (0x05117f15) READS NOTHING -- zero stream-reader
            # calls -- so the OK is header-only, like 0x100E and 0x3016. It
            # clears [screen+0x70], clears scene pending bit 0x80 (0x05117f24),
            # rebuilds the window through vtable +0x74 with (3,0), and sets
            # [screen+0x61] = 0.
            #
            # WARNING: NG (0x1021, arm 0x05117f7c) is NOT the safe default here: it
            # sets [screen+0x68] = -1 and re-sends. Answer OK unless
            # explicitly A/B-ing the refusal path.
            f = inner[2:]
            army = struct.unpack_from(">I", f, 0)[0] if len(f) >= 4 else 0
            if args.decide_country == "off":
                print("[feworld]    0x2018 MSG_DECIDE_COUNTRY_REQUEST army=%d "
                      "-- NOT answering (--decide-country off)" % army, flush=True)
            else:
                mid = 0x1020 if args.decide_country == "ok" else 0x1021
                send(conn, outbound, inner_msg(mid, b"", unit_id_of(args)),
                     mode, be, args.seq_mode == "echo", args.world_prefix)
                print("[feworld] -> 0x30 inner 0x%04X MSG_DECIDE_COUNTRY_%s "
                      "(empty body) for army=%d -- the client asked this right "
                      "after 'PLAY_START done.'; watch its log for the reply and "
                      "for [scene+0x528] bit 0x80 clearing again"
                      % (mid, "OK" if mid == 0x1020 else "NG", army), flush=True)
        elif real_id == 0x2084:
            # KEY: 0x2084 MSG_GET_INFO_OF_PROCLAMATION_OF_WAR_REQUEST [u32 AREA id]
            # -- THE WAR-PREP WINDOW'S OWN 1-SECOND HEARTBEAT, and until now we
            # answered it with nothing at all.
            #
            # It is the war-map screen's vtable slot +0x78 (0x05118900 on vtable
            # 0x528c0b0), fired by the 1s tick at 0x05117cd4 for as long as
            # [screen+0x61] is set -- and the ONLY thing that sets +0x61 is the
            # 0x1018/0x1019 arm at 0x051184de, i.e. OUR war notify. So we armed
            # the poll and then never fed it. Measured live 2026-08-24 in the
            # feworld log: `id=0x2084, 4 bytes of fields  20 84 00 00 00 01`,
            # once a second, no reply, forever.
            #
            # The body is one u32 = [scene+0x4ec] (0x05118910).
            #
            # WARNING: THAT IS THE AREA, NOT THE ISLAND, and this handler called it
            # islandId for two weeks. [scene+0x4ec] is the GROUP/AREA id -- the
            # same word the capital predicate 0x04ff7ef0 tests on entry and the
            # move classifier 0x04ffbad5 bounds against 95. It read as an
            # island because the only frame ever captured said 1, and under
            # --islands 5 --groups 1 the island and its single group BOTH have
            # id 1: the observation could not tell them apart.
            # an earlier note
            #
            # Under --world dat they diverge -- area 39 is on island 3 -- so
            # the poll now names a real field, and a war layer that keys off
            # this must key off the FIELD.
            #
            # THE ANSWER IS 0x1127 MSG_GET_INFO_OF_PROCLAMATION_OF_WAR_OK, and
            # it is reachable: the transport tries three handlers in turn
            # (0x050532f0 -> 0x05023ad0 -> 0x05057d50, each returning al=1 when
            # it consumed the id, chain at 0x0504734b..0x05047394). The main
            # dispatcher's tree drops 0x1127 (0x050549c7 `cmp 0x1123 / jg` ->
            # table 0x5057620 has no entry for it), but the THIRD handler
            # 0x05057d50 takes it: `cmp 0x1089 / jg 0x05058189` -> byte table
            # 0x5058c18 (ids 0x108A..0x1127) slot 0x9d -> arm 0x050581A8.
            #
            # THE BODY IS FOUR u16 (ntohs -- reader 0x5045e30 -> 0x522f970 ->
            # the ws2_32 thunk 0x524d3b0), read in this order at 0x050581af..:
            #
            #     u16 attack_count, u16 defense_count,
            #     u16 attack_max,   u16 defense_max
            #
            # The order is not a guess: the arm logs them through the client's
            # own format string 0x52d5fbc,
            #     ">MSG_GET_INFO_OF_PROCLAMATION_OF_WAR_OK
            #       Attack  [Count %3d / Max %3d]  %08d
            #       Defense [Count %3d / Max %3d]"
            # with args (read1, read3, tick, read2, read4) -- so read1/read3 are
            # the ATTACK pair and read2/read4 the DEFENSE pair.
            #
            # Then, if the scene [0x5336d1c] and the field/war manager
            # [0x5336f74] are both live, it stores all four into the manager via
            # 0x5001c60 -> 0x5001c40 (`[mgr + idx*2 + 0x5c] = u16`):
            #
            #     mgr+0x5c = defense_count   mgr+0x5e = defense_max
            #     mgr+0x60 = attack_count    mgr+0x62 = attack_max
            #
            # -- i.e. the DEFEND pair first, which is the same order as the
            # "Defend n/m vs Attack n/m" the war UI draws. (The manager's other
            # half, [mgr + idx*4 + 0x50] via 0x5001200/0x5001210, is where
            # 0x1018/0x1019's first two u32s land; the war-prep window reads
            # slots 0 and 1 back at 0x051157ff.. and looks each up in the 0xa00-
            # byte record table [0x5336fa8] by `[rec+8] == key` (0x5005560),
            # then draws that record's nation byte [rec+0x1bc] through the
            # per-nation resource table 0x5336fe8 (0x5008680). So those two u32s
            # are RECORD KEYS for the two sides, not counts -- the "Count/Max"
            # reading in war_notify's docstring was inferred from a neighbouring
            # string and is superseded here.)
            #
            # WARNING: UNMEASURED: whether non-zero counts change anything visible. The
            # values are a knob (--war-counts), NOT baked in, and the reply can
            # be turned off wholesale with --proclamation off for a clean A/B.
            f = inner[2:]
            area = struct.unpack_from(">I", f, 0)[0] if len(f) >= 4 else 0
            if args.proclamation == "off":
                print("[feworld]    0x2084 PROCLAMATION-OF-WAR poll area=%d (%s) "
                      "-- NOT ANSWERED (--proclamation off)"
                      % (area, fegamedata.areas().get(area, {}).get("name", "?")),
                      flush=True)
            else:
                atk_c, def_c, atk_m, def_m = args.war_counts
                send(conn, outbound,
                     inner_msg(0x1127,
                               struct.pack(">HHHH", atk_c & 0xFFFF,
                                           def_c & 0xFFFF, atk_m & 0xFFFF,
                                           def_m & 0xFFFF),
                               unit_id_of(args)),
                     mode, be, args.seq_mode == "echo", args.world_prefix)
                _SESSION["proc_polls"] = _SESSION.get("proc_polls", 0) + 1
                if _SESSION["proc_polls"] <= 3 or _SESSION["proc_polls"] % 30 == 0:
                    print("[feworld]    0x2084 PROCLAMATION-OF-WAR poll #%d "
                          "area=%d -> 0x1127 OK Attack[%d/%d] Defense[%d/%d] "
                          "-- expect the client log '>MSG_GET_INFO_OF_"
                          "PROCLAMATION_OF_WAR_OK Attack [Count %d / Max %d]'"
                          % (_SESSION["proc_polls"], area, atk_c, atk_m,
                             def_c, def_m, atk_c, atk_m), flush=True)
        elif real_id == 0x400B:
            # The SIBLING of 0x400A, and it has no name string of its own -- so it
            # is left unnamed here rather than guessed at. Same shape, one state
            # word over: the builder (0x0500956d) sets [obj+0x18] = 2, and the
            # only functions that clear it are 0x5009590 -> 0 and 0x50095a0 -> 1.
            #
            # 0x5009590's sole caller is the THIRD arm of the same dispatcher that
            # answered 0x400A (0x050569ce, reached by `sub 0x3016 / dec / dec`),
            # so its id is 0x3018 -- and that arm reads nothing from the message,
            # so the reply carries no fields. The NG setter is called from
            # 0x5056a30, a different arm, if a failure ever needs serving.
            #
            #     0x3018 = OK for 0x400B, no fields
            #
            # Worth noting the two requests were mapped in one pass: walking that
            # dispatcher once for 0x400A had already produced 0x400B's answer
            # before the client asked for it.
            print("[feworld]    0x400B (no fields) -- the 0x400A sibling, "
                  "unnamed in the image", flush=True)
            send(conn, outbound, inner_msg(0x3018), mode, be,
                 args.seq_mode == "echo", args.world_prefix)
            print("[feworld] -> 0x30 inner 0x3018 (OK for 0x400B, no fields)",
                  flush=True)
        elif real_id == 0x4006:
            # MSG_MOVE_MY_CHARACTER_INFO_TO_AREA_REQUEST [u32 fieldId] -- what
            # the map screen actually sends when the player picks a field
            # (0x04ffb9a0 classifies the transition kind at 0x04ffbad5; kind 0 =
            # this message; kinds 1/2/3 are 0x2017/0x2016/0x20A6). First seen
            # live 2026-08-22, the test player picking "Move to Ruined Plain" on
            # the first map screen ever to render.
            #
            #     0x300C = MSG_MOVE_OK -- NO FIELDS. The arm (0x0505685d in the
            #     compare ladder at 0x0505680d: sub 0x20b2 then sub 0xf5a) reads
            #     nothing, sets [player+0x29a] = 1 (the byte 0x04ffb9a0 armed to
            #     0xFF and polls), runs a socket op on [0x533998c]+0x980 and
            #     queues `/getblacklist <charid>`.
            #     0x300D = MSG_MOVE_NG, [u32 err], sets [player+0x29a] = 0.
            #
            # After the OK the client is expected to walk its own enter-area
            # path (0x2000), which is already answered below.
            f = inner[2:]
            field_id = struct.unpack_from(">I", f, 0)[0] if len(f) >= 4 else 0
            print("[feworld]    MOVE_MY_CHARACTER_INFO_TO_AREA fieldId=%d"
                  % field_id, flush=True)
            send(conn, outbound, inner_msg(0x300C), mode, be,
                 args.seq_mode == "echo", args.world_prefix)
            print("[feworld] -> 0x30 inner 0x300C MSG_MOVE_OK (no fields)",
                  flush=True)
        elif real_id == 0x4014:
            # TUTORIAL END, [u32 charid] -- fire-and-forget (the builder at
            # 0x051333d0 registers no replies, so nothing is owed on the wire).
            # The map screen sends it from 0x05105a73 alongside its own log line
            # "チュートリアル終了" (0x52e5d1c) and sets the tutorial-done global
            # 0x52d3a88 = 1 locally. The FIRST world entry is the tutorial: the
            # 0xD008 DECIDE_CHARACTER_OK trailing u8 seeds that global, and 0
            # routes mode 8 into the tutorial map variant, which ends -- by
            # design -- with the client exiting back to the Viewer after its
            # field pick ("please wait" -> clean GameStart return). Persist the
            # flag so felobby serves u8=1 next login and the client boots the
            # NORMAL map instead of replaying the tutorial forever.
            f = inner[2:]
            t_charid = struct.unpack_from(">I", f, 0)[0] if len(f) >= 4 else 0
            if _store_char_field(args, "tutorial", 1):
                print("[feworld]    TUTORIAL END charid=%d -- persisted "
                      "tutorial=1; next login serves 0xD008 u8=1 (normal map)"
                      % t_charid, flush=True)
            else:
                print("[feworld]    TUTORIAL END charid=%d -- NO stored "
                      "character matched; flag NOT persisted" % t_charid,
                      flush=True)
        elif real_id == 0x4012:
            # MSG_JOIN_FORCE_REQUEST -- "registering nation". Built at 0x05005697
            # as a single dword, logged by the client as
            # `< MSG_JOIN_FORCE_REQUEST ForceID = %d` (0x52d2f7c), and its
            # registration two instructions earlier (0x0500567d) names the only
            # two answers: 0x3033 OK / 0x3034 NG.
            #
            #     0x3033 = MSG_JOIN_FORCE_OK, NO FIELDS AT ALL
            #
            # The OK arm (0x050057ec) reads nothing: it sets the screen's result
            # word [esi+0x54] = 0 and logs `> MSG_JOIN_FORCE_OK`. The NG arm
            # (0x0500580e) is the one that takes a payload -- a u32 error code it
            # resolves to a message via 0x5061290(0x3034, code) -- and sets
            # [esi+0x54] = 1. Both live in the same dispatcher as GET_FORCE_INFO
            # (id - 0x3027 through the tables at 0x5005958 / 0x5005944).
            f = inner[2:]
            force_id = struct.unpack_from(">I", f, 0)[0] if len(f) >= 4 else 0
            name = args.force_table.get(force_id, {}).get("name", "?")
            print("[feworld]    JOIN FORCE ForceID=%d (%s)" % (force_id, name),
                  flush=True)
            send(conn, outbound, inner_msg(0x3033), mode, be,
                 args.seq_mode == "echo", args.world_prefix)
            print("[feworld] -> 0x30 inner 0x3033 MSG_JOIN_FORCE_OK (no fields)",
                  flush=True)
            # PERSIST THE CHOICE. Asked outright -- "not sure if it saves it for
            # real". It did not; now it does, into the same character store
            # felobby keeps, keyed by the account and charid that arrived in
            # 0x400F.
            #
            # The 0xD002 field that carries this back IS established now: it is
            # `force` (wire u32 -> [rec+0x30], read at 0x0502513d; CHAR_FIELDS in
            # felobby). The nation-prompt decision is scene mode 6 (0x04ffc7d0):
            # [rec+0x30] == 0 or 0x7FFFFFFF -> mode 7 shows the NationSelect
            # screen; ANY other value skips the prompt and goes straight to the
            # map (mode 8). So a persisted choice really does suppress the
            # prompt on the next login -- and a STALE persisted choice is why
            # "the join-nation flow never runs": the client was told it had
            # already joined.
            if _store_char(args, force_id):
                print("[feworld]    saved nation ForceID=%d for %r/charid=%s "
                      "-- served back as 0xD002 `force`, so the nation prompt "
                      "will be SKIPPED on the next login"
                      % (force_id, _SESSION.get("account"),
                         _SESSION.get("charid")), flush=True)
        elif real_id == 0x2000:
            # 🔵 THE MESSAGE THE WORLD DOOR HAS BEEN WAITING FOR.
            #
            #     C->S 0x2000 MSG_ENTER_AREA [u32 areaId]
            #
            # Built at 0x0505e600: it logs `Send : MSG_ENTER_AREA %d`
            # (0x52d6564), pre-registers ids[0]=0x1000 / ids[1]=0x1001 at
            # 0x0505e62e-0x0505e635, writes the area id as one dword (0x5045be0)
            # and flushes. Its caller, the driver at 0x04ff6a30, has ALREADY set
            # [player+0x295] = 0xFF by the time this lands, which is the only
            # state in which the 0x1000 handler (0x04ff80d0) will do anything.
            #
            # Answering it is therefore the ONLY route to a non-negative current
            # island, and so to the war-prepare window.
            f = inner[2:]
            area = struct.unpack_from(">I", f, 0)[0] if len(f) >= 4 else 0
            print("[feworld]    *** 0x2000 MSG_ENTER_AREA area=%d (%d body "
                  "bytes) -- the client armed itself; 0x1000 is now accepted"
                  % (area, len(f)), flush=True)
            if args.capture_only:
                print("[feworld]    --capture-only: NOT answering", flush=True)
                continue
            # Answer with the group the CLIENT asked for, not the last island the
            # sweep happened to poll. Measured live 2026-08-22: the first-ever
            # 0x2000 carried area=1 (the picked field, "Ruined Plain") and the
            # stale _SESSION leftover answered group=5 -- entering the player
            # into the wrong island. The area id is the group/field id the map
            # screen resolved; trust it when it is a group we serve.
            n = max(1, args.groups)
            # (this hardcoded island 5 until 2026-09-04; --islands is the count)
            served_max = _group_id(max(1, args.islands), n - 1, n)
            # KEY: AND THAT BOUND IS THE PRE-`dat` NUMBERING (2026-09-12, live).
            # --islands defaults to 5 and --groups to 1, so served_max is FIVE
            # -- while `--world dat` announces all 95 real area ids on the map
            # screen. The test player clicked Rhinelay Valley (area 84, island 6),
            # 84 failed `1 <= area <= served_max`, and the fallback below
            # answered with _SESSION["group"] = _group_id(6, 0, 1) = 6, so the
            # client was told it had entered group 6 -- Schelln Greenwood --
            # while its own loader had already put Rhinelay Valley's terrain on
            # screen. "It says I'm in Schelln Greenwood, but I clicked Rhinelay
            # Valley and the environment is Rhinelay Valley."
            #
            # The right test is the set we actually ANNOUNCED, from the same
            # function that builds the map answer. The synthetic bound stays as
            # the fallback for a world that is not dat-driven.
            served = set()
            try:
                for _i in range(1, max(1, int(args.islands)) + 1):
                    served |= set(group_ids_for(_i, args))
                if world_from_dat(args):
                    served |= set(fegamedata.areas())
            except Exception:                          # noqa: BLE001
                served = set()
            # A capital id is far above served_max (21..95 vs 1..5), so without
            # this the client's own pick was silently rerouted to a war field
            # and the capital could never be entered no matter what we announced.
            announced_caps = {g for gs in _CAPITALS.values() for g in gs}
            room = None
            if area in announced_caps or area in CAPITAL_GROUP_IDS:
                group = area
                print("[feworld]    area %d is a CAPITAL (%s) -- entering it. "
                      "The client's predicate 0x04ff7ef0 will take the capital "
                      "branch (0x5001d70) and load %s instead of Data/Hmap."
                      % (area,
                         "announced" if area in announced_caps else
                         "NOT announced on the map screen, but the client knows "
                         "it and we only get here by having sent the player "
                         "ourselves -- a door or a !goto",
                         CAPITAL_MAP.get(area, "DATA/capital/*.oct")),
                      flush=True)
            elif area in served or 1 <= area <= served_max:
                group = area
                if area not in served and area <= served_max:
                    print("[feworld]    (area %d passed the synthetic bound "
                          "%d, not the announced set)" % (area, served_max),
                          flush=True)
            elif (ROOM_AREA_BASE <= area < ROOM_AREA_BASE + 0x100
                  and _SESSION.get("field") is not None):
                # KEY: A DOOR DESTINATION we handed out in 0x1166 (see
                # ROOM_AREA_BASE). Enter the room on the island's war-field
                # gid -- the capital's own id would load the town again --
                # and remember the field to come back OUT to.
                room = area - ROOM_AREA_BASE
                outside = _SESSION["field"]
                island = next((i for i in range(1, int(args.islands) + 1)
                               if outside in group_ids_for(i, args)), 1)
                group = _group_id(island, 0, n)
                _SESSION["outside"] = outside
                print("[feworld]    area 0x%X = DOOR into room %d (%s) -- "
                      "entering it on gid %d (island %d); the exit returns "
                      "to field %d" % (area, room, room_label(room), group,
                                       island, outside), flush=True)
            elif area == 0xFFFFFFFF and _SESSION.get("field") is not None:
                # KEY: THE ROOM EXIT, measured live 2026-09-04: walking out of
                # the arms shop's door the client sent 0x2017 MOVE_FIELD -1
                # and then 0x2000 area=-1 (the transition classifier at
                # 0x04ffbad5 makes -1 kind 1 because it equals the -1 we serve
                # at [scene+0x4e8]). We answered with --field-rooms' shop
                # again and put the player straight back inside. -1 is "out":
                # the same group, forced OUTDOORS (room -1) -- or the capital
                # loader, which wins on the id anyway.
                group = _SESSION.pop("outside", None) or _SESSION["field"]
                room = -1
                print("[feworld]    area -1 = LEAVING the room -> back to "
                      "group %d outdoors (was room %s)"
                      % (group, _SESSION.get("room")), flush=True)
            else:
                group = _SESSION.get("group") or _group_id(1, 0, n)
                print("[feworld]    WARNING: area %d (0x%08X) is not a served group, "
                      "an announced capital or -1 -- falling back to group %d. "
                      "If this followed walking into a DOOR, this number is "
                      "the door protocol: record it."
                      % (area, area, group), flush=True)
            # WARNING: 0xE00D IS NOT THE EXIT FIX -- DISPROVEN LIVE 2026-08-23.
            # Two runs (0xE00D before AND after 0x1000): the client exits
            # identically. The "cannot leave field in this state" log the
            # before-order produced PROVES 0xE00D decodes and dispatches, but
            # the exit is independent of it. The 0x1000 handler (0x04ff80d0,
            # re-read end to end) resolves group->island, sets the current
            # field, and returns cleanly -- no exit path -- and the field
            # asset loader (mode 0xa substate 3: building.pak/common2.pak/
            # monster00.pak) never even starts. GameStart returns right after
            # `erase >>> 0x2000`, before the next enter-area poll. So the exit
            # is GameStart completing the map phase, which is the memory's
            # original relaunch/field-boot frontier -- NOT a missing message.
            #
            # 0xE00D is left in as an off-by-default knob (it may belong in the
            # field/battle phase we haven't reached). When enabled, send it
            # AFTER 0x1000 so [scene+0x4ec] is already the entered field and
            # the arm takes the clean same-field path instead of tripping the
            # leave-field guard.
            enter_area(conn, outbound, mode, be, args, group, area, room=room)
            # THE GROUP ACTUALLY ENTERED. `group` above (the 0x4011 leftover)
            # is what we WOULD answer with and is rewritten every lap; this is
            # what war_notify's capital guard reads.
            _SESSION["field"] = group
            # A new field is a new set of monsters: the registry npc_send fills
            # is keyed by object id, and ids are re-used across fields.
            # KEY: SHARED (2026-09-13): outdoors the registry IS the field's --
            # one set for every player in it (field_mobs); spawn_push shows it
            # to this client and mobs_shown opens the relays to it.
            _SESSION.pop("mobs_shown", None)
            if (mobs_shared(args) and room == -1
                    and group not in CAPITAL_GROUP_IDS):
                _SESSION["mobs"] = field_mobs(group)["mobs"]
                _SESSION["mobs_field"] = int(group)
            else:
                _SESSION["mobs"] = {}
                _SESSION.pop("mobs_field", None)
            # The NEXT 0x4011 the client sends is mode 0xb substate 1 (post
            # field entry) -- the trigger for 0x100E MSG_ADD_COMPLETE.
            _SESSION["in_field"] = True
            _SESSION["add_complete_sent"] = False
            # arm the EXP-threshold seed: the client builds its own unit AND
            # its HUD while the field loads, and the HUD's exp gauge caches
            # [unit+0x135c] at construction. See exp_max_seed_pump.
            _SESSION["exp_max_seed_left"] = int(
                getattr(args, "exp_max_seed", 8) or 0)
            exp_max_seed_pump(conn, outbound, mode, be, args)
            _SESSION["war_notified"] = False
            # KEY: FIELD NOT READY YET (2026-09-11). The client mounts
            # Data\building.pak inside its field-load phase machine (singleton
            # 0x5349800, phase [+0x39]; the mount is 0x04ff97a1). That finishes
            # DURING field load, before the first 28-byte 0x2023 clock sample.
            # A type-1 building pushed BEFORE the mount completes loads its
            # models from an unmounted pak -- the `_stand.mdl` comes back "not
            # found" and the building's update derefs the NULL model at
            # 0x05071531 (`[[obj+0x84]+0x2bd]`). Live 09-11 that was the crash
            # on the SECOND war field of a session, where the placement raced
            # ahead of the remount; the first field happened to win the race.
            # So keeps (like worn items) wait for field_ready -- see the first
            # clock-sample handler.
            _SESSION["field_ready"] = False
            # WARNING: AND THE GRACE CLOCK WITH IT (2026-09-12, live regression).
            # field_ready_pump counts --field-ready-ms from add_complete_at,
            # and on a SECOND field entry that stamp still held the PREVIOUS
            # field's 0x100E -- already many seconds old. So the batch fired
            # the moment this field's 0x2000 armed, 2.5 s BEFORE its own
            # 0x100E, and the 0x107A Equip landed DURING field load: the
            # player's character could not move in the second area. That is
            # the 2026-09-05 #14 freeze exactly ("equip DURING field entry ...
            # dressed the character over the default outfit and froze
            # movement"), reintroduced by a stamp that was set but never
            # cleared. The pump is a no-op while this is absent.
            _SESSION.pop("add_complete_at", None)
            # 15 s of protection after an area move [SE interface05]; the new
            # unit carries no INVINCIBLE bit of ours yet.
            _SESSION.pop("protect_flag_sent", None)
            spawn_protect_start(args, "an area move (field entry)")
            # A new field is a new war. (CHOSEN: war_started used to persist
            # across re-entries, which is why `!war` said "re-enter to do it
            # again" and then could not.)
            _SESSION["war_started"] = False
            # WARNING: `clock_synced` IS NOT HERE ANY MORE (2026-09-12): the 0x1148
            # base lives as long as the CONNECTION (only the RESUME sequence
            # zeroes it), so re-arming it per entry re-sent it per entry --
            # and the re-send was computed from a clock that already carried
            # the first base, so it came out ~0 and put the clock BACK ~56
            # years. See clock_sync_push.
            for k in FIELD_ENTRY_CLOCK_CLEAR:
                _SESSION.pop(k, None)
            # 0x1027 MUST follow 0x1000: it releases mode 0xa substate 2, which
            # only starts waiting once the enter-area round trip has armed it.
            # Without this the client parks there forever -- assets loaded, field
            # never built, black screen. See set_position().
            if args.set_position:
                set_position(conn, outbound, mode, be, args)
            if args.move != "none":
                move_character(conn, outbound, mode, be, args, group)
            # The blacklist the player left with, restored before they can open
            # the window. 0x1163 is a whole-list PUT and the client is in the
            # field by now, so this is the natural place for it.
            if args.blacklist == "on" and blacklist_rows(args):
                blacklist_send(conn, outbound, mode, be, args)
            if args.char_record != "off":
                char_record_push(conn, outbound, mode, be, args)
            if args.status != "off":
                status_push(conn, outbound, mode, be, args)
            for _cmd in args.gmcmd or []:
                gm_command(conn, outbound, mode, be, args, _cmd)
            # The war notify already went out with the group detail -- see the
            # note there on why it is not gated on this message.
        elif real_id == 0x2017:
            # KEY: 0x2017 MSG_MOVE_FIELD_REQUEST [u32 fieldId] -- THE CLIENT ASKING
            # TO LEAVE THE DUMMY AREA FOR THE REAL FIELD, and the first question
            # it has ever put to us that we could answer.
            #
            # Reaching this at all is what 0x1027 unlocked. Mode 0xa's branch
            # takes the DUMMY arm when [scene+0x4e8] == [scene+0x4ec] (0x4ff7eb0
            # via 0x04ff9d03; the [scene+0x2ac] escape at 0x04ff9d0e is dead --
            # +0x2ac's only writer sets it to 1 and nothing clears it). We send
            # area and group as the SAME number, so it always dummies.
            #
            # WARNING: THAT IS NOT A FAILURE. The dummy arm is a staging area: it logs
            # "entered the dummy area", resets the substate and sets mode 0xd
            # (0x4ff73e0 zeroes +0x38..+0x3b and writes +0x3c = 0xd), then sends
            # THIS request (0x4ff9d3f -> 0x5128900) and waits. The client is
            # driving its own way to the real field and we were leaving it
            # hanging.
            #
            # THE REPLY IS EMPTY. Arm 0x5054af3 (id 0x1012, byte table slot 8)
            # makes ZERO stream reads: it logs "> MSG_MOVE_FIELD_REQUEST_OK",
            # sets [scene+0x29a]=1, calls 0x4ff84e0(scene, 0x4000) and
            # 0x4ffef90(0), then needs [0x533998c] and [+0x980] non-null (a null
            # there is a silent drop, not a crash). 0x1013 is the NG and DOES
            # read a u32 error code (0x5054b62), which it feeds to the error
            # string table via 0x5061290 -- so OK and NG are not symmetric, and
            # an empty 0x1013 would desync.
            f = inner[2:]
            want = struct.unpack_from(">I", f, 0)[0] if len(f) >= 4 else 0
            if args.move_field == "ok":
                send(conn, outbound, inner_msg(0x1012, b"", unit_id_of(args)),
                     mode, be, args.seq_mode == "echo", args.world_prefix)
                print("[feworld]    0x2017 MOVE_FIELD_REQUEST field=%d -> 0x1012 "
                      "OK (empty body) -- the client asked to leave the dummy "
                      "area for the real field" % want, flush=True)
            elif args.move_field == "ng":
                send(conn, outbound,
                     inner_msg(0x1013, struct.pack(">I", args.move_field_err),
                               unit_id_of(args)),
                     mode, be, args.seq_mode == "echo", args.world_prefix)
                print("[feworld]    0x2017 MOVE_FIELD_REQUEST field=%d -> 0x1013 "
                      "NG err=%d" % (want, args.move_field_err), flush=True)
            else:
                print("[feworld]    0x2017 MOVE_FIELD_REQUEST field=%d -- NOT "
                      "ANSWERED (--move-field none); the client will sit in the "
                      "dummy area" % want, flush=True)
        elif real_id == 0x20AC:
            # KEY: THE DOOR. Live 2026-09-05: a player walked into one of
            # the capital's minimap doors and the client sent [f32 x][f32 y]
            # [f32 z] = (186.5, 0.003, -132.5), the door's own position, with
            # nothing else on the wire -- no building object was needed. Its
            # builder (0x04ffbc40) registers exactly one reply, 0x1166, and
            # marks the request in flight at [screen+0x62]; until an answer
            # lands no door in the field fires again, which is why the
            # second door was as dead as the first.
            #
            # THE ANSWER is where the door leads -- see ROOM_AREA_BASE for
            # what 0x1166's arm does with it. Doors are matched by position
            # against --door entries (the client tells us where the door is,
            # so mapping them is a matter of touching each one and reading
            # this log line); an unmapped door opens --door-default.
            f = inner[2:]
            x, y, z = (struct.unpack_from(">fff", f, 0) if len(f) >= 12
                       else (0.0, 0.0, 0.0))
            field = _SESSION.get("field")
            # WARNING: THE LATCH FIRST. If the player is still standing on the
            # arrival a door just gave them, this touch is that same door
            # firing again, not a new one -- answering it is the loop.
            if field is not None and not door_latch_ok(args, field, x, z):
                print("[feworld]    0x20AC door at (%.1f, %.1f) in field %s "
                      "IGNORED -- the player has not left the arrival point "
                      "they were just put on. Walk away from the doorway and "
                      "it arms again." % (x, z, field), flush=True)
                send(conn, outbound, inner_msg(0x1167, struct.pack(">I", 4),
                                               unit_id_of(args)),
                     mode, be, args.seq_mode == "echo", args.world_prefix)
                continue
            room = town_door_for(args, field, x, z) if field is not None else None
            how = "mapped (--door / town file)"
            _SESSION["last_door"] = (field, x, z)
            # A `!link` row wins over everything: it is the admin having
            # WALKED both sides, so it carries an arrival position and the
            # shipped table does not know about it at all.
            # WARNING: IS THE DESTINATION A ROOM OR AN AREA? Until 2026-09-10 that
            # was inferred from the NUMBER -- inside the client's room window
            # (9..30) meant room, outside meant group -- and room indices and
            # area ids OVERLAP. So a shipped door pointing at AREA 21 (a
            # capital!) was read as "room 21", hit the empty-room guard, and
            # the player got MSG_GOTO_SEARCH_NG and stood there. The same door
            # in the other direction pointed at area 91, which is outside the
            # window, and worked -- which is why it failed one way only.
            #
            # Provenance settles it: fet_area_portal and a `!link` row are
            # AREAS by construction. Only a `--door`/`!door` row is ambiguous,
            # and there the 9..30 convention is what the command documents.
            dat_pos, dest_is_area = None, False
            via = None
            face = None
            if field is not None:
                lk = town_link_for(args, field, x, z)
                if lk is not None:
                    room, dat_pos = lk
                    dest_is_area = True
                    how = "!link (walked, both ways)"
            # The shipped table answers with an ARRIVAL POSITION too -- SE's
            # own spot on the other side of the door, not the group's default
            # spawn. A hand-mapped --door row still wins: it is the admin
            # saying "this door goes here", and a capital's town file may map
            # a door the shipped table does not have.
            if room is None and field is not None:
                hit = dat_door_for(args, field, x, z, y)
                if hit is not None:
                    room, dat_pos, via, face = hit
                    dest_is_area = True
                    how = "dat.pak fet_area_portal (--doors dat)"
            if room is None:
                room = getattr(args, "door_default", None)
                how = "UNMAPPED -> --door-default"
            print("[feworld]    *** 0x20AC DOOR touched at (%.1f, %.3f, %.1f) "
                  "in field %s -> %s: room %s (%s). To map it: `!door ROOM` "
                  "now, or --door %s:%.1f:%.1f:ROOM"
                  % (x, y, z, field, how, room,
                     room_label(room) if room is not None else "-",
                     field, x, z), flush=True)
            if room is None or field is None:
                # 0x1167 [u32 err] -- code 4 is the client's own "system
                # error / database" text; it also clears the in-flight flag
                # so the door can be tried again.
                send(conn, outbound, inner_msg(0x1167, struct.pack(">I", 4),
                                               unit_id_of(args)),
                     mode, be, args.seq_mode == "echo", args.world_prefix)
                print("[feworld] -> 0x30 inner 0x1167 MSG_GOTO_SEARCH_NG err=4 "
                      "(no room for this door; --door-default is unset)",
                      flush=True)
                continue
            # WARNING: NEVER SEND A PLAYER INTO A ROOM THEY CANNOT LEAVE. A room has
            # no door of its own -- inside one the client sends nothing at all
            # at its door -- so the ONLY way out is talking to somebody
            # (--room-exit) or a hand-typed !goto. --door-default is 10 in
            # prod, and room 10 has no keeper, so touching any unmapped door
            # would have dropped the player into an empty room with no exit and
            # held them there until the 120 s read window closed the session.
            # That is the tavern trap of 2026-09-06 with a stranger's door
            # instead of a stranger's dialogue.
            #
            # The refusal is the door's own NG, which clears the in-flight flag
            # so the next door still works, and the log says exactly what to do
            # about it. `!goto room:N` still goes anywhere: this guards the
            # path a player can walk into by accident, not the admin's lever.
            # KEY: A DOOR MAY LEAD TO ANOTHER GROUP, NOT JUST A ROOM. The
            # client's own capital table (0x052D1880, stride 0x24, its last
            # dword the GROUP ID) says every capital ships as TWO map files
            # under TWO group ids -- 91 = map00_00 and 39 = map00_01, 92/57 for
            # map01, 62/93 for map02, 94/78 for map03, 95 for map04_00 -- with
            # the SAME street layout and DIFFERENT shop icons baked into each
            # one's minimap. So a door in a capital plausibly leads to the
            # other half of that capital rather than into a shop interior, and
            # until now `!door N` could only ever say "a room".
            #
            # Same convention the event `goto:N` parser uses: inside the
            # client's room-switch window (9..30) it is a ROOM, anything else
            # is a group id. Hypothesis of 2026-09-06, and the table is
            # what makes it testable.
            if dest_is_area or int(room) not in ROOM_INDEX_WINDOW:
                print("[feworld]    door -> GROUP %d (not a room: %d is outside "
                      "the client's room-switch window %d..%d). No keeper check "
                      "applies -- a group is a whole field, not a room with one "
                      "way out." % (room, room, ROOM_INDEX_WINDOW[0],
                                    ROOM_INDEX_WINDOW[-1]), flush=True)
                goto_push(conn, outbound, mode, be, args, int(room),
                          pos=dat_pos, via=via, face=face)
                continue
            # WARNING: Only when a town file is actually configured. Without one no
            # room can have a keeper, so an unconditional check would refuse
            # every door on a server that simply does not author rooms.
            keepers = town_get(args, "room:%d" % int(room), "npcs")
            if (town_path(args) and not keepers
                    and getattr(args, "room_exit", "conversation") != "off"):
                send(conn, outbound, inner_msg(0x1167, struct.pack(">I", 4),
                                               unit_id_of(args)),
                     mode, be, args.seq_mode == "echo", args.world_prefix)
                print("[feworld] -> 0x30 inner 0x1167 MSG_GOTO_SEARCH_NG err=4 "
                      "-- REFUSED: room %d (%s) has nobody in it, and a room "
                      "has no door of its own, so this would trap the player "
                      "until the read window closed the session. Put a keeper "
                      "in it first (`!goto room:%d`, then `!npc MODEL "
                      "event=say:...;goto:%s`), or map this door somewhere "
                      "else with `!door N`."
                      % (room, room_label(room), room,
                         _SESSION.get("field")), flush=True)
                continue
            goto_push(conn, outbound, mode, be, args, ROOM_AREA_BASE + int(room))
        elif real_id == 0x2046:
            # MSG_NPC_EVENT_ACTION_REQUEST -- the player TALKED to an NPC.
            # Builder 0x05153580: [u32 npc unit id][u32], registers 0x1071 OK /
            # 0x1072 NG. See THE EVENT VM (event_step) for the conversation.
            f = inner[2:]
            npc = struct.unpack_from(">I", f, 0)[0] if len(f) >= 4 else 0
            rows = town_get(args, town_key(), "npcs")
            idx = npc - (int(getattr(args, "monster_base", 400)) + 100)
            who = rows[idx] if 0 <= idx < len(rows) else {}
            steps = (event_script_for(args, who)
                     if getattr(args, "events", "on") == "on" else [])
            script = int(who.get("script") or 0) if steps else 0
            print("[feworld]    0x2046 NPC_EVENT_ACTION npc=%d -- %s -> %s"
                  % (npc, "%s (dat.pak script %s)" % (who.get("name") or "unnamed",
                                                     who.get("script", "?"))
                     if who else "not a town-file NPC",
                     "%d-step event, D=%d" % (len(steps), script) if steps
                     else "no event (D=0)"), flush=True)
            send(conn, outbound,
                 inner_msg(0x1071, struct.pack(">IHHI", npc, 0, 0, script),
                           unit_id_of(args)),
                 mode, be, args.seq_mode == "echo", args.world_prefix)
            if not steps:
                # LIVE 2026-09-05: D=0 alone LEFT THE CLIENT IN TALK MODE (bit
                # 1 of the UI-mode word, set by the 0x2046 builder; the door
                # builder 0x04ffbb50 bails on it). The event END arm 0x1175
                # (0x05056039) clears it -- NOT 0x1172, whose arm LOCKS.
                send(conn, outbound, inner_msg(0x1175, b"", unit_id_of(args)),
                     mode, be, args.seq_mode == "echo", args.world_prefix)
                print("[feworld] -> 0x30 inner 0x1175 event END (no script) -- "
                      "releases the talk-mode bit", flush=True)
            else:
                _SESSION["event"] = {"npc": npc, "script": script, "steps": steps,
                                     "pc": 0, "name": who.get("name", "")}
                print("[feworld] -> 0x30 inner 0x1071 D=%d -- the client's event "
                      "starter 0x5173f70 now sends 0x20A7/0x20A8; the first "
                      "command follows 0x20A7" % script, flush=True)
        elif real_id == 0x20A7:
            # The event starter's request (0x5173f70): [u32 npc][u32 D],
            # registering 0x1172/0x1173. The cue for the first command;
            # 0x1172 goes out when the script is exhausted.
            f = inner[2:]
            print("[feworld]    0x20A7 event start body=%s" % f.hex(), flush=True)
            # WARNING: LIVE 2026-09-05 #6: the shop opened, listed all four pages,
            # and the client sat on "waiting..." with every reply consumed
            # (its own log: four `erase >>> 0x204a`, nothing after). The
            # starter 0x5173f70 REGISTERS 0x1172/0x1173 as 0x20A7's reply in
            # the pending table (0x535cec8); an entry never erased is the
            # "waiting..." overlay -- the unanswered door showed the same.
            # 0x1172 is the START acknowledgement: its arm is 0x5055f70 (the
            # dispatcher table maps it there, NOT to 0x5056039 as first read)
            # and it ENTERS EVENT MODE: scene flag 0x4000, byte 0x53378f3 = 1,
            # the manager's modal bit, [mgr+0x94] slot 32 -- the player is
            # locked for the conversation, as SE intended. Zero stream reads.
            # The release is 0x1175 (arm 0x5056039), sent after the close OK.
            send(conn, outbound, inner_msg(0x1172, b"", unit_id_of(args)),
                 mode, be, args.seq_mode == "echo", args.world_prefix)
            ev = _SESSION.get("event")
            print("[feworld] -> 0x30 inner 0x1172 event START OK (header-only; "
                  "erases 0x20A7's pending entry)%s"
                  % ("" if ev else " (no event in flight)"), flush=True)
            if ev and ev["pc"] == 0:
                event_step(conn, outbound, mode, be, args)
        elif real_id == 0x20A8:
            # The per-command ACK (0x5173fd0): [u32 a][u16 b][u32 c]. The
            # dialogue window sends (id, 6, 0) on click-through; the choice
            # menu is expected to put the pick in one of them -- LOGGED so the
            # first live menu names the slot. Each ack advances one command.
            f = inner[2:]
            a = struct.unpack_from(">I", f, 0)[0] if len(f) >= 4 else 0
            b = struct.unpack_from(">H", f, 4)[0] if len(f) >= 6 else 0
            c = struct.unpack_from(">I", f, 6)[0] if len(f) >= 10 else 0
            ev = _SESSION.get("event")
            print("[feworld]    0x20A8 event ACK a=%d b=%d c=%d%s"
                  % (a, b, c, " -- step %d of %d acknowledged"
                     % (ev["pc"], len(ev["steps"])) if ev else " (no event)"),
                  flush=True)
            if ev:
                if ev["pc"] == 0 and ev.get("started") is None:
                    ev["started"] = True          # the starter's own ack
                elif ev.get("in_window"):
                    # The window's (npc, 8, 0) ack is sent by its CLOSE routine
                    # (the shop's 0x50f00c0: release the list, 0x2085, this
                    # ack, hide, [mgr+0xe0]=0) -- it means CLOSED, and the
                    # interpreter now wants the next command: the END WINDOW
                    # (scripts carry it; see event_script_for). WARNING: LIVE #1
                    # and #4: a 0x1172 here stuck the client both times.
                    ev["in_window"] = False
                    _SESSION.pop("shop", None)
                    _SESSION.pop("bank_open", None)
                    print("[feworld]    (the window closed; next command)",
                          flush=True)
                    event_step(conn, outbound, mode, be, args)
                else:
                    ev.setdefault("acks", []).append((a, b, c))
                    if ev.get("await_menu") is not None:
                        # a choice menu is up: this ack is its pick
                        event_menu_pick(ev, a, b, c)
                    event_step(conn, outbound, mode, be, args)
        elif real_id == 0x2085:
            # An event window's CLOSED notify: [u32 mode], registers nothing.
            # Sent by the shop's close 0x50f00c0 (after ReleaseItemListData,
            # before its (npc, 8, 0) ack), the bank's 0x50ecf80 and the
            # box's slot-30 routine 0x50c74c0. Two earlier readings were
            # wrong: it is NOT the dialogue box closing under a new window,
            # and the box does NOT sit at [mgr+0xe8] swallowing the shop's
            # replies (the 0x1102 arm 0x0502409e tries +0xe8, else +0xe0;
            # +0xe8 is the bank-style window that clears it at 0x50ecfd3).
            # So nothing is held on its account any more; the ack that
            # follows it advances the event.
            f = inner[2:]
            ev = _SESSION.get("event")
            _SESSION.pop("bank_open", None)     # its replies deref the window
            print("[feworld]    0x2085 event window closed body=%s%s"
                  % (f.hex(), " (its 0x20A8 ack cues the next command)"
                     if ev else " (no event)"), flush=True)
        elif real_id == 0x2099:
            # never seen INSIDE the envelope live -- the client sends it as a
            # bare outer frame (see conversation_close); kept for symmetry
            conversation_close(conn, outbound, mode, be, args, inner[2:], "inner")
        elif real_id == 0xE00F:
            # The client's NACK for a 0xE00D MOVE order (arm 0x50573a8): sent
            # when a second order arrives while [scene+0x84] is still armed.
            #     [u32 token][u32 0]
            f = inner[2:]
            tok = struct.unpack_from(">I", f, 0)[0] if len(f) >= 4 else 0
            print("[feworld]    0xE00F MOVE NACK token=%d -- the client "
                  "already holds an unconsumed 0xE00D; do not resend until "
                  "mode 0xb clears it" % tok, flush=True)
        elif real_id == 0x204B and _SESSION.get("shop") and args.ui_auto != "off":
            # MSG_BUY_SHOP_ITEM [u32 shop][u32 item number][u16 count]
            # (0x50ee970; live #8: 000001f4 00000213 0001 = wand x1). The
            # reply 0x107D is header-only (arm 0x05023e19 reads nothing) and
            # the client then asks 0x204D -> 0x1082.
            #
            # RETRACTED 2026-09-05: "NOTHING delivers the item live / no
            # incremental item-add message exists". 0x107A DOES -- one item,
            # add or remove, into a named bag slot (worker 0x0503d540, the same
            # per-item reader 0x0503d280 the 0x1000 bag record uses). That
            # claim came from noticing 0x1000's bag reader has a single caller
            # and concluding no other path existed, without decoding the second
            # field dispatcher's jump table. The purchase is still STORED here
            # -- delivering it live also needs a free bag slot chosen the way
            # the client would, which the store does not model yet -- but the
            # channel is no longer missing. See item_add_body.
            #
            # VERIFIED: DELIVERED LIVE SINCE 2026-09-06. The store half was right and
            # the missing half was the same one Sort and Stack were missing: the
            # OK is an acknowledgement (arm 0x05023E19 reads nothing), so the
            # purchase has to be PUSHED. It goes on the end of the bag, which
            # shifts nobody, so the burst is one add per unit bought.
            f = inner[2:]
            shop_id = struct.unpack_from(">I", f, 0)[0] if len(f) >= 4 else 0
            item = struct.unpack_from(">I", f, 4)[0] if len(f) >= 8 else 0
            count = struct.unpack_from(">H", f, 8)[0] if len(f) >= 10 else 0
            #
            # KEY: AND SINCE 2026-09-11 IT IS PAID FOR. The row's own price (the
            # item table's, see shop_stock) times the count comes out of the
            # stored wallet -- gold at a gold shop, Rings at the Ring Shop --
            # and a player who cannot afford it gets the client's own refusal
            # (BUY_NG_NO_GOLD / BUY_NG_NO_RINGS) and keeps both the money and
            # the bag they had. Checked BEFORE the bag is written, charged
            # after, so a refusal changes nothing.
            shop = _SESSION["shop"]
            price = {r[0]: (r[1], r[2]) for r in shop["stock"]}
            ok = item in price and 1 <= count <= 16
            code, why = BUY_NG_DEFAULT, "not in this shop's stock"
            old = item_rows(args)
            items = old
            cost_g, cost_r = 0, 0
            if ok:
                cost_g, cost_r = price[item][0] * count, price[item][1] * count
                # item_rows, not a bare unpack: a stacked row is FOUR long
                # (see the Stack button) and `for u, _, _ in items` raised on it.
                short = wallet_short(args, cost_g, cost_r)
                if len(items) + count > bag_capacity(args):
                    # the character's own grid (uPossessItemNum), <= 96 deep
                    ok, code, why = False, BUY_NG_BAG_FULL, "bag full"
                elif short:
                    ok = False
                    code = BUY_NG_NO_GOLD if short == "gold" else BUY_NG_NO_RINGS
                    why = ("costs %d gold, has %s" % (cost_g, gold_get(args))
                           if short == "gold" else
                           "costs %d rings, has %s" % (cost_r, rings_get(args)))
                else:
                    nxt = new_item_uid(args, items)     # bag AND bank uids
                    items = old + [(nxt + i, item, 1, 1) for i in range(count)]
                    ok = _store_char_field(args, "items", [list(x) for x in items])
                    why = "no stored character to write to"
            if ok:
                send(conn, outbound, inner_msg(0x107D, b"", unit_id_of(args)),
                     mode, be, args.seq_mode == "echo", args.world_prefix)
                wallet_charge(conn, outbound, mode, be, args, cost_g, cost_r,
                              "bought item %d x%d" % (item, count))
                print("[feworld] -> 0x30 inner 0x107D MSG_BUY_SHOP_ITEM_OK -- item %d x%d "
                      "stored on the character (bag now %d) for %d gold + %d rings"
                      % (item, count, len(items), cost_g, cost_r), flush=True)
                if getattr(args, "bag_organize", "on") != "off":
                    bag_layout_push(conn, outbound, mode, be, args, old, items,
                                    [], "bought item %d x%d" % (item, count))
            else:
                send(conn, outbound, inner_msg(0x107E, struct.pack(">I", code), unit_id_of(args)),
                     mode, be, args.seq_mode == "echo", args.world_prefix)
                print("[feworld] -> 0x30 inner 0x107E MSG_BUY_SHOP_ITEM_NG err=%d -- item %d "
                      "x%d refused: %s" % (code, item, count, why), flush=True)
        elif real_id in (0x2021, 0x2022, 0x2098) and args.ui_auto != "off":
            # EQUIP / UNEQUIP. All three carry [u32 uid][u8 worn slot] and all
            # three are answered by their header-only OK -- but the OK is not
            # the reflection. 0x102A's arm (0x0503c390) looks the player up and
            # clears the in-flight flag 0x200000; it reads no body and touches
            # no item, so answering it and stopping is exactly what "OK and
            # NOTHING CHANGES" looked like. See equip_reflect_push.
            #
            #   0x2021 MSG_EQUIP_ITEM        (0x0507c0f0)  put it on
            #   0x2022 MSG_DISRAM_ITEM       (0x0507c1f2)  take it off
            #   0x2098 MSG_DISRAM_EQUIP_ITEM (0x0507c2dd)  swap out of a full slot
            #
            # The client has ALREADY validated (0x05076090 at 0x050b6638) and
            # already picked the worn slot.
            #
            # WARNING: THE THREE ARE NOT THE SAME SHAPE, and the comment above used
            # to say they were. Measured live 2026-09-06 off the wire:
            #
            #     0x2021  20 21 | 00 00 03 ea | 03      [u32 uid][u8 worn]
            #     0x2022  20 22 | 00 00 03 ef          [u32 uid]  -- NO SLOT
            #
            # An UNEQUIP names only the item. So the worn index has to come
            # from the ITEM TABLE, exactly the way the client's own Equip
            # derives it (0x0507b920 on [tbl+0x50]) -- and until this was
            # noticed, `cslot` fell to the 0xFF default and unequip_push
            # refused every single unequip as "outside the 13-slot array".
            # On screen that read as a hat that would not come off,
            # even clicked four times in a row.
            ok, ng, name, arm_va = UI_HEADER_ONLY_OK[real_id]
            f = inner[2:]
            uid = struct.unpack_from(">I", f, 0)[0] if len(f) >= 4 else 0
            cslot = f[4] if len(f) >= 5 else 0xFF
            # WARNING: 0x2098 IS AN EQUIP, and calling it an unequip is why the
            # quick-access pockets stayed empty. Live 2026-09-06: a
            # player set two items "to pocket 1 and pocket 2" and the
            # client sent 0x2098 carrying worn slots 11 and 12 -- exactly
            # where item slot type 11 lands in Equip's own jump table
            # (0x0507b920, "first free of 11..12"). It uses this verb
            # rather than 0x2021 because the target slot is already
            # occupied: MSG_DISRAM_EQUIP_ITEM is unequip-THEN-equip, a
            # SWAP, whose net effect is that `uid` ends up worn. Treating
            # it as a removal took the item back out of the stored equip
            # list and then reflected it with the 0xff marker -- the
            # client was told, correctly and uselessly, that the thing it
            # had just put in a pocket was not worn.
            wear = real_id in (0x2021, 0x2098)
            items = [tuple(x) for x in (_load_char_field(args, "items", []) or [])]
            equip = [tuple(x) for x in (_load_char_field(args, "equip", []) or [])]
            by_uid = {int(u): int(no) for u, no, _f, _c in item_rows(items)}
            stored = True
            if uid in by_uid:
                # The store keeps (item table slot TYPE, uid) -- felobby seeds
                # it that way and the 0xD002 record carries it -- so the pair
                # is rebuilt from the item table, not from the client's worn
                # index. worn_layout() is the one place that converts.
                slot_type = fegamedata.items().get(by_uid[uid], {}).get("slot", -1)
                equip = [(int(sl), int(u)) for sl, u in equip if int(u) != uid]
                if wear and slot_type is not None and slot_type >= 0:
                    # one item per worn slot: whatever else Equip would put in
                    # this slot comes off, the same way the client's own
                    # 0x0507b950 clears the previous occupant
                    taken = worn_layout(equip, items)
                    want = worn_index(slot_type, set(taken.values()))
                    equip = [(sl, u) for sl, u in equip
                             if taken.get(int(u)) != want]
                    equip.append((int(slot_type), uid))
                stored = _store_char_field(args, "equip",
                                           [list(x) for x in equip])
            else:
                stored = False
            mid = ok if (uid in by_uid and stored) else ng
            body = b"" if mid == ok else struct.pack(">I", args.ui_auto_err)
            send(conn, outbound, inner_msg(mid, body, unit_id_of(args)),
                 mode, be, args.seq_mode == "echo", args.world_prefix)
            # The CLIENT's slot and the one worn_layout derives are printed
            # together on purpose: they are computed from different things
            # (its jump table vs our copy of the item table) and the only
            # cheap way to notice them drifting is to see both.
            derived = worn_layout(equip, items).get(uid)
            print("[feworld] -> 0x30 inner 0x%04X %s_%s -- uid=%d (%s); "
                  "client worn slot=%s, we derive %s; stored equipment is "
                  "now %s"
                  % (mid, name, "OK" if mid == ok else "NG", uid,
                     "EQUIP" if wear else "UNEQUIP",
                     "none" if cslot == 0xFF else cslot,
                     "none" if derived is None else derived,
                     [(sl, u) for sl, u in equip] if uid in by_uid
                     else "unchanged -- that uid is not in this character's bag"),
                  flush=True)
            if (mid == ok and wear and cslot != 0xFF
                    and derived is not None and derived != cslot):
                print("[feworld]    \u26a0 WORN INDEX DISAGREEMENT: the client "
                      "put uid %d in worn slot %d and we will reflect %d. "
                      "Both come from item slot type %s; ours is "
                      "order-dependent for the multi-slot types (8, 11)."
                      % (uid, cslot, derived,
                         fegamedata.items().get(by_uid.get(uid, -1), {})
                         .get("slot")), flush=True)
            if mid == ok:
                # THE UNEQUIP GOES FIRST, while [unit+0x870] still names the
                # item: 0x2004's uid==0 branch reads it back out of that array.
                # The client's own worn slot (the u8 it just sent) is the one
                # to clear -- it picked the index, not us.
                # WARNING: ONLY 0x2022 IS AN UNEQUIP. Measured live 2026-09-06:
                # a player put cheese, a potion and a feather "into slot 1
                # and 2 for quick use" and the client sent 0x2098 with worn
                # slots 11 and 12 -- which is exactly where worn_index_for
                # sends item slot type 11. So 0x2098 ASSIGNS an item to a worn
                # slot that is already occupied; the name
                # MSG_DISRAM_EQUIP_ITEM reads like a removal and is not one
                # (a message NAME is not evidence -- again). Sending the
                # 0x2004 clear for it would have emptied the quick slot the
                # player had just filled.
                # WARNING: The STORE still treats 0x2098 as a removal, which is why
                # none of those three items appears in `equip`. Left alone on
                # purpose: quick slots are unmodelled either way, and changing
                # store semantics on an untested reading is how this file
                # collected its regressions.
                if real_id == 0x2022:
                    # 0x2022 carries no slot, so derive it. worn_index_for
                    # is the client's own jump table; for the two-handed
                    # types it answers 0, and 0x0507b950's own branch
                    # clears the paired [unit+0x874] with it.
                    wslot = cslot if 0 <= cslot <= 12 else None
                    if wslot is None:
                        wslot = fegamedata.worn_index_for(
                            fegamedata.items().get(by_uid.get(uid, -1), {})
                            .get("slot", -1))
                    unequip_push(conn, outbound, mode, be, args, wslot,
                                 "0x%04X for uid %d (item %s, slot type %s)"
                                 % (real_id, uid, by_uid.get(uid),
                                    fegamedata.items()
                                    .get(by_uid.get(uid, -1), {}).get("slot")))
                equip_reflect_push(conn, outbound, mode, be, args,
                                   stored_equip_rows(args, only_uid=uid),
                                   "0x%04X for uid %d" % (real_id, uid))
                # WARNING: LIVE 2026-09-12: ONLY the field-entry replay called
                # motion_refresh_push, so a weapon equipped mid-session never
                # got its motion set and every skill on it was a T-pose --
                # Quinn's bow, 0x2021 at seq 86, long after the entry restate,
                # while Lex (wand worn at entry) animated. The 0x107A path
                # never selects the motion set (its docstring says so).
                # Only for the HELD weapon (worn 0/1): the motion set depends on
                # nothing else, and a 0x2098 into a pocket (worn 11/12) must
                # not be followed by any 0x2004 (fe_ui_test part14, live 09-06).
                if (wear and real_id == 0x2021
                        and getattr(args, "equip_reflect", "request") != "off"
                        and worn_layout(equip, items).get(uid) in (0, 1)):
                    motion_refresh_push(conn, outbound, mode, be, args,
                                        stored_equip_rows(args),
                                        "after 0x%04X for uid %d (a weapon "
                                        "equipped in the field)" % (real_id, uid))
                cast_report_log(args, "after 0x%04X" % real_id)
        elif (real_id == 0x2051 and args.ui_auto == "ok"
              and getattr(args, "use_item", "on") != "off"):
            # KEY: USING AN ITEM -- unanswered until now, so the cheese did
            # nothing and the request hung. Reported live 2026-09-06 ("I just
            # tried eating cheese").
            #
            # The request, captured live (uid 1011 = item 7, the thing that had
            # just been bought), 25 body bytes:
            #
            #     [u32 uid][u32 ?1] [8 bytes] [u8 hasPos] [u32 ?][u32 ?]
            #     00 00 03 f3|00 00 00 01|00 01 0f 35 00 01 14 e0|00|...
            #
            # WARNING: ONLY THE FIRST FIELD IS DECODED, and it is decoded by
            # elimination plus the builder: 0x05042DF4 writes [win+0x84] first
            # and 1011 was a uid in that bag and not an item number in it. The
            # eight bytes in the middle come from a sub-writer (0x050389E0) and
            # look like two client timestamps; the u8 is the builder's own
            # "position follows" flag (0x05042E4D `cmp bl,1` gates three floats,
            # and it was 0 here). The rest is LOGGED, not guessed at -- naming a
            # field off its shape is what cost this channel six probes.
            #
            # KEY: AND THE OK IS AN ACKNOWLEDGEMENT AGAIN. 0x1089's arm
            # (0x050580EC) reads [u32 A][u32 B], finds object B, and calls
            # 0x05074E20 -- which is `and byte [obj+0x4ec], 0xfe; ret 4`. It
            # clears one in-flight bit and DISCARDS A. Nothing consumes the
            # item, nothing applies an effect. A miss on B is a log line
            # (0x0505814C), not a fault.
            f = inner[2:]
            uid = struct.unpack_from(">I", f, 0)[0] if len(f) >= 4 else 0
            arg1 = struct.unpack_from(">I", f, 4)[0] if len(f) >= 8 else 0
            old = item_rows(args)
            equip = [tuple(x) for x in (_load_char_field(args, "equip", []) or [])]
            hit = [(i, r) for i, r in enumerate(old) if r[0] == uid]
            why = ""
            if not hit:
                why = "that uid is not in this character's bag"
            elif uid in {int(u) for sl, u in equip
                         if int(sl) != POCKET_SLOT_TYPE}:
                # WARNING: LIVE 2026-09-12: a player used both POCKET items, the
                # client emptied the pockets, and a relog brought them back --
                # because a pocket IS a worn slot (type 11 -> worn 11/12) and
                # this refused every worn uid: "REFUSED: that item is EQUIPPED"
                # for uids 1009/1011, 6 times in the log. A pocket item is
                # exactly the one meant to be used.
                why = "that item is EQUIPPED"
            fx = None
            if not why and getattr(args, "item_effects", "table") == "table":
                fx = fegamedata.item_effect(hit[0][1][1])
                cur = ((_SESSION.get("item_fx") or {}).get(fx["stat"])
                       if fx and fx["total_ms"] else None)
                if cur and cur["tier"] > fx["tier"]:
                    # refused BEFORE it is eaten, so the weaker potion is kept
                    why = ("a stronger %s potion (tier %d) is still working -- "
                           "fewiki 2006 (fv_consum.txt): a potion only replaces "
                           "one of equal or lower rank"
                           % (fx["stat"].upper(), cur["tier"]))
            new_rows, gone = list(old), []
            if not why:
                i, row = hit[0]
                # ONE. `arg1` is 1 in the only capture we have and is NOT
                # confirmed to be a count, so it is logged rather than obeyed:
                # obeying an unmeasured field is how a stack of five gets eaten
                # in one bite.
                if row[3] > 1:
                    new_rows[i] = (row[0], row[1], row[2], row[3] - 1)
                else:
                    new_rows = old[:i] + old[i + 1:]
                    gone = [(uid, i)]
                if not _store_char_field(args, "items",
                                         [list(r) for r in new_rows]):
                    why = ("no stored character matched account=%r charid=%s"
                           % (_SESSION.get("account"), _SESSION.get("charid")))
                elif gone and any(int(u) == uid for _sl, u in equip):
                    # the pocket item is GONE from the bag: forget its worn
                    # entry too, or the next login re-fills the pocket (a
                    # stack that still has some keeps its entry)
                    _store_char_field(args, "equip",
                                      [list(e) for e in equip if int(e[1]) != uid])
                    print("[feworld]    pocket uid %d emptied from the stored "
                          "worn map (pockets are worn slots)" % uid, flush=True)
            if why:
                send(conn, outbound,
                     inner_msg(0x108A, struct.pack(">II", 0, uid),
                               unit_id_of(args)),
                     mode, be, args.seq_mode == "echo", args.world_prefix)
                print("[feworld] -> 0x30 inner 0x108A MSG_USE_ITEM_NG uid=%d "
                      "REFUSED: %s (body %s)" % (uid, why, f.hex()), flush=True)
            else:
                # THE OK GOES FIRST, while the object still exists: its arm
                # looks uid up and clears the in-flight bit on it. The removal
                # below destroys that object, so the other order would clear the
                # flag on nothing.
                send(conn, outbound,
                     inner_msg(0x1089, struct.pack(">II", 0, uid),
                               unit_id_of(args)),
                     mode, be, args.seq_mode == "echo", args.world_prefix)
                item_no = hit[0][1][1]
                item_use_effect(conn, outbound, mode, be, args, item_no, fx)
                print("[feworld] -> 0x30 inner 0x1089 MSG_USE_ITEM_OK [u32 0]"
                      "[u32 %d] -- item %d consumed, bag %d -> %d row(s). The "
                      "arm only clears [obj+0x4ec] bit 0; the 0x107A below is "
                      "what takes it out of the bag; the effect is "
                      "item_use_effect's (above). Body tail "
                      "(undecoded): %s"
                      % (uid, item_no, len(old), len(new_rows), f[8:].hex()),
                      flush=True)
                bag_layout_push(conn, outbound, mode, be, args, old, new_rows,
                                gone, "used uid %d (item %d)" % (uid, item_no))
        elif (real_id == 0x204C and args.ui_auto == "ok"
              and getattr(args, "bag_organize", "on") != "off"):
            # KEY: SELLING, and it is the last of the acknowledge-and-do-nothing
            # family. 0x1080's arm (0x05023FEE) reads nothing, so answering it
            # left the item in the bag -- reported live 2026-09-06, "I bought
            # and sold an item but my inventory didn't change".
            #
            #     0x204C  [u32 shop][u32 uid][u16 count]    builder 0x050EF530
            #
            # WARNING: THE MIDDLE FIELD IS A uid, NOT AN ITEM NUMBER, and that is the
            # client's own word: 0x050EF7F5 fills it with
            # `0x0507BA90(unit, [row+0x88], 0)` -- the same "uid at bag slot N
            # of array 0" call the 0x107A remove branch uses. (The live capture
            # agrees: `000001f6 000003ee 0001` = shop 502, uid 1006, count 1,
            # and 1006 was a uid in that bag and not an item number in it.)
            # Reading it as an item number would sell the wrong row whenever a
            # bag held two of anything.
            f = inner[2:]
            shop_id = struct.unpack_from(">I", f, 0)[0] if len(f) >= 4 else 0
            uid = struct.unpack_from(">I", f, 4)[0] if len(f) >= 8 else 0
            count = struct.unpack_from(">H", f, 8)[0] if len(f) >= 10 else 0
            old = item_rows(args)
            equip = [tuple(x) for x in (_load_char_field(args, "equip", []) or [])]
            worn = {int(u) for _sl, u in equip}
            hit = [(i, r) for i, r in enumerate(old) if r[0] == uid]
            why, code = "", args.ui_auto_err
            if not hit:
                why, code = "that uid is not in this character's bag", SELL_NG_NOT_HELD
            elif uid in worn:
                # The client builds its sell list off the bag array, which still
                # holds worn items, so this is reachable. Refusing is the honest
                # answer: selling what you are wearing needs an unequip we would
                # have to invent, and the equip pair would be left dangling.
                why = "that item is EQUIPPED -- take it off first"
                code = SELL_NG_EQUIPPED
            elif count < 1:
                why, code = "count %d" % count, SELL_NG_COUNT
            new_rows, gone = list(old), []
            earned = 0
            if not why:
                i, row = hit[0]
                sold = min(count, row[3])
                earned = item_sell_value(args, row[1]) * sold
                if sold >= row[3]:
                    new_rows = old[:i] + old[i + 1:]
                    gone = [(uid, i)]
                else:
                    # a partial stack: the row stays where it is with fewer in
                    # it, so there is nothing to remove and nothing shifts
                    new_rows = list(old)
                    new_rows[i] = (row[0], row[1], row[2], row[3] - sold)
                if not _store_char_field(args, "items",
                                         [list(r) for r in new_rows]):
                    why = ("no stored character matched account=%r charid=%s"
                           % (_SESSION.get("account"), _SESSION.get("charid")))
            if why:
                send(conn, outbound,
                     inner_msg(0x1081, struct.pack(">I", code),
                               unit_id_of(args)),
                     mode, be, args.seq_mode == "echo", args.world_prefix)
                print("[feworld] -> 0x30 inner 0x1081 MSG_SELL_ITEM_NG err=%d -- "
                      "uid=%d x%d at shop %d REFUSED: %s"
                      % (code, uid, count, shop_id, why), flush=True)
            else:
                send(conn, outbound, inner_msg(0x1080, b"", unit_id_of(args)),
                     mode, be, args.seq_mode == "echo", args.world_prefix)
                # 09-11: the sale PAYS -- the same value the window was shown
                # through 0x1086 (item_sell_value), into the stored wallet.
                got = wallet_credit(conn, outbound, mode, be, args, earned, 0,
                                    "sold uid %d x%d" % (uid, count))
                print("[feworld] -> 0x30 inner 0x1080 MSG_SELL_ITEM_OK "
                      "(header-only, arm 05023fee reads nothing) -- uid=%d x%d "
                      "at shop %d; bag %d -> %d row(s), %d gold credited. The "
                      "OK moves nothing; the 0x107A below is what empties the "
                      "slot." % (uid, count, shop_id, len(old), len(new_rows),
                                 got), flush=True)
                bag_layout_push(conn, outbound, mode, be, args, old, new_rows,
                                gone, "sold uid %d" % uid)
        elif (real_id in (0x114D, 0x20AA) and args.ui_auto == "ok"
              and getattr(args, "bag_organize", "on") != "off"):
            # `--ui-auto ng` and `off` deliberately fall through to the generic
            # UI_HEADER_ONLY_OK arm below, which is where the refusal and the
            # silence A/Bs live. This branch is the SUCCESS path only.
            # KEY: THE STACK AND SORT BUTTONS. Answered since 2026-08-25, inert
            # ever since, and inert for the same reason the equip was: the OK
            # is an ACKNOWLEDGEMENT. 0x2095's arm (0x05058747) and 0x1179's
            # (0x0505846D) make zero stream reads and move no item. In live
            # testing Sort was pressed four times in a row, which is what a
            # button that acknowledges and does nothing looks like.
            #
            #   0x114D  STACK  [u32 1]  builder 0x050b9330 / 0x050ea220; the
            #                           u32 is a literal 1 in both builders,
            #                           not a page or an array selector
            #   0x20AA  SORT   no body  builder 0x050b9390 / 0x050ea280
            #
            # Both also set the inventory window's in-flight state, which only
            # the OK clears -- so the OK still has to go, and it goes FIRST:
            # the 0x107A burst is the result of an operation the client has
            # already been told succeeded.
            ok, ng, name, arm_va = UI_HEADER_ONLY_OK[real_id]
            how = "stack" if real_id == 0x114D else "sort"
            f = inner[2:]
            send(conn, outbound, inner_msg(ok, b"", unit_id_of(args)),
                 mode, be, args.seq_mode == "echo", args.world_prefix)
            print("[feworld] -> 0x30 inner 0x%04X %s_OK (header-only, arm %08x "
                  "reads nothing) for 0x%04X %s%s -- the OK only clears the "
                  "window's in-flight state; the bag itself moves on the "
                  "0x107A burst below"
                  % (ok, name, arm_va, real_id, how.upper(),
                     " body=%s" % f.hex() if f else ""), flush=True)
            bag_organize(conn, outbound, mode, be, args, how)
        elif (real_id in (0x2029, 0x202A) and args.ui_auto != "off"
              and getattr(args, "skill_palette", "request") != "off"):
            # KEY: THE SKILL PALETTE -- and the message that answers it is the
            # SAME ID coming back. See the PALETTE_SLOTS block for the whole
            # derivation; the short version is that the double-click sender
            # (vtable +0x24) and the local setter (+0x28) are different methods
            # and only the inbound worker calls the setter, so a click the
            # server never echoes changes nothing on screen.
            f = inner[2:]
            mask = struct.unpack_from(">H", f, 0)[0] if len(f) >= 2 else 0
            rows, off, bad = [], 2, []
            for slot in range(PALETTE_MASK_BITS):
                if not mask & (1 << slot):
                    continue
                if real_id == 0x202A:
                    rows.append((slot, None))
                    continue
                if len(f) < off + 4:
                    bad.append(slot)
                    break
                skill = struct.unpack_from(">H", f, off)[0]
                off += 4                        # [u16 skill][u8][u8]
                rows.append((slot, skill))
            keep = {s: k for s, k in palette_rows(args)}
            for slot, skill in rows:
                if slot >= PALETTE_SLOTS:
                    continue                    # 0x0516236F bails above 7
                if skill is None:
                    keep.pop(slot, None)
                else:
                    keep[slot] = skill
            stored = _store_char_field(args, "palette",
                                       [[s, k] for s, k in sorted(keep.items())])
            # ECHO ONLY WHAT THE CLIENT ASKED FOR. Re-sending the whole palette
            # here would also re-apply slots it already has, which is harmless
            # but makes the log unreadable; the full push is the entry replay.
            if real_id == 0x202A:
                body = palette_clear_body([s for s, _k in rows])
            else:
                body = palette_set_body([(s, k) for s, k in rows
                                         if k is not None])
            send(conn, outbound, inner_msg(real_id, body, unit_id_of(args)),
                 mode, be, args.seq_mode == "echo", args.world_prefix)
            print("[feworld] -> 0x30 inner 0x%04X SKILL PALETTE %s: %s -- "
                  "echoed back, which is what applies it (%s); palette is now "
                  "%s%s"
                  % (real_id, "CLEAR" if real_id == 0x202A else "SET",
                     ", ".join("slot %d%s" % (s, "" if k is None
                                              else " = skill %d" % k)
                               for s, k in rows) or "nothing (mask 0)",
                     "worker 0x0503D0F0" if real_id == 0x202A
                     else "worker 0x0503CF60",
                     ", ".join("%d:%d" % r for r in sorted(keep.items()))
                     or "empty",
                     "" if stored else " WARNING: NOT PERSISTED -- no stored character "
                     "matched, so it is gone at the next login"), flush=True)
            if bad:
                print("[feworld]    WARNING: 0x%04X mask claimed slot(s) %s the body "
                      "had no record for -- %d body bytes for %d set bit(s)"
                      % (real_id, bad, len(f), bin(mask).count("1")), flush=True)
        elif real_id == 0x204A and _SESSION.get("shop") and args.ui_auto != "off":
            # MSG_GET_SHOP_ITEM_LIST [u32 shop][u32 page] from the list data
            # object's 0x50eec20 ([list+0x90], [list+0x88] = the page it is
            # on). Its 0x107B handler (0x50ee7a0) reads the page straight
            # from the stream, then asks the NEXT page until [list+0x84]
            # (the 0x1102 count) is reached, then renders (0x50f6350) and
            # clears the waiting flag. See shop_page_body for the layout.
            f = inner[2:]
            shop_id = struct.unpack_from(">I", f, 0)[0] if len(f) >= 4 else 0
            page = struct.unpack_from(">I", f, 4)[0] if len(f) >= 8 else 0
            shop = _SESSION["shop"]
            body = shop_page_body(args, shop["stock"], page)
            # THE SELL PRICE, while the window that consumes it is open. See
            # sell_value_push: [item+0x4f0] is -1 from the ctor and 0x1086 is
            # the only thing that ever writes it, the client never asks, and
            # the arm drops the message when [mgr+0xe0] is null.
            if page == 0:
                sell_value_push(conn, outbound, mode, be, args,
                                sell_value_rows(args))
            n = struct.unpack_from(">H", body, 4)[0]
            send(conn, outbound, inner_msg(0x107B, body, unit_id_of(args)),
                 mode, be, args.seq_mode == "echo", args.world_prefix)
            print("[feworld] -> 0x30 inner 0x107B MSG_GET_SHOP_ITEM_LIST_OK "
                  "[page %d][u16 %d] x {[item][gold][rings][mask1=2][u16 item]"
                  "[3 x mask 0]} for the "
                  "%s shop (shop id %d in the request, %d/%d pages); items %s"
                  % (page, n, shop["kind"], shop_id, page + 1,
                     shop_pages(args, shop["stock"]),
                     shop["stock"][page * 30:page * 30 + 6]),
                  flush=True)
        elif (real_id in BANK_REQUESTS and args.ui_auto == "ok"
              and getattr(args, "bank", "on") == "on"):
            # THE BANK, simulated since 2026-09-11 -- see bank_request and the
            # block above BANK_REQUESTS. `--ui-auto ng`/`off` and `--bank off`
            # fall through to the generic header-only arm below, which is the
            # old acknowledge-and-store-nothing behaviour.
            bank_request(conn, outbound, mode, be, args, real_id, inner[2:])
        elif real_id in UI_REPLY_BODY and args.ui_auto != "off":
            # The body-carrying siblings of UI_HEADER_ONLY_OK. Same rule: the
            # OK's shape is measured, not assumed -- see the table.
            ok, ng, name, arm_va, spec = UI_REPLY_BODY[real_id]
            f = inner[2:]
            if args.ui_auto == "ng":
                send(conn, outbound,
                     inner_msg(ng, struct.pack(">I", args.ui_auto_err),
                               unit_id_of(args)),
                     mode, be, args.seq_mode == "echo", args.world_prefix)
                print("[feworld] -> 0x30 inner 0x%04X %s_NG err=%d"
                      % (ng, name, args.ui_auto_err), flush=True)
                continue
            if spec == "echo32":
                val = struct.unpack_from(">I", f, 0)[0] if len(f) >= 4 else 0
                why = "echoed from the request"
            else:
                val = spec[1]
                why = "constant"
            if real_id == 0x2073 and _SESSION.get("shop"):
                val = shop_pages(args, _SESSION["shop"]["stock"])
                why = "the open shop's stock / --shop-page"
            send(conn, outbound,
                 inner_msg(ok, struct.pack(">I", val & 0xFFFFFFFF),
                           unit_id_of(args)),
                 mode, be, args.seq_mode == "echo", args.world_prefix)
            print("[feworld] -> 0x30 inner 0x%04X %s_OK [u32 %d] (%s) -- for "
                  "0x%04X; arm %08x reads exactly one u32"
                  % (ok, name, val, why, real_id, arm_va), flush=True)
        elif (real_id in UI_HEADER_ONLY_OK
              or (real_id == UI_MOVE_REQUEST[0]
                  and args.move_request != "off")):
            # KEY: THE GENERIC HEADER-ONLY ANSWER -- see UI_HEADER_ONLY_OK.
            #
            # This exists because the same failure arrived twice in one hour
            # from two different buttons (STACK -> 0x114D, SORT -> 0x20AA), and
            # both times the fix was "send the OK the request already told us it
            # wanted". Answering them one at a time is a queue with no end; the
            # client publishes the whole request -> reply map in its own image,
            # so the table does.
            if real_id in UI_HEADER_ONLY_OK:
                ok, ng, name, arm_va = UI_HEADER_ONLY_OK[real_id]
                want = args.ui_auto
            else:
                _, ok, ng, name, arm_va = UI_MOVE_REQUEST
                want = args.move_request
            f = inner[2:]
            if want == "off":
                print("[feworld]    0x%04X %s_REQUEST (%d body bytes) -- NOT "
                      "ANSWERED; the dialog that sent it WILL HANG"
                      % (real_id, name, len(f)), flush=True)
                continue
            mid = ok if want == "ok" else ng
            body = b"" if mid == ok else struct.pack(">I", args.ui_auto_err)
            send(conn, outbound, inner_msg(mid, body, unit_id_of(args)),
                 mode, be, args.seq_mode == "echo", args.world_prefix)
            print("[feworld] -> 0x30 inner 0x%04X %s_%s%s -- for 0x%04X (%d "
                  "body bytes in); OK arm %08x makes ZERO stream reads, so the "
                  "reply is the header and nothing else"
                  % (mid, name, "OK" if mid == ok else "NG",
                     "" if mid == ok else " err=%d" % args.ui_auto_err,
                     real_id, len(f), arm_va), flush=True)
            if f:
                print("[feworld]    (request body: %s)" % f.hex(), flush=True)
            # THE VALIDATE SEQUENCE IS A TIMER, NOT A ROUND TRIP. 0x1154's arm
            # sets [unit+0x138c] = 0x2710 and stamps [unit+0x1390], so the OK
            # only STARTS a countdown -- the client then waits for the server to
            # say it finished. Answering OK and stopping would move the hang ten
            # seconds later rather than fix it.
            if real_id == 0x209A and mid == ok and args.validate_finish > 0:
                _SESSION["validate_due"] = time.time() + args.validate_finish
                print("[feworld]    validate sequence armed: 0x1157 FINISH in "
                      "%.1fs (the client's own countdown constant is 0x2710 = "
                      "10000ms, so the default matches what it already expects)"
                      % args.validate_finish, flush=True)
            if real_id == 0x209C:
                _SESSION.pop("validate_due", None)
            # THE DUMMY AREA. 0x1045 releases the field, and mode 0x0B then
            # walks state 6 -> 7 -> 8 and PARKS in 8 forever, because state 8
            # is the war-result screen's frame and there is no war-result
            # screen. 0x1100 is the only message that builds one. See
            # WAR_RESULT for the whole chain, including the part that is the
            # PLAYER's move (closing the window) and not ours.
            if real_id == 0x2033 and mid == ok and args.war_result != "off":
                war_result_push(conn, outbound, mode, be, args)
            if real_id == 0x2033 and mid == ok:
                # KEY: FIELD OUT IS WHERE `in_field` GOES FALSE -- and until
                # 2026-09-12 NOTHING EVER CLEARED IT. It was set True once on
                # field entry (one assignment in the whole file) and stayed
                # true for the life of the session, with `field` holding
                # whatever the player last entered. Found live: the map's
                # population marker stayed on the field the player had LEFT
                # ("the 1 icon is still over the map I first went to"), because
                # field_census counts sessions by (in_field, field) -- and my
                # own comment in field_census asserted "to field OUT,
                # `in_field` goes false", which was never true.
                #
                # It is not only the census. Everything that asks "is this
                # player in a field" was answered yes forever:
                # fecampaign._present_here could never take its cleanup branch
                # (the keeps, the giant crystals and the served buildings are
                # popped there), fepvp would still route a hit at a player
                # standing on the map, and the war pump's own in_field gate
                # (the one whose failure it logs at 5021) could not close.
                #
                # Pushed AFTER war_result_push above, which reads the session.
                if _SESSION.get("in_field"):
                    print("[feworld]    FIELD OUT: in_field cleared (was field "
                          "%s). Until today this flag was never cleared, so the "
                          "map kept counting this player in the field they had "
                          "left." % _SESSION.get("field"), flush=True)
                _SESSION["in_field"] = False
                _SESSION.pop("field", None)
                battle_reset()
        elif real_id == 0x2049:
            # KEY: THE `GET!` BUTTON -- MSG_ACQUIRE_SKILL_REQUEST.
            #
            #     [u16 skillId][u8 1]
            #
            # built at 0x050d4a8c: 0x5045bb0 writes the u16 from [window+0xc8]
            # (+2 on the cursor) and 0x5045b80 writes the u8 (+1). Its
            # registration two instructions earlier (0x050d4a7c/0x050d4a83)
            # names the only two answers: 0x1078 OK / 0x1079 NG.
            #
            # 0x1078's arm (0x050534f7) READS NOTHING -- it just calls
            # 0x050d4cf0 on the skill window if [0x534406c] is live. So the OK
            # is header-only. 0x1079 (0x05053511) logs MSG_ACQUIRE_SKILL_NG and
            # reads a u32 error code, so the pair is NOT symmetric.
            #
            # WARNING: ANSWERING OK IS NOT ENOUGH ON ITS OWN. The skill has to go into
            # the store, because the list the client displays comes back from
            # US in 0x303E -- acknowledge without persisting and the skill is
            # gone on the next login, having cost the player SP for nothing.
            # That is the whole reason this is its own arm and not another row
            # in UI_HEADER_ONLY_OK.
            f = inner[2:]
            skill = struct.unpack_from(">H", f, 0)[0] if len(f) >= 2 else 0
            if args.acquire_skill == "off":
                print("[feworld]    0x2049 ACQUIRE_SKILL id=%d -- NOT ANSWERED "
                      "(--acquire-skill off); the skill window will hang"
                      % skill, flush=True)
                continue
            if args.acquire_skill == "ng":
                send(conn, outbound,
                     inner_msg(0x1079, struct.pack(">I", args.ui_auto_err),
                               unit_id_of(args)),
                     mode, be, args.seq_mode == "echo", args.world_prefix)
                print("[feworld] -> 0x30 inner 0x1079 MSG_ACQUIRE_SKILL_NG "
                      "err=%d for skill=%d" % (args.ui_auto_err, skill),
                      flush=True)
                continue
            stored, rows = acquire_skill(args, skill)
            send(conn, outbound, inner_msg(0x1078, b"", unit_id_of(args)),
                 mode, be, args.seq_mode == "echo", args.world_prefix)
            print("[feworld] -> 0x30 inner 0x1078 MSG_ACQUIRE_SKILL_OK "
                  "(header-only) for skill=%d -- %s; %d skill(s) now stored, "
                  "and they are what 0x303E serves back"
                  % (skill, "PERSISTED" if stored is True
                     else "already known, list unchanged" if stored is None
                     else "WARNING: NOT PERSISTED -- no stored character matched "
                          "account=%r charid=%s; the point is SPENT and the "
                          "skill will be gone at the next login"
                          % (_SESSION.get("account"), _SESSION.get("charid")),
                     len(rows)),
                  flush=True)
            # Re-push the status record so the window agrees with the store
            # immediately rather than at the next login.
            if args.status_resync == "on":
                if args.char_record != "off":
                    char_record_push(conn, outbound, mode, be, args)
                if args.status != "off":
                    status_push(conn, outbound, mode, be, args)
        elif real_id in (0x20A0, 0x20A1, 0x20A2):
            # KEY: THE BLACKLIST, END TO END -- three requests, and until now all
            # three hung the dialog that sent them.
            #
            # All three are SLASH COMMANDS with local handlers that build the
            # message; the UI just formats a command line and runs it
            # (0x05171489 does sprintf("/setblacklist %d %s", myCharId, name)).
            # So the command table at 0x052eacc0 and the wire protocol are the
            # same surface -- see GM_COMMANDS.
            #
            #   0x20A0  /setblacklist  0x05133220  [u32 myCharId][cstr NAME]
            #           registers 0x115F/0x1160 at 0x05133270/0x05133277
            #   0x20A1  /rmblacklist   0x051332c0  [u32 myCharId][u32 targetId]
            #           registers 0x1161/0x1162 at 0x05133383/0x0513338a
            #   0x20A2  /getblacklist  0x051333d0  [u32 myCharId]
            #           registers NOTHING -- the list arrives unsolicited
            #
            # THE REPLY BODIES, read reader-call by reader-call off each arm
            # (0x5045dc0 = u8, 0x5045e30 = u16, 0x5045e60 = u32,
            # 0x5045f50 = cstr; every one of those confirmed by the byte count
            # its stream primitive advances):
            #
            #   0x115F  arm 0x050241e2   [u32 id][cstr name]   -> append
            #   0x1161  arm 0x05024413   [u32 id]              -> erase by id
            #   0x1163  arm 0x05024490   [u32 count] then
            #                            count x { [u32 id][cstr name] }
            #                            -> CLEARS the vector first, then fills
            #
            # WARNING: THE u32 IN 0x115F IS THE TARGET'S ID, NOT THE REQUESTER'S. The
            # client appends {id, name} to its vector (0x05170be0) and
            # MSG_REMOVE erases by that id (0x05170cc0, `cmp [eax], edx` over a
            # 0x14 stride). Echoing the requester's charid -- which is what the
            # request carries -- would give every row the SAME id and make
            # removing one remove the wrong one. blacklist_add() allocates a
            # stable id instead.
            f = inner[2:]
            if args.blacklist == "off":
                print("[feworld]    0x%04X blacklist request -- NOT ANSWERED "
                      "(--blacklist off); the dialog will hang, which is the "
                      "pre-2026-08-25 behaviour and only useful as an A/B"
                      % real_id, flush=True)
                continue
            who = struct.unpack_from(">I", f, 0)[0] if len(f) >= 4 else 0
            if real_id == 0x20A0:
                # WARNING: THE CLIENT UPPER-CASES THE NAME: adding "Jimmy" put
                # 4a 49 4d 4d 59 00 = "JIMMY\0" on the wire. Store what
                # arrived; do not try to restore the case, we do not have it.
                raw = f[4:]
                name = raw.split(b"\0", 1)[0].decode("cp932", "replace")
                nid, rows, fresh = blacklist_add(args, name)
                if not fresh:
                    print("[feworld]    0x20A0 SET_BLACKLIST %r from charid=%d "
                          "-- ALREADY on the list as id=%d; re-answering 0x115F "
                          "with the SAME id so the client's append is a no-op "
                          "duplicate of a row it has, not a second row"
                          % (name, who, nid), flush=True)
                body = (struct.pack(">I", nid)
                        + name.encode("cp932", "replace") + bytes(1))
                send(conn, outbound, inner_msg(0x115F, body, unit_id_of(args)),
                     mode, be, args.seq_mode == "echo", args.world_prefix)
                print("[feworld] -> 0x30 inner 0x115F MSG_SET_BLACKLIST_OK "
                      "id=%d name=%r (%d row(s) stored)"
                      % (nid, name, len(rows)), flush=True)
            elif real_id == 0x20A1:
                target = (struct.unpack_from(">I", f, 4)[0]
                          if len(f) >= 8 else 0)
                gone = blacklist_remove(args, target)
                send(conn, outbound,
                     inner_msg(0x1161, struct.pack(">I", target),
                               unit_id_of(args)),
                     mode, be, args.seq_mode == "echo", args.world_prefix)
                print("[feworld] -> 0x30 inner 0x1161 MSG_REMOVE_BLACKLIST_OK "
                      "id=%d (requested by charid=%d; %s)"
                      % (target, who,
                         "row dropped from the store" if gone else
                         "WARNING: NO stored row had that id -- the client will still "
                         "erase it locally"), flush=True)
            else:
                blacklist_send(conn, outbound, mode, be, args, who)
        elif real_id == 0x2080:
            # KEY: 0x2080 MSG_GET_CHARACTER_DISTRIBUTION_INFO_REQUEST -- no body,
            # polled every ~10s (accumulator [obj+0x9e] vs 0x2710) and
            # unanswered 80 times in a single measured session.
            #
            # OK = 0x1123 (main dispatcher, special-cased at 0x050549c7
            # `cmp 0x1123 / je` -> arm 0x05055b74 -> 0x05010ff0).
            # NG = 0x1124 (arm 0x05055bc2).
            #
            # THE BODY, read call by call in 0x05010ff0:
            #
            #     0x05011006  0x5045e30  u16 count   -> clamped to 0xFF by
            #                                          0x05010d70 and stored at
            #                                          [obj+0xda2]
            #     then, count times:
            #     0x0501104c  0x5045dc0  u8
            #     0x0501105b  0x5045dc0  u8
            #     0x0501106a  0x5045dc0  u8   <- low 5 bits = a class code
            #                                    (1,4,5,6,7,8,9 are tested at
            #                                    0x050110cc..), top bit = the
            #                                    side, compared against the
            #                                    player's own nation
            #     0x05011079  0x5045e60  u32  <- a CHARACTER ID: it is fed to
            #                                    0x05051160 to find the unit and
            #                                    read [unit+0x50]
            #
            # WARNING: COUNT 0 IS THE DEFAULT AND IT IS THE HONEST ANSWER. What the
            # rows DRAW is unmeasured -- probably the minimap distribution dots
            # (cf. the A-H x 1-5 minimap grid) -- so serving invented characters
            # would be inventing a screen. The point of answering at all is that
            # the poll stops being an unanswered request.
            if args.distribution == "off":
                print("[feworld]    0x2080 CHARACTER_DISTRIBUTION poll -- NOT "
                      "ANSWERED (--distribution off)", flush=True)
                continue
            rows = args.distribution_rows
            payload = struct.pack(">H", len(rows) & 0xFF)
            for a, b, cls, cid in rows:
                payload += struct.pack(">BBBI", a & 0xFF, b & 0xFF,
                                       cls & 0xFF, cid & 0xFFFFFFFF)
            send(conn, outbound, inner_msg(0x1123, payload, unit_id_of(args)),
                 mode, be, args.seq_mode == "echo", args.world_prefix)
            _SESSION["dist_polls"] = _SESSION.get("dist_polls", 0) + 1
            if _SESSION["dist_polls"] <= 3 or _SESSION["dist_polls"] % 30 == 0:
                print("[feworld]    0x2080 poll #%d -> 0x1123 "
                      "MSG_GET_CHARACTER_DISTRIBUTION_INFO_OK with %d row(s)"
                      % (_SESSION["dist_polls"], len(rows)), flush=True)
        elif real_id == 0xF900:
            # KEY: THE GM COMMAND CHANNEL, INBOUND.  [u16 len][ascii command line]
            #
            # FE routes a whole class of UI actions through its own slash
            # command dispatcher and then forwards the line here with the
            # LEADING SLASH STRIPPED -- setting a profile comment to
            # "Hello comment" put
            #
            #     f9 00 | 00 15 | "comment Hello comment"
            #
            # on the wire, len = strlen, no terminator. The vocabulary is the
            # client's own table at 0x052eacc0; see GM_COMMANDS.
            #
            # WARNING: THE FRAME REGISTERS NO REPLY (its builder 0x0517e050 just does
            # beginMessage/serialise/flush, with none of the
            # `mov word ptr [esp+N], imm16` pairs every other request has). So
            # "what answers 0xF900" has no single answer: the COMMAND's own OK
            # id does. For `comment` that is 0x111E MSG_SET_COMMENT_OK
            # (arm 0x05055b24, which logs "> MSG_SET_COMMENT_OK" and READS
            # NOTHING -- header-only, like 0x1020 and 0x100E; a body here would
            # desynchronise the stream). 0x111F is the NG (arm 0x05055b3f).
            f = inner[2:]
            ln = struct.unpack_from(">H", f, 0)[0] if len(f) >= 2 else 0
            text = f[2:2 + ln].decode("cp932", "replace")
            verb, _, rest = text.partition(" ")
            print("[feworld]    *** 0xF900 GM COMMAND %r (len=%d, verb=%r)"
                  % (text, ln, verb), flush=True)
            if verb == "comment":
                # The client truncates to 23 bytes itself (0x05138240 checks
                # strlen > 0x17 and clips on a DBCS lead byte), so whatever
                # arrives is already the field's real width.
                # WARNING: THE KEY IS "profile_comment", NOT "comment".
                # felobby's CHAR_FIELDS maps the key "comment" to record
                # offset 0xE4, and 0xE4 is the USE-PROHIBITED (suspension)
                # comment -- named from the client's own
                # 0x05025493 "use-prohibited comment %s" and printed by its
                # dump at 0x05025481 as `banned comment %s`. Storing the
                # profile text under "comment" served it back as a BAN
                # NOTICE: the live log read `banned comment JOJ`, which is
                # us telling the client the player is suspended with their
                # own profile text as the reason. It only stayed harmless
                # because the suspension PERIOD fields beside it
                # (period_from 0xDC / period_to 0xE0) are still zero.
                # WARNING: This leaves the comment STORED BUT UNSERVED, which is
                # honest: the channel that carries a comment TO the profile
                # window is still unmapped. Ruled out so far -- /profile's
                # handler 0x05137960 is a stub (`mov al,1; ret`),
                # /comment's 0x05138240 only truncates to 23 bytes so the
                # client keeps nothing locally, and the NG name table has
                # no MSG_*PROFILE*/MSG_GET_COMMENT at all. Best remaining
                # lead: identity sub-record bit 0x8000 -> +0x3d8, a cstr we
                # have never served.
                if _store_char_field(args, "profile_comment", rest):
                    print("[feworld]    profile comment persisted: %r -- served "
                          "back on the next login by whatever carries it; the "
                          "STORE side is now real, which is the half that was "
                          "losing it across a relaunch" % rest, flush=True)
                else:
                    print("[feworld]    WARNING: profile comment %r NOT persisted -- "
                          "no stored character matched account=%r charid=%s"
                          % (rest, _SESSION.get("account"),
                             _SESSION.get("charid")), flush=True)
                if args.set_comment != "off":
                    mid = 0x111E if args.set_comment == "ok" else 0x111F
                    send(conn, outbound,
                         inner_msg(mid, b"", unit_id_of(args)),
                         mode, be, args.seq_mode == "echo", args.world_prefix)
                    print("[feworld] -> 0x30 inner 0x%04X MSG_SET_COMMENT_%s "
                          "(header-only) -- watch the client log for "
                          "'> MSG_SET_COMMENT_OK'"
                          % (mid, "OK" if mid == 0x111E else "NG"), flush=True)
            elif verb in ("setblacklist", "rmblacklist", "getblacklist"):
                # These have local handlers that ALSO build 0x20A0/0x20A1/0x20A2
                # (0x05133220 / 0x051332c0 / 0x051333d0), so the same action can
                # reach us twice by two routes. Answer the message form and log
                # the command form rather than acting on both -- acting twice is
                # how a name lands in the list twice.
                print("[feworld]    (handled via 0x20A0/0x20A1/0x20A2, not "
                      "here -- the command form is logged only)", flush=True)
            else:
                known = any(verb in v for v in GM_COMMANDS.values())
                print("[feworld]    no server-side handler for %r (%s)"
                      % (verb, "a known verb in the client's own table"
                         if known else "NOT in the client's command table -- "
                         "new vocabulary, worth recording"), flush=True)
        elif real_id in _CHAT_IDS:
            # CHAT, all six ids. Built by the /say /all /army /party /tell
            # handlers at 0x051334f0 / 0x05133610 / 0x05133730 / 0x05133970 /
            # 0x05133a90: [cstr [unit+0x389] name][cstr text], and 0x2067 is
            # [cstr TARGET][cstr name][cstr text]. None registers a reply.
            #
            # KEY: THE CLIENT DOES NOT LOG ITS OWN /say. 0x051334f0 joins the
            # words (0x5133c50), sends, and calls 0x05129890 -- which is the
            # per-object BALLOON slot ([obj+0x47c]), not the log. The chat
            # LOG line comes from the chat-window listener at 0x0512bf60,
            # which only ever sees lines the arm 0x05053cbe BROADCASTS
            # (0x509fc50) -- i.e. lines that arrived from the server. So the
            # server's echo of your own line is what put it in the log in
            # retail, and 'self' echoes it with your own unit id, which is
            # the shape the arm has a test for (0x05053d8a: speaker == me ->
            # skip the balloon it already drew). /tell is the exception: its
            # handler logs ">> target : text" itself (0x512c8b0 at
            # 0x05133b22), so echoing a tell would double it.
            #
            # WARNING: THE TEXT IS cp932 ON THE WIRE. Relayed bytes go back out as
            # the same cp932 (encode after decode is byte-identical for valid
            # sequences), and the far client draws them as cp932 too.
            name, want = _CHAT_IDS[real_id]
            want = want or 2
            f = inner[2:]
            parts = [p.decode("cp932", "replace")
                     for p in f.split(bytes(1))[:want]]
            while len(parts) < want:
                parts.append("")
            speaker = parts[1] if real_id == 0x2067 else parts[0]
            text = parts[-1]
            _chat_room_name(speaker)
            print("[feworld]    0x%04X CHAT %s %r: %r%s"
                  % (real_id, name, speaker, text,
                     " (to %r)" % parts[0] if real_id == 0x2067 else ""),
                  flush=True)
            if args.chat_echo == "gm":
                gm_command(conn, outbound, mode, be, args,
                           "@%s: %s" % (speaker, text))
            elif args.chat_echo == "say":
                # The 08-25 shape: back on the same id with --chat-unit-id.
                chat_send(conn, outbound, mode, be, args, real_id, parts)
            elif args.chat_echo == "self" and real_id != 0x2067:
                # The retail shape: the speaker IS this player.
                chat_send(conn, outbound, mode, be, args, real_id, parts,
                          speaker=unit_id_of(args))
            if getattr(args, "chat_relay", "on") == "on":
                n = chat_relay(real_id, parts, field=_SESSION.get("field"),
                               nation=nation_of(args))
                print("[feworld]    chat relay: queued for %d other "
                      "session(s)%s" % (n, "" if n or real_id != 0x2067 else
                                        " -- no in-field session signs as %r"
                                        % parts[0]), flush=True)
        elif (real_id == 0xF102
              and getattr(args, "discard", "on") != "off"):
            # KEY: DISCARDING AN ITEM -- unhandled until now, so a dropped item
            # came back on the next field entry. Reported live 2026-09-06
            # ("dropping my extra cane"), captured the same minute:
            #
            #     f1 02 | 00 00 | 00 00 00 01 | 00 00 03 ed | 02 13 | 00 01 | 00 00
            #
            # Builder 0x05074ea0, and the client names it itself at 0x052de878:
            # `> ComamndDiscardItem name = %s objid = %d` (SE's own typo). Field
            # for field, from the stores into the 16-byte struct it sends:
            #
            #     [u16 0]
            #     [u32 owner ]  0x050739e0(item) -- the object id 0x05073f90
            #                   compares against the local player, and it was 1
            #                   here, which is --unit-id
            #     [u32 uid   ]  [item+0x3c]
            #     [u16 item  ]  word 0 of [item+0x4e8], the TABLE record --
            #                   i.e. the item number, not the uid
            #     [u16 count ]  the caller's argument
            #     [u16 0]
            #
            # WARNING: The uid is the field to act on; the item number is only a
            # cross-check. Acting on the item number would drop the WRONG
            # stack whenever a bag held two of something -- and this bag held
            # two Beginner Wands, which is what made the difference visible.
            f = inner[2:]
            if len(f) < 14:
                print("[feworld]    0xF102 DISCARD: %d-byte body, expected 16 "
                      "-- not decoded: %s" % (len(f), f.hex()), flush=True)
                continue
            owner, duid = struct.unpack_from(">II", f, 2)
            dno, dcount = struct.unpack_from(">HH", f, 10)
            old = item_rows(args)
            equip = [tuple(x) for x in (_load_char_field(args, "equip", []) or [])]
            hit = [(i, r) for i, r in enumerate(old) if int(r[0]) == duid]
            if not hit:
                print("[feworld]    0xF102 DISCARD uid=%d item=%d x%d owner=%d "
                      "-- NOT in this character's bag, nothing removed "
                      "(body %s)" % (duid, dno, dcount, owner, f.hex()),
                      flush=True)
                continue
            i, row = hit[0]
            if int(row[1]) != dno:
                # A cross-check, not a gate: the client built the number from
                # the item's own table record, so a mismatch means our bag and
                # the client's disagree about what uid %d IS -- worth saying
                # out loud rather than silently trusting either.
                print("[feworld]    WARNING: 0xF102 uid=%d is item %d here and %d on "
                      "the client" % (duid, row[1], dno), flush=True)
            if row[3] > dcount:
                new_rows = list(old)
                new_rows[i] = (row[0], row[1], row[2], row[3] - dcount)
                gone = []
            else:
                new_rows = old[:i] + old[i + 1:]
                gone = [(duid, i)]
            worn = [(sl, u) for sl, u in equip if int(u) == duid]
            if worn:
                # Dropping something you are wearing takes it off first, or the
                # stored equipment names a uid the bag no longer has and every
                # later worn-index lookup misses.
                equip = [(sl, u) for sl, u in equip if int(u) != duid]
                _store_char_field(args, "equip", [list(x) for x in equip])
            stored = _store_char_field(args, "items",
                                       [list(r) for r in new_rows])
            print("[feworld]    0xF102 DISCARD uid=%d item=%d x%d -- bag %d -> "
                  "%d row(s)%s, stored=%s. No reply is registered for this id "
                  "and none is sent; the client drops it locally and this is "
                  "only what makes the drop SURVIVE the next field entry."
                  % (duid, dno, dcount, len(old), len(new_rows),
                     ", unequipped from worn slot %s" % worn[0][0] if worn
                     else "", stored), flush=True)
            if worn:
                unequip_push(conn, outbound, mode, be, args,
                             fegamedata.worn_index_for(
                                 fegamedata.items().get(int(row[1]), {})
                                 .get("slot", -1)),
                             "0xF102 discard of worn uid %d" % duid)
            if getattr(args, "bag_organize", "on") != "off":
                bag_layout_push(conn, outbound, mode, be, args, old, new_rows,
                                gone, "discarded uid %d (item %d)"
                                % (duid, dno))
        elif real_id == 0xA011:
            # VERIFIED:KEY: MSG_NPC_HIT_NOTIFY -- THE COMBAT CHANNEL, decoded
            # 2026-09-06 (static). The client is authoritative for its OWN hits
            # on an NPC: it swings, it does the collision, and it TELLS us.
            # Nothing about damage is computed client side -- see combat_hit.
            #
            # Builder 0x05069700 (a method on the unit being hit; the log line
            # is 0x052de4f8 `< MSG_NPC_HIT_NOTIFY : [%08x] SkillId=%d
            # UniqueId=%d`). Writer for writer, and each writer's width is its
            # own advance of [0x533835c] -- 0x5045b80 +1, 0x5045bb0 +2,
            # 0x5045be0 +4, 0x5045ca0 +4 (f32):
            #
            #     [u32 target ]  0x5077cc0(this)     the unit that was HIT
            #     [u32 attacker] 0x5021f00(ev)       gated == the local player
            #     [u32 b      ]  0x5021fb0(ev)
            #     [u32 c      ]  0x5021ee0(ev)
            #     [u16 skill  ]  0x5021ef0(ev)       the skill that landed
            #     [u8  kind   ]  0x5021f20(ev) + 1
            #     [f32 x][f32 y][f32 z]              the HIT POINT
            #
            # It is only sent when ALL of these hold (0x05069700):
            #   * the event object's class tag is 0x3E8 (0x4fcf8f0)
            #   * 0x5021bb0(ev) is true
            #   * the attacker id == [0x533998c]+0x9e0, THE LOCAL PLAYER --
            #     so this is never another player's hit, and PvP is not here
            #   * the target is out of its invincibility window
            #     ([unit+0x8d4] vs the clock); otherwise it logs `Invincible`
            #     (0x052de530) and sends NOTHING
            #   * the skill resolves (0x505f4b0) and 0x504a7c0 accepts it
            f = inner[2:]
            combat_hit(conn, outbound, mode, be, args, f)
        elif real_id in (0x209F, 0x2002, 0x2023):
            # The three fire-and-forget notifies. WARNING: CHECKED: none of them
            # registers an expected reply, so none of them hangs anything, and
            # answering them is not work that is waiting to be done.
            #
            #   0x209F  [u32 [obj+0x3d4]]  built at 0x05079f60, sent by
            #           /disphp (0x05135531) and /freecam (0x05135605/0x051356a5)
            #           and from the scene update (0x04ffa23c/0x04ffa3c0). A
            #           display-state toggle; the observed "toggles 0 -> 1"
            #           is that flag.
            #   0x2002  [u16][u16]  built at 0x0507fe15 (0x5045c40 is the u16
            #           writer, not the u32 one -- the old "[u32]" reading came
            #           from the 4-byte length, not from the writers), gated on
            #           [0x5336d1c]+0x4fc and 0x04ff7f70.
            #   0x2023  14 or 28 B of telemetry at ~400ms.
            f = inner[2:]
            if real_id == 0x2023:
                _SESSION["telemetry"] = _SESSION.get("telemetry", 0) + 1
                if len(f) == 28:
                    note_client_clock(f)
                    field_ready_release(conn, outbound, mode, be, args,
                                        "the first 28-byte clock sample")
                    # The client's own position, i16 x0.1 (see _MV_POS) --
                    # what `!build` places a building at.
                    px, py, pz = struct.unpack_from(">hhh", f, _MV_POS)
                    _SESSION["cpos"] = (px * 0.1, py * 0.1, pz * 0.1)
                echoed = move_authority(conn, outbound, mode, be,
                                        args, f)
                if args.unit_speed_repeat == "on":
                    unit_speed_push(conn, outbound, mode, be, args)
                npc_walk_push(conn, outbound, mode, be, args, f)
                monster_place_push(conn, outbound, mode, be, args, f)
                mob_respawn_tick(conn, outbound, mode, be, args)
                monster_chase_tick(conn, outbound, mode, be, args, f)
                monster_attack_tick(conn, outbound, mode, be, args)
                if _SESSION["telemetry"] % 100 == 1:
                    print("[feworld]    0x2023 telemetry x%d (%d B) -- %s"
                          % (_SESSION["telemetry"], len(f),
                             "ECHOED back as action 0 (--move-authority)"
                             if echoed else
                             "fire-and-forget, not answered"), flush=True)
            elif real_id == 0x209F:
                v = struct.unpack_from(">I", f, 0)[0] if len(f) >= 4 else None
                print("[feworld]    0x209F display-state notify = %s "
                      "(no reply registered)" % v, flush=True)
            else:
                v = struct.unpack_from(">HH", f, 0) if len(f) >= 4 else None
                print("[feworld]    0x2002 %s (no reply registered)" % (v,),
                      flush=True)
        elif real_id == 0x400F:
            # MSG_SERVER_UNIT_LOGIN_REQUEST, built at 0x0504859e and named by the
            # client's own log line at 0x52d5260:
            #     <MSG_SERVER_UNIT_LOGIN_REQUEST : [%s] / ChrID=%d
            #
            #     [cstr account][u32 charid][52-byte credential blob]
            #
            # -- writer for writer: 0x5045cd0 (string, from [0x5336d1c]+0x8e),
            # 0x5045be0 (dword, [edi+0x34] = the chosen character's id), then
            # 0x5045ad0 with an explicit length of 0x34.
            f = inner[2:]
            try:
                e = f.index(b"\0")
                acct = f[:e].decode("cp932", "replace")
                charid = struct.unpack_from(">I", f, e + 1)[0]
                blob = f[e + 5:]
            except (ValueError, struct.error):
                acct, charid, blob = "?", 0, b""
            print("[feworld]    WORLD LOGIN account=%r charid=%d blob=%dB"
                  % (acct, charid, len(blob)), flush=True)
            # WARNING: `acct` IS THE CLIENT'S ECHO OF WHATEVER felobby PUT IN 0xC010 --
            # not a name we can key a store by on its own. Before 2026-08-24
            # that was the constant "TestPlayer" for everybody, and
            # _store_char_field wrote the chosen nation onto whatever character
            # in the single shared roster happened to carry this charid.
            #
            # resolve_account() turns it into the store key felobby used: the
            # echo first (free and exact when the client is verbatim, which is
            # LIKELY but has never been proven byte-for-byte on a live 0x400F),
            # then felobby's handoff file by address, then a direct POL member
            # lookup. It logs which one fired, because a carry that quietly
            # stopped working looks exactly like one that worked.
            key = resolve_account(acct, _peer_ip(conn), args)
            _SESSION["account"], _SESSION["charid"] = key, charid
            _SESSION["wire_account"] = acct
            print("[feworld]    blob: %s" % blob.hex(), flush=True)
            if args.capture_only:
                print("[feworld]    --capture-only: NOT answering", flush=True)
                continue
            # Its builder pre-registers exactly two acceptable replies
            # (0x05048584/0x0504858b): 0x302B OK and 0x302C NG.
            #
            # What the OK arm (0x050476d3) actually DOES is the useful part: it
            # stores one dword at [obj+0x9e0], logs `> MSG_SERVER_UNIT_LOGIN_OK`,
            # and sets [obj+0x948] = 0. That last store is the one that matters --
            # the relay-connect state at 0x0504860b reads [esi+0x948] and only
            # advances the login routine when it is 0 (1 takes the failure path).
            # The NG arm (0x050476b0) sets it to 1.
            #
            # WARNING: THE DWORD IS A GUESS. Its slot could not be pinned by hand-tracing
            # esp through that switch, so --unit-login-value is exposed rather
            # than pretended: 0 is the default, and the client's own log
            # (`> MSG_SERVER_UNIT_LOGIN_OK`) says whether the message was accepted
            # regardless of what the dword turns out to mean.
            # KEY: 2026-08-24: RESOLVE 'auto' TO THE CHARID, and note WHY this is
            # the single most informative value to send.
            #
            # Measured live in the field with felive:
            #   server unit ([0x533998c], the 0x302B target) +0x9e0 = 0
            #   the entity we spawn for the player in 0x1000  id    = charid = 1
            #   player unit [0x533aab4]                       pos   = (0,15.948,0)
            # Three ids that should describe ONE character, and they disagree:
            # the client is told "you are unit 0" and then handed a body in the
            # world called unit 1. The server unit sits inert at the origin while
            # the player unit stands correctly on the ground -- and movement input
            # does nothing. WARNING: THAT IS A HYPOTHESIS FOR THE MOVEMENT WALL, NOT A
            # FINDING; it is a coherent story for the two-object split, no more.
            #
            # KEY: SETTLED 2026-08-24 (STATIC, not yet corroborated live):
            # [esp+0x10] IS THE INNER HEADER'S LEADING u32. --unit-login-value
            # CANNOT reach +0x9e0; --unit-id is the only knob that does.
            #
            # The arm is not a function on its own -- it is an arm of the pump
            # at 0x05047590, and reading its esp needs that prologue:
            # `sub esp,0x14 / push ebp / push esi`, so the 0x14 bytes of locals
            # start at the first local dword. The pump then reads TWO values off
            # the stream before dispatching:
            #     0x050475b0  0x522f9b0(stream, &A)   advances 4  -> u32
            #     0x050475bd  0x522f970(stream, &B)   advances 2  -> u16
            # (both readers confirmed by their own `add ecx,4` / `add ecx,2`
            # bounds check at 0x0522f9c4 / 0x0522f984), and B is the one
            # compared against 0x2005 / 0x302B / 0x302C at 0x050475e1..0x050475f8
            # -- so B is the MESSAGE ID and A is the u32 read BEFORE it, i.e. the
            # frame's leading u32.
            #
            # Four independent sites in that frame agree on the two slots:
            #     0x050475fe  main dispatcher   f(A, B, stream)
            #     0x0504765b  handler chain 1   f(A, B, stream)
            #     0x0504767a  handler chain 2   f(A, B, stream)
            #     0x05047699  handler chain 3   f(A, B, stream)
            # and the OK arm's `mov eax,[esp+0x10]` at 0x050476d9 resolves to the
            # same A. Every one of those only type-checks if A is the header.
            #
            # WARNING: SO ff265024 (--unit-login-value auto) WAS A NO-OP FOR +0x9e0.
            # The payload candidate was already ruled out live (sent charid, read
            # 0 back); this says why, and closes the row.
            #
            # WARNING: AND THERE IS A SECOND, UNMEASURED MISMATCH IN THE SAME PAIR.
            # 0x302B WRITES [0x533998c]+0x9e0 (0x050476d3), but the 0x1027
            # MSG_SET_POSITION handler TESTS [[scene+0x88]]+0x9e0
            # (0x05054e4a: `mov edx,[ecx+0x88]` / 0x05054e57: `mov eax,[edx+0x9e0]`).
            # If those two pointers are not the same object, ANY non-zero
            # --unit-id writes one and tests the other and 0x1027 is dropped in
            # silence -- which is a second, sufficient explanation for the
            # --unit-id auto black screen, independent of the header-on-0x302B
            # bug that was fixed in 36358c17. felive prints both pointers and
            # flags them when they differ; check that BEFORE trusting --unit-id
            # auto as a clean test of anything.
            ulv = (_SESSION.get("charid", 0) if args.unit_login_value == "auto"
                   else int(args.unit_login_value, 0))
            # WARNING: THE HEADER GOES HERE TOO. 2026-08-24: --unit-id auto changed
            # the leading u32 on 0x1027/0x100E/0x1012/0x1127 but NOT on this
            # message, which is the only one that can set the server unit's id.
            # So 0x1027 arrived carrying 1 against a server unit still holding
            # 0, was dropped, [scene+0x296] never got set, and mode 0xa substate
            # 2 parked -> BLACK SCREEN (measured live: the client goes silent
            # right after "0x1027 ... unit=1" and idles out). A mismatch BY
            # CONSTRUCTION, entirely self-inflicted.
            body = inner_msg(0x302B, struct.pack(">I", ulv & 0xFFFFFFFF),
                             unit_id_of(args))
            send(conn, outbound, body, mode, be,
                 args.seq_mode == "echo", args.world_prefix)
            print("[feworld] -> 0x30 inner 0x302B MSG_SERVER_UNIT_LOGIN_OK "
                  "(value=%d%s) -- lands at [0x533998c]+0x9e0, the SERVER "
                  "UNIT's id; re-read it with `felive --scene` in the field"
                  % (ulv, " = charid, --unit-login-value auto"
                     if args.unit_login_value == "auto" else ""), flush=True)
            print("[feworld]    watch the client for '> MSG_SERVER_UNIT_LOGIN_OK'. "
                  "'> MSG_SERVER_UNIT_LOGIN_NG' means it parsed but rejected; "
                  "SILENCE means it never accepted the frame at all.", flush=True)
            # the world clock, now: logged in, no field loading, the map
            # screen about to draw its clock (--world-clock connect)
            clock_connect_push(conn, outbound, mode, be, args)


def acquired_skills(args):
    """The session character's acquired skill ids, as a list of ints."""
    out = []
    for k in _load_char_field(args, "skills", None) or []:
        try:
            out.append(int(k) & 0xFFFFFFFF)
        except (TypeError, ValueError):
            continue
    return out


def acquire_skill(args, skill_id):
    """Add one skill id. Returns (was_new, the full list).

    WARNING: DEDUPED. 0x303E's list is read into a fresh std::list every time
    (0x05024be5 allocates a node per id with no membership check), so serving
    the same id twice puts the same skill in the window twice.
    """
    rows = acquired_skills(args)
    if skill_id in rows:
        return None, rows          # None = already known, nothing written
    rows.append(skill_id)
    # WARNING: REPORT WHAT THE STORE SAID, not what we intended. The first version
    # returned True here and the caller printed "PERSISTED" off it -- so a
    # failed write (no matching stored character) would have logged success and
    # the player would have lost the points silently. `check-our-own-logs` is
    # worth nothing if the log is generous with itself.
    return _store_char_field(args, "skills", rows), rows


# ---------------------------------------------------------------------------
# 0x1075 -- THE ACQUIRED SKILL LIST. Skills persisted server-side but never came
# back, so they vanished on every relaunch. This is the message that returns
# them, and it was found by walking the DRAW site backwards, not by name.
#
# THE CHAIN, bottom up, every link measured 2026-08-25:
#
#   the skill row's "acquired" flag is
#       0x050D3A06  cmp word [unit + skillId*2 + 0xA14], 0
#                   seta al ; mov [widget+0x85], al
#   and the same array gates whether a row is offered at all
#       0x050D50C1  cmp word [unit + prereq*2 + 0xA14], 0
#   the array is built by the CONSTRUCTOR at
#       0x0507D5B6  lea edi,[esi+0xA14] ; mov ecx,0x252 ; rep stosd
#                   0x252 dwords = 0x948 bytes = **0x4A4 u16 entries**, ending
#                   at 0x135C -- and 0x4A4 is exactly the bound the client's own
#                   accessors check (0x0507D608 add, 0x0507D62A get) and exactly
#                   the bound the learn path checks on the SKILL ID
#                   (0x050D4D23 `cmp ax,0x4A4; jae`). So the index IS the id.
#   the only network writer of that array is
#       0x05052180  0x0504CB30(objId,1) -> 0x0504D410 -> unit
#                   [u16 count] then count x { [u16 idx][u8 value] }
#                   [unit + idx*2 + 0xA14] = value
#   which is bit 3 of a four-way mask decoder
#       0x05051E20  [u32 mask]
#                     &1 -> 0x05051E80  [u8 n] x {u8 idx, u8 v} -> [unit+0x9F0+idx]
#                                       (and [unit+0x3AC]) -- a different array
#                     &2 -> 0x05052200      &4 -> 0x05051F10   -- not needed here
#                     &8 -> 0x05052180  THE SKILLS
#   whose only caller is the arm at 0x0503A423, which fedisp resolves to
#       0x1075, dispatcher c0 (0x05039FA0 -- `cmp eax,0x1075 / je` is literally
#       the first comparison in that dispatcher, before its own jump table)
#
# 🚫 THIS IS WHY THE NAME SEARCHES FAILED. 0x1075 has NO entry in the client's
# NG table and no registered request, so no name sweep and no reply-pair sweep
# could reach it -- the same blind spot that hid 0x2033 and 0x1100. The two ids
# whose NAMES said "acquired skill list" (0x1073/0x1074) only log, and 0x303E,
# picked the same way, was a debug echo. Three for three: walk the arm, not the
# name.
#
# WARNING: THE INDEX IS UNBOUNDED ON THE WIRE. 0x05052180 writes
# `[unit + idx*2 + 0xA14]` with **no range check** -- unlike every one of the
# client's own accessors. An idx of 0xFFFF writes ~0x1FFFE bytes past the array,
# straight through [unit+0x1360] (the dress-applier witness) and [unit+0x138C]
# (the Field Out countdown). skill_list_body() drops anything >= 0x4A4 rather
# than clamping it, because clamping would silently mark the WRONG skill.
#
# WARNING: NOT LIVE-TESTED. What the u8 VALUE means is also not measured: the predicate
# is `!= 0`, but 0x0507D600 ADDs into the same slot, which reads like a level or
# a count rather than a flag. 1 is the smallest thing that satisfies every
# reader found; --skill-list-value exists to try others without a redeploy.
# ---------------------------------------------------------------------------
# 0x1075 MASK BIT 0 -- THE CLASS LEVEL ARRAY, and it is why a skill you own
# still cannot be equipped.
#
# Reported live 2026-08-25: bit 3 landed, the skills came back and the window
# shows them as owned -- and double-clicking one to equip does nothing. The
# skill window sends NOTHING when you do that (its only outbound builder in the
# whole class is the 0x2049 GET! at 0x050D4AA8/0x050D4AB4), so equip is a purely
# LOCAL decision and something local is refusing it.
#
# The refusal is a validator that returns small reason codes, and one of its
# arms is:
#
#     0x05076195  movzx eax, byte [edx + ebx + 0x9F0]   ; [unit + class + 0x9F0]
#     0x0507619D  cmp   ax, word [ebp + 0x86]           ; the skill's REQUIRED LEVEL
#     0x050761A6  sbb   eax, eax
#     0x050761A8  and   eax, 4                          ; 0 = allowed, 4 = too low
#
# `[unit + 0x9F0 + classId]` is the player's LEVEL IN THAT CLASS (the class id is
# `[unit+0x3AB]`, the same byte 0x050D4E24 uses to pick the skill table). It is
# read as a byte in a dozen places -- 0x050CCA96, 0x050DEA4E/0x050DEA69,
# 0x050DFF01, 0x050E129E, 0x050E439F, 0x050E5298 -- and its constructor clears
# it at 0x0507D596. **We have never sent it, so every class sits at level 0 and
# every skill's level requirement fails.**
#
# It is bit 0 of the SAME 0x1075 record the acquired list rides on
# (0x05051E80): [u8 count] then count x { [u8 idx][u8 value] }, writing
# [unit + 0x9F0 + idx] and ALSO [unit+0x3AC] with the last value written.
#
# WARNING: A LEVEL IS A CLAIM, and we do not track progression -- so this is a knob
# with a chosen default, said out loud, rather than a number that arrives by
# accident. The accident is the status quo: nobody chose 0 either, and 0 is what
# has been blocking every equip. That is an earlier note read the
# other way round -- the unchosen zero is the bug, not the safe option.
# WARNING: Bit 0 also writes [unit+0x3AC], which the Status screen draws, so whatever
# is set here is VISIBLE to the player as their level. Do not raise it casually.
SKILL_LIST = (0x1075, "acquired skill list (unnamed -- no NG entry, no request)",
              0x0503A423)
SKILL_ARRAY_MAX = 0x4A4      # 0x0507D5B6's own `mov ecx,0x252` (= 0x4A4 u16)
SKILL_MASK_BIT = 0x8         # 0x05051E20 bit 3 -> 0x05052180
CLASS_MASK_BIT = 0x1         # 0x05051E20 bit 0 -> 0x05051E80
CLASS_ARRAY_MAX = 0x100      # [u8 idx] -- the index is a BYTE, so 0..255
# WARNING: RETRACTED 2026-09-09. This said: "it starts at [unit+0x9F0] and the SKILL
# array starts at [unit+0xA14], so there are 0x24 = 36 bytes of it, and `all:N`
# fills exactly that -- not one byte into the skills." The gap is real and the
# skills are where it said, but the 36 bytes are NOT all levels: the Status
# screen draws `Exp %d/%d` from `[unit + class*4 + 0x9F8]` and `[unit+0x135c]`
# (0x050e1388), so a per-class EXP DWORD array sits at +0x9F8, immediately
# behind 8 bytes of levels. `all:30` therefore wrote level 30 over the EXP of
# every class, and the live Status screen read **Exp 505290270/1679**:
# 505290270 is 0x1E1E1E1E, four bytes of 30. Seven levels + seven dwords +
# the skill array fit the gap exactly, and FE_CLASS_BASIC_PARAM_DATA has
# exactly 7 rows.
CLASS_LEVEL_SLOTS = 7        # bytes at +0x9F0 (+0x9F7 is padding)
CLASS_EXP_BASE = 0x8         # +0x9F8, as an index into the same byte array


def self_class_id(args):
    """The class index the CLIENT will look this player up under.

    KEY: It is `[unit+0x3AB]`, and we already serve that byte -- as `look1` out of
    the stored character, bit 0x04 of the avatar sub-record. It is not
    --status-class and it is not a constant.

    THIS IS WHY THE FIRST ATTEMPT DID NOTHING. `--class-levels 1:30` wrote level
    30 into class index 1 while the stored character's look1 is 2, so
    [unit+0x9F0+2] stayed at 0 and the gate it was meant to open never saw a
    different number. The level theory was not falsified by that attempt -- the
    attempt never tested it. WARNING: Deriving the index from the same place the byte itself
    comes from is the only way these two cannot drift apart again.

    WARNING: `look1` is feworld's own label for +0x3AB and it is an APPEARANCE guess
    inherited from felobby's CHAR_FIELDS. The client uses that byte as a CLASS:
    0x050D4E24 feeds it to 0x05006F40 to pick the skill table, and 0x05076152
    feeds it to the level lookup. Two independent class uses, no appearance use
    found. The name is kept for store compatibility; the meaning is class.
    """
    ch = _self_char(args)
    if not ch:
        return None
    try:
        return int(ch.get("look1", 0)) & 0xFF
    except (TypeError, ValueError):
        return None


# WARNING: THE CLASS-LEVEL ARRAY IS 8 BYTES LONG, AND WHAT FOLLOWS IT IS THE EXP.
# Read 2026-09-09 off the Status screen's own draw (0x050e1388):
#
#     mov ecx, [esi+0x135c]                 ; the SECOND %d
#     mov dl, [esi+0x3ab]                   ; the class
#     mov eax, [esi + edx*4 + 0x9f8]        ; the FIRST %d  <-- per-class EXP
#     sprintf(buf, "%d/%d", eax, ecx)
#
# so the unit lays out: class LEVELS as bytes at +0x9F0, then a per-class EXP
# DWORD array at +0x9F8, then the skill array at +0xA14 -- and 7 classes fit
# each of them exactly (FE_CLASS_BASIC_PARAM_DATA has 7 rows).
#
# The bit-0 setter (0x05051edf `mov [ecx+esi+0x9f0], dl`) takes the index as a
# u8 and is UNBOUNDED, so `--class-levels all:30` wrote 36 levels straight
# through the EXP array: the live Status screen read
# **Exp 505290270/1679**, and 505290270 is 0x1E1E1E1E -- four bytes of level 30.
# Levels are clamped to the array here, on the way OUT, because the store was
# seeded with 36 of them before this was known and a stored table cannot be
# fixed by changing a flag.
def class_exp_rows(self_class, exp):
    """The four (index, byte) pairs that put `exp` in the current class's EXP
    dword, addressed through the SAME byte array the levels use.

    That is not a trick, it is the only wire path: 0x1075's four bits are the
    level bytes (0x1), +0x135c (0x2), an effect record (0x4) and the skill
    words (0x8) -- nothing carries +0x9F8, and the level setter's index reaches
    it because it is unbounded. Little-endian, because the client reads the
    result as a dword."""
    if self_class is None:
        return []
    base = CLASS_EXP_BASE + int(self_class) * 4
    v = max(0, int(exp)) & 0xFFFFFFFF
    return [(base + i, (v >> (8 * i)) & 0xFF) for i in range(4)]


def class_level_rows(spec, self_class=None):
    """Parse `--class-levels` (`CLASS:LEVEL,...`) into (idx, level) pairs.

    CLASS may be the literal `self`, which resolves to the stored character's
    own class -- see self_class_id(). That is the default, and a hardcoded index
    is the thing it exists to stop anyone writing again.

    Out-of-range indices are DROPPED for the same reason skill ids are: the
    decoder at 0x05051E80 reads the index as a u8, so it cannot overrun on its
    own -- but a level for a class that does not exist is a silent lie in the
    array rather than an error, and dropping it says so in the log.
    """
    rows, dropped = [], []
    for part in (spec or "").split(","):
        part = part.strip()
        if not part:
            continue
        try:
            idx_s, lvl_s = part.split(":")
            lvl = int(lvl_s, 0)
            if idx_s.strip().lower() == "all":
                # WARNING: LIVE 2026-09-05: EVERY item refused with "Wrong class;
                # can't equip", which is reason code 4 of the validator at
                # 0x05076090 -- `[unit+0x9F0 + [unit+0x3AB]] < [tbl+0x86]`,
                # i.e. the level in the class the CLIENT thinks the unit is.
                # We set only the class our stored `look1` names, so if that
                # byte lands differently the level sits in the wrong slot and
                # every item is "too low". `all:N` fills the whole array,
                # which cannot miss.
                rows.extend((i, lvl) for i in range(CLASS_LEVEL_SLOTS))
                continue
            if idx_s.strip().lower() == "self":
                if self_class is None:
                    dropped.append(part + "  (no stored character yet)")
                    continue
                idx = self_class
            else:
                idx = int(idx_s, 0)
        except ValueError:
            dropped.append(part)
            continue
        if 0 <= idx < CLASS_ARRAY_MAX and 0 <= lvl <= 0xFF:
            rows.append((idx, lvl))
        else:
            dropped.append(part)
    return rows, dropped


def _clamp_class_rows(rows, why=""):
    """Drop level rows outside the 7-slot array. See CLASS_LEVEL_SLOTS."""
    keep = [(i, v) for i, v in rows if 0 <= int(i) < CLASS_LEVEL_SLOTS]
    if len(keep) != len(rows):
        print("[feworld]    class levels: %d of %d rows are outside the "
              "%d-slot array and were DROPPED%s -- index %d onward is the "
              "per-class EXP dwords at +0x9F8, and writing levels over them is "
              "what made the Status screen read Exp 505290270 (0x1E1E1E1E)"
              % (len(rows) - len(keep), len(rows), CLASS_LEVEL_SLOTS,
                 (" (%s)" % why) if why else "", CLASS_LEVEL_SLOTS), flush=True)
    return keep


def stored_class_levels(args, self_class):
    """This CHARACTER's class levels, seeded from `--class-levels` once.

    KEY: THE LEVEL TABLE IS PROGRESSION, so it cannot be a flag. `--class-levels
    all:30` gave every class of every player on the server level 30; a player
    who levelled could not be told from one who had not, and nothing a player
    did could change the number. Same contract as _seeded_value one type up: the
    flag is the STARTING table for a character with none stored, and after that
    the store is served.

    Stored as {class index: level} with STRING keys, because that is what JSON
    does to an int key and pretending otherwise is how a dict read back from a
    store stops matching the one written to it. Converted here, once.

    Returns (rows, dropped) exactly as class_level_rows does, so the caller and
    its whole log block are unchanged.

    WARNING: AN EMPTY `--class-levels` STILL SENDS NOTHING, whatever the store holds,
    and that is not a corner case -- it is the same rule _seeded_value states
    for an unset flag ("unset must not look like broke"). Here it is also
    PROTOCOL-CRITICAL: an empty flag clears CLASS_MASK_BIT, and a mask bit set
    with no block behind it desynchronises the whole 0x1075 record (bits 0/1/2
    each promise an array to 0x05051E80 / 0x05052200 / 0x05051F10). So the
    admin's off switch has to win over the store, or turning the class block
    off would stop working the moment a table had been seeded -- which is
    exactly what fe_ui_test caught when this was written the other way round.

    2026-09-11: the default seed is `self:1` (DEFAULT_CLASS_LEVELS) -- a NEW
    character starts at Lv1 in its own class and climbs by EXP (feprog's
    0x2059). A character that already has a table keeps it: prod's stored
    Lv30s stay 30 (nobody is demoted by a deploy); `!setlevel N` resets one.
    """
    spec = getattr(args, "class_levels", DEFAULT_CLASS_LEVELS)
    if not (spec or "").strip():
        return [], []
    stored = _load_char_field(args, "class_levels", None)
    if stored:
        rows, bad = [], []
        for k, v in sorted(stored.items() if isinstance(stored, dict)
                           else stored, key=lambda kv: int(kv[0])):
            try:
                idx, lvl = int(k), int(v)
            except (TypeError, ValueError):
                bad.append("%r:%r  (unreadable stored row)" % (k, v))
                continue
            if 0 <= idx < CLASS_ARRAY_MAX and 0 <= lvl <= 0xFF:
                rows.append((idx, lvl))
            else:
                bad.append("%d:%d  (stored, out of range)" % (idx, lvl))
        if rows:
            return rows, bad

    rows, bad = class_level_rows(spec, self_class)
    if rows and _store_char_field(
            args, "class_levels", {str(i): l for i, l in rows}):
        print("[feworld]    class_levels: no stored table for account=%r "
              "charid=%s -- seeded %d class(es) from --class-levels; from now "
              "on the STORE is served, not the flag"
              % (_SESSION.get("account"), _SESSION.get("charid"), len(rows)),
              flush=True)
    return rows, bad


def skill_list_body(skill_ids, value=1, class_rows=()):
    """Build 0x1075 the way 0x05051E20 + 0x05052180 read it.

    Ids at or past SKILL_ARRAY_MAX are DROPPED, not clamped: the decoder has no
    bounds check of its own, and folding an out-of-range id onto the last slot
    would light up a skill the player does not have instead of writing past the
    object. Both are wrong; only one is silent.
    """
    rows, dropped = [], []
    for sid in skill_ids:
        sid = int(sid)
        if 0 <= sid < SKILL_ARRAY_MAX:
            rows.append(sid)
        else:
            dropped.append(sid)
    class_rows = list(class_rows)
    mask = (CLASS_MASK_BIT if class_rows else 0) | SKILL_MASK_BIT
    body = struct.pack(">I", mask)
    # WARNING: BIT ORDER IS WIRE ORDER. 0x05051E20 tests bit 0 first and bit 3 last,
    # so the class block must precede the skill block or both decode as garbage.
    if class_rows:
        body += struct.pack(">B", len(class_rows))
        for idx, lvl in class_rows:
            body += struct.pack(">BB", idx, lvl)
    body += struct.pack(">H", len(rows))
    for sid in rows:
        body += struct.pack(">HB", sid, value & 0xFF)
    return body, rows, dropped


def skill_list_push(conn, outbound, mode, be, args):
    """Push 0x1075 so the skills the store already holds come back."""
    ids = acquired_skills(args)
    grant = getattr(args, "skill_grant", DEFAULT_SKILL_GRANT)
    if grant == "class":
        # KEY: 2026-09-11, THE DEFAULT: the stored skills PLUS what the class
        # starts knowing -- FE_CLASS_BASIC_PARAM_DATA's +0x70 array, served as
        # owned and FREE (sp_spent skips them). It carries BOTH halves a Lv1
        # character needs: the weapon/armour PROFICIENCIES the equip
        # validator's code 5 tests on the starting gear (Warrior 437..441/444/
        # 447, Scout 442/436/446, Sorcerer 443/445) and the starting SKILLS
        # (Warrior 0 basic attack + 5; Scout 130/135 basic bow/dagger + 140;
        # Sorcerer 270 basic magic + 275). Nothing in the client grants them
        # itself: the class record's only readers are the validator's class
        # check (0x0507615B) and UI. 'items' served proficiencies off the BAG
        # instead, which let any class wear any family it happened to carry.
        start = granted_class_skills(args)
        ids = sorted(set(ids) | set(start))
        print("[feworld]    --skill-grant class: %d stored + the class's own "
              "starting set %s (FE_CLASS_BASIC_PARAM_DATA +0x70, free)"
              % (len(acquired_skills(args)), start or "EMPTY -- no class "
                 "row; nothing granted"), flush=True)
    elif grant == "all":
        # THE PROBE THAT ANSWERED IT, kept only as an A/B. Every item refused
        # with "Wrong class; can't equip." -- and that TEXT is sub-code 3 of
        # message 0xF0FF (the catalogue row at 0x5281d80), which the caller
        # emits for validator code 5 (0x050b66b9), not the class code. Code 5
        # is the PREREQUISITE SKILL arm (0x050761AC). Granting all 1188 ids
        # proved that; it also hands the character every skill in the game,
        # which is why it is no longer the default.
        ids = list(range(SKILL_ARRAY_MAX))
        print("[feworld]    --skill-grant all: serving every skill id as owned "
              "-- A PROBE, not a setting. It grants the whole skill tree; use "
              "`items` unless you are re-running the 2026-09-05 A/B.",
              flush=True)
    elif grant == "items":
        # THE NARROW FORM. An item names up to two prerequisite skills at its
        # table record's +0x88 and the validator (0x050761AC) passes when ONE
        # of them is owned in [unit+0xA14 + id*2]; an item that names none
        # (both 0xffff) skips the check. They are weapon/armour PROFICIENCIES,
        # one per family -- 436 dagger, 437..439 axe/sword, 440 great axe,
        # 441 hammer, 442 bow, 443 wand, 444 shield, 445..447 armour weights --
        # so what a character needs is exactly the set its own bag names.
        # Anything it does not carry stays unlearned.
        bag = [int(no) for _u, no, _f, _c in item_rows(args)]
        need = fegamedata.item_skills(bag)
        ids = sorted(set(ids) | set(need))
        print("[feworld]    --skill-grant items: %d stored skill(s) + the %d "
              "PREREQUISITE skill(s) the %d item(s) in this bag name (%s) -- "
              "the ids at each item table record's +0x88, which is what "
              "validator code 5 tests. Nothing else is granted."
              % (len(ids) - len(need) if not set(need) & set(ids) else
                 len(acquired_skills(args)), len(need), len(bag),
                 ", ".join(str(x) for x in need) or "none"), flush=True)
    self_class = self_class_id(args)
    class_rows, class_bad = stored_class_levels(args, self_class)
    # WARNING: the levels are 7 bytes; index 8 onward is the per-class EXP dwords.
    class_rows = _clamp_class_rows(class_rows, "stored table")
    # ...and the EXP goes in on the SAME bit, as the dword the Status screen
    # draws as the first half of "Exp %d/%d". 2026-09-11: EXP bytes FIRST and
    # the own class's level LAST, because the bit-0x1 setter also stores the
    # last value it writes into [unit+0x3AC] (0x05051EEA) -- a unit-list row
    # draws that as the level (0x050E43B7), and it used to get an EXP byte.
    own = [r for r in class_rows if self_class is not None and r[0] == self_class]
    class_rows = (exp_class_rows(args)
                  + [r for r in class_rows if r not in own] + own)
    body, rows, dropped = skill_list_body(ids, args.skill_list_value, class_rows)
    mid, name, arm = SKILL_LIST
    send(conn, outbound, inner_msg(mid, body, unit_id_of(args)),
         mode, be, args.seq_mode == "echo", args.world_prefix)
    mask = (CLASS_MASK_BIT if class_rows else 0) | SKILL_MASK_BIT
    print("[feworld] -> 0x30 inner 0x%04X %s  mask=0x%X %d skill(s) value=%d "
          "(%d body bytes, arm %08x) -- writes [unit+0x%X + id*2] on unit %d; "
          "the Status/skill window reads that array directly (0x050D3A06)"
          % (mid, name, mask, len(rows), args.skill_list_value,
             len(body), arm, 0xA14, unit_id_of(args)), flush=True)
    if rows:
        print("[feworld]    ids: %s" % ", ".join(str(x) for x in rows),
              flush=True)
    print("[feworld]    this character's class ([unit+0x3AB], served as the "
          "stored `look1`) = %s"
          % ("UNKNOWN -- no stored character, so `self:` rows are dropped"
             if self_class is None else self_class), flush=True)
    if class_rows:
        print("[feworld]    class levels: %s -- [unit+0x9F0+class] is what the "
              "equip validator compares against a skill's required level "
              "(0x05076195); at 0 every skill is refused and double-click does "
              "nothing"
              % ", ".join("class %d = %d" % r for r in class_rows), flush=True)
    if class_bad:
        print("[feworld]    DROPPED unparseable/out-of-range --class-levels "
              "entries: %s" % ", ".join(class_bad), flush=True)
    if dropped:
        print("[feworld]    DROPPED %d id(s) outside 0..%d: %s -- the client's "
              "decoder has NO bounds check, so these would have written past "
              "the array and through [unit+0x1360]/[unit+0x138C]"
              % (len(dropped), SKILL_ARRAY_MAX - 1,
                 ", ".join(str(x) for x in dropped)), flush=True)


# ---------------------------------------------------------------------------
# THE SKILL PALETTE: 0x2029 AND 0x202A ARE THE SAME MESSAGE IN BOTH DIRECTIONS
#
# 2026-09-06. Double-clicking a skill in the skill window ALREADY sent a
# request and feworld had no handler for it, so nothing reached the skill bar.
# The reason the request looked like a dead end is that it registers no reply
# pair -- and it registers none because the answer is the SAME ID COMING BACK.
#
#     out  0x051622F0   [u16 1 << slot][u16 skillId][u8 1][u8 0]
#     out  0x051623B0   [u16 1 << slot]                        (clear a slot)
#     in   c0 arm 0x0503A739 -> 0x0503CF60                     (set)
#     in   c0 arm 0x0503A753 -> 0x0503D0F0                     (clear)
#
# and the inbound workers read a MASK plus one record per set bit, so one
# message can carry the whole palette:
#
#     [u16 mask]                                        0x0503CF70
#     per set bit, ascending:  [u16 skillId][u8][u8]     0x0503CF90/9C/A8
#
# KEY: THE CLIENT DOES NOT APPLY ITS OWN CLICK. The sender (vtable 0x05297688
# +0x24) and the local setter (+0x28, 0x05162360) are two different methods and
# the double-click only calls the first; the inbound worker calls the second
# (0x0503CFC8, `call [vtbl+0x28]` on the singleton at 0x053491E8). That is the
# equip pattern exactly -- 0x102A all over again -- and it is why pressing a
# skill did nothing at all rather than doing something and losing it.
#
# The local setter takes four arguments (`ret 0x10`) and uses two: the slot and
# the skill id. It bails unless 0 <= slot < 8 (0x0516236A/0x0516236F), so the
# palette is EIGHT slots even though the mask is sixteen bits wide, and it
# resolves the id through 0x0505F4B0 into `[palette + slot*12 + 0x54]`.
#
# WARNING: BOTH WORKERS DEREFERENCE TWO SINGLETONS WITH NO NULL CHECK -- the palette
# at 0x053491E8 (per set bit) and 0x053491EC (unconditionally, at 0x0503CFE9,
# even for an empty mask). Both are zeroed at startup (0x05155FA0) and built
# with the in-game HUD, so this must never be sent to a client that has no HUD.
# Answering a request the client itself just sent is safe by construction -- it
# sent it FROM that object. The entry replay is not, which is why it is a knob.
PALETTE_SLOTS = 8               # 0x0516236F `cmp edi, 8 / jge` -- the bail
PALETTE_MASK_BITS = 16          # 0x0503CFCC `cmp esi, 0x10` -- the loop bound


def palette_rows(args):
    """The stored palette as a sorted [(slot, skill id)], slots 0..7."""
    out = {}
    for row in (_load_char_field(args, "palette", []) or []):
        try:
            slot, skill = int(row[0]), int(row[1])
        except (TypeError, ValueError, IndexError):
            continue
        if 0 <= slot < PALETTE_SLOTS and 0 <= skill <= 0xFFFF:
            out[slot] = skill
    return sorted(out.items())


def palette_set_body(rows):
    """0x2029 outbound: [u16 mask] + [u16 skill][u8 1][u8 0] per set bit.

    The two trailing bytes are what the client's own builder sends (1 then 0)
    and what its reader consumes; the local setter ignores both. Copying the
    client is the cheap way to be right about a field nothing reads yet.
    """
    rows = [(s, k) for s, k in rows if 0 <= s < PALETTE_MASK_BITS]
    mask = 0
    for slot, _skill in rows:
        mask |= 1 << slot
    body = struct.pack(">H", mask)
    for _slot, skill in sorted(rows):
        body += struct.pack(">HBB", skill & 0xFFFF, 1, 0)
    return body


def palette_clear_body(slots):
    """0x202A outbound: [u16 mask] and nothing else (worker 0x0503D0F0)."""
    mask = 0
    for slot in slots:
        if 0 <= int(slot) < PALETTE_MASK_BITS:
            mask |= 1 << int(slot)
    return struct.pack(">H", mask)


def palette_push(conn, outbound, mode, be, args, rows, why):
    """Send the palette the client should be showing."""
    if not _SESSION.get("in_field"):
        print("[feworld]    0x2029 NOT sent (%s): no field yet. Both workers "
              "deref the HUD singletons 0x053491E8/0x053491EC with no null "
              "check, and they are null until the in-game HUD is built."
              % why, flush=True)
        return 0
    if not rows:
        print("[feworld]    palette (%s): nothing stored, nothing to push"
              % why, flush=True)
        return 0
    send(conn, outbound,
         inner_msg(0x2029, palette_set_body(rows), unit_id_of(args)),
         mode, be, args.seq_mode == "echo", args.world_prefix)
    print("[feworld] -> 0x30 inner 0x2029 SKILL PALETTE %s (%s) -- one record "
          "per set bit, applied by 0x05162360 into [palette + slot*12 + 0x54]"
          % (", ".join("slot %d = skill %d" % r for r in rows), why), flush=True)
    return len(rows)


def char_record_push(conn, outbound, mode, be, args):
    """0x1003 -- THE CHARACTER RECORD. This is what actually writes Skill Points.

    WARNING: 0x303E DOES NOT. Retracted 2026-08-25 after serving it live with nine
    sentinels and watching the Status screen come back all zeros: its arm decodes
    the record, prints it to the in-game message window and FREES it, storing
    nothing. See status_push() -- kept as a decode oracle, not a setter.

    THE CHAIN, every link measured, bottom up:

        the Status window draws Skill Points from
            0x050e13fc  movsx edx, word ptr [esi + 0x498]      i16
        the ONLY writer of +0x498 is the mask-gated applier
            0x0507a990  test bl,1 -> lea eax,[esi+0x498]       BIT 0
                        (17 field reads, ALL of them mask-gated -- verified, so
                         a mask with one bit set puts exactly one i16 on the
                         wire and nothing else)
        which is called by the character-record decoder
            0x0503acb3  call 0x0507a990(stream, mask, mask2)
        which is 0x1003 kind 0
            0x0503ab2d  u8 kind -> jump table 0x0503bb0c, kind 0 = 0x0503ab4b
        dispatched by 0x05039fa0 -- the FIFTH handler on the world pump, which
        was missing from our map until 2026-08-25. 0x100E MSG_ADD_COMPLETE lives
        in it too, and we have been serving that successfully for weeks, which
        is the proof the handler list was short and not the client.

    THE WIRE:

        [u8  kind]        0 = the full record (8 = an update form, unmapped)
        [u32 flags]       read at 0x0503ac62, then:
          flags & 1  ->   [u32 x]           0x0503ac75, fed to 0x05079d60
          flags & 2  ->   [u32 mask]        0x0503ac95
                          [u32 mask2]       0x0503aca1
                          then ONE i16 per set bit, in bit order:
                              bit 0 -> +0x498  SKILL POINTS
                              bit 1 -> +0x49a    bit 2 -> +0x49e
                              bit 3 -> +0x4a0    bit 4 -> +0x4a4
                              bit 5 -> +0x4a6    bit 6 -> +0x4aa
                              bit 7 -> +0x4ac    ...

    WARNING: THE TARGET IS THE FRAME'S LEADING u32. Kind 0 looks the object up with
    0x0504cb30(<that u32>, 3) and allocates a fresh 0xa08-byte one if it misses
    (0x0503ab4b..0x0503ab73). So --unit-id has to name the player's unit or this
    writes Skill Points onto a phantom nobody is looking at. It currently sends
    1, and the charid is 1.

    WARNING: AND ONLY BIT 0 IS MEASURED. The other sixteen offsets are known but which
    STAT each one is is not -- +0x498 is pinned only because the Status window
    reads that exact offset for that exact label. --char-mask is deliberately
    1, not 0xFFFF: a mask is a promise about how many i16 follow, so a bit set
    without a value behind it does not draw a wrong number, it DESYNCHRONISES
    the record mid-decode.
    """
    fields = args.char_fields
    mask = args.char_mask & 0xFFFFFFFF
    body = struct.pack(">BII", 0, 2, mask) + struct.pack(">I", 0)
    for i in range(32):
        if mask & (1 << i):
            # The same two bytes for -1 and 0xFFFF; the old `>h` of a masked
            # value raised struct.error on anything above 32767.
            body += struct.pack(">H", int(fields.get(i, 0)) & 0xFFFF)
    send(conn, outbound, inner_msg(0x1003, body, unit_id_of(args)),
         mode, be, args.seq_mode == "echo", args.world_prefix)
    named = {0: "SKILL POINTS (+0x498)"}
    print("[feworld] -> 0x30 inner 0x1003 CHARACTER RECORD kind=0 flags=2 "
          "mask=0x%X -> %d i16: %s  [target unit = the frame's leading u32 = %d]"
          % (mask, bin(mask).count("1"),
             ", ".join("bit%d=%d%s" % (i, fields.get(i, 0),
                                       " " + named[i] if i in named else "")
                       for i in range(32) if mask & (1 << i)),
             unit_id_of(args)), flush=True)


def status_push(conn, outbound, mode, be, args):
    """0x303E -- THE CHARACTER STATUS RECORD, and it carries the SKILL LIST.

    WARNING: THE REASON SP IS 0, SKILL POINTS IS 0 AND EVERY `GET!` IS GREYED OUT:
    feworld has never sent this message. Not once -- 0x303E appears nowhere in
    this file before 2026-08-25.

    THE WIRE, read call by call off arm 0x05024a80 (c2), reader by reader:

        0x05024b08  u32     id
        0x05024b17  cstr    name
        0x05024b23  u8      sex
        0x05024b32  u16     class_type
        0x05024b41  u32  \
        0x05024b50  u32   |
        0x05024b5f  u32   |
        0x05024b6e  u32   |
        0x05024b7d  u32   >  NINE u32 -- see the warning below
        0x05024b89  u32   |
        0x05024b95  u32   |
        0x05024ba1  u32   |
        0x05024bad  u32  /
        0x05024bb9  u16     nation
        0x05024bc8  cstr    (a second string)
        0x05024bd4  u32     COUNT
        0x05024bf0  u32     skill id      -- x COUNT, loop 0x05024be5..0x05024c44,
                                             each id linked into a 0xc-byte list
                                             node at [node+8]

    The client's own debug dump at the end of that arm prints the decoded record
    field by field (format strings 0x052d3c64..0x052d3d0c) and then the list
    under `--------skilllist--------` (0x052d3c48), resolving each id to a skill
    NAME through 0x0505f4b0. The dumped scalars are exactly nine numbers --
    skill_point, life, power, stamina, down, gold, ring, fame, total_score --
    which is why the nine u32 above is a clean fit and not a coincidence.

    WARNING: WHICH OF THE NINE IS `skill_point` IS **NOT ESTABLISHED**. The dump's
    PRINT order is known; the WIRE order is not, and the two need not agree.
    Trying to pin it by matching the readers' `lea ecx,[esp+N]` destinations
    against the dump's loads did not converge -- the stack delta drifts through
    the sprintf sequence -- so it is left UNKNOWN rather than guessed.

    Guessing here is the an earlier note failure exactly:
    a wrong slot would put the player's skill points into `gold` or `fame`,
    every screen would still render, and it would read as "served, works".

    🔬 SO THE DEFAULT IS A PROBE, NOT A GUESS. --status-nums defaults to
    101..109, nine DISTINCT sentinels in wire order. Send it once and read the
    status screen: whichever field shows 10N names slot N, and one run labels
    all nine at once. Then set the real values and this becomes a server record.

    WARNING: AND THE TRIGGER IS UNMEASURED. 0x303E registers no reply anywhere in the
    image, so it is a server PUSH with no request behind it -- but WHEN the
    client expects it is not known. This fires it after field entry, next to the
    other post-entry pushes, because that is where the client is when the status
    screen can be opened. If the screen shows nothing, the message may simply
    have arrived with no screen to receive it, which is the same failure mode
    0x1018 had (measured 2026-08-19: one sent, zero received) -- resend rather
    than concluding the body is wrong.
    """
    nums = args.status_nums
    # The stored list is the real one; --status-skills overrides it for a probe.
    # Without this, a skill the player just learned through 0x2049 would come
    # back missing on the next login and the SP would have bought nothing.
    skills = args.status_skills or acquired_skills(args)
    # THE IDENTITY FIELDS COME FROM THE STORED CHARACTER unless a flag pins
    # them. Until 2026-09-04 the defaults were id=1, name "Lex", class 1,
    # nation 1 -- one specific test character, hard-coded -- so any other
    # player who ever had --status on would have been told they were Lex.
    ch = _self_char(args) or {}
    sid = args.status_id
    if sid is None:
        sid = _SESSION.get("charid") or 0
    name = args.status_name
    if name is None:
        name = str(ch.get("name") or "")
    sex = args.status_sex
    if sex is None:
        sex = int(ch.get("sex") or 0)
    cls = args.status_class
    if cls is None:
        cls = int(ch.get("look1") or 0)      # [unit+0x3AB], the CLASS byte
    nation = args.status_nation
    if nation is None:
        force = ch.get("force")
        nation = int(force) if force not in (None, 0, 0x7FFFFFFF) else 0
    payload = (struct.pack(">I", sid & 0xFFFFFFFF)
               + name.encode("cp932", "replace") + bytes(1)
               + struct.pack(">BH", sex & 0xFF, cls & 0xFFFF)
               + b"".join(struct.pack(">I", n & 0xFFFFFFFF) for n in nums)
               + struct.pack(">H", nation & 0xFFFF)
               + args.status_str2.encode("cp932", "replace") + bytes(1)
               + struct.pack(">I", len(skills))
               + b"".join(struct.pack(">I", k & 0xFFFFFFFF) for k in skills))
    send(conn, outbound, inner_msg(0x303E, payload, unit_id_of(args)),
         mode, be, args.seq_mode == "echo", args.world_prefix)
    print("[feworld] -> 0x30 inner 0x303E CHARACTER STATUS: id=%d name=%r "
          "sex=%d class=%d nation=%d, nine u32 %s, %d skill(s) %s"
          % (sid, name, sex, cls, nation, list(nums), len(skills),
             list(skills)), flush=True)
    if list(nums) == list(range(101, 110)):
        print("[feworld]    🔬 PROBE VALUES (101..109 in WIRE order). Open the "
              "status screen and read which field shows which number -- that "
              "labels all nine slots in one run, including skill_point, which "
              "is the whole point. Then set --status-nums for real.",
              flush=True)


def blacklist_send(conn, outbound, mode, be, args, who=0):
    """Push 0x1163 MSG_GET_BLACKLIST_OK -- the WHOLE list, every time.

        [u32 count] then count x { [u32 id][cstr name] }

    read at 0x05024522 (count) and 0x0502454f/0x0502455e (the pair) in arm
    0x05024490. The arm CLEARS the client's vector before it fills it
    (0x050244a2..0x05024510 walks [0x535c29c]..[0x535c2a0] destroying every
    row), so this is a whole-list PUT and re-sending it is idempotent -- unlike
    0x115F, which appends.

    0x20A2 registers no reply of its own (0x051333d0 has none of the
    `mov word ptr [esp+N], imm16` pairs), so 0x1163 is an unsolicited push and
    may be sent whenever the list changes.
    """
    rows = blacklist_rows(args)
    payload = struct.pack(">I", len(rows))
    for r in rows:
        payload += (struct.pack(">I", r["id"])
                    + r["name"].encode("cp932", "replace") + bytes(1))
    send(conn, outbound, inner_msg(0x1163, payload, unit_id_of(args)),
         mode, be, args.seq_mode == "echo", args.world_prefix)
    print("[feworld] -> 0x30 inner 0x1163 MSG_GET_BLACKLIST_OK, %d row(s)%s"
          % (len(rows), " for charid=%d" % who if who else ""), flush=True)
    for r in rows:
        print("[feworld]        id=%d %r" % (r["id"], r["name"]), flush=True)


def _serve_one(conn, peer, args):
    """One world session, on its own thread."""
    try:
        hs = do_handshake(conn, args)
        if hs:
            serve(conn, args, *hs)
    except (OSError, IOError) as e:
        print("[feworld] socket error (%s:%d): %r" % (peer[0], peer[1], e),
              flush=True)
    except Exception as e:                      # noqa: BLE001
        # A thread dying silently would look like the client hanging up, which
        # is the single most misleading failure this file can produce.
        print("[feworld] session error (%s:%d): %r" % (peer[0], peer[1], e),
              flush=True)
    finally:
        try:
            conn.close()
        except OSError:
            pass
        print("[feworld] CLOSED (%s:%d)" % peer, flush=True)


def main():
    for stream in (sys.stdout, sys.stderr):
        try:
            stream.reconfigure(encoding="utf-8", errors="replace")
        except (AttributeError, ValueError):
            pass
    # A copy of the console in /logs/feworld.log, which outlives the container
    # (docker-compose.yml mounts the fe-logs volume there). See filelog.py.
    import filelog
    filelog.tee("feworld")

    load_extensions()
    ap = argparse.ArgumentParser(description=__doc__,
                                 formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--port", type=int, default=54850)
    ap.add_argument("--master-key", default="fantasyearth")
    ap.add_argument("--master-mode", default="ecb/le",
                    choices=["ecb/be", "ecb/le", "cbc/be", "cbc/le"],
                    help="ecb/le is the measured one -- LITTLE-endian block "
                         "halves, which is unusual for Blowfish and easy to miss")
    ap.add_argument("--server-key", default="0123456789abcdef0123456789abcdef",
                    help="hex of OUR half of the exchange. MUST be non-empty.")
    ap.add_argument("--seq", type=int, default=1)
    ap.add_argument("--seq-mode", default="echo",
                    choices=["echo", "count"],
                    help="see felobby.py --seq-mode. The world door is the case\n"
                         "where the two DIFFER: 0x20 arrives first and goes\n"
                         "unanswered, so echo makes our first reply carry 2.")
    # THE NAMES AND THEIR ORDER ARE THE CLIENT'S OWN, not invented. It carries a
    # five-entry pointer table at 0x052ea81c and indexes it with `ForceID - 1`:
    #
    #     mov esi, [esi+0x3bc]          ; the force id
    #     dec esi                       ; id - 1
    #     js / cmp esi,5 / jge          ; bounds 1..5
    #     mov eax, [esi*4 + 0x52ea81c]  ; the name         (0x05130453)
    #
    # so 1=Netzawar 2=Cathedira 3=Elsord 4=Holdein 5=Gebrand. Those are this
    # PlayOnline-era build's romanisations of the five kingdoms later shipped in
    # Fantasy Earth ZERO as Netzavare, Cesedria, Yelsord, Hordaine and
    # Gevrandian -- the account holder supplied that list, and matching it
    # against the binary is what pinned both the spellings and the ID order.
    # (An earlier default here guessed "Hordaine, Netzmilt, Ordan, Cesell,
    # Geburand" in the wrong order; only Hordaine was close.)
    ap.add_argument("--forces",
                    default="1:Netzawar,2:Cathedira,3:Elsord,4:Holdein,"
                            "5:Gebrand",
                    help="the NATIONS offered at the nation-select screen, as "
                         "id:Name pairs. The client polls ForceID 1..5 and an "
                         "empty record leaves its list blank. The defaults are "
                         "the client's own names in its own ID order.")
    ap.add_argument("--devtool-port", type=int, default=0, metavar="PORT",
                    help="serve the WORLD-BUILDING PANEL on this port: where "
                         "you are standing, what the area is still missing, and "
                         "a button for each of it. 0 (the default) is off. "
                         "WARNING: the panel runs !goto, !npc and !land against the "
                         "live session -- it binds LOOPBACK unless told "
                         "otherwise, and refuses to bind wider without a token.")
    ap.add_argument("--devtool-bind", default="127.0.0.1", metavar="ADDR",
                    help="what the panel listens on. Leave it on loopback and "
                         "reach it through an ssh tunnel unless you have a "
                         "reason not to.")
    ap.add_argument("--devtool-token", default="", metavar="STR",
                    help="required for any non-loopback bind; appended to the "
                         "panel's URL as ?t=... Not a password -- it is the "
                         "difference between 'awkward to reach' and 'open'.")
    ap.add_argument("--spawn-file", default=None,
                    help="the SPAWN STORE (default data/fe_spawn.json): area id "
                         "-> the point a player arrives at in that area, "
                         "written by `!spawn` from where the player is actually "
                         "standing. An area with no row falls back to "
                         "--spawn-pos, which is ONE position for all 95 and is "
                         "therefore wrong for 94 of them.")
    ap.add_argument("--spawn-derive", default="castle", choices=["castle", "off"],
                    help="where a war field with no `!spawn` row puts a player: "
                         "'castle' = beside their side's keep (the castle for a "
                         "defender, the attacker's keep for an attacker; "
                         "fet_castle_info + keep_grids), five cells toward the "
                         "centre, at the map's ground height. Needs "
                         "--spawn-height dat. 'off' = the old one-point fallback.")
    ap.add_argument("--spawn-height", default="dat", choices=["dat", "off"],
                    help="what an area with NO spawn row falls back to. `dat` "
                         "uses that area's own battle-map height -- the median "
                         "of the Hmap's shipped sound emitters, which is the "
                         "only per-map height dat.pak gives us. Those medians "
                         "run 8 to 62 across the twelve maps that carry "
                         "samples, and --spawn-pos unset is y=0, which is under "
                         "ALL of them. WARNING: a sound emitter is not standable "
                         "ground; this stops a player falling through the "
                         "world, it does not replace standing somewhere and "
                         "saying `!spawn`. `off` uses --spawn-pos verbatim.")
    ap.add_argument("--spawn-area", default="", metavar="GID:X:Y:Z[:H[:TAG]],...",
                    help="arrival points by area, over the top of the store. "
                         "Repeat a GID with different TAGs to give a "
                         "battlefield more than one -- a war has two sides and "
                         "they do not arrive together. The heights matter more "
                         "than the horizontals: world (0,0,0) is the CENTRE of "
                         "the terrain grid at height zero, which on every "
                         "battle map that ships heights is underneath it.")
    ap.add_argument("--door-height", default="dest", metavar="dest|client|N",
                    help="where a shipped door's arrival HEIGHT comes from. "
                         "fet_area_portal carries (x, z) only -- FE takes "
                         "height off the heightmap. `dest` (the default) uses "
                         "the DESTINATION's own ground: its spawn row first, "
                         "then its battle map's height, then the client's "
                         "reported y if that is plausible. WARNING: `client` was the "
                         "default until 2026-09-10 and was WRONG: it used the "
                         "height at the doorway you left, but a capital's two "
                         "halves are different maps at different heights, so "
                         "the player arrived in the air, fell, and the falling "
                         "y (10041, then 10064) fed the next door -- a loop "
                         "they could not walk out of. A number pins a literal.")
    ap.add_argument("--world", default="synthetic", choices=["synthetic", "dat"],
                    help="WHICH WORLD TO SERVE. `dat` serves the one the client "
                         "ships: fet_area's 95 areas over SIX islands -- island "
                         "1 the shared frontier continent (15 areas, three per "
                         "nation), islands 2..6 one home continent per nation "
                         "with its capital -- each field carrying the table's "
                         "own name, owner, Hmap number, map pixel, flags and "
                         "ADJACENCY LIST. `synthetic` is the old behaviour: "
                         "--islands x --groups invented fields with ids from a "
                         "formula. dat overrides --field-coords, --field-hmaps, "
                         "the --field-nations DEFENDER and --islands; it leaves "
                         "--field-names, --field-status and the attacker alone.")
    ap.add_argument("--world-neighbours", default="on", choices=["on", "off"],
                    help="whether --world dat serves 0x3031 mask bit 12, the "
                         "field's adjacency list. THIS IS WHAT LETS A PLAYER "
                         "ENTER ENEMY LAND: the client's frontier test "
                         "0x05009870 walks it, and with no list the only "
                         "enterable fields are the ones your own nation already "
                         "holds -- which is how 'you cannot leave your country' "
                         "looked like a rule instead of our omission. `off` is "
                         "the A/B, not a setting to run.")
    ap.add_argument("--world-inner-capitals", default="on", choices=["on", "off"],
                    help="whether --world dat announces the capitals' INNER "
                         "halves (91..95). They are door-only -- nothing in the "
                         "graph points at them -- but a group the client was "
                         "never told about cannot be resolved when a door lands "
                         "the player in it. They draw at the same map pixel as "
                         "their outer half.")
    ap.add_argument("--territory", default="", metavar="AREA:NATION,...",
                    help="hand areas to nations at startup, over the top of "
                         "fet_area's shipped board and the territory store. "
                         "`--territory 18:2` gives nation 2 a field bordering "
                         "nation 1's capital, which is the smallest test that "
                         "the adjacency rule works: 21 should become enterable "
                         "for a nation-2 character and stay shut for nation 3.")
    ap.add_argument("--territory-file", default=None,
                    help="the TERRITORY STORE (default data/fe_territory.json): "
                         "area id -> holding nation, seeded from fet_area and "
                         "rewritten whenever a field changes hands.")
    ap.add_argument("--islands", type=int, default=5,
                    help="how many islands to announce in 0x3030. The client "
                         "bounds-checks each id as (id-1) < count, so the list is "
                         "always 1..count; the per-island 16-byte record is not "
                         "mapped yet, so only the ids are sent.")
    ap.add_argument("--groups", type=int, default=1,
                    help="groups announced per island in 0x3031. Each is sent as "
                         "an id with a ZERO field mask, which the parser reads as "
                         "'no optional fields'. 0 is a complete valid answer.")
    ap.add_argument("--force-targets", default=None, metavar="FID:FIELD,...",
                    help="m_TargetFieldID per nation -- which field it is "
                         "attacking. Unset, the ATTACKING nation from "
                         "--field-nations targets field 1. Every nation reported "
                         "0 before this existed, i.e. nobody was attacking "
                         "anything anywhere, which is not a world that can have a "
                         "war to prepare for.")
    ap.add_argument("--world-notice", default=None, metavar="TITLE|TEXT",
                    # default shown in the help text below rather than set here,
                    # so --world-notice-none can still tell "unset" from "empty"
                    help="answer 0x4015 with a 0x303C notice instead of 0x303D "
                         "'nothing to show'. The client caches the notice id at "
                         "0x52e4a48 and only reacts when it CHANGES, so re-sending "
                         "the same id is a no-op.")
    ap.add_argument("--world-notice-id", type=lambda v: int(v, 0), default=1,
                    help="the i32 the client caches at 0x52e4a48. It reacts only "
                         "when this CHANGES, so bump it between runs.")
    ap.add_argument("--world-notice-none", action="store_true",
                    help="answer 0x4015 with 0x303D 'nothing to show' instead. "
                         "0x303D sets [screen+0xec]=0xFF, which sends the "
                         "map-select screen to state 7 and (unless "
                         "[screen+0x5c]==4) straight back to state 0 -- the "
                         "black-screen loop. Kept only for an A/B run.")
    ap.add_argument("--island-names", default=None,
                    help="comma-separated, one per island, attached to 0x3030. "
                         "Each island's record is [u16 id][u16 nameCount] + that "
                         "many strings; omitting them sends nameCount 0, which is "
                         "aligned and valid.")
    ap.add_argument("--area-echo", default="-1",
                    help="what 0x1000 puts in the u32 that lands at "
                         "[scene+0x4e8]. Mode 0xa dummies the whole field entry "
                         "when that equals the group id at +0x4ec, and since the "
                         "client derives its 0x2000 area FROM the group id, "
                         "'echo' (the old behaviour) collides every time. -1 is "
                         "the client's own ctor value for the slot and makes the "
                         "test fail, taking the real load path instead. Any "
                         "integer, or the literal 'echo'.")
    ap.add_argument("--move-field", choices=("ok", "ng", "none"), default="ok",
                    help="how to answer 0x2017 MSG_MOVE_FIELD_REQUEST, which the "
                         "client sends from the dummy area to ask for the real "
                         "field. 'ok' sends 0x1012 with an EMPTY body (its arm "
                         "0x5054af3 reads nothing); 'ng' sends 0x1013 with a u32 "
                         "error code; 'none' leaves it unanswered, which is what "
                         "parked the client in the dummy area.")
    ap.add_argument("--move-field-err", type=lambda v: int(v, 0), default=0,
                    help="the u32 error code carried by a 0x1013 NG "
                         "(--move-field ng). Looked up in the client's error "
                         "string table by 0x5061290.")
    ap.add_argument("--set-position", dest="set_position",
                    action=argparse.BooleanOptionalAction, default=True,
                    help="send 0x1027 MSG_SET_POSITION after 0x1000. THIS IS "
                         "WHAT UNPARKS THE FIELD: mode 0xa substate 2 waits on "
                         "[scene+0x296]==1 and only 0x1027's handler sets it, so "
                         "without it the client loads the field assets and then "
                         "stops forever. --no-set-position restores the old "
                         "(parked) behaviour for an A/B run.")
    ap.add_argument("--spawn-pos", default="0:0:0", metavar="X:Y:Z",
                    help="the pos(...) triple in 0x1027, big-endian f32. The "
                         "coordinate space is UNMEASURED; zeros are served so the "
                         "value is recognisable in the client's own "
                         "MSG_SET_POSITION log line.")
    ap.add_argument("--spawn-dir", default="0:0:1", metavar="X:Y:Z",
                    help="the FACING triple -- dir(...) in 0x1027 and, when "
                         "--add-mask2 has bit 2, the three f32 the 0x1006 "
                         "record writes to unit+0x1e4..+0x1ec. WARNING: IT IS A "
                         "DIRECTION VECTOR AND IT MUST NOT BE ZERO: "
                         "0x05078e40 builds the look-at target as "
                         "position + facing, componentwise, so an all-zero "
                         "facing makes the target EQUAL the position and "
                         "the orientation basis degenerate. Default 0:0:1 "
                         "is the value the client itself carried before we "
                         "started writing this field (measured live "
                         "2026-08-24).")
    ap.add_argument("--unit-id", default="0",
                    help="the leading u32 of every world inner header -- the "
                         "message's TARGET UNIT ID, not padding (see "
                         "inner_msg()). MEASURED 2026-08-24: this, NOT the "
                         "0x302B payload, is what lands at [0x533998c]+0x9e0 "
                         "as the server unit's id -- WARNING: UNTESTED. What IS "
                         "measured is only that the 0x302B PAYLOAD is NOT the "
                         "slot (sent charid there, read 0 back live). Default "
                         "is 0, the value every working session has used. "
                         "'auto' sends the session charid on EVERY world header "
                         "including 0x302B's, so the header, 0x1027's target "
                         "and the entity id we spawn in 0x1000 all name one "
                         "character -- that is the experiment, and it is opt-in "
                         "because getting it wrong is a BLACK SCREEN: 0x1027 is "
                         "dropped unless it matches [0x533998c]+0x9e0, and a "
                         "dropped 0x1027 parks mode 0xa substate 2 forever.")
    ap.add_argument("--enter-room", type=lambda v: int(v, 0), default=-1,
                    help="the i16 at [scene+0x4e6] in 0x1000 -- the ROOM index. "
                         "-1 (the client's own default) means OUTDOORS and "
                         "routes field entry to the Hmap battlefield loader; any "
                         "other value is an indoor room id resolved through the "
                         r"name map 0x5192030 into Rooms\<name>.mdl. We sent 0 "
                         "until 2026-08-23, so every field entry was an indoor "
                         "room (room_test.pak) with no battlefield ground.")
    ap.add_argument("--field-rooms", default="", metavar="GID:INDEX[,...]",
                    help="per-GROUP override of --enter-room: which group id "
                         "is a DOOR into an indoor room, and which room. "
                         "Unlisted groups keep --enter-room (default -1, "
                         "outdoors). This exists because --enter-room is one "
                         "global value and the entry branch is ordered capital "
                         "-> outdoors -> room: a global room index leaves the "
                         "capital untouched and sends every WAR FIELD indoors "
                         "instead, which is the opposite of the intent. Named "
                         "indices: %s. Any other value falls to the switch's "
                         "default arm, which our own runs show is room_test -- "
                         "a wasted probe, not a wedge."
                         % ", ".join("%d=%s" % (i, SHIPPED_ROOMS[i])
                                     for i in sorted(SHIPPED_ROOMS)))
    ap.add_argument("--field-status", type=lambda v: int(v, 0), default=1,
                    help="the group/FIELD status byte (mask bit 0). Zero is what "
                         "an all-empty record produced, and the war map showed "
                         "nothing; 1 is the first value worth trying.")
    ap.add_argument("--field-flags", type=lambda v: int(v, 0), default=8,
                    help="the group flags word at [group+0x8c] (mask bit 15). "
                         "Bit 3 (value 8) is what the home-field resolve "
                         "0x05009240 requires; without it map-select state 7 "
                         "can never find the player's nation's field and the "
                         "island sweep restarts forever (the black window).")
    ap.add_argument("--field-coords",
                    default="300:200,500:250,420:380,260:430,600:410",
                    help="per-field marker coordinates on the continent map, "
                         "`x:y` comma-separated by group id (mask bit 17, the "
                         "[%%03d-%%03d] pair in the client's FIELD log line). "
                         "Unserved they default to 0,0 and every marker stacks "
                         "in the top-left corner. The coordinate SPACE is "
                         "unmeasured -- these defaults spread the markers so "
                         "one screenshot calibrates it. Empty disables.")
    ap.add_argument("--field-hmaps", default="1,2,3,4,5",
                    help=r"per-field Data\Hmap\mapNN.pak numbers (mask bit 18, "
                         "[group+0x94]), comma-separated and indexed by group "
                         "id. THE OUTDOOR FIELD'S TERRAIN. The client's table "
                         "0x52d30e0 knows 1..14 (all shipped) and dev maps "
                         "100..105 (not shipped); anything else -- including the "
                         "0 an unserved field leaves -- makes 0x5007e30 return "
                         "NULL and the caller deref it. Empty disables the "
                         "field, which is only safe with --enter-room != -1.")
    ap.add_argument("--field-names", default="", metavar="A,B,.. | dat",
                    help="comma-separated field names (mask bit 7), one per "
                         "group id. Empty sends no name at all. `dat` serves "
                         "dat.pak's OWN names for all 95 areas out of "
                         "fet_area (in Japanese, as shipped); `dat-en` "
                         "serves the ENGLISH names in "
                         "fedata/fe-area-names-en.tsv -- all 95 of them, ours "
                         "rather than SE's because dat.pak ships no English "
                         "for this table and its string harvest recovers 7 of "
                         "the 95 paired with the wrong strings. A field with "
                         "no row falls back to 'Field N', which is what "
                         "dat-en did for every field before 2026-09-09.")
    ap.add_argument("--exp-next", default="auto", metavar="auto|N|off",
                    help="the SECOND number of the Status screen's "
                         "'Exp %%d/%%d' -- [unit+0x135c], which is what decides "
                         "whether the HUD bar is full. WARNING: It was full because "
                         "we wrote the same running total into BOTH halves: "
                         "the numerator is the per-class dword at "
                         "[unit+0x9F8+class*4] and the denominator is a "
                         "different field (draw at 0x050E1388). `auto` "
                         "(default) is the next multiple of --exp-per-level "
                         "above the total, an obvious placeholder that makes "
                         "the bar fill and reset; a number pins it; `off` "
                         "restores the full bar. WARNING: NO exp curve ships in "
                         "dat.pak, so any denominator here is OURS.")
    ap.add_argument("--exp-per-level", type=int, default=1000, metavar="N",
                    help="the step --exp-next auto rounds up to. CHOSEN.")
    ap.add_argument("--monster-wander", default="on", choices=["on", "off"],
                    help="idle monsters STROLL (2026-09-12): each live monster "
                         "outside --monster-aggro walks to a random spot within "
                         "--monster-wander-radius of its HOME at its model's "
                         "own walk speed, then pauses --monster-wander-secs. "
                         "The chase's own 0x2023 action-0 record. 'off' = they "
                         "stand in their spawn formation, as before. CHOSEN.")
    ap.add_argument("--monster-wander-secs", default="6:15", metavar="LO:HI",
                    help="the random pause between strolls, seconds.")
    ap.add_argument("--monster-wander-radius", type=float, default=12.0,
                    metavar="U",
                    help="how far from home an idle monster strolls.")
    ap.add_argument("--monster-share", default="on", choices=["on", "off"],
                    help="ONE set of monsters per field for every player in "
                         "it: the first player in builds it, later ones are "
                         "shown it as it is (position, HP), one session "
                         "drives chase/wander/respawn toward the nearest "
                         "living player, and moves, hits, deaths and respawns "
                         "are relayed to everyone in the field. off = each "
                         "session its own copy (before 2026-09-13).")
    ap.add_argument("--monster-chase", default="on", choices=["on", "off"],
                    help="monsters WALK TOWARD the player (0x2023 action 0) "
                         "when inside --monster-aggro, stopping at three "
                         "quarters of --monster-range so they close and then "
                         "swing. VERIFIED: The arm takes them: its kind gate "
                         "(0x04FEA91E) branches on 2 for an avatar and on "
                         "0xBBB/0xBBC for an NPC, and 0xBBC is what a monster "
                         "is. WARNING: LIVE 2026-09-09: THE MONSTER DID NOT CHASE. "
                         "Two client gates can eat it silently -- bit 0x800000 "
                         "('no ground under the unit') and an unloaded model "
                         "([model+0x27c] == 0) -- and the log now says whether "
                         "we sent anything at all, which is what tells those "
                         "apart from a range problem.")
    ap.add_argument("--monster-aggro", type=float, default=15.0, metavar="U",
                    help="how close the player has to be before a monster "
                         "starts walking toward them, X/Z only. CHOSEN.")
    ap.add_argument("--monster-speed", default="run", metavar="run|walk|U",
                    help="how fast a monster chases. 'run' (the default) is "
                         "each monster's OWN run speed, NPC_ModelType +0x420 "
                         "(Duke_Orc 3.7, King_Griffon 4.8, Barbatos 10.9 u/s); "
                         "'walk' is +0x41c; a number pins every monster to it. "
                         "The client picks walk or run by comparing the speed "
                         "with the model's own pair and plays the motion at "
                         "speed/that, clamped to 0.4..2.0 -- so a flat speed "
                         "faster than a model's run slides it along the "
                         "ground (live 2026-09-12 at a flat 10). HISTORY -- "
                         "monster walk speed in world units per second while "
                         "chasing. CHOSEN -- fet_npc_type ships no speed "
                         "column (hp/attack/defence/exp/level/radius/skills/"
                         "resists and nothing else). WARNING: WAS 3.0, AND THE "
                         "REASON WAS A UNITS ERROR: this help used to say 'the "
                         "PLAYER's own base is 4.0 on a war field, so this is "
                         "deliberately slower', but move_row's 4.0 is a "
                         "MULTIPLIER of the engine's own speed, not world "
                         "units -- the same confusion that had the jump launch "
                         "at 4.7 when it is 16.5. So 3.0 was not 75%% of a "
                         "player's pace, it was about a fifth of it, and the "
                         "live-test verdict on 2026-09-12 was 'very very "
                         "slow'. 10.0 is still under a player's, so you can "
                         "walk away from one.")
    ap.add_argument("--monster-chase-interval", type=float, default=0.5,
                    metavar="S",
                    help="seconds between chase steps for one monster. Each "
                         "step is one 0x2023, so this is also the wire cost.")
    ap.add_argument("--war-trace", default="off", choices=["on", "off"],
                    help="say why the war cycle did NOT advance. Live testing "
                         "saw a full cycle and then 'at the end of the second "
                         "battle start timer, nothing happens' -- and the three "
                         "gates that produce that (not in a field, the phase is "
                         "not one that advances, the deadline is not due) look "
                         "identical from outside. This prints which, once per "
                         "gate per phase, plus a per-second countdown over the "
                         "last 10 s so the approach to zero is visible. Static "
                         "RE has already ruled out the two client-side "
                         "explanations -- see the note in war_deadline_pump.")
    ap.add_argument("--field-home", default="all", choices=["all", "capital"],
                    help="who gets bit 3 of --field-flags. That bit is what "
                         "the client calls a CAPITAL: its map-label builder "
                         "(0x0510A2A4) draws \"首都%s\" -- 'Capital <name>', "
                         "which our UI table renders \"Cap\" -- for any group "
                         "carrying it, which is why every marker on the world "
                         "map reads 'Cap <field>'. `all` (default) sets it "
                         "everywhere, as this has always done. `capital` sets "
                         "it only on --capital groups, which is what the bit "
                         "means. WARNING: NOT the default because the home-field "
                         "resolve 0x05009240 accepts a group only when BOTH "
                         "def_id == the player's nation AND this bit is set, "
                         "so narrowing it can return a nation to the "
                         "2026-08-27 black screen unless that nation's capital "
                         "is served on the island with a matching def_id. "
                         "PARTIAL: Neither setting has been tested since this was "
                         "found.")
    ap.add_argument("--field-color", default="owner", metavar="owner|off|N",
                    help="the map record's COLOUR byte (+0x96, mask bit 19, "
                         "which the client logs as 'COLOR[%%d]') -- a palette "
                         "index the map screen reads SIX times per field and "
                         "we had never sent at all. 'owner' = the nation "
                         "holding the field (a READING: it is the only "
                         "per-field quantity a five-nation palette would key "
                         "on); N pins one index for a probe; 'off' leaves the "
                         "field absent, which is what drew no colour")
    ap.add_argument("--force-color", default="id", metavar="id|off|N",
                    help="the NATION record's colour byte (force+0x1bc, "
                         "FORCE_FIELDS f1bc) -- the '<nation> (of Player)' "
                         "circle and the war-prep window's two sides. 'id' = "
                         "the force id, the same palette index the field "
                         "colour uses; 'off' sends 0, which draws BLACK (what "
                         "every nation showed until 2026-09-12)")
    ap.add_argument("--field-tail", default="on", choices=("on", "off"),
                    help="fill the map record's two ALWAYS-READ tail fields: "
                         "+0xC0 = the attacker's palette index (the war "
                         "panel's second circle) and +0xC4 = the holder's "
                         "FIELDS HELD (the field panel's row). 'off' sends "
                         "both as 0, the old behaviour")
    ap.add_argument("--field-census-probe", type=int, default=0, metavar="N",
                    help="report N players in EVERY field for one probe run, "
                         "instead of the real census. A tester looking at the "
                         "continent map has field-ed OUT, so the true count is "
                         "0 everywhere and 'the client ignores chars_all' and "
                         "'the client draws nothing for nobody' look the same. "
                         "120 draws the largest silhouette on every field if "
                         "chars_all is the marker source. 0 = off (the default "
                         "and the only correct setting for players)")
    ap.add_argument("--field-census", default="on", choices=("on", "off"),
                    help="serve each field's PLAYER COUNT in the map record "
                         "(chars_all, mask bit 2, which the client logs as "
                         "'(ALL%%d)'), and the defenders' sign-ups during a "
                         "war (def_chars, bit 11, 'D%%d'). KEY: this is what draws a "
                         "field's MARKER: mapselect.tex's `Mark2` sheet is four "
                         "person silhouettes labelled 100~ / 50~ / 10~ / ~9 "
                         "plus a crown for a capital, so the marker is a "
                         "POPULATION TIER. Both bits were clear until "
                         "2026-09-12 and the map drew no field markers at all")
    ap.add_argument("--field-owner", default="board",
                    choices=("board", "knob"),
                    help="where a field's OWNING NATION comes from in the map "
                         "record (group+0x78 def_id, which SE's continent-map "
                         "page says draws the field's 国アイコン). 'board' = "
                         "the live territory board, so the icon follows a "
                         "conquest; 'knob' = the pre-2026-09-12 behaviour, one "
                         "constant per island from --field-nations / "
                         "--field-defenders, which showed all fifteen frontier "
                         "fields as one nation's and never changed hands")
    ap.add_argument("--field-nations", default="",
                    help="DEF:ATK nation ids for every field (mask bits 10/9). "
                         "Empty leaves the contest unset.")
    ap.add_argument("--capital", default="", metavar="ISLAND:GID[,...]",
                    help="announce a CAPITAL (town) field on an island, as an "
                         "extra group whose id the client's own predicate "
                         "0x04ff7ef0 accepts: %s. The id is the whole mechanism "
                         "-- on entry the client tests [scene+0x4ec] against "
                         "that set and takes the capital loader (0x5001d70, "
                         "DATA/capital/mapNN_*.oct via the table at 0x052d1858) "
                         "instead of the Hmap battlefield arm. The capital takes "
                         "its island's defender so the home-field resolve "
                         "accepts it, and war_notify refuses to arm in one. "
                         "WARNING: 21's assets are incomplete in our mirror -- use 39, "
                         "57, 62 or 78. Empty = no capital, the pre-2026-09-04 "
                         "behaviour."
                         % ", ".join(str(g) for g in CAPITAL_GROUP_IDS))
    ap.add_argument("--capital-name", default="Capital", metavar="NAME",
                    help="the name the map screen shows for a --capital group.")
    ap.add_argument("--capital-coords", default="450:300", metavar="X:Y",
                    help="the capital's marker position on the continent map "
                         "(mask bit 17). --field-coords is indexed gid-1 and a "
                         "capital id is past the end of it, so without this the "
                         "capital had NO marker and the client clamped it to the "
                         "corner (coords below 0x28 are forced to 0x28 at "
                         "0x0500fae6). WARNING: The coordinate SPACE is still "
                         "unmeasured -- the client scales it through a magic "
                         "divide at 0x0500faff -- so this is a position that "
                         "puts the marker ON the map, not a calibrated one.")
    ap.add_argument("--capital-attacker", default="off", choices=["on", "off"],
                    help="whether a --capital group carries atk_id/atk_name "
                         "like a war field does. THIS IS AN A/B, not a "
                         "preference. `off` was the first attempt and the map "
                         "screen CRASHED (2026-09-04, c0000005 reading address "
                         "0x1 in a strcmp at FE_Client+0xFA576). `on` makes the "
                         "capital record identical in SHAPE to a war field's -- "
                         "which is known not to crash that screen -- so the only "
                         "difference left is the group ID. If it still crashes "
                         "with `on`, the id is the cause and these fields are "
                         "innocent; if it stops, the client needs the pair.")
    ap.add_argument("--field-defenders", default="",
                    help="comma-separated DEFENDING nation id per island "
                         "(island i takes entry i-1, cycling). Overrides the DEF "
                         "half of --field-nations per field so EVERY nation owns "
                         "a home field -- the map-select home resolve 0x05009240 "
                         "gates field entry on [group+0x78]==the character's "
                         "`force`, so a single defender blacks the screen for "
                         "every OTHER nation (the Elena fix, 2026-08-27). Empty "
                         "keeps the single --field-nations pair on every field. "
                         "WARNING: THE COST, measured 2026-09-04: it also CONFINES each "
                         "character to its own nation's island. Before it, every "
                         "field was def_id=1 and a nation-1 character could enter "
                         "all five; now Netzawar (force 1) gets island 1 and the "
                         "other four refuse. Entities served on field entry "
                         "(--npc/--monster) follow the player into whatever field "
                         "they DO enter, so testing props are not lost with them.")
    ap.add_argument("--world-prefix", type=int, default=4,
                    help="bytes to insert between the length and the id on THIS "
                         "connection. The transport reads the id at cursor + "
                         "[conn+0x1ca], which the relay dial (connect mode 2) "
                         "sets to 4 where the lobby (mode 1) leaves it 0. Use 0 "
                         "to send lobby-shaped frames.")
    ap.add_argument("--push-enter-area", action="store_true",
                    help="restore the pre-2026-08-19 behaviour of PUSHING "
                         "0x1000 MSG_ENTER_AREA_OK right after the group detail, "
                         "instead of waiting for the client's 0x2000 "
                         "MSG_ENTER_AREA and answering it. The disassembly says "
                         "the push cannot work -- the 0x1000 handler requires "
                         "[player+0x295]==0xFF, which only the client's own "
                         "request driver (0x04ff6a30) sets -- so this exists "
                         "only for an A/B run against the old capture.")
    ap.add_argument("--war", default="offensive",
                    choices=["none", "offensive", "defensive"],
                    help="push a START_WAR notify after the area is set, to arm "
                         "the war-prepare window ([screen+0x62]). 'offensive' "
                         "(id 0x1018) arms without driving a scene transition and "
                         "is the safe default; 'defensive' (0x1019) acts on the "
                         "four --war-fields via 0x5111650/0x5111010 -- a war-timer "
                         "countdown, NOT a scene transition, so only use it with "
                         "real values; 'none' leaves the map as-is.")
    ap.add_argument("--war-fields", default="0,0,0,0",
                    help="the four big-endian u32s the START_WAR handler reads "
                         "(0x0511843b). u32_1/u32_2 -> the field manager's array; "
                         "u32_3/u32_4 -> the war-view object (and the defensive "
                         "transition args). Meanings unverified; arming does not "
                         "depend on them, so 0,0,0,0 is fine for OFFENSIVE.")
    ap.add_argument("--proclamation", default="on", choices=["on", "off"],
                    help="answer the war-prep window's 1-second 0x2084 poll "
                         "with 0x1127 MSG_GET_INFO_OF_PROCLAMATION_OF_WAR_OK. "
                         "'off' restores the pre-2026-08-24 silence for an A/B.")
    ap.add_argument("--item-heal", type=int, default=0, metavar="N",
                    help="with --item-effects flat: how much HP using ANY item "
                         "restores (CHOSEN, uniform). Ignored under the "
                         "default --item-effects table.")
    ap.add_argument("--item-effects", default="table", choices=["table", "flat"],
                    help="what using an item does. 'table' (2026-09-12): the "
                         "client's own EFFECT_DATA row behind the item's use "
                         "skill -- bread 50 HP, cheese 90, steak 150 at once; "
                         "regen potions 25/48/100 HP every 4 s for 32 s; power "
                         "pots 5/10/15 Pw every 4 s for 60 s; a weaker potion "
                         "is refused while a stronger one runs. 'flat' = "
                         "--item-heal for every item. HP needs --monster-attack "
                         "on, which owns it.")
    ap.add_argument("--exp-display", default="on", choices=["on", "off"],
                    help="write the character's EXP into the per-class dword "
                         "at [unit+0x9F8 + class*4], which is the FIRST number "
                         "the Status screen's 'Exp %%d/%%d' draws (0x050e139d). "
                         "It goes through the class-level byte array because "
                         "that is the only 0x1075 bit that reaches those "
                         "bytes. 'off' leaves the numerator whatever the unit "
                         "was built with.")
    ap.add_argument("--monster-attack", default="off", choices=["on", "off"],
                    help="let monsters hit back: any live monster within "
                         "--monster-range of the player's own reported "
                         "position swings every --monster-interval seconds for "
                         "--monster-damage. The wire is 0x2024 maskA bit 0x4, "
                         "which is a STORE of the NEW hp (0x04ff3d2a) -- the "
                         "client draws old-minus-new as the damage number. At "
                         "0 the player is marked DEAD (CONDITION 0x800000) and "
                         "revived --revive-secs later, unconditionally.")
    ap.add_argument("--monster-damage", type=int, default=60, metavar="N",
                    help="damage per swing from the WEAKEST monster in the "
                         "game (level 1, attack 92). CHOSEN: no damage formula "
                         "is traced. 60 against --player-hp 1000 is ~17 swings "
                         "-- the same lethality 12 had against the old 200. "
                         "With --damage-model table every other monster scales "
                         "up from this by its own shipped ATTACK column.")
    ap.add_argument("--damage-model", default="table", choices=["table", "flat"],
                    help="how hard a monster hits. `table` (default since "
                         "2026-09-09) scales --monster-damage by the monster's "
                         "own ATTACK out of dat.pak's fet_npc_type, so a level "
                         "53 Duke Orc (attack 630) hits about seven times as "
                         "hard as a level 1 Venomous (92) instead of exactly "
                         "as hard. `flat` is the old behaviour: one number for "
                         "every monster in the game. PARTIAL: STATIC ONLY -- the "
                         "RATIO is shipped, the SCALE is ours, and nothing has "
                         "been seen on a screen.")
    ap.add_argument("--armour-defence", default="on", choices=["on", "off"],
                    help="monster damage x (1 - 耐性/400), 耐性 = the sum of "
                         "the worn pieces' defence from fewiki's 2006 armour "
                         "tables (fe-armour-defence.tsv), capped at 400 "
                         "(2026-09-12). The formula is FEZ's (2009) -- no "
                         "RoD one survives; BEST EFFORT. 'off' = no armour.")
    ap.add_argument("--monster-timing", default="table", choices=["table", "flat"],
                    help="how far and how often a monster swings. 'table' "
                         "(2026-09-12): its own melee skill (fet_npc_type "
                         "slot 0) out of SKILL_DATA -- reach = +0xF8 (7.0 for "
                         "most), period = wind-up + active + recovery, the "
                         "client's own busy-until (0x0505F500; 2.2 s for most, "
                         "Duke Orc 2.7). 'flat' = --monster-range / "
                         "--monster-interval for every monster.")
    ap.add_argument("--monster-reach-y", type=float, default=8.0, metavar="U",
                    help="how far above or below a monster may be and still "
                         "reach the player, world units. KEY: --monster-range is "
                         "measured HORIZONTALLY (y dropped), so without this a "
                         "monster on a cliff swings at someone it is forty "
                         "units above while their own cast -- gated by the "
                         "CLIENT's real 3D reach -- cannot answer. Found live "
                         "2026-09-12. 0 = the old behaviour, no height limit")
    ap.add_argument("--monster-range", type=float, default=8.0, metavar="U",
                    help="how close a monster has to be to swing, in world "
                         "units, measured on X/Z only. CHOSEN.")
    ap.add_argument("--monster-interval", type=float, default=2.0, metavar="S",
                    help="seconds between one monster's swings. CHOSEN.")
    ap.add_argument("--player-hp", type=int, default=1000, metavar="N",
                    help="the player's maximum HP for the server's own "
                         "bookkeeping. 1000 (since 2026-09-11; was 200) is "
                         "2006's flat HP at every level and the class table's "
                         "own first base value. nothing here changes +0x49a "
                         "(felobby's --char-hp serves that), so keep the two "
                         "equal or the bar looks wrong.")
    ap.add_argument("--respawn-wait", default=DEFAULT_RESPAWN_WAIT,
                    metavar="BASE:STEP:CAP|off",
                    help="RoD's respawn wait, in seconds: a death sets the "
                         "client's own Return to Base countdown (0x2024 bit "
                         "0x1000000 -> [player+0x1384]) to BASE, +STEP for "
                         "each further death in the same area (a new area, "
                         "or 10 min without dying, starts over), at most CAP; "
                         "the press starts it and the revive follows it. "
                         "15 s is SOURCED (fewiki Guide/メモ: 約15秒, longer "
                         "for repeated deaths in one area); STEP and CAP are "
                         "CHOSEN. off = the press revives at once")
    ap.add_argument("--revive-secs", type=float, default=60.0, metavar="S",
                    help="the SAFETY NET for a dead player who never presses "
                         "Return to Base. Since 2026-09-12 a death waits for "
                         "that button (0x2015 -> return_to_base), which is "
                         "the way back; this only guarantees a client that "
                         "cannot send it is never wedged. Was 8, which beat "
                         "the button every time -- players never needed "
                         "to press it.")
    ap.add_argument("--hunt-death-return", default="arrival",
                    choices=["arrival", "place"],
                    help="where a player dead OUTSIDE a war revives (Return "
                         "to Base, 0x2015, or the --revive-secs safety net). "
                         "'arrival' (the default, the design choice of "
                         "2026-09-12) warps them by a same-field 0x1166 to "
                         "the field's own arrival point -- at peace the castle "
                         "side, where anyone walking in lands -- instead of "
                         "beside whatever killed them. No source says where a "
                         "hunting death revives. 'place' is the old revive "
                         "where they fell. War deaths are --war-death-return's.")
    ap.add_argument("--war-death-return", default="base",
                    choices=["base", "place"],
                    help="where a player dead in a PREP/WAR field revives. "
                         "`base` (default, 2006: 'at 0 HP you are returned to "
                         "your base, keep or castle' [SE flow08]) warps them "
                         "to their side's arrival point with a same-field "
                         "0x1166; `place` is the old revive where they fell. "
                         "Outside a war it is always in place (no source says "
                         "otherwise -- ours).")
    ap.add_argument("--spawn-protect-secs", type=float, default=15.0,
                    metavar="S",
                    help="protection after a return to base or an area move: "
                         "monster hits do no damage for S seconds, and any "
                         "action other than moving (a hit, a cast, building, "
                         "talking to an NPC, using an item...) ends it at "
                         "once [SE interface05: 15 s]. 0 = off.")
    ap.add_argument("--spawn-protect-flag", default="off", choices=["on", "off"],
                    help="also mirror the protection into CONDITION bit "
                         "0x1000, which the client's own table names "
                         "INVINCIBLE. WARNING: UNPROVEN: what the client does with "
                         "it is unmeasured, and the protection does not need "
                         "it. Off by default.")
    ap.add_argument("--death-exp-pct", type=float,
                    default=DEFAULT_DEATH_EXP_PCT, metavar="P",
                    help="percent of NEXT (the EXP the current level needs) "
                         "lost on a HUNTING death, out of the progress into "
                         "the level and never below 0 of it -- nobody loses a "
                         "level (whether RoD de-levelled is unknown). RoD: 10 "
                         "(fewiki Guide/メモ 2006-05-26 「Nextの10%%の経験値」). "
                         "Never in a PREP/WAR/TRUCE field. 0 = off.")
    ap.add_argument("--death-exp-of", default=DEFAULT_DEATH_EXP_OF,
                    choices=["next", "progress"],
                    help="what --death-exp-pct is a percent of: next (RoD, "
                         "default) or the progress into the level (the "
                         "2026-09-11 first pass)")
    ap.add_argument("--death-gold-pct", type=float,
                    default=DEFAULT_DEATH_GOLD_PCT, metavar="P",
                    help="percent of the gold CARRIED lost on a HUNTING death "
                         "(the bank is safe). RoD: 20 (fewiki Guide/メモ: "
                         "「所持金の20%%を失う」; FEZ-early FFSKY says 10). "
                         "0 = off.")
    ap.add_argument("--death-war-crystals", type=int,
                    default=DEFAULT_DEATH_WAR_CRYSTALS, metavar="N",
                    help="crystals lost on a death in a PREP/WAR field, "
                         "floored at 0 -- RoD: 3 (fewiki WAR/クリスタル). A war "
                         "death costs no EXP or gold. 0 = off.")
    ap.add_argument("--peace-arrival", default="castle",
                    choices=["castle", "holder"],
                    help="where a player arrives in a war field at PEACE. "
                         "`castle` (default): the castle side whoever holds "
                         "it [early-FEZ atwiki 251 / FFSKY; SE is silent]. "
                         "`holder`: the old rule -- castle side only when "
                         "your nation holds the field, else the keep side.")
    ap.add_argument("--motion-refresh", default="on", choices=["on", "off"],
                    help="after the worn items are re-sent, restate them in a "
                         "0x2004 so the client picks the weapon's MOTION SET "
                         "(0x0503c70e -> 0x0506aa30). Without it the cast "
                         "plays as a T-pose, because the only other caller is "
                         "the entity decoder's tail, which also sets STANCE "
                         "and freezes the character.")
    ap.add_argument("--item-durability", default="-1:100", metavar="MAX:CUR",
                    help="group-4 bits 0x4/0x8 of every item record: +0x4aa "
                         "durability maximum and +0x4ac current. The cast "
                         "ladder's rung after gate 4 (0x0504b8c0) refuses a "
                         "held weapon with current <= 0 unless max is -1 -- "
                         "the third emitter of 'Skill conditions not met.', "
                         "found 2026-09-08 after the other two were measured "
                         "passing. -1:100 (default) is infinite; a real max "
                         "makes the client print its own wear warnings at "
                         "20%% and nothing here decrements it yet.")
    ap.add_argument("--worn-gear-record", default="off", choices=["on", "off"],
                    help="carry the stored worn gear in the self 0x1006's "
                         "mask3. OFF: live 2026-09-08 runs 2/3, the worn-gear "
                         "tail 0x0503aecb sets OBJSTATUS STANCE (0x40000) on "
                         "the self when the record names a weapon, nothing ends "
                         "it, and the character cannot move or cast. The field "
                         "dresses through the 0x1000 bag markers (--field-equip) "
                         "and the 0x107A replay after the first clock sample.")
    ap.add_argument("--unit-physics", default="push", choices=["table", "push"],
                    help="'push' (default): the 0x2024 --unit-speed and "
                         "--jump-phys pushes. 'table' was the default for runs "
                         "6-9 of 2026-09-08 on the theory that the class copy "
                         "(0x0506a5e0, rec+0x44/+0x48/+0x4c -> +0x4d4/+0x4dc/"
                         "+0x4e4) supplies them -- LIVE it does not: run 8 "
                         "moved in some directions only, run 9 ran in place, "
                         "the 08-25 server-authoritative-speed signature. "
                         "The run-5 'moves so much slower' under the push is "
                         "still unexplained; measure it, do not turn the push "
                         "off again.")
    ap.add_argument("--add-self", default="off", choices=["on", "off", "client"],
                    help="'client' (2026-09-08): send NO self record -- the unit "
                         "the client builds from the lobby record STANDS, and "
                         "the stat block (--add-stats bits 0/7/8) rides 0x2024 "
                         "maskA 0x1/0x80/0x100 instead. Why: the type-0 arm's "
                         "lookup HIT is a tear-down-and-rebuild ('Chara 1 "
                         "already exists'); the rebuilt unit is dressed only "
                         "from mask3, its worn items are the OLD unit's objects "
                         "(destroyed with it -> not in the item manager -> gate "
                         "4 refuses), and the decoder tail sets STANCE with no "
                         "action to end it (frozen, cast refused silently). The "
                         "client's own builder sets USESKILLRDY without STANCE. "
                         "'on' = send 0x1006 MSG_ADD for the player's own avatar "
                         "before 0x100E, carrying the NAME and APPEARANCE read "
                         "back out of felobby's stored character -- the client's "
                         "own path for building the model, and the only thing "
                         "that can fill unit+0x84, whose empty slot 0 is the "
                         "null deref that kills the client ON MOVEMENT. OFF by "
                         "default: the record is decoded, but that it ends in a "
                         "non-null slot is NOT yet measured. The self-check is "
                         "the client's own 'MSG_ADD> Avatar( <name> )' log line.")
    ap.add_argument("--gold", type=lambda v: int(v, 0), default=None,
                    help="the player's GOLD -- 0x2024 maskA bit 0x200000 "
                         "-> [unit+0x4ec], the field the Status screen "
                         "draws under the label at 0x052e29d8 (format "
                         "'%%lu'). Named live by sentinel and confirmed "
                         "against that table. UNSET SENDS NOTHING, because "
                         "zero is a real value and 'nobody served it' must "
                         "not look like 'you are broke'. Since 2026-09-04 this "
                         "is the SEED for a character with no stored gold; "
                         "the wire carries the character's stored value after "
                         "that (see _seeded_value). \u26a0 Still nothing debits "
                         "it -- per-character, not yet a balance anything "
                         "spends.")
    ap.add_argument("--kill-score", default="exp", metavar="exp|N|off",
                    help="what a kill adds to the character's TOTAL SCORE "
                         "(+0x500), which is what dat.pak's fet_fame_rank "
                         "ladder is keyed by: Beginner at 0, Apprentice at "
                         "10k, ... Commander at 12M, and those names ship in "
                         "ENGLISH even in the JP build. `exp` (default) adds "
                         "the monster's own EXP reward, a number N adds N, "
                         "`off` leaves the score alone. PARTIAL: STATIC ONLY: the "
                         "ladder is keyed by 'a score' and +0x500 is 'the "
                         "total score' -- that the client draws its RANK TITLE "
                         "from the two together is a reading, and the feworld "
                         "log prints the rank it should read so one look at "
                         "the Status screen settles it. Retail earned score in "
                         "the WAR, so per-kill scoring is our rule for making "
                         "the ladder reachable at all.")
    ap.add_argument("--total-score", type=lambda v: int(v, 0), default=None,
                    help="the player's TOTAL SCORE -- 0x2024 maskB bit 0x1 "
                         "-> [unit+0x500], drawn by the Status window at "
                         "0x050e13ca against the label at 0x052e29a8. Note "
                         "it rides maskB, so its field goes AFTER every "
                         "maskA field on the wire. Unset sends nothing.")
    ap.add_argument("--crystal", type=int, default=None, metavar="N",
                    help="CRYSTAL, the Status-screen row between Skill Points "
                         "and GOLD. NOT a 0x2024 bit: it is [unit+0x8ac] and "
                         "the only message that writes it is 0x2035, mask bit "
                         "1 (0x04fe4e50). Found from the draw site backwards "
                         "(0x050e142e). WARNING: the client plays its pickup effect "
                         "when the value INCREASES, so this is an "
                         "authoritative total; nothing debits it, so do not "
                         "build the summon economy on it. Unset sends nothing, "
                         "which is not the same as 0. Seeds the character's "
                         "stored crystal once; the store is served after that. "
                         "`!crystal N` in --gmcmd-file serves N once WITHOUT "
                         "storing it (a probe).")
    ap.add_argument("--ring", type=lambda v: int(v, 0), default=None,
                    help="the player's RING -- 0x2024 maskA bit 0x4000000 "
                         "-> [unit+0x4f0], label at 0x052e29e8. Same "
                         "caveats as --gold.")
    ap.add_argument("--stat-probe", default="off", choices=["on", "off"],
                    help="send one 0x2024 carrying DISTINCT SENTINELS "
                         "(4001..4010) in the ten stat-block fields that "
                         "are zero AND unnamed, to name them off the "
                         "screen in one look -- the trick that settled "
                         "0x303E. The last digit identifies the offset. "
                         "\u26a0 PUTS DELIBERATELY WRONG NUMBERS ON SCREEN; "
                         "off by default and not to be left running. HP, "
                         "Pw, Skill Points and our own walk speed are "
                         "excluded -- they already have writers.")
    ap.add_argument("--stat-probe2", default="off", choices=["on", "off"],
                    help="send one 0x2025 (the SECOND COLUMN of the stat "
                         "block: same setters, index 1) carrying DISTINCT "
                         "SENTINELS 5001..5012 into +0x49c..+0x4d0. HP and Pw "
                         "BONUS slots are included because the gauge draws "
                         "max = base + bonus, which is the on-screen proof. "
                         "\u26a0 deliberately wrong numbers; off by default.")
    ap.add_argument("--jump-phys", default=None, metavar="V:G",
                    type=lambda v: tuple(float(x) for x in v.split(":")),
                    help="0x2024 maskA bits 0x40000|0x80000: f32 +0x4dc (jump "
                         "vertical launch, x4.7 u/s) and f32 +0x4e4 (jump "
                         "gravity, x24.5 u/s^2), both ZERO on our character, "
                         "which is why the SmartJump is a flat weightless "
                         "dash. CHOSEN values, e.g. 1.0:1.0 -> 0.38 s flight, "
                         "0.45 u apex -- but LIVE 2026-09-08 run 4, 1.5:1.0 read as "
                         "high, jumps in place, SmartJumpMessage N ~2700 (a "
                         "~2 s flight, not 0.58), so the launch term in this "
                         "model is low by ~3x; prod runs 0.6:1.0. Read "
                         "SmartJumpMessage N in the client "
                         "log: the 300+400 ms wind-up/landing are immediates "
                         "in 0x05152670 and will not move. Unset sends nothing.")
    ap.add_argument("--npc", action="append", default=None,
                    metavar="NAME[:X:Y:Z]",
                    help="spawn an extra avatar in the field, repeatable. "
                         "It rides the same 0x1006 record --add-self uses, "
                         "and the type-0 ctor 0x050679c0 stamps "
                         "[obj+0x24]=2 -- the kind 0x2023 action 0 will "
                         "move, unlike the player (kind 1). Appearance is "
                         "copied from the stored character so the model is "
                         "one the client is known to build. Unset = none.")
    ap.add_argument("--npc-walk", default=None, metavar="SPEED:STEP",
                    type=lambda v: tuple(float(x) for x in v.split(":")),
                    help="walk each --npc with 0x2023 action 0, driven off "
                         "the client's own 0x2023 heartbeat. SPEED goes to "
                         "the first speed component; STEP is how far the "
                         "target advances on +Z per push. The tick pair is "
                         "lifted VERBATIM from the client's frame, because "
                         "its timebase is unmeasured and reusing the "
                         "client's own clock beats inventing one. \u26a0 The "
                         "position is dead-reckoned server-side and will "
                         "drift from what is drawn -- a probe for 'does he "
                         "move', not a simulation. Unset = the NPC stands "
                         "still.")
    ap.add_argument("--npc-base", type=lambda v: int(v, 0), default=1000,
                    help="object id for the first --npc; each subsequent "
                         "one takes the next. Must not collide with a real "
                         "charid -- the id is what 0x1006 looks up and what "
                         "a 0x2023 record targets.")
    ap.add_argument("--unit-speed", type=float, default=None,
                    help="push 0x2024 with maskA bit 0x20000 -- ONE f32, "
                         "stored RAW and unscaled at [unit+0x4d4] by "
                         "0x04ff4670. This is the setter 0x2023 could never "
                         "reach: it gates on [unit+0x20] (measured 3 on the "
                         "player) rather than [unit+0x24] (measured 1, which "
                         "is why every 0x2023 action-0 record was discarded). "
                         "Unset = send nothing. \U0001f7e2 WHAT A VALUE MEANS, "
                         "static 2026-09-09: it is a MULTIPLIER. Every reader "
                         "of the pair computes ([+0x4d8] + [+0x4d4]) x row[0] "
                         "of the movement table, and with no metamorphosis "
                         "row[0] is 6.0 IN A CAPITAL and 4.0 ON A WAR FIELD "
                         "(the client picks the row with a predicate that is "
                         "literally 'am I in a capital' -- 0x04FF7EF0 returns "
                         "true for exactly 21/39/57/62/78/91..95). So 1.0 is "
                         "the game's own walk, and prod's 1.3 is 7.8 u/s in "
                         "town and 5.2 afield. \u26a0 ONE BIT ONLY: the other 24 "
                         "setters have unpinned widths and a bit with nothing "
                         "behind it desynchronises the record.")
    ap.add_argument("--unit-speed-repeat", default="on",
                    choices=["on", "off"],
                    help="re-push --unit-speed on every inbound 0x2023 "
                         "(~2.5/s, the only regular tick we get in the "
                         "field). 'off' sends it once at field entry, which "
                         "is the A/B for whether the field decays.")
    ap.add_argument("--move-authority", default="off",
                    choices=["off", "echo", "state1", "walk"],
                    help="answer the client's own 0x2023 by sending the "
                         "SAME 28 bytes back. 0x2023 runs both ways and the "
                         "receive side (action 0, arm 0x04fea890) is what "
                         "writes the speed pair at unit+0x4d4/+0x4d8 and "
                         "drives the movement controller -- felive measured "
                         "both halves at 0.0 while the walk animation "
                         "played. The two directions are the same record in "
                         "the same units (the scales are exact inverses), so "
                         "the echo invents nothing. 'state1' additionally "
                         "forces the u16 at offset 8 to 1, the flag whose "
                         "zero SKIPS the controller (0x04feadd8) -- that one "
                         "IS an invented value, hence a separate mode. OFF "
                         "by default: this is a probe for whether the "
                         "receive side moves the player, not authority. "
                         "\U0001f534 'echo' IS PROVEN INERT (live 2026-08-25): the "
                         "client reports speed (0,0) and state 0 because its "
                         "outbound builder reads the same +0x4d4/+0x4d8 the "
                         "inbound arm writes, so the loop has nothing driving "
                         "it and relaying it relays zeros. 'walk' INVENTS a "
                         "speed and a target ahead of the player -- see its "
                         "note -- to test the mover without the intent "
                         "channel.")
    ap.add_argument("--move-speed", type=float, default=1.0,
                    help="--move-authority walk: the value written to the "
                         "FIRST speed component (unit+0x4d4), before the "
                         "client's x0.001. Which of the two components is "
                         "which is UNMEASURED -- 0x0515bce0 only ever sums "
                         "them -- so this moves one field and leaves the "
                         "other as the client sent it.")
    ap.add_argument("--move-dist", type=float, default=5.0,
                    help="--move-authority walk: how far AHEAD of the "
                         "player's own reported position to put the target, "
                         "on +Z. The axis is a guess (it is the facing we "
                         "serve); movement along the wrong one still answers "
                         "the question this probe asks.")
    ap.add_argument("--draw-self", default="off",
                    help="push the camera/draw-self switch after the add "
                         "stream. 'off' (default) sends nothing; '1'/'0' "
                         "send 0x1170 with that u16; 'on'/'hide' send the "
                         "header-only 0x1181/0x1182. [0x52ffad0]+0x1d is the "
                         "byte /stealth calls 'Draw self' and the only gate "
                         "on the player unit's own per-frame block "
                         "(0x0507e7f0). POLARITY UNMEASURED -- test with "
                         "/stealth in the game's own chat first.")
    ap.add_argument("--add-submask", type=lambda v: int(v, 0),
                    default=0x82FF,
                    help="the mask1-bit0 sub-record mask. 0xFF = name + all "
                         "seven appearance fields (bits 0..7 -> unit+0x389, "
                         "+0x3aa sex, +0x3ab, +0x3b0, +0x3b4, +0x3b6, +0x3b7, "
                         "+0x3b8), every one of them a field felobby already "
                         "stores. KEY: 0x200 IS NOW ON BY DEFAULT (0x2FF): it is "
                         "+0x3bc, the NATION, and felive measured it live as "
                         "0x7FFFFFFF -- the client's own 'no nation' "
                         "sentinel -- while the stored character has force 1. "
                         "A client with no nation is why it then sends "
                         "'army choice req sent : 0' on 0x2018 and why "
                         "+0x94 reads 0. Bit 0x100 (+0x94, ARMY, one byte) is "
                         "in the table but LEFT OFF: the client picks its own "
                         "army and overriding that is unmeasured. Every width "
                         "here is pinned to a reader's stream advance -- a "
                         "wrong one desynchronises the record, it does not "
                         "just draw a wrong number.")
    ap.add_argument("--add-parts", default="",
                    help="optional mask3 parts as SLOT:PARTID[:PARAM],... with "
                         "SLOT in 0..12. Equipment layered ON TOP of the base "
                         "model; a partId that misses 0x504cb40(id, 0xbb8) fails "
                         "SILENTLY. Leave empty until the base model works.")
    ap.add_argument("--add-type", type=lambda v: int(v, 0), default=0,
                    help="the u8 entity type in the 0x1006 record. 0 = Avatar, "
                         "the arm that dresses a character (jump table "
                         "0x0503bb0c has 9 arms; 3..6 are the no-op default).")
    ap.add_argument("--add-mask1", type=lambda v: int(v, 0), default=0x1,
                    help="0x1006 record mask1. bit0 = the NAME+APPEARANCE "
                         "sub-record (0x5079d60) -- default ON, because it is "
                         "the whole point: it is what feeds unit+0x3aa, the byte "
                         "the model-path builder at 0x0507a04f indexes to choose "
                         "Model\\<dir>\\<prefix>face%%02d_%%d.mdl. bit1 "
                         "(0x507a990, two u16s at unit+0x498/+0x49a) stays off; "
                         "it is undecoded.")
    ap.add_argument("--add-stats", default="0:5",
                    type=lambda v: {int(k, 0): _stat_num(x)
                                    for k, _, x in (q.partition(":")
                                                    for q in v.split(",") if q)},
                    help="BIT:VALUE pairs for the 0x1006 record's STAT block "
                         "(mask1 bit 1, applier 0x0507a990). Bit 0 is SKILL "
                         "POINTS at [unit+0x498] -- the exact i16 the Status "
                         "window draws (0x050e13fc), confirmed live with "
                         "`felive --stats`. WARNING: BIT 0 IS A BUDGET, NOT A "
                         "BALANCE: what goes on the wire is this value MINUS "
                         "the skills already stored, because serving it flat "
                         "would hand the player a fresh five at every field "
                         "entry, forever. Empty string sends no stat block at "
                         "all. WARNING: mask1 bit 1 is derived from THESE VALUES and "
                         "must never be set by hand: the mask promises how many "
                         "i16 follow, so a bit with nothing behind it "
                         "desynchronises the record. Bits 1-4 read 200/200/100/"
                         "100 live against a screen showing HP 200/200 Pw "
                         "100/100 -- a strong inference, not a measurement, so "
                         "they are not in the default.")
    ap.add_argument("--add-mask2", type=lambda v: int(v, 0), default=0x5,
                    help="0x1006 record mask2. bit0 = position (3 f32 -> "
                         "unit+0x1c4, taken from --spawn-pos), bit2 = facing "
                         "(3 f32 -> unit+0x1e4, from --spawn-dir). Default 0x5 "
                         "= both.")
    ap.add_argument("--decide-country", default="ok",
                    choices=["ok", "ng", "off"],
                    help="answer 0x2018 MSG_DECIDE_COUNTRY_REQUEST -- the army "
                         "choice the client sends immediately after "
                         "'PLAY_START done.' and then waits on. 'ok' sends "
                         "0x1020 (header-only; its arm reads no body and clears "
                         "scene pending bit 0x80), 'ng' sends 0x1021 (which "
                         "makes the client re-ask -- diagnostic only), 'off' "
                         "restores the old silence for an A/B.")
    ap.add_argument("--war-start", default="off",
                    choices=["on", "off", "deadline"],
                    help="after the 0x1018/0x1019 war notify, push 0x1015 -- the "
                         "message whose arm (0x0511850f) is the ONLY thing that "
                         "clears scene pending bit 0x80, the bit our own war "
                         "notify arms and which felive measured still set in "
                         "the field. It also moves the war-view phase [+0x70] "
                         "from 0 to 2 and installs a fresh deadline. OFF by "
                         "default: the pending bit is measured, the MEANING of "
                         "the phase advance is not. A/B it and read "
                         "[scene+0x528] after. 'deadline' sends it when "
                         "--war-deadline-ms has elapsed instead of "
                         "immediately -- which is the retail SHAPE, because the "
                         "client drops its own countdown-expiry event "
                         "(0x05117d37) and therefore never starts a war by "
                         "itself. 'on' fires in the same burst as the notify "
                         "and skips the countdown entirely.")
    ap.add_argument("--war-start-fields", default="0,0", metavar="HI,LO",
                    help="the two big-endian u32s in 0x1015 -- the same deadline "
                         "pair as the last two --war-fields, in the same wire "
                         "order: HIGH dword FIRST, then LOW (see war_notify's "
                         "docstring for the stack that proves it; the metavar "
                         "read LO,HI until 2026-08-26 and was wrong). A deadline "
                         "under ~49 days has a zero high word, so the pair is "
                         "0,<ms>. Prefer --war-deadline-ms, which cannot be got "
                         "round the wrong way. 0,0 reproduces the "
                         "already-expired deadline 0x1018 installs.")
    ap.add_argument("--war-deadline-ms", type=int, default=0, metavar="MS",
                    help="the 0x1015 war deadline as ONE number of "
                         "milliseconds, split into the wire's HIGH/LOW pair "
                         "here rather than by hand. Overrides "
                         "--war-start-fields when non-zero. THE UNITS ARE "
                         "MEASURED: 0x5111010 divides the remaining time by the "
                         "f32 at 0x528b738, which is 3600000.0 -- one hour in "
                         "ms -- and that is the arc the needle sweeps, so a "
                         "value ABOVE 3600000 drives the fraction negative. "
                         "WARNING: IT IS NOT A WALL CLOCK. The client's `now` is "
                         "[0x5336ec0] + the session timer, and that base is "
                         "written ONLY by message 0x1148, which we have never "
                         "sent -- so it is 0 and `now` is ms since the "
                         "field-load timer reset (0x1012 / 0x300C on the way "
                         "in). 1800000 = half an hour after the field started "
                         "loading, which leaves a visibly-moving needle at "
                         "roughly half sweep. Read the result with "
                         "`felive --war --watch --interval 1`: a moving frame "
                         "counter with a frozen needle is EXPIRED, a frozen "
                         "counter is a SHUT GATE.")
    # WARNING: DEFAULT FLIPPED BACK TO `off` 2026-09-12, THE SAME DAY IT WENT ON.
    # Since --world-clock on shipped, every field entry parks the
    # client in mode 0xb SUBSTATE 3 -- the fade -- instead of reaching
    # substate 4, the steady gameplay loop. Measured with felive on a
    # live client: `substates = 0 3 0 0` while standing still,
    # `0 4 0 0` after any input. In substate 3 nothing per-frame updates, so
    # the sky is the previous scene's, the HUD gauges draw empty (the unit
    # itself reads HP 1000/1000, Pw 100/100 -- the values are fine) and the
    # body and the worn armour are drawn unposed, which is the "base outfit
    # clipping through the equipment" report.
    #
    # Substate 3 advances only when the fade's own flag is set (0x05039630 ->
    # `[0x5338154]+0x54`), and that flag is set at 0x05039163 when the fade's
    # ELAPSED (`+0x4c`, accumulated per frame at 0x0503949b) exceeds its
    # DURATION (`+0x48`). 0x1148 moves the client's clock base by ~1.79e12 ms
    # (server epoch), at field entry, every entry.
    #
    # WARNING: THE CAUSAL LINK IS NOT PROVED -- the fade's per-frame delta has not
    # been traced to this clock. What IS established: the symptom is the
    # substate-3 park, it appeared the day this default went on, and the
    # 0x1148 note in this file already warned that "the base is harmless to
    # every other consumer" was NOT measured, listing five other readers.
    # Turning it back off is the cheap half of that test and costs only the
    # in-game time display. If the park survives `off`, the clock is
    # exonerated and the next step is tracing the delta at 0x0503949b --
    # do NOT flip this back and forth beyond that one run.
    # KEY: 2026-09-12 (evening): the per-ENTRY send is gone; 'session' sends
    # 0x1148 ONCE per connection, --world-clock-after-ms after the field is
    # ready, never while a war countdown in the client's units is armed.
    # VERIFIED: DEFAULT 'session' SINCE 2026-09-12 ~21:20Z, on a live measurement
    # (felive --scene, player standing still): a `!clock` base landing in
    # steady state held `0 4 0 0` throughout and was accepted, and a field
    # change WITH the base set reached `0 4` in 2 s with no input -- so the
    # park was the base JUMPING DURING an entry, which 'session' never does.
    # The flip was approved. Not yet measured: two players, one synced
    # (fepresence.rebase_clock maps the full 64 bits; tested offline).
    # 'on' is kept as a spelling of 'session' so an old argv cannot
    # crash-loop the container.
    # PARTIAL: DEFAULT 'connect' SINCE 2026-09-12 ~21:45Z (design call: "we should just
    # have it send the clock the second you connect ... the clock shows on the
    # map screen too"). Under 'session' the player arrived at NIGHT (the unset
    # clock) and the sky jumped to day ~12 s later. 'connect' sends with the
    # 0x302B login OK, before any field loads; the first sample verifies it
    # and 'session' is the fallback. Not yet seen live.
    ap.add_argument("--world-clock", default="connect",
                    choices=("off", "connect", "session", "on"),
                    help="send 0x1148 to set the client's clock base. KEY: "
                         "that clock IS the in-game WORLD TIME: the getter "
                         "0x04FFEF10 returns the base plus the client's own "
                         "elapsed ms, and -1 ('no time') until the base is "
                         "set, which only 0x1148 does. The world-time object "
                         "divides it for the year/day/hour/minute the client "
                         "logs as `fetime=`. 'session' (= 'on'): ONCE per "
                         "connection, --world-clock-after-ms after the field "
                         "is ready, deferred while a war countdown is armed. "
                         "The default. 'off': never, except `!clock`.")
    ap.add_argument("--world-clock-after-ms", type=int, default=10000,
                    metavar="MS",
                    help="under --world-clock session, how long after the "
                         "field-ready batch the 0x1148 waits -- the base must "
                         "never land during the entry fade (substate 3), "
                         "which is what the per-entry send did.")
    ap.add_argument("--clock-epoch-ms", type=int, default=0, metavar="MS",
                    help="offset added to the 0x1148 base. The base is server "
                         "epoch ms, which every client shares (so they agree) "
                         "but which makes the in-game YEAR read about 2043 -- "
                         "FE's own calendar epoch is not written down in any "
                         "source we have. This is where it goes if one turns up")
    ap.add_argument("--war-clock", default="telemetry",
                    choices=["off", "telemetry", "sync"],
                    help="how war deadlines relate to the CLIENT's clock. "
                         "'telemetry' (default, CHOSEN 2026-08-27): read the "
                         "client's own 64-bit ms clock off bytes 4..12 of "
                         "every 28-byte 0x2023 it sends (builder 0x0515dd85 "
                         "writes [u32 0][u32 HI][u32 LO] straight from "
                         "0x4ffef10) and make every deadline 'client now + N', "
                         "judging expiry against the same clock; sends no new "
                         "message. 'sync': additionally push 0x1148 once "
                         "(arm 0x05055edb, two u32s HIGH first -> "
                         "[0x5336ec4]:[0x5336ec0]) with base = server epoch ms "
                         "- client elapsed, so the client's clock becomes wall "
                         "time; the next 0x2023 must show the jump. 'off': the "
                         "pre-08-27 behaviour -- N is ms after the client's "
                         "field-load timer reset and expiry is our own "
                         "monotonic() since the notify.")
    ap.add_argument("--war-cycle", default="off", choices=["off", "on"],
                    help="run the whole war on a timer: 0x1018 (phase 0, "
                         "--war-deadline-ms) -> 0x1015 (phase 2, "
                         "--war-length-ms) -> 0x1016 truce (phase 1, "
                         "--war-truce-ms) -> 0x1017 peace -> a fresh 0x1018. "
                         "Implies the 'deadline' shape of --war-start. OFF by "
                         "default: 0x1016/0x1017 have never been sent to a "
                         "client. `!war` forces the next step.")
    ap.add_argument("--war-length-ms", type=int, default=600000, metavar="MS",
                    help="--war-cycle: how long phase 2 lasts before the "
                         "truce. CHOSEN 600000 (10 min); the arc's full sweep "
                         "is 3600000 (0x528b738) so keep it under an hour. "
                         "VERIFIED: 2026-09-09, WHY THE TOP BAR LOOKS DEAD: the arc "
                         "gauge draws (3600000 - remaining) / 3600000 "
                         "(0x0511105F..0x05111065), a fraction of a FIXED "
                         "hour -- so a 300000 ms war starts its needle at "
                         "91.7%% of the way along and creeps through the last "
                         "twelfth. The reported 'top bar during combat that "
                         "doesn't seem to do anything' is that: it moves, "
                         "across 1/12 of its width. Set this near 3600000 for "
                         "a bar that sweeps end to end.")
    ap.add_argument("--war-truce-ms", type=int, default=120000, metavar="MS",
                    help="--war-cycle: how long the truce (phase 1, "
                         "休戦終了まで) lasts before 0x1017 and the next "
                         "declaration. CHOSEN 120000 (2 min).")
    ap.add_argument("--war-counts", default="0,1,64,64",
                    type=lambda v: tuple((list(int(x, 0) for x in v.split(","))
                                          + [0, 0, 0, 0])[:4]),
                    help="the four u16s of the 0x1127 body, IN WIRE ORDER: "
                         "attack_count, defense_count, attack_max, defense_max "
                         "(read order at 0x050581af, named by the client's own "
                         "log format 0x52d5fbc). They land in the field manager "
                         "at mgr+0x5c/0x5e (defense pair) and mgr+0x60/0x62 "
                         "(attack pair). The default says: nobody attacking, "
                         "the one player defending, 64 slots a side. Whether a "
                         "non-zero max opens the deploy UI is UNMEASURED -- "
                         "this is the knob for finding out.")
    ap.add_argument("--self-unit", default="on", choices=["on", "none"],
                    help="serve the player's OWN unit in the 0x1000 entity list "
                         "(one { u8 type, u32 id=charid, f32 x4 } record) so the "
                         "loaded-but-black field has a camera subject -- the FMO "
                         "self-unit pattern. 'none' sends an empty field.")
    ap.add_argument("--self-type", type=lambda v: int(v, 0), default=0,
                    help="the u8 unit type for the self-unit ([entity+0x18]); "
                         "which value means 'player' is unmeasured -- a knob.")
    ap.add_argument("--self-pos", default="0:0:0", metavar="X:Y:Z",
                    help="spawn position (f32 x,y,z) for the self-unit. WARNING: Y IS "
                         "AN ABSOLUTE HEIGHT, not an offset, and the terrain "
                         "varies ~25 units across one field: 0:0:0 lands at the "
                         "LOW point of group 1 under a cliff. Measure a real one "
                         "with `felive --avatar` (prints pos [+0x1c4]) while "
                         "standing where you want to arrive -- 2.16:24.76:-60.51 "
                         "was measured there 2026-09-04. The client ground-snaps "
                         "on entry when the query at 0x5000450 succeeds "
                         "([unit+0x2ac] bit 3), so a near-miss settles; a wild Y "
                         "does not.")
    ap.add_argument("--self-heading", type=float, default=0.0,
                    help="the 4th f32 in the entity record (heading/spare).")
    ap.add_argument("--add-complete", default="on", choices=["on", "off"],
                    help="push 0x100E MSG_ADD_COMPLETE after answering a "
                         "POST-ENTRY 0x4011 group-detail request. Its handler "
                         "(0x503a050) sets [scene+0x509]=1, the flag mode 0xb "
                         "substate 2 waits on -- without it the client parks on "
                         "the loading screen forever (measured live 2026-08-23, "
                         "the 210s hang). 'off' restores that for A/B.")
    ap.add_argument("--move", default="none", choices=["auto", "none"],
                    help="push 0xE00D MOVE_CHARACTER after answering the "
                         "client's 0x2000 with 0x1000. WARNING: DISPROVEN as the exit "
                         "fix (live 2026-08-23): it decodes and arms [scene+0x84] "
                         "but the client exits regardless -- the exit is "
                         "GameStart completing the map phase, not a missing "
                         "message. Default OFF; kept as a knob because 0xE00D "
                         "may belong to the unreached field/battle phase.")
    ap.add_argument("--move-pos", default="0:0:0", metavar="X:Y:Z",
                    help="the f32 position served in 0xE00D (-> scene+0x74..). "
                         "Units/origin unmeasured; mode 0xb walks/warps the "
                         "unit there when it is farther than the 0x525f5bc "
                         "radius, so keep it 0:0:0 until a live run says more.")
    ap.add_argument("--move-seq", type=lambda v: int(v, 0), default=1,
                    help="the leading u32 token in 0xE00D (-> scene+0x6c). "
                         "Echoed back in the client's 0xE00F NACK; semantics "
                         "beyond that unmeasured.")
    ap.add_argument("--probe-on-auth", action="store_true",
                    help="answer 0x20 (which needs no answer) with a minimal "
                         "enciphered frame, to find out whether ANY frame from us "
                         "is rejected on this connection or only the login reply")
    ap.add_argument("--capture-only", action="store_true",
                    help="decode and print but never reply, the behaviour this "
                         "service shipped with before 0x400F was understood")
    ap.add_argument("--unit-login-value", default="auto",
                    help="the u32 payload of 0x302B MSG_SERVER_UNIT_LOGIN_OK, "
                         "which its OK arm (0x050476d3) stores at "
                         "[0x533998c]+0x9e0 -- the SERVER UNIT's id. 'auto' "
                         "(default since 2026-08-24) sends the session charid, "
                         "so the server unit's id matches the entity id we "
                         "spawn for the player in 0x1000; they disagreed (0 vs "
                         "1) in every session before that. Pass an explicit "
                         "number (e.g. 0) to restore the old behaviour for an "
                         "A/B. WARNING: Whether [esp+0x10] in that arm is this payload "
                         "or the inner header's leading u32 is STILL UNSETTLED "
                         "-- both were 0 forever, so no live read could "
                         "separate them; this makes them differ so one field "
                         "read decides it.")

    ap.add_argument("--captures", type=int, default=0,
                    help="exit after this many connections; 0 = never")
    ap.add_argument("--life", type=int, default=0,
                    help="exit after this many seconds; 0 = never")
    ap.add_argument("--read-window", type=float, default=120.0,
                    help="hang up a connection idle this long. NOT optional -- a "
                         "bind that leaves FE waiting strands the player with no "
                         "way back to the Viewer.")
    ap.add_argument("--idle-tick-ms", type=int, default=250, metavar="MS",
                    help="run the pump chain this often even when the client "
                         "says nothing. 0 = the pre-2026-09-11 loop, which "
                         "blocked in recv until the client spoke -- so chat "
                         "relays, the revive, campaign phases and peer "
                         "movement all ran at the mercy of THIS client's "
                         "outbound rate. Measured cost: a player standing "
                         "still saw a walking peer update every 3-6 seconds.")
    ap.add_argument("--war-max-laps", type=int, default=0,
                    help="cap how many 0x1018 war notifies are pushed per lap "
                         "BEFORE field entry. 0 (default) = unbounded, which is "
                         "the behaviour every measurement so far ran against. "
                         "A brand-new character that never reaches field entry "
                         "re-arms [screen+0x62] with each one and re-polls "
                         "0x4011 at frame rate -- 3,185 in one prod session on "
                         "2026-08-24, black screen. Set 3 to test whether that "
                         "re-arm IS the loop. WARNING: NOT a settled fix: per-lap was "
                         "chosen because a single 0x1018 can be dropped when no "
                         "screen is up (prod 2026-08-19), so a cap trades a "
                         "measured delivery problem for an unmeasured one.")
    ap.add_argument("--account-mode", default="resolve",
                    choices=["resolve", "echo"],
                    help="how the character store is keyed. `resolve` turns the "
                         "0x400F account echo into the POL member felobby "
                         "resolved (echo -> felobby's handoff file -> a direct "
                         "lookup; see resolve_account). `echo` keys by the raw "
                         "echoed string, which with felobby's old constant "
                         "--account is ONE ROSTER FOR EVERY PLAYER -- kept only "
                         "for reproducing pre-2026-08-24 captures.")
    ap.add_argument("--char-record", default="off", choices=["on", "off"],
                    help="push 0x1003 kind 0 after 0x1000. WARNING: OFF BY DEFAULT "
                         "SINCE 2026-09-04, AND KEEP IT OFF: this CRASHED THE "
                         "CLIENT on field load (live 2026-08-25 -- 'Chara 1 "
                         "already exists' then m_body.mdl::Release then an AV "
                         "at FE_Client+0xEB70E). 0x1003 kind 0 is a character "
                         "CREATE/REPLACE that releases the models on a lookup "
                         "hit, and a stats-only record (flags=2) gives the "
                         "rebuild nothing to build from. Prod has carried an "
                         "explicit `--char-record off` ever since while the "
                         "code default stayed 'on', so a bare run reproduced "
                         "the crash. Skill Points are served by --add-stats "
                         "bit 0 on the 0x1006 MSG_ADD instead. 'on' exists for "
                         "an A/B and needs flags=3 with the identity block "
                         "populated before it can be safe -- see "
                         "char_record_push.")
    ap.add_argument("--char-mask", type=lambda v: int(v, 0), default=1,
                    help="the 0x1003 field mask. WARNING: DEFAULT 1 -- BIT 0 ONLY -- "
                         "and that is not timidity. A mask is a promise about "
                         "how many i16 follow it, so setting a bit with no "
                         "measured meaning does not draw a wrong number, it "
                         "DESYNCHRONISES the record mid-decode. Bit 0 is the "
                         "only slot pinned to a label; the other sixteen "
                         "offsets are known but unidentified. Widen this only "
                         "as each bit is measured.")
    ap.add_argument("--char-fields", default="0:5",
                    type=lambda v: {int(k, 0): int(x, 0)
                                    for k, _, x in (p.partition(":")
                                                    for p in v.split(",") if p)},
                    help="BIT:VALUE pairs for --char-mask, e.g. '0:5' = five "
                         "skill points. Values are i16.")
    ap.add_argument("--acquire-skill", default="ok",
                    choices=["ok", "ng", "off"],
                    help="answer 0x2049 MSG_ACQUIRE_SKILL_REQUEST -- the GET! "
                         "button -- with 0x1078 (header-only, arm 0x050534f7) "
                         "and PERSIST the skill id onto the stored character, "
                         "so 0x303E serves it back. Acknowledging without "
                         "persisting would spend the player's SP for a skill "
                         "that vanishes at the next login. 'ng' sends 0x1079 "
                         "with --ui-auto-err; 'off' leaves the window hanging.")
    ap.add_argument("--status-resync", default="on", choices=["on", "off"],
                    help="after a successful 0x2049, re-push 0x303E so the "
                         "skill window agrees with the store immediately "
                         "instead of at the next login.")
    ap.add_argument("--status", default="off", choices=["on", "off"],
                    help="push 0x303E, the CHARACTER STATUS record -- the "
                         "message that carries skill_point AND the acquired "
                         "skill list, and which feworld has never sent. That is "
                         "why SP reads 0, Skill Points reads 0 and every GET! "
                         "is greyed out. OFF by default only because the "
                         "message has never been on the wire; turn it on with "
                         "the probe values below and read the status screen.")
    ap.add_argument("--status-nums", default="101,102,103,104,105,106,107,108,109",
                    type=lambda v: [int(x, 0) for x in v.split(",") if x],
                    help="the NINE u32 of the 0x303E body, IN WIRE ORDER "
                         "(readers 0x05024b41..0x05024bad). The client's own "
                         "dump names nine scalars -- skill_point, life, power, "
                         "stamina, down, gold, ring, fame, total_score -- but "
                         "WARNING: WHICH SLOT IS WHICH IS NOT ESTABLISHED: the dump's "
                         "print order and the wire order need not agree. The "
                         "default is nine DISTINCT SENTINELS so one look at the "
                         "status screen labels all nine. Do not replace them "
                         "with real values until that run has happened.")
    ap.add_argument("--status-skills", default="",
                    type=lambda v: [int(x, 0) for x in v.split(",") if x],
                    help="acquired skill ids for the 0x303E list ([u32 count] "
                         "then one u32 each, loop 0x05024be5). Empty = none, "
                         "which is what the client is already showing.")
    ap.add_argument("--status-id", type=lambda v: int(v, 0), default=None,
                    help="0x303E leading u32 (the client dumps it as `id`). "
                         "Unset = the session's charid. (These five used to "
                         "default to one hard-coded test character -- id 1, "
                         "'Lex', class 1, nation 1 -- for every player.)")
    ap.add_argument("--status-name", default=None,
                    help="0x303E cstr #1, right after the id. Unset = the "
                         "stored character's name.")
    ap.add_argument("--status-sex", type=lambda v: int(v, 0), default=None,
                    help="0x303E u8. Rendered through a name lookup, so a value "
                         "the table does not know is not a blank field. Unset "
                         "= the stored character's `sex`.")
    ap.add_argument("--status-class", type=lambda v: int(v, 0), default=None,
                    help="0x303E u16 class_type, also a name lookup. Unset = "
                         "the stored character's `look1`, the [unit+0x3AB] "
                         "class byte.")
    ap.add_argument("--status-nation", type=lambda v: int(v, 0), default=None,
                    help="0x303E u16 after the nine (dumped as `nation`). "
                         "Unset = the stored character's `force`, or 0 while "
                         "it is the 0x7FFFFFFF 'none' sentinel.")
    ap.add_argument("--status-str2", default="",
                    help="0x303E cstr #2, between the nation u16 and the skill "
                         "count. Its role is unmeasured; empty is a valid "
                         "cstr and keeps the stream aligned.")
    ap.add_argument("--validate-finish", type=float, default=10.0,
                    metavar="SECONDS",
                    help="after answering 0x209A (the Field Out button) with "
                         "0x1154, push 0x1157 FINISH_NOTIFY this many seconds "
                         "later. 0x1154's arm only STARTS a countdown -- it "
                         "sets [unit+0x138c] = 0x2710 and stamps a timestamp -- "
                         "so answering OK alone moves the hang ten seconds "
                         "later instead of fixing it. The default matches the "
                         "client's own constant (10000ms); 0 sends no FINISH. "
                         "0x209C (Cancel) clears the pending push.")
    ap.add_argument("--skill-grant", default=DEFAULT_SKILL_GRANT,
                    choices=["class", "stored", "items", "all"],
                    help="which skills to mark owned in 0x1075. 'class' "
                         "(default, 2026-09-11) = the character's own PLUS its "
                         "class's starting set, FE_CLASS_BASIC_PARAM_DATA "
                         "+0x70: the proficiencies its starting gear needs "
                         "and its first skills (basic attack etc.), free of "
                         "SP -- what a 2006 Lv1 started with; a class can no "
                         "longer wear another class's weapon family. 'items' "
                         "= the character's own PLUS the "
                         "prerequisite skills the items in its bag actually "
                         "name (each item table record's +0x88, up to two ids, "
                         "0xffff = none) -- the exact gate validator "
                         "0x05076090 code 5 tests, and the refusal that reads "
                         "as 'Wrong class; can't equip'. They are weapon and "
                         "armour proficiencies (443 = wand, 439 = axe, 445..7 "
                         "= armour weights), so this grants a proficiency per "
                         "family carried and nothing else. 'stored' = the "
                         "character's own only. 'all' is the PROBE that found "
                         "the gate: every id in the array, i.e. the whole "
                         "skill tree -- an A/B, not a setting.")
    ap.add_argument("--equip-reflect", default="request",
                    choices=["on", "request", "off"],
                    help="reflect an equip so the client actually wears it. "
                         "VERIFIED LIVE 2026-09-06: the test character's staff "
                         "appeared on screen, no crash. 'request' (default) "
                         "answers a click the player made -- 0x2021/0x2022/"
                         "0x2098 -- with a 0x107A carrying the item's equip "
                         "marker, which is what makes the click DO something: "
                         "0x102A's arm only clears a flag and moves no item. "
                         "'on' ALSO replays the stored equipment after field "
                         "entry, which is NOT the default because it is "
                         "redundant -- the client already dresses the character "
                         "at unit-build time from the 0xD002 equip pairs "
                         "(measured: six Equip calls from FE_Client+0x5788C "
                         "during entry, markers 0/3/5/6, before any server "
                         "push). 'off' restores the old accept-and-do-nothing. "
                         "WARNING: Never sent before the field exists whatever this "
                         "says -- the client resolves the unit id with no null "
                         "check and dies (0x05077D14, live 2026-09-06).")
    ap.add_argument("--use-item", default="on", choices=["on", "off"],
                    help="answer 0x2051 MSG_USE_ITEM and consume the item. "
                         "Unanswered the request hangs and the item does "
                         "nothing (reported live 2026-09-06). The OK is an "
                         "acknowledgement like every other one in this channel "
                         "-- 0x1089's arm clears one in-flight bit "
                         "([obj+0x4ec] & 0xfe) and discards the rest -- so the "
                         "consumption is a separate 0x107A push. WARNING: NO EFFECT "
                         "is applied: which table column says what an item "
                         "heals is not identified, so this takes the item and "
                         "grants nothing. 'off' restores the hang.")
    ap.add_argument("--room-exit", default="conversation",
                    choices=["conversation", "off"],
                    help="walk the player OUT of a room when a conversation "
                         "ends. A room (shop, tavern, bank) has NO exit of its "
                         "own -- measured twice: inside one, the client sends "
                         "nothing at all at its door, and the 0x2000 area -1 "
                         "once read as an exit was the war screen's countdown "
                         "expiring. We put the player in a room with an "
                         "unsolicited 0x1166, so taking them out is the "
                         "server's move too; before this the only way out was "
                         "a hand-typed `!goto` in the gm command file, and a "
                         "player without one is TRAPPED until the read window "
                         "times out (reported live 2026-09-06 from the "
                         "tavern). 'off' restores that. WARNING: Fires only when the "
                         "session is in a room: outdoors the same message with "
                         "B = -1 is a same-field warp to the spawn point.")
    ap.add_argument("--bag-organize", default="on", choices=["on", "off"],
                    help="make the inventory's STACK (0x114D) and SORT "
                         "(0x20AA) buttons do something. Both have been "
                         "answered since 2026-08-25 and inert ever since, for "
                         "the reason the equip was inert: the OK arms "
                         "0x05058747 and 0x0505846D make ZERO stream reads, so "
                         "the acknowledgement moves no item. The server owns "
                         "the bag layout, so 'on' decides the new layout, "
                         "persists it and pushes one 0x107A per changed row -- "
                         "the same message the equip reflection uses. Sort "
                         "order and what counts as stackable are CHOSEN, not "
                         "measured: see bag_sort_key and bag_stacked. 'off' "
                         "restores the acknowledge-and-do-nothing behaviour.")
    ap.add_argument("--skill-palette", default="request",
                    choices=["on", "request", "off"],
                    help="the SKILL BAR. Double-clicking a skill sends 0x2029 "
                         "and the client does NOT apply its own click -- the "
                         "sender and the local setter are two different vtable "
                         "methods (0x05297688 +0x24 and +0x28) and only the "
                         "INBOUND worker calls the setter. So 0x2029 has to "
                         "come back: it is the same id in both directions, "
                         "which is why it registers no reply pair and looked "
                         "like a dead end. 'request' (default) echoes the "
                         "player's own set/clear, which is safe by "
                         "construction -- the client sent it from the very "
                         "object the answer dereferences. 'on' ALSO replays "
                         "the stored palette after the ADD burst so the bar "
                         "survives a relogin; that has never had a live run, "
                         "and both workers deref the HUD singletons "
                         "0x053491E8/0x053491EC with no null check. 'off' goes "
                         "back to not answering at all.")
    ap.add_argument("--sell-price", type=int, default=50,
                    help="percent of an item's BUY price (its FE_ITEM_DATA "
                         "+0x90, or --shop-price under --shop-prices flat) "
                         "offered when SELLING -- credited to the stored "
                         "wallet on 0x204C, and pushed as 0x1086 [u32 uid]"
                         "[u32 value] while a shop window is open. That "
                         "message is the only writer of [item+0x4f0]; the "
                         "item ctor sets it to -1 (0x05073976) and the client "
                         "never asks for it, which is why every sell price "
                         "drew -1. 0 disables. CHOSEN: FE's buy-back rate is "
                         "in no table we have read, so this is a percentage.")
    ap.add_argument("--skill-list", default="on", choices=["on", "off"],
                    help="push 0x1075 with the character's acquired skills "
                         "after the ADD burst. This is what makes a learned "
                         "skill SURVIVE A RELAUNCH: 0x2049 GET! persists it "
                         "server-side, but nothing sent it back, so the skill "
                         "window came up empty every session and the points "
                         "spent on it looked lost. It writes "
                         "[unit+0xA14 + id*2], which is the exact array the "
                         "skill row reads at 0x050D3A06.")
    ap.add_argument("--class-levels", default=DEFAULT_CLASS_LEVELS,
                    metavar="CLASS:LEVEL,...",
                    help="ride bit 0 of the same 0x1075 record and set "
                         "[unit+0x9F0+class], the CLASS LEVEL array. This is "
                         "what gates equipping: the validator at 0x05076195 "
                         "compares that byte against each skill's required "
                         "level and returns reason code 4 when it is short, so "
                         "with the array at 0 (which is where it has always "
                         "been, because nothing ever sent it) a skill you own "
                         "and paid points for still cannot be double-clicked "
                         "on. CLASS may be the literal `self`, which resolves "
                         "to [unit+0x3AB] as taken from the STORED character "
                         "(its `look1`) -- and `self` is the default because "
                         "the first attempt hardcoded 1 while the character's "
                         "class is 2, so it wrote a level nothing was going to "
                         "read and the theory went untested. \U0001f511 SINCE "
                         "2026-09-08 THIS IS ONLY A SEED: the table is stored "
                         "PER CHARACTER (festore.py `class_levels`) and a "
                         "character that already has one is served the STORE, "
                         "not this flag -- so levelling a character up is a "
                         "write to its row, and one player's progress is no "
                         "longer every player's. \U0001f511 2026-09-11: the "
                         "default seed is self:1 -- a new character starts at "
                         "Lv1 in its own class (2006) and climbs by EXP "
                         "(feprog: 0x2059). The old all:30 was a workaround for "
                         "the equip validator at level 0; every starting item "
                         "ships req_level 1. Bit 0 also writes [unit+0x3AC] "
                         "(the last value), so the own class is written last. "
                         "Empty string sends no class block at "
                         "all (bit 0 clear) WHATEVER IS STORED -- the off "
                         "switch wins, because a mask bit with no block behind "
                         "it desynchronises the record.")
    ap.add_argument("--skill-list-value", type=int, default=1,
                    help="the u8 written per acquired skill. The 'do I have "
                         "it' predicate is != 0, so 1 is the smallest value "
                         "that satisfies every reader found -- but 0x0507D600 "
                         "ADDs into the same slot, so it may be a level rather "
                         "than a flag. UNMEASURED; this knob is here to try "
                         "others without a redeploy.")
    ap.add_argument("--war-result", default="auto",
                    choices=["off", "auto", "desert", "win", "lose"],
                    help="after answering the Field Out settlement (0x2033 -> "
                         "0x1045), push 0x1100 to build the WAR RESULT window. "
                         "Without it the client reaches the dummy area and "
                         "parks there forever: scene mode 0x0B state 8 spins on "
                         "[scene+0x59], and the only code in the client that "
                         "sets that byte hangs off this window's close button. "
                         "'auto' (the default since 2026-09-12) is win or "
                         "lose when a war this session fought has SETTLED "
                         "(fecampaign's reward relay says which) and desert "
                         "otherwise -- SE warsystem04's own three outcomes. "
                         "'desert' is the semantically right one for Field Out "
                         "(the client's own text is 'You left the "
                         "front. More is expected.'), and it is CONFIRMED LIVE "
                         "2026-08-25: the window renders and Close returns the "
                         "player to the map, so the worry that the desert arm's "
                         "extra 0x0508D9F0 would stop the widget ticking was "
                         "unfounded. win/lose remain for a real battle result. "
                         "'off' restores the hang.")
    ap.add_argument("--war-result-values", default="session",
                    choices=["session", "zero", "sentinel"],
                    help="what to put in 0x1100's eleven scalars. 'zero' is the "
                         "default because we do not simulate a battle, and a "
                         "number we invented rendered under 'Score' is a lie "
                         "the player cannot tell from a fact. 'sentinel' sends "
                         "101..111, DISTINCT per field -- that is how the field "
                         "map was read off one live screenshot on 2026-08-25 "
                         "(Attack/Defend/Score/Exp/Crystal/Destroyed/Built/"
                         "Rewards, plus three parsed-but-undrawn), and it is "
                         "the right setting for one probe run and the wrong one "
                         "for a session a player is actually in.")
    ap.add_argument("--war-result-rows", type=int, default=0,
                    help="how many per-army records to put in 0x1100. The "
                         "window constructs EXACTLY TWO (0x05113D07) and the "
                         "decode loop is unbounded, so this is CLAMPED to 2 in "
                         "war_result_body() -- 3 would write 0x4FC bytes past a "
                         "0xADC allocation. Default 0: the four masks per record "
                         "are all-zero anyway, so rows carry no data yet and "
                         "0 is the smallest thing that decodes.")
    ap.add_argument("--ui-auto", default="ok", choices=["ok", "ng", "off"],
                    help="answer every request in UI_HEADER_ONLY_OK with its "
                         "registered OK, which is the 6-byte header and nothing "
                         "else (each row carries the arm address the "
                         "header-only reading was measured at). This is the "
                         "inventory STACK and SORT buttons, the bank window and "
                         "the shop. WARNING: OK here means ACKNOWLEDGED, not "
                         "simulated: there is no inventory or economy behind it "
                         "-- but an unanswered request hangs that dialog "
                         "forever and takes the session with it. 'ng' answers "
                         "the refusal instead (a body-carrying u32, see "
                         "--ui-auto-err); 'off' restores the hang for an A/B.")
    ap.add_argument("--ui-auto-err", type=lambda v: int(v, 0), default=0,
                    help="the u32 error code for --ui-auto ng. Every NG arm in "
                         "this family reads exactly one u32 and resolves it "
                         "through the client's error table (0x50613e0), so this "
                         "picks which refusal the player is shown.")
    ap.add_argument("--move-request", default="ok",
                    choices=["ok", "ng", "off"],
                    help="answer 0x20A6 MSG_MOVE_REQUEST with 0x1168 (measured "
                         "header-only, arm 0x05056248). ON since 2026-09-05: "
                         "it is transition kind 3 of the field-transition "
                         "machine, the one a DOOR takes after 0x1166 sets "
                         "0x5345ea0, so 'off' hangs every door. (It was off "
                         "while 'movement' was an open investigation; that "
                         "closed on 08-25 and this was never revisited.)")
    ap.add_argument("--door", action="append", default=None,
                    metavar="GID:X:Z:ROOM",
                    help="where a door in field GID at world (X, Z) leads: a "
                         "room index (9 bar, 10 arms shop, 11 magic shop, 13 "
                         "bath, 14 house, 15 castle). The client SENDS the "
                         "door's position in 0x20AC, and feworld logs it as a "
                         "ready-made --door line -- touch each door once to "
                         "map the town. Matched within --door-radius.")
    ap.add_argument("--events", default="on", choices=["on", "off"],
                    help="play a conversation when a town-file NPC is clicked "
                         "(THE EVENT VM: 0x1071 D=script -> 0x20A7 -> 0x1174 "
                         "commands, each acked by 0x20A8 -> 0x1172). Shops "
                         "open the shop window (op 8 type 1..4), the bank its "
                         "window (0x18). 'off' = acknowledge and release.")
    ap.add_argument("--keeps", default="off", choices=["on", "off"],
                    help="serve the two KEEPS of a war field while a campaign "
                         "war is on: the defender's castle at fet_castle_info's "
                         "grid, the attacker's keep 24 cells toward the centre. "
                         "Hits on them (0xA011/0x2010 with the keep's id) take "
                         "--hit-damage off --keep-hp through 0x2024 bit 0x4; at "
                         "0 the keep is 0x1004'd and the war ends for the side "
                         "still standing (--war-decide keeps).")
    ap.add_argument("--castle-always", default="on", choices=["on", "off"],
                    help="with --keeps on, the defender's CASTLE stands in "
                         "every war field in every phase, served for whoever "
                         "holds it; only the attacker's keep comes and goes "
                         "with a war. The client's own book puts the castle "
                         "on the PEACETIME radar (fet_bookset_info 52/53). "
                         "off = the 2026-09-11 rule: both bases only during "
                         "PREP/WAR.")
    ap.add_argument("--keep-hp", type=int, default=3000, metavar="N",
                    help="hit points of each keep (u16 on the wire, <= 32767). "
                         "CHOSEN, a scale model: the client's FE_BUILDING_DATA "
                         "ships 12,000,000 for the Castle/Keep (+0xb0, FFSKY's "
                         "figure; Hordaine 2006 said 4.8M), which the u16 hit "
                         "channel cannot carry. What the 2006 rules fix is the "
                         "FRACTIONS of it (fecampaign --base-dots, 480 dots).")
    ap.add_argument("--keep-types", default="20:16", metavar="DEF:ATK",
                    help="FE_BUILDING_DATA rows for the two bases. Default "
                         "20 Castle / 16 Keep -- SE warsystem02: the defender's "
                         "base IS the castle ('防衛軍の拠点となる建築物') "
                         "and both it and the keep offer the KNIGHT (their "
                         "+0xde is 954; feunit.SUMMON_BY_TYPE). The old default "
                         "4 GateOfHades offered the WRAITH (955), which SE's "
                         "RoD page never lists as a summon at all.")
    ap.add_argument("--keep-models", default="30:16", metavar="DEF:ATK",
                    help="FE_BUILDING_MODEL_DATA rows. Default 30 castle00_a "
                         "/ 16 b_build06_a. castle00_a ships no `_stand.mdl` "
                         "and 4 gateofhades_a does, which is why the default "
                         "was 4:16 from 2026-09-11 -- but that reading was "
                         "RETRACTED the same day: setup 0x05070530 puts `_stand` "
                         "in an embedded KcMODEL (0x0507087e skips a missing "
                         "one) and the only UNCHECKED pointer is slot 0, the "
                         "base mesh. castle00_a.mdl/_m/_s/_light/_hit/.anm/.tex "
                         "all ship (building.pak, re-verified 2026-09-12), so "
                         "it is crash-safe by that reading and the crash was "
                         "the unmounted pak (fixed by the field_ready gate). "
                         "PARTIAL: The live bar is a war field entered, left and "
                         "RE-entered with the castle on screen.")
    ap.add_argument("--keep-base", type=int, default=2900, metavar="ID",
                    help="object id of the castle; the keep is +1")
    ap.add_argument("--capital-staff", default="off", choices=["on", "off"],
                    help="at start-up, place the capital roster's nine "
                         "non-shop roles (Jade, Luke, Mo, the managers, the "
                         "trainer, the prize clerk, the bank keeper) in the "
                         "castle room around its exit guide, each with a "
                         "conversation (ROLE_LINES; Manager_Karin reports the "
                         "campaign). Idempotent; needs one NPC row in room:15 "
                         "to anchor on.")
    ap.add_argument("--shop-types", default="weapon=1,armor=2,item=3,ring=4",
                    help="op-8 window type per shop kind. CHOSEN until the "
                         "first live window shows which is which.")
    ap.add_argument("--shop-price", type=int, default=100,
                    help="the flat price for --shop-prices flat (and the "
                         "fallback when the item table carries no price "
                         "column): gold at a gold shop, Rings at the Ring "
                         "Shop. The 0x107B record's A field is verified live as "
                         "the gold column, B as the rings column.")
    ap.add_argument("--shop-prices", default="table", choices=["table", "flat"],
                    help="table (default) = each item's own price out of "
                         "FE_ITEM_DATA: +0x90 gold at the weapon/armour/item "
                         "shops, +0x94 Rings at the per-class Ring Shop, which "
                         "stocks exactly the rows that carry a ring price; "
                         "buying DEBITS it and refuses when the wallet is "
                         "short. flat = every row at --shop-price (the old "
                         "behaviour, still charged).")
    ap.add_argument("--shop-level-max", type=int, default=40, metavar="LV",
                    help="stock nothing whose required level is above LV. "
                         "CHOSEN: 40 is RoD's launch level cap (4Gamer), and "
                         "the table carries Lv45/50 rows no 2006 character "
                         "could wear. 0 = no cap.")
    ap.add_argument("--bank", default="on", choices=["on", "off"],
                    help="on (default) = the Bank_Keeper STORES: 0x114B/0x114C "
                         "move an item between the bag and a per-character "
                         "bank (festore `bank`), 0x1149/0x114A move gold "
                         "(festore `bank_gold`), each pushed (0x107A kind 1 / "
                         "0x2024) and only then answered. off = the old "
                         "header-only OK that stores nothing.")
    ap.add_argument("--bank-slots", type=int, default=40, metavar="N",
                    help="the bank's cell count, served as uBankItemNum "
                         "([unit+0x4fe], 0x2024 bit 0x40000000) when the bank "
                         "window opens -- the window builds exactly that many "
                         "cells. 40 is SE's 2006 guide (flow06, 「保管数の上限は"
                         "40個」); the client itself allows up to 96.")
    ap.add_argument("--inn-fees", default=DEFAULT_INN_FEES,
                    metavar="rod|level|G:LO-HI,...",
                    help="the Inn's fee per stay (full HP/Pw restore). rod "
                         "(default) = RoD's brackets: free to Lv5, 10 G at "
                         "Lv6-10, 20 G at Lv11-20, 50 G at Lv21-40 (fewiki "
                         "Guide/Q&A 2006-05-26). level = level x "
                         "--inn-price-per-level above Lv5 (OURS, the old "
                         "rule); or explicit brackets G:LO-HI,...")
    ap.add_argument("--inn-price-per-level", type=int, default=10, metavar="G",
                    help="only with --inn-fees level: level x G gold, free to "
                         "Lv5. The per-level price was OURS (10); 0 = free.")
    ap.add_argument("--kill-gold", default=DEFAULT_KILL_GOLD,
                    metavar="rod|exp|N|off",
                    help="gold a monster kill credits (war gives none in "
                         "RoD). rod (default) = by the monster's LEVEL, the "
                         "2006 table (fewiki Monster 2006-05-26): 5 G at L1, "
                         "44 at L10, 126 at L20, 536 at L30, 3,735 at L40, "
                         "34,426 at L48 (held above -- ASSUMED). exp = the "
                         "monster's shipped EXP reward (OURS, the first pass); "
                         "N = a flat N; off = nothing. The client prints its "
                         "own '%%dGold' line when the wallet grows.")
    ap.add_argument("--mob-exp", default=DEFAULT_MOB_EXP,
                    choices=["rod", "shipped"],
                    help="EXP a kill pays when --kill-exp is 0. rod (default) "
                         "= by the monster's LEVEL, the 2006 table (fewiki "
                         "Monster): the level itself to L20, then 30 at L21 "
                         "... 195 at L30 ... 2,258 at L40 (L41 interpolated, "
                         "L44's 6,567 held above -- ASSUMED). The server pays "
                         "EXP, so the retail server's observed values win "
                         "over the client's own npc_type column; shipped = "
                         "that column (fegamedata.npc_exp), the old rule.")
    ap.add_argument("--bag-size", type=int, default=30, metavar="N",
                    help="uPossessItemNum, sent as 0x2024 maskA bit "
                         "0x20000000 on field entry: THE NUMBER OF BAG SLOTS. "
                         "The item window sizes its grid from it at "
                         "construction, so 0 draws an empty '0/0' window "
                         "however full the bag is. \U0001f511 SINCE 2026-09-08 "
                         "ONLY A SEED: the size is stored per character "
                         "(festore.py `bag_size`) and a character that has one "
                         "is served the STORE, so a bag expansion can survive a "
                         "relog. 0 disables the send, and does so WHATEVER IS "
                         "STORED -- the off switch wins.")
    ap.add_argument("--field-item-kind", default="0", choices=["0", "1", "both"],
                    help="which of the unit's two 96-slot arrays bag items go "
                         "into: 0 = +0x570, 1 = +0x6f0. The inventory widget "
                         "reads whichever its own +0x9c says, and kind 0 alone "
                         "showed nothing -- and so did 'both' (LIVE #16: each "
                         "item in BOTH arrays, still 0/0), so the array is NOT "
                         "the reason the window is empty.")
    ap.add_argument("--field-equip", default="off", choices=["on", "off"],
                    help="mark the character's worn items equipped in the bag "
                         "record (+0x4c8 = the WORN INDEX), which makes the "
                         "reader's tail call Equip(uid, -1, 1) -- the client's "
                         "field dressing, and what registers the worn items in "
                         "the FIELD's item manager (gate 4's lookup). The 09-05 "
                         "'over the default outfit, cannot move' run marked the "
                         "items with their slot TYPE (a wand in worn 10), fixed "
                         "2026-09-08. Default off for the capture replay; prod "
                         "runs on with --add-self client.")
    # PARTIAL: DEFAULT 'armour' since 2026-09-12 evening -- approved: "Go for it".
    # Not yet seen live; `off` is the rollback if the 09-05 crash comes back.
    ap.add_argument("--self-redress", default="armour", choices=["off", "armour"],
                    help="'armour' (2026-09-12): with --add-self on and "
                         "--field-equip on, re-send the worn ARMOUR (every worn "
                         "item but worn 0/1) as 0x107A straight after the self "
                         "0x1006 and before 0x100E. Why: the self record's hit "
                         "path always rebuilds face/hair/body (unit vtable "
                         "+0x4c -> 0x0507dc00 -> model builder 0x5079f90) and "
                         "strips the armour the bag reader attached, so the "
                         "player stood in the all00 base outfit until the "
                         "field-ready replay 1.5 s after the loading screen. "
                         "The weapon stays on that replay (STANCE). The "
                         "default. 'off' is the rollback: a 0x107A in this "
                         "window crashed the client on 2026-09-05, in the "
                         "wrong-marker era.")
    ap.add_argument("--field-items", default="bag", choices=["on", "bag", "off"],
                    help="carry the stored character's bag (and with 'on' the "
                         "worn gear) in the 0x1000 enter-area snapshot (the "
                         "ONLY message that fills the field inventory; readers "
                         "0x0503d330 / 0x0503c470). 'bag' (default) leaves "
                         "the worn mask 0: live #11 crashed with both. 'off' "
                         "= the empty sub-records.")
    ap.add_argument("--shop-page", type=int, default=30,
                    help="items per 0x107B page (the list asks page by page "
                         "up to the 0x1102 count).")
    ap.add_argument("--event-greeting", default=None,
                    help="override every NPC's opening line (a probe knob).")
    ap.add_argument("--talk-wrap", type=int, default=48, metavar="COLS",
                    help="the NARROWEST a talk balloon line is laid out, in "
                         "columns (a full-width character counts 2): a long "
                         "line widens until it fits --talk-lines. The balloon "
                         "never wraps by itself, is 4 lines tall and sizes "
                         "itself a few percent short, so lines are broken with "
                         "the client's own <br/> and padded (measured live "
                         "09-11). A line with its own <br/> keeps its breaks. "
                         "0 = off")
    ap.add_argument("--talk-lines", type=int, default=4, metavar="N",
                    help="lines a talk balloon shows (4, measured live: a "
                         "fifth is clipped at its bottom edge)")
    ap.add_argument("--quests", default="on", choices=["on", "off"],
                    help="QUESTS (2026-09-12): the capital's quest givers "
                         "(QUESTS: Cheese at scripts 115/315/515/715/915, "
                         "Goblin Book at 137/340/536/738/936 -- the 2006 "
                         "fewiki's) play a quest conversation on the event VM: "
                         "offer -> Yes/No menu (op 0x107) -> accepted; later, "
                         "holding the item -> Yes/No -> the item is taken and "
                         "gold paid AFTER the conversation closes. Repeatable "
                         "with a per-character cooldown. 'off' = they say "
                         "their plain townsfolk line, as before.")
    ap.add_argument("--quest-cooldown-secs", type=int, default=-1, metavar="S",
                    help="override every quest's cooldown (-1 = each quest's "
                         "own, one in-game day = 2400 s).")
    ap.add_argument("--town-file", default=None, metavar="PATH",
                    help="the TOWN FILE (default data/fe_town.json): per-group "
                         "NPCs, buildings and door->room mappings, written by "
                         "`!npc`, `!build` and `!door` as the town is walked "
                         "and served on every entry of that group. What SE's "
                         "server knew and the client does not ship. Empty "
                         "disables it.")
    ap.add_argument("--npc-names", default="on", choices=["on", "off"],
                    help="send each NPC/monster its NAME in the 0x1006 type-8 "
                         "identity sub-record (mask1 bit 0, name-only) so the "
                         "client's name field [unit+0x389] is set -- the "
                         "over-head label and the target window. Off restores "
                         "the old nameless units. The internal role name is "
                         "made readable (Warrior_Weapon_Shop -> Warrior Weapon "
                         "Shop).")
    ap.add_argument("--spawns", default="dat", choices=["dat", "off"],
                    help="serve each war field's OWN monsters from dat.pak's "
                         "fet_npc_generator_pos/_data tables (services/fedata, "
                         "fegamedata.py): 7..11 spawn points per field with "
                         "shipped positions and monster types. Capitals have "
                         "none. 'off' serves only --monster.")
    ap.add_argument("--spawn-population", default="dat", choices=["dat", "one"],
                    help="how many monsters a dat.pak spawn point holds. 'dat' "
                         "(the default, 2026-09-12) serves the generator's own "
                         "population -- fet_npc_generator_data +0x10, about "
                         "nine on most generators -- split across its types by "
                         "their shipped weights and capped per type, placed "
                         "inside the point's radius. A READING of the record "
                         "(nothing in the client consumes it). 'one' is the "
                         "old single monster per point.")
    ap.add_argument("--drops", default="on", choices=["on", "off"],
                    help="MONSTER DROPS as retail had them (2026-09-12): a kill "
                         "rolls fedata/fe-drops.tsv and a hit puts a TREASURE "
                         "CHEST on the ground (0x1006 type 2) that the killer "
                         "and their party right-click to pick up (0x201F -> "
                         "0x107A announce=1 'Got %s.' + 0x1023 + 0x1004). "
                         "'off' = nothing drops.")
    ap.add_argument("--drop-rate-mult", type=float, default=1.0, metavar="X",
                    help="multiply every drop rate (SE ran 'x2' events).")
    ap.add_argument("--drop-lifetime", type=float, default=90.0, metavar="S",
                    help="seconds an unclaimed chest stays on the ground.")
    ap.add_argument("--drop-range", type=float, default=20.0, metavar="U",
                    help="pickup reach -- the JP client's own 20.0, which the "
                         "EN overlay overwrote, so the SERVER enforces it.")
    ap.add_argument("--drop-obj-base", type=int, default=900000, metavar="N",
                    help="first object id for chests (clear of monsters, "
                         "NPCs, keeps, buildings and peers).")
    ap.add_argument("--drop-table", default=None, metavar="PATH",
                    help="the drop table (default fedata/fe-drops.tsv).")
    ap.add_argument("--spawn-layout", default="scatter",
                    choices=["scatter", "spiral"],
                    help="how a point's population stands (2026-09-12). "
                         "'scatter': seeded packs of 1..3 at random spots "
                         "within --spawn-spread x the table radius -- the same "
                         "for every player (spawn_scatter). 'spiral': the "
                         "first cut, an even golden-angle disc inside 0.8 x "
                         "the radius, which read as obvious clusters.")
    ap.add_argument("--spawn-spread", type=float, default=2.0, metavar="X",
                    help="scatter reach as a multiple of the point's table "
                         "radius (25..50 u on most points). CHOSEN.")
    ap.add_argument("--spawn-mobs-max", type=int, default=200, metavar="N",
                    help="cap on monsters served per field entry under "
                         "--spawn-population dat, so object ids (from "
                         "--monster-base + 1000) stay far below --keep-base.")
    ap.add_argument("--spawns-max", type=int, default=12,
                    help="cap on dat.pak spawn points served per entry.")
    ap.add_argument("--door-radius", type=float, default=15.0,
                    help="world units either side of a --door's X/Z that "
                         "still count as that door.")
    ap.add_argument("--door-default", type=lambda v: None if v == "" else int(v, 0),
                    default=10,
                    help="the room an UNMAPPED door opens. Default 10, the arms "
                         "shop, so every door works while the town is being "
                         "mapped; empty ('') answers 0x1167 NG instead, which "
                         "shows the client's own 'system error' text. "
                         "`!door N` in --gmcmd-file changes it live.")
    ap.add_argument("--blacklist", default="on", choices=["on", "off"],
                    help="answer the three blacklist requests -- 0x20A0 "
                         "SET with 0x115F, 0x20A1 REMOVE with 0x1161, 0x20A2 "
                         "GET with the whole-list 0x1163 -- and persist the "
                         "rows onto the stored character. OFF restores the "
                         "pre-2026-08-25 silence, in which every blacklist "
                         "dialog hangs; it is an A/B, not a fallback.")
    ap.add_argument("--distribution", default="on", choices=["on", "off"],
                    help="answer 0x2080 MSG_GET_CHARACTER_DISTRIBUTION_INFO_"
                         "REQUEST (a ~10s poll) with 0x1123.")
    ap.add_argument("--distribution-rows", default="",
                    metavar="A:B:CLASS:CHARID,...",
                    help="the rows of the 0x1123 body. EMPTY (the default) "
                         "sends count 0, which is the honest answer: the third "
                         "byte's low 5 bits are a class code and its top bit "
                         "the side, and the u32 is a character id the client "
                         "looks up -- but what the rows DRAW is unmeasured "
                         "(probably the minimap distribution dots), so making "
                         "some up would be inventing a screen. This is the "
                         "knob for finding out.")
    ap.add_argument("--set-comment", default="ok", choices=["ok", "ng", "off"],
                    help="answer the 0xF900 `comment <text>` command with "
                         "0x111E MSG_SET_COMMENT_OK (header-only -- its arm "
                         "0x05055b24 makes zero stream reads, so a body would "
                         "desynchronise). 'ng' sends 0x111F, 'off' answers "
                         "nothing. The comment is persisted onto the stored "
                         "character either way.")
    ap.add_argument("--chat-echo", default="off",
                    choices=["off", "gm", "say", "self"],
                    help="what to do with the player's OWN chat line (all six "
                         "ids). 'self' echoes it back with the player's own "
                         "unit id in the header, which is the retail shape: "
                         "0x051334f0 does NOT log a /say, it only sends and "
                         "draws the balloon (0x05129890 = [obj+0x47c]); the "
                         "log line is drawn by the chat-window listener at "
                         "0x0512bf60 from what the ARM broadcasts, so without "
                         "an echo your own line never reaches the log. /tell "
                         "is never echoed (its handler logs itself). "
                         "'say' RELAYS the line "
                         "back as the same id, which is the real chat channel "
                         "-- the client's receive dispatcher routes 0x201A / "
                         "0x201B / 0x2065 / 0x2066 / 0x208A to arm 0x05053cbe "
                         "and 0x2067 to 0x05053e28, so the inbound id IS the "
                         "outbound one. WARNING: the player already echoes their "
                         "own line locally (0x051334f0), so 'say' shows it "
                         "TWICE -- that doubling is the confirmation, not a "
                         "bug. 'gm' is the older stopgap: it prints through "
                         "the 0xF900 '@' system-message path, which is not the "
                         "chat window.")
    ap.add_argument("--chat-line", action="append", metavar="ID|NAME|TEXT",
                    help="serve one chat line at field entry, e.g. "
                         "0x201a|Bob|hello. Repeatable. 0x2067 (/tell) takes "
                         "ID|A|B|TEXT -- it reads three strings and which is "
                         "from/to/text is UNMEASURED. WARNING: both fields are "
                         "clamped (name 0x20, text 0x80): the client reads "
                         "them with an UNBOUNDED strcpy into a 0x81-byte stack "
                         "slot. WARNING: a name on the player's own blacklist is "
                         "dropped SILENTLY by 0x05170e10 and reads exactly "
                         "like a broken message.")
    ap.add_argument("--chat-unit-id", type=int, default=0, metavar="ID",
                    help="the SPEAKER's unit id in every chat message's world "
                         "header. WARNING: THE 08-26 READING HERE WAS HALF WRONG AND "
                         "IS CORRECTED: 0x05053cbe suppresses the speech BUBBLE "
                         "when the speaker is you, but the chat LOG is an "
                         "UNCONDITIONAL broadcast (0x05053da3) gated only by the "
                         "blacklist -- so a self-spoken line still appears in the "
                         "log. Verified live 2026-09-04: --chat-echo self sends the "
                         "player's own unit id and the line appeared. 0 is "
                         "the client's 'no unit' sentinel, matches no object, "
                         "and takes the CHAT LOG path. Give a live unit's id "
                         "(e.g. an --npc) to aim the text at that unit instead "
                         "-- that A/B is what proves the reading.")
    ap.add_argument("--chat-bubbles", default="all", choices=["all", "say", "off"],
                    help="a SPEECH BALLOON over the player who spoke "
                         "(2026-09-12): a relayed line carries the sender's "
                         "charid as its speaker unit id when this client draws "
                         "that player (fepresence, --unit-id auto). The arm "
                         "0x05053cbe skips the balloon only for a kind-1 unit "
                         "(the local player) and 0x5129890 accepts the kind-2 "
                         "avatar a peer is. 'all' = /say /all /army /party "
                         "(the client treats them alike), 'say' = /say only, "
                         "'off' = speaker 0, no balloon (the old behaviour).")
    ap.add_argument("--chat-relay", default="on", choices=["on", "off"],
                    help="fan every player's chat line out to the OTHER "
                         "in-field sessions on this door (queue per session, "
                         "drained by its own read loop; /tell goes only to "
                         "the session whose client signs as the target). "
                         "The relayed copy's speaker unit id is set by "
                         "--chat-bubbles (the sender's charid, or 0). Names on the "
                         "receiver's served blacklist are dropped here with a "
                         "log line instead of silently by 0x05170e10.")
    ap.add_argument("--monster", action="append", metavar="TYPE[:X:Y:Z]",
                    help="spawn a MONSTER: 0x1006 entity type 8, the arm we "
                         "had never sent (0x1006 dispatches NINE types at "
                         "0x0503bb0c; --npc is type 0). TYPE is an id in "
                         "dat\\data_NPC_ModelType.dat, which the client names "
                         "itself when the lookup misses: 'ERROR : "
                         "CFeClientNPCObject::Initialize() get Modeltype type "
                         "= %%d'. 271 rows ship in dat.pak -- 0..6 goblins, "
                         "7..17 orcs, 18..24 undead, 25..44 "
                         "dragon/griffin/harpy/salamander/venom, 45..47 and "
                         "61..71 the rest, 216..227 more monsters; 52..60, "
                         "72..215, 221 and 228..274 are town NPCs "
                         "(Npc00..Npc45 -- 201 rows, regenerated in full into "
                         "the fe-npc-modeltypes TSV 2026-09-04; that TSV "
                         "had first been written with fenpc.py --monsters and "
                         "so held only the 69 with a bestiary entry). WARNING: 221 "
                         "is a town NPC INSIDE the monster block and 227 "
                         "(ulf_01) is a monster model with no bestiary row, so "
                         "neither the id ranges nor the scalars classify these "
                         "cleanly -- read the TSV, do not interpolate. "
                         "Repeatable. X:Y:Z go into the ADD itself (mask2 "
                         "bit 0 -> [unit+0x1c4], ground-snapped by "
                         "0x05000450); TYPE must be one of the 271 shipped "
                         "ids (0..47, 52..274) and the object id must not "
                         "collide with the player or an --npc -- both are "
                         "refused at startup, see monster_push.")
    ap.add_argument("--monster-walk", choices=("on", "off"), default="off",
                    help="also re-place every --monster with 0x2023 action 0 "
                         "on each client move tick (the --npc-walk "
                         "machinery). Default off: the ADD already places "
                         "it, and the first live test wants one new message, "
                         "not two.")
    ap.add_argument("--monster-base", type=int, default=400, metavar="ID",
                    help="object id of the first --monster; each subsequent "
                         "one takes the next. Kept clear of --npc-base so the "
                         "two families cannot collide in the client's object "
                         "list, which is keyed by this id.")
    ap.add_argument("--monster-kind", type=int, default=0, metavar="N",
                    # (per-entity override: the optional 5th field of --monster)
                    help="the second u16 of the type-8 record. 0 makes the "
                         "ctor stamp [unit+0x24]=0xBBC, non-zero 0xBBB "
                         "(0x05068fd4). What the two mean in game terms is "
                         "UNMEASURED -- both are inside the range 0x2023 "
                         "action 0 accepts. A sentinel knob, not a setting.")
    ap.add_argument("--monster-level-source", default="shipped",
                    choices=("shipped", "knob"),
                    help="where a monster's LEVEL comes from: 'shipped' = its "
                         "own fet_npc_type row (what the CLIENT draws on the "
                         "target ring), 'knob' = --monster-level for every "
                         "monster in the world, which is the pre-2026-09-12 "
                         "behaviour and paid a level-1 reward for a level-47 "
                         "kill because --mob-exp rod is rod_mob_exp(level)")
    ap.add_argument("--monster-level", type=int, default=1, metavar="N",
                    help="the trailing u8 -> [unit+0x3ac]. On the PLAYER that "
                         "offset is the class level the Status screen draws, "
                         "so 'level' is the obvious reading and obvious is not "
                         "measured. Default 1 rather than 0 on purpose: nobody "
                         "chooses the zero either, and zero is what silently "
                         "refuses things elsewhere in this client.")
    ap.add_argument("--building", action="append", default=None,
                    metavar="GID:TYPE:MODEL:GX:GZ",
                    help="place a BUILDING (0x1006 entity type 1) when group "
                         "GID is entered; repeatable. TYPE is a row of "
                         "data_FE_BUILDING_DATA.dat (9 Bar, 10 BlackSmith, 11 "
                         "ItemShop, 13 PublicBath, 14 House, 15 Castle, 16 "
                         "Keep, 6 Obelisk...), MODEL a row of "
                         "data_FE_BUILDING_MODEL_DATA.dat -- and models 9/10/"
                         "11/13/14/15 are the ROOM buildings (bar, arms shop, "
                         "magic shop, bath, house, castle), i.e. the DOORS the "
                         "capital's minimap draws. GX/GZ are 0..255 on the "
                         "field grid: world = -(g-128)*2.5, so 128:128 is the "
                         "centre; Y comes off the heightmap. The record is "
                         "measured to the byte (building_record); what a "
                         "placed building DOES is not -- `!build TYPE` in "
                         "--gmcmd-file drops one where the player stands, "
                         "which is how to find the door coordinates.")
    ap.add_argument("--building-base", type=int, default=3000, metavar="ID",
                    help="object id of the first building; clear of --npc-base "
                         "and --monster-base. The type-1 arm looks the id up "
                         "in kind 0x7D0 and logs 'already exists' on a hit.")
    ap.add_argument("--building-hp", default="100:100", metavar="A:B",
                    type=lambda v: tuple(int(x, 0) for x in v.split(":")),
                    help="the two i32s at +0x778 and +0x774 (that wire order). "
                         "0x5111010 ratios the pair as a gauge, so HP/max-HP "
                         "fits -- WHICH IS WHICH IS UNMEASURED. Equal values "
                         "sidestep the question for a town.")
    ap.add_argument("--monster-chase-timing", default="step",
                    choices=["step", "client"],
                    help="the two u32s after the action in a monster's 0x2023 "
                         "move are a START and an END tick, and the client "
                         "reads END minus START as the move's DURATION in ms "
                         "(0x04FEAB38). 'step' (the default) sends (t, t + "
                         "step/speed), so a step takes as long as it should. "
                         "'client' copies the client's own heartbeat pair, "
                         "which is the HIGH and LOW half of its clock -- a "
                         "duration of minutes per step, so the monster plays "
                         "its walk and stays where it is (the pre-2026-09-12 "
                         "behaviour).")
    ap.add_argument("--monster-height", default="dat",
                    choices=["dat", "table"],
                    help="where a dat.pak spawn's Y comes from. 714 of "
                         "fet_npc_generator_pos' 721 rows ship y = 0 exactly "
                         "-- the table has no world height, SE's own server "
                         "resolved it -- and every map that ships samples has "
                         "its lowest ground at 8, medians 8..62. So y=0 puts "
                         "the monster UNDER the terrain, which put our own "
                         "registry tens of units below the player and made "
                         "the vertical reach test refuse every attack. 'dat' "
                         "(the default) "
                         "raises a y=0 row to the map's ground height, the "
                         "same estimate the player's derived spawn uses; "
                         "'table' serves the raw 0 back.")
    ap.add_argument("--exp-max-seed", type=int, default=8, metavar="N",
                    help="how many times to repeat the 0x1075 bit-2 EXP "
                         "THRESHOLD ([unit+0x135c]) during field load, from "
                         "the 0x2000 enter-area answer until the field-entry "
                         "burst. The HUD exp gauge caches that value at "
                         "construction (0x050CCA9D) and its only refresh "
                         "(0x050CE346) is unreachable once the cache is 0 -- "
                         "step = (long)(0*K) = 0, so the fill can never exceed "
                         "the max -- which is the bar that is always full. "
                         "[unit+0x135c] has exactly ONE writer in the client, "
                         "the bit-2 arm at 0x0505222C, so this is the only "
                         "lever there is. A push before the unit exists is a "
                         "silent no-op, hence the repeat. 0 = off.")
    ap.add_argument("--field-ready-ms", type=int, default=1500, metavar="N",
                    help="how long after 0x100E MSG_ADD_COMPLETE the "
                         "FIELD-READY batch is released: the war notify, the "
                         "0x107A worn-item replay that dresses the rebuilt "
                         "unit, the skill palette, and the field_ready flag "
                         "fecampaign gates keeps and buildings on. It used to "
                         "wait for the client's first 28-BYTE 0x2023, which "
                         "the client does not send UNTIL THE PLAYER MOVES -- "
                         "measured at 6.3 s on 2026-09-12, during which the "
                         "character stood there in its base outfit with the "
                         "equipment clipping through it. 0 = the old trigger "
                         "(movement only). Raise it if a field entry starts "
                         "crashing on the palette: the 0x2029 workers deref "
                         "the HUD singletons with no null check.")
    ap.add_argument("--build-age", default="real",
                    choices=["real", "zero", "done"],
                    help="what the type-1 building record's LAST u32 carries. "
                         "It is the building's AGE IN MS at the moment it is "
                         "added: the client stores now-minus-it and compares "
                         "now-minus-that against FE_BUILDING_DATA +0xac, its "
                         "build time (Arrow Tower 40000, Obelisk 30000, War "
                         "Craft 60000, Keep 30000, shops 10000), and draws a "
                         "construction site while it is short (0x05072770). "
                         "'real' (the default) sends 0 only for a build the "
                         "player is paying for this second and the true age "
                         "for everything already standing. 'zero' is the "
                         "pre-2026-09-12 behaviour -- every building raised "
                         "itself again at every player it was sent to. 'done' "
                         "never shows a site at all.")
    ap.add_argument("--doors", default="dat", choices=["dat", "off"],
                    help="fall back to dat.pak's own fet_area_portal table for "
                         "any door no --door entry and no town file claims. "
                         "The table covers the ten CAPITAL areas (21/39/57/62/"
                         "78 and their 91..95 twins) and pairs each door with "
                         "the one it leads to, which is the shipped answer to "
                         "'a door leads to the other half of the capital'. It "
                         "also carries the ARRIVAL position, so the player "
                         "lands where SE put them rather than at the group's "
                         "default spawn. ON since 2026-09-09: the record's "
                         "frame was settled off the client's own parser "
                         "(0x0519D85A) -- every position is a two-float (x, z) "
                         "pair and the float previously read as a third "
                         "coordinate is the door's RADIUS. A war field has no "
                         "rows, so this changes nothing outside a capital. "
                         "PARTIAL: STATIC ONLY -- no door has been walked through "
                         "since; `--doors off` restores the old behaviour.")
    ap.add_argument("--unequip-reflect", default="on", choices=["on", "off"],
                    help="on an unequip, send 0x2004 with the worn slot empty "
                         "so the CLIENT runs its own unequip (0x0507b950 -> "
                         "0x05073f00). Without it the 0x102C OK and the 0x107A "
                         "marker leave [unit+0x870] still naming the item, so "
                         "the inventory keeps showing it worn and the body "
                         "part the equip swapped out never comes back -- "
                         "reported live 2026-09-06.")
    ap.add_argument("--cast-report", default="on", choices=["on", "off"],
                    help="log, from dat.pak's own tables, which of the cast "
                         "ladder's gates would refuse each of the character's "
                         "skills and why. Gate 4 ('Skill conditions not met.') "
                         "reads WORN SLOTS 0 AND 1 ONLY and matches the item's "
                         "category bits against the skill's, so the answer is "
                         "usually 'nothing with the right category is in your "
                         "hand'.")
    ap.add_argument("--discard", default="on", choices=["on", "off"],
                    help="act on 0xF102, the client's DISCARD (its own log "
                         "line is `> ComamndDiscardItem`): take the item out "
                         "of the stored bag so the drop survives the next "
                         "field entry. Nothing answers it -- the id registers "
                         "no reply and the client drops it locally -- so "
                         "'off' just means a dropped item comes back.")
    # ---- COMBAT (2026-09-06, static; nothing here has been live-tested) ----
    ap.add_argument("--combat", default="off", choices=["on", "off"],
                    help="answer 0xA011 MSG_NPC_HIT_NOTIFY: subtract "
                         "--hit-damage from the monster's hit points, push the "
                         "new HP as a 0x1006 type-8 re-apply, and on zero send "
                         "0x1004 MSG_DEL and award EXP. OFF by default because "
                         "no part of it has been seen on a screen -- with it "
                         "off the hit is still LOGGED, which is itself the "
                         "first thing to check (does the client send 0xA011 at "
                         "all, and what is in the two undecoded u32s?).")
    ap.add_argument("--hit-damage", type=int, default=25, metavar="N",
                    help="flat damage per 0xA011 (CHOSEN): what a hit on a "
                         "keep, a building or (via fepvp) a player does, and "
                         "the fallback against a monster when --player-damage "
                         "is flat or the skill has no damage effect.")
    ap.add_argument("--player-damage", default="table", choices=["table", "flat"],
                    help="a hit on a MONSTER. 'table' (2026-09-12): the "
                         "player's attack (class base +0x28/+0x2A + the worn "
                         "weapon's +0x38/+0x3A) x the skill's power %% out of "
                         "EFFECT_DATA (Sonic Boom L1 70, basic attack 100). "
                         "'flat' = --hit-damage. Either way it is then scaled "
                         "by --mob-level-correction. Monster defence is not "
                         "applied (no source says how).")
    ap.add_argument("--mob-level-correction", default="on", choices=["on", "off"],
                    help="scale --hit-damage against a monster by "
                         "fet_npc_lv_diff_correction's f0 for (monster level - "
                         "your class level), the row picked the way the "
                         "client's 0x050DFEB0 picks it (exact, else clamped): "
                         "1.4 at even, 1.0 at +3, 0.05 at +15 and above "
                         "(2026-09-12, static). 'off' = flat --hit-damage.")
    ap.add_argument("--monster-hp", type=int, default=0, metavar="N",
                    help="override every monster's hit points. 0 (default) "
                         "takes them from dat.pak's fet_npc_type table via "
                         "fegamedata.npc_hp, falling back to 100.")
    ap.add_argument("--kill-exp", type=int, default=0, metavar="N",
                    help="a flat EXP per kill; 0 (default) pays by --mob-exp "
                         "(the RoD table by monster level, or the shipped "
                         "column).")
    ap.add_argument("--kill-reward", default="on", choices=["on", "off"],
                    help="push EXP on a kill (0x1075 mask bit 2 -> "
                         "[unit+0x135c]). 'off' kills without paying.")
    ap.add_argument("--respawn-secs", type=float, default=0.0, metavar="S",
                    help="put a dead monster back after S seconds, re-sending "
                         "its 0x1006 type-8 ADD at the same position. 0 "
                         "(default) leaves the field cleared -- which is also "
                         "the only way to see whether 0x1004 removed anything.")
    ap.add_argument("--unit-state", type=lambda v: int(v, 0), default=None,
                    metavar="MASK",
                    help="serve [unit+0x2b4], the unit STATE WORD, on field "
                         "entry (0x2024 maskA bit 0x100000). THIS IS THE SKILL "
                         "GATE: bits 25..28 (0x1E000000) are what the palette's "
                         "Select and the cast's 0x0504a500 test against each "
                         "skill's [skill+0xd0], the field is server-owned (the "
                         "client has no local writer), and we have never sent "
                         "it -- so it has been 0 and no gated skill has ever "
                         "been selectable. Try 0x1E000000. Unset by default: "
                         "the same word carries stealth (0x2000) and the "
                         "move/animation transitions (0x800000, 0x1000000, "
                         "0x20000000) that 0x0506caa0 fires, so a wide value "
                         "changes more than the gate.")
    ap.add_argument("--gmcmd", action="append", default=None, metavar="LINE",
                    help="a 0xF900 command line to send once, after field "
                         "entry; repeatable. A leading '/' makes the client RUN "
                         "it through its own slash dispatcher (/warp, /summon, "
                         "/healme, /toggleinterface, the emotes -- see "
                         "GM_COMMANDS); a leading '@' makes it PRINT the rest "
                         "in the message window. Anything else is decoded and "
                         "dropped by the client.")
    ap.add_argument("--gmcmd-file", default=None, metavar="PATH",
                    help="a file polled on every inbound frame: each line is "
                         "sent as a 0xF900 command and the file is then "
                         "truncated. A live console into the running client. "
                         "Same '/' and '@' rules as --gmcmd. SERVER-SIDE "
                         "directives start with '!' and never reach the "
                         "client: '!chat ID|NAME|TEXT' sends one chat line, "
                         "'!war' advances the war phase on demand (once per "
                         "field entry -- it moves a phase, and re-sending a "
                         "phase advance is the re-arming loop 0x1018's note "
                         "warns about), and '!crystal N' re-serves CRYSTAL "
                         "while the Status screen is open. These exist because "
                         "the alternative is a --force-recreate, and that "
                         "drops the session you are testing in.")
    ap.add_argument("--accounts-db", default=None,
                    help="POL accounts.db used to resolve an address to a member "
                         "when the echo and the handoff both miss (default: "
                         "data/accounts.db, or $FE_ACCOUNTS_DB / "
                         "$POL_ACCOUNTS_DB). Empty skips the lookup.")
    ap.add_argument("--member-window", type=float, default=None,
                    help="seconds a POL session row may still name the member at "
                         "an address (default 86400 / $FE_MEMBER_WINDOW)")
    ap.add_argument("--session-store", default=None,
                    help="felobby's handoff file (default data/fe_sessions.json). "
                         "Empty disables it, leaving only the account echo and "
                         "the direct lookup.")
    for _fn in EXT_ARGS:
        _fn(ap)
    # The game rules as tuned in play. Each is still a command-line option
    # (docker-compose.yml or the command line overrides any of them); these
    # are simply the values a working world runs with, so a stock bring-up
    # needs none of them spelled out. Deployment-specific options (ports,
    # binds, tokens, webhooks) keep their plain parser defaults.
    RELEASE_DEFAULTS = {
        "port": 54850, "seq_mode": "count", "world": "dat",
        "field_names": "dat-en", "field_home": "capital",
        "field_nations": "1:5", "field_defenders": "1,2,3,4,5",
        "capital": "1:39", "capital_name": "Capital",
        "captures": 0, "life": 0, "read_window": 120,
        "war_start": "deadline", "war_deadline_ms": 60000,
        "war_clock": "telemetry", "combat": "on", "hit_damage": 400,
        "respawn_secs": 45, "monster_attack": "on", "monster_damage": 60,
        "monster_range": 8.0, "monster_interval": 2.0, "revive_secs": 60,
        "item_heal": 250, "unit_state": "0x1E000000", "jump_phys": "0.78:1.0",
        "unit_physics": "push", "war_cycle": "on", "war_length_ms": 3600000,
        "war_truce_ms": 600000, "campaign": "on", "war_prep_ms": 65000,
        "declare_accepts": 4, "build_costs": "2006", "keeps": "on",
        "keep_types": "20:16", "keep_models": "30:16", "obelisk_drain": "on",
        "build_share": "on", "tower_fire": "on", "base_cannon": "off",
        "influence": "buildings", "keep_hp": 3000, "war_decide": "keeps",
        "capital_staff": "on", "add_self": "on", "field_equip": "on",
        "self_pos": "2.16:24.76:-60.51", "unit_id": "auto",
        "move_authority": "off", "unit_speed": 1.3,
        "add_stats": "0:5,7:200,8:200", "gold": 1000, "ring": 1,
        "crystal": 0, "total_score": 0, "unit_speed_repeat": "off",
        "char_record": "off", "char_mask": 1, "char_fields": "0:5",
        "chat_echo": "self", "gmcmd_file": "/data/fe_gmcmd.txt",
    }
    known = {a.dest for a in ap._actions}
    unknown = sorted(k for k in RELEASE_DEFAULTS if k not in known)
    if unknown:
        raise SystemExit("RELEASE_DEFAULTS names unknown options: %s" % unknown)
    # string values go through each option's own type/choices handling
    ap.set_defaults(**{k: (str(v) if not isinstance(v, str) else v)
                       for k, v in RELEASE_DEFAULTS.items()})
    args = ap.parse_args()
    try:
        _dm, _dc = (int(x, 0) for x in args.item_durability.split(":"))
        globals()["ITEM_DURABILITY"] = (_dm, _dc)
    except ValueError:
        raise SystemExit("--item-durability wants MAX:CUR, e.g. -1:100")
    try:
        args.move_xyz = tuple(float(v) for v in args.move_pos.split(":"))
        if len(args.move_xyz) != 3:
            raise ValueError
    except ValueError:
        raise SystemExit("--move-pos wants X:Y:Z, got %r" % args.move_pos)
    # WARNING: THESE THREE MUST BE PARSED BEFORE ANYTHING READS THEM, and on
    # 2026-09-09 they were not: the spawn-store block below reads
    # args.spawn_xyz, this ran AFTER it, and feworld crash-looped on prod with
    # AttributeError on the first start. Derived coordinates go first.
    try:
        args.self_xyz = tuple(float(v) for v in args.self_pos.split(":"))
        if len(args.self_xyz) != 3:
            raise ValueError
    except ValueError:
        raise SystemExit("--self-pos wants X:Y:Z, got %r" % args.self_pos)
    for _opt, _dst in (("spawn_pos", "spawn_xyz"), ("spawn_dir", "spawn_dir_xyz")):
        try:
            setattr(args, _dst,
                    tuple(float(v) for v in getattr(args, _opt).split(":")))
            if len(getattr(args, _dst)) != 3:
                raise ValueError
        except ValueError:
            raise SystemExit("--%s wants X:Y:Z, got %r"
                             % (_opt.replace("_", "-"), getattr(args, _opt)))
    global _CAPITALS
    _CAPITALS = parse_capitals(args.capital)
    if world_from_dat(args):
        # KEY: --islands is DERIVED here, not configured. 0x3030's handler
        # bounds-checks every island id as (id-1) < count, so announcing six
        # islands' worth of groups under a count of five means island 6's
        # records are asked for and never resolve. The table says six.
        _isls = fegamedata.island_ids()
        if not _isls:
            raise SystemExit(
                "--world dat needs fedata/fe-fet-area.tsv; it is missing or "
                "has no `island` column. Regenerate it with tools/fedatagen/fefet.py.")
        args.islands = max(_isls)
        territory_load(args)
        _held = {}
        for _a in fegamedata.areas():
            _held[territory_owner(_a, args)] = _held.get(territory_owner(_a, args), 0) + 1
        print("[feworld] WORLD = dat: %d islands, %d areas, holdings %s"
              % (args.islands, len(fegamedata.areas()),
                 ", ".join("n%d:%d" % kv for kv in sorted(_held.items()))),
              flush=True)
        if args.world_neighbours != "on":
            print("[feworld] WARNING: --world-neighbours off: 0x3031 bit 12 is NOT "
                  "served, so the client's frontier test can only ever match a "
                  "field your own nation already holds. No player will be able "
                  "to enter enemy land.", flush=True)
    capital_staff_fill(args)
    if getattr(args, "devtool_port", 0):
        # The tee is what makes the panel usable: "did that work?" is answered
        # by a log line, and until now that line was on a terminal somewhere
        # else. Wrapping stdout is contained and only happens when the panel
        # is on.
        class _Tee(object):
            def __init__(self, inner):
                self._inner = inner

            def write(self, text):
                try:
                    fedevtool.note(text)
                except Exception:
                    pass
                return self._inner.write(text)

            def flush(self):
                return self._inner.flush()

            def __getattr__(self, k):
                return getattr(self._inner, k)

        sys.stdout = _Tee(sys.stdout)
        fedevtool.start(args.devtool_port, args.devtool_bind,
                        args.devtool_token,
                        lambda area=None: devtool_state(args, area),
                        lambda op: devtool_edit(args, op),
                        floor_fn=lambda area: devtool_floor(args, area))
        print("[feworld] world-building panel on http://%s:%d/%s"
              % (args.devtool_bind, args.devtool_port,
                 "?t=" + args.devtool_token if args.devtool_token else ""),
              flush=True)
    spawn_load(args)
    mapcal_load(args)
    doorarr_load(args)
    with _DOORARR_LOCK:
        _n_arr = len(_DOORARR)
    if _n_arr:
        print("[feworld] door arrivals: %d portal(s) have a hand-placed "
              "arrival point" % _n_arr, flush=True)
    with _MAPCAL_LOCK:
        _n_cal = len(_MAPCAL)
    if _n_cal:
        print("[feworld] minimap calibration: %d map half/halves have "
              "their own anchors" % _n_cal, flush=True)
    with _SPAWN_LOCK:
        _n_spawn = len(_SPAWN)
    if _n_spawn:
        print("[feworld] spawn store: %d area(s) have their own arrival point"
              % _n_spawn, flush=True)
    if tuple(args.spawn_xyz) == (0.0, 0.0, 0.0):
        # WARNING: The single loudest thing this file can say. World (0,0,0) is the
        # centre of the terrain grid at height zero -- under the map on most of
        # them -- and it is where EVERY area with no spawn row puts the player,
        # including the fallback arrival of every warp.
        print("[feworld] WARNING: --spawn-pos is 0:0:0, so every area without a "
              "`!spawn` row drops the player at the terrain origin at height "
              "zero. Set --spawn-pos to measured ground, or stand somewhere "
              "sensible in each area and type `!spawn`. (--self-pos is a "
              "DIFFERENT record and does not cover this.)", flush=True)
    elif tuple(args.spawn_xyz) != tuple(args.self_xyz):
        print("[feworld] WARNING: --spawn-pos %s and --self-pos %s disagree: the "
              "client is told two different places it is standing."
              % (args.spawn_xyz, args.self_xyz), flush=True)
    global _FIELD_ROOMS
    _FIELD_ROOMS = parse_field_rooms(args.field_rooms)
    if args.enter_room != -1:
        print("[feworld] WARNING: --enter-room %d is GLOBAL: every group without a "
              "--field-rooms entry now enters an indoor room instead of the "
              "Hmap battlefield. It does NOT affect a capital -- the capital "
              "test comes first. If you meant 'one field is a shop door', that "
              "is --field-rooms." % args.enter_room, flush=True)
    for _g, _r in sorted(_FIELD_ROOMS.items()):
        if _g in CAPITAL_GROUP_IDS:
            print("[feworld] WARNING: --field-rooms %d:%d has NO EFFECT -- %d is a "
                  "capital id, and the entry branch tests that FIRST "
                  "(0x04ff9d5e), so the capital loader runs and the room index "
                  "is never read. Put the room on a war-field group instead."
                  % (_g, _r, _g), flush=True)
        elif _r == -1:
            print("[feworld] group %d forced OUTDOORS (the Hmap battlefield)"
                  % _g, flush=True)
        else:
            print("[feworld] group %d is a DOOR into room %d (%s)"
                  % (_g, _r, room_label(_r)), flush=True)
    for _isl, _gs in sorted(_CAPITALS.items()):
        for _g in _gs:
            if _g in CAPITAL_INCOMPLETE:
                print("[feworld] WARNING: --capital %d:%d -- our W20-0011 mirror does "
                      "NOT serve %s. Every other capital id is complete; if the "
                      "town half-loads, that is why, and 39/57/62/78 are the "
                      "ones to use."
                      % (_isl, _g, CAPITAL_INCOMPLETE[_g]), flush=True)
        if world_from_dat(args):
            # Don't let the log claim something the world no longer does:
            # group_ids_for takes the island's membership from fet_area in dat
            # mode, so --capital contributes nothing and the id sits on
            # whichever island the table puts it on, not this one.
            print("[feworld] WARNING: --capital %d:%s is INERT under --world dat -- "
                  "the table already places every capital (%s is on island %s). "
                  "It is read only to validate the id."
                  % (_isl, ",".join(str(g) for g in _gs), _gs[0],
                     fegamedata.areas().get(_gs[0], {}).get("island", "?")),
                  flush=True)
        else:
            print("[feworld] island %d also announces CAPITAL group(s) %s"
                  % (_isl, ", ".join(str(g) for g in _gs)), flush=True)
    # WARNING: A ZERO FACING IS NOT A FACING -- MEASURED LIVE 2026-08-25.
    # felive --avatar in the field read the player unit fully dressed
    # (+0x3c=1, +0x38=1, +0x1360 non-zero, slot 0 set, face and hair models
    # both non-null) and STILL invisible, with one field wrong:
    #     facing [+0x1e4] = (0.0000, 0.0000, 0.0000)
    # against (0, 0, 1) measured on 2026-08-24, before this record started
    # writing the field. mask2 bit 2's arm (0x0503ad49..0x0503adaf) reads
    # three f32 into +0x1e4/+0x1e8/+0x1ec, and 0x05078e40 consumes them as
    # `look-at = position + facing`, componentwise, feeding
    # 0x4fb8ad0(&[unit+0xc0], &at, &eye) -- the unit's world matrix. All
    # zero makes `at` EQUAL `eye`, the forward axis zero-length and the
    # basis degenerate, so the mesh rasterises nothing while the position
    # (0, 15.948, 0) stays valid and the SHADOW still draws. That is exactly
    # the symptom reported live.
    #
    # Refused HERE and not at the send: a SystemExit inside add_entities
    # would kill a live field entry, dropping the bit quietly would
    # desynchronise the record (three fewer floats), and substituting a
    # value silently is how a served zero launders into a measurement.
    # Fail before the listener opens, or not at all.
    if (args.add_mask2 & 0x4) and args.add_self == "on" \
            and not any(args.spawn_dir_xyz):
        raise SystemExit(
            "--add-mask2 bit 2 serves the FACING at unit+0x1e4, and "
            "--spawn-dir is 0:0:0. A zero-length direction makes the "
            "client's own look-at target equal its position and the "
            "character renders as nothing but its shadow (measured live "
            "2026-08-25). Pass a unit vector -- 0:0:1 is the default -- or "
            "clear bit 2 with --add-mask2 1 to leave the facing alone.")
    rows = []
    for spec in (args.distribution_rows or "").split(","):
        spec = spec.strip()
        if not spec:
            continue
        bits = spec.split(":")
        if len(bits) != 4:
            raise SystemExit("--distribution-rows wants A:B:CLASS:CHARID per "
                             "row, got %r" % spec)
        try:
            rows.append(tuple(int(x, 0) for x in bits))
        except ValueError:
            raise SystemExit("--distribution-rows: %r is not four numbers"
                             % spec)
    if len(rows) > 0xFF:
        # The client clamps to 0xFF itself (0x05010d70) and then reads only
        # that many rows -- so a longer list does not truncate, it DESYNCHRONISES
        # the stream. Refuse rather than send it.
        raise SystemExit("--distribution-rows: %d rows, but the client clamps "
                         "the count to 255 and would leave the rest of the "
                         "body unread" % len(rows))
    args.distribution_rows = rows

    # WARNING: THIS USED TO BE `args.doors = []`, AND IT KILLED THE SHIPPED DOOR
    # TABLE OUTRIGHT. `--doors` is a MODE ("dat"/"off"); `--door` is a repeated
    # GID:X:Z:ROOM row. argparse gives them dests `doors` and `door`, and this
    # line then overwrote the mode string with the row list -- so
    # dat_door_for's guard `getattr(args, "doors", "off") != "dat"` compared a
    # LIST to "dat", was always true, and returned None every single time.
    # fet_area_portal has therefore never been consulted once: every door fell
    # through to --door-default with the spawn fallback for a position, which
    # is exactly "I walked through a door and ended up nowhere near it".
    # The rows now have their own name.
    args.door_rows = []
    for _spec in args.door or []:
        try:
            _g, _x, _z, _r = _spec.split(":")
            args.door_rows.append((int(_g, 0), float(_x), float(_z), int(_r, 0)))
        except ValueError:
            raise SystemExit("--door wants GID:X:Z:ROOM, got %r" % _spec)
    for _g, _x, _z, _r in args.door_rows:
        print("[feworld] door in field %d at (%g, %g) -> room %d (%s)"
              % (_g, _x, _z, _r, room_label(_r)), flush=True)
    args.buildings = parse_buildings(args.building)
    if len(args.building_hp) != 2:
        raise SystemExit("--building-hp wants A:B")
    for _gid, _t, _m, _gx, _gz in args.buildings:
        print("[feworld] group %d gets building type %d (%s) model %d (%s%s) "
              "at grid (%d,%d)"
              % (_gid, _t, BUILDING_TYPES[_t], _m, BUILDING_MODELS[_m],
                 " = door into " + BUILDING_ROOM_MODELS[_m]
                 if _m in BUILDING_ROOM_MODELS else "", _gx, _gz), flush=True)

    args.force_table = parse_forces(args.forces)
    apply_force_targets(args.force_table, args)
    # KEY: EXTENSION THREADS START HERE -- after EVERY args.* main() derives
    # (force_table, the stores, the building list), just before the door
    # listens. They were started ~170 lines earlier on 2026-09-12 and femap's
    # first snapshot ran before force_table existed: its first Discord post
    # carried no nations (corrected by its own next edit a minute later).
    for _fn in EXT_START:
        try:
            _fn(args)
        except Exception:                              # noqa: BLE001
            import traceback
            print("[feworld] EXTENSION start %r failed -- world door still up:"
                  % (getattr(_fn, "__module__", "?"),), flush=True)
            traceback.print_exc()

    srv = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    srv.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    srv.bind(("0.0.0.0", args.port))
    srv.listen(4)
    print("[feworld] FE WORLD DOOR on 0.0.0.0:%d -- handshake then CAPTURE"
          % args.port, flush=True)
    print("[feworld] %s" % ("runs until stopped" if args.captures <= 0
                            and args.life <= 0 else
                            "exits after %d capture(s) / %ds"
                            % (args.captures, args.life)), flush=True)

    # Tell the deploy gate when an FE world session is live, so a push does not
    # bounce feworld mid-field.
    # One named thread per session already exists, so counting them IS the
    # liveness metric -- no per-session change.
    try:
        import live_sessions
        live_sessions.start_heartbeat(
            "feworld", lambda: live_sessions.thread_count("feworld-"))
    except Exception as _e:
        print("[feworld] live-session heartbeat not started: %r" % _e, flush=True)

    got, deadline = 0, time.time() + (args.life or 0)
    while ((args.captures <= 0 or got < args.captures)
           and (args.life <= 0 or time.time() < deadline)):
        if args.life > 0:
            srv.settimeout(max(1.0, deadline - time.time()))
        try:
            conn, peer = srv.accept()
        except (OSError, IOError):
            continue
        got += 1
        print("\n[feworld] CONNECT from %s:%d" % peer, flush=True)
        # THREADED for the same reason felobby is: this loop used to serve one
        # connection to completion -- up to --read-window 120s -- before
        # accepting the next, so a second player's FE sat unanswered on a
        # connected socket. Every per-session value now lives on _TLS
        # (_SESSION, _OUT_SEQ, _LAST_IN); the character store is felobby's and
        # is written through its atomic save.
        threading.Thread(target=_serve_one, args=(conn, peer, args),
                         name="feworld-%s-%d" % peer, daemon=True).start()
    srv.close()
    # Wait out sessions in flight -- these are daemon threads, so returning
    # would kill a live world session mid-frame, and a capture run reaches its
    # --captures limit at ACCEPT, before the session has done anything.
    for t in threading.enumerate():
        if t is not threading.current_thread() and t.name.startswith("feworld-"):
            t.join(timeout=max(args.read_window, 5.0) + 5.0)
    print("[feworld] listener closed", flush=True)


if __name__ == "__main__":
    main()
